def _pg_rollback(conn) -> None:
    """Transaktion nach Fehler sofort freigeben (PostgreSQL aborted block)."""
    if conn is None:
        return
    try:
        conn.rollback()
    except Exception:
        pass


def _request_pg_track(conn: Any) -> None:
    """Verbindung dem aktuellen Request-Kontext zuordnen (Rollback bei Fehler)."""
    bucket = _REQUEST_PG_CONNS.get()
    if bucket is None:
        bucket = []
        _REQUEST_PG_CONNS.set(bucket)
    bucket.append(conn)


def _pg_rollback_safeguard_request() -> None:
    """Rollback aller PG-Verbindungen des laufenden Requests (Pool-Sperren vermeiden)."""
    bucket = _REQUEST_PG_CONNS.get()
    if not bucket:
        return
    for conn in list(bucket):
        _pg_rollback(conn)
    _REQUEST_PG_CONNS.set([])


def _pg_close_cursor(cur) -> None:
    if cur is None:
        return
    try:
        cur.close()
    except Exception:
        pass


def pg_fetchone(conn, sql: str, params: tuple | list = ()) -> Any:
    """Einzelzeile — bei Fehler sofort rollback(), Cursor wird geschlossen."""
    cur = None
    try:
        cur = conn.cursor()
        cur.execute(sql, params)
        return cur.fetchone()
    except Exception:
        _pg_rollback(conn)
        raise
    finally:
        _pg_close_cursor(cur)


def pg_fetchall(conn, sql: str, params: tuple | list = ()) -> list[Any]:
    cur = None
    try:
        cur = conn.cursor()
        cur.execute(sql, params)
        return cur.fetchall()
    except Exception:
        _pg_rollback(conn)
        raise
    finally:
        _pg_close_cursor(cur)


def pg_execute(conn, sql: str, params: tuple | list = (), *, commit: bool = False) -> int:
    """SQL ausführen — bei psycopg2/sonstigem Fehler rollback(), Cursor close."""
    cur = None
    try:
        cur = conn.cursor()
        cur.execute(sql, params)
        n = int(cur.rowcount or 0)
        if commit:
            conn.commit()
        return n
    except Exception:
        _pg_rollback(conn)
        raise
    finally:
        _pg_close_cursor(cur)


def pg_commit(conn) -> None:
    try:
        conn.commit()
    except Exception:
        _pg_rollback(conn)
        raise


def _desktop_bridge_signature(hardware_id: str, ts: int) -> str:
    import hashlib
    import hmac

    hid = (hardware_id or "").strip()[:128]
    payload = f"{hid}:{int(ts)}".encode("utf-8")
    key = DESKTOP_BRIDGE_SECRET.encode("utf-8")
    return hmac.new(key, payload, hashlib.sha256).hexdigest()


def _verify_desktop_bridge(hardware_id: str, ts: int, sig: str) -> bool:
    import hmac

    hid = (hardware_id or "").strip()[:128]
    if not hid or not sig:
        return False
    try:
        ts_i = int(ts)
    except (TypeError, ValueError):
        return False
    if abs(time.time() - ts_i) > 7200:
        return False
    expected = _desktop_bridge_signature(hid, ts_i)
    try:
        return hmac.compare_digest(expected, (sig or "").strip().lower())
    except Exception:
        return False


def _desktop_bridge_hid_from_request(request: Request) -> str:
    qp = request.query_params
    hid = str(qp.get("desktop_hid") or "").strip()[:128]
    ts = qp.get("desktop_ts")
    sig = str(qp.get("desktop_sig") or "").strip()
    if hid and _verify_desktop_bridge(hid, ts, sig):
        return hid[:64]
    return ""


def _license_required_message(lang: str) -> str:
    l = "en" if str(lang or "").lower().startswith("en") else "de"
    if l == "en":
        return (
            "LICENSE REQUIRED: Please enter your 16-character SkyTycoon activation key "
            "(ST-XXXX-XXXX-XXXX)."
        )
    return (
        "LIZENZ ERFORDERLICH: Bitte gib deinen 16-stelligen SkyTycoon "
        "Aktivierungsschlüssel ein (ST-XXXX-XXXX-XXXX)."
    )


def _license_required_json(request: Request | None = None, *, extra: dict[str, Any] | None = None) -> JSONResponse:
    lang = _api_lang_from_request(request) if request is not None else "de"
    payload: dict[str, Any] = {
        "status": "license_required",
        "message": _license_required_message(lang),
        "has_license": 0,
        "license_status": 0,
    }
    if extra:
        payload.update(extra)
    return JSONResponse(payload, status_code=403)


def _email_hwid_has_active_license(email: str, hardware_id: str) -> tuple[bool, str]:
    """
    True wenn für diese E-Mail ein aktivierter ST-Key an die Client-HWID gebunden ist
    (SQLite license_keys + PostgreSQL assigned_licenses/users).
    """
    em = str(email or "").strip().lower()[:200]
    hid = str(hardware_id or "").strip()[:128]
    hid64 = hid[:64]
    if not hid64:
        return False, ""

    def _hw_matches(bound: str) -> bool:
        return _hwid_accounts_match(bound, hid, em)

    if em and "@" in em:
        sconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            row = sconn.execute(
                """
                SELECT license_key, hardware_id, status
                FROM license_keys
                WHERE lower(trim(customer_email)) = ?
                  AND upper(trim(license_key)) LIKE 'ST-%'
                ORDER BY created_ts DESC
                LIMIT 1;
                """,
                (em,),
            ).fetchone()
            if row:
                lk = str(row[0] or "").strip()
                st = str(row[2] or "").strip().lower()
                bound = str(row[1] or "").strip()
                if st in ("activated", "active") and lk and (
                    _hw_matches(bound, hid, em)
                    or _login_placeholder_hardware_for_bonding(hid)
                    or _login_placeholder_hardware_for_bonding(bound)
                ):
                    return True, lk
        finally:
            sconn.close()

    conn = None
    try:
        conn = get_db_connection()
        if em and "@" in em:
            row = pg_fetchone(
                conn,
                """
                SELECT al.license_key, al.hardware_id
                FROM assigned_licenses al
                INNER JOIN users u ON (
                    u.hardware_id = al.hardware_id
                    OR substring(u.hardware_id from 1 for 64) = substring(al.hardware_id from 1 for 64)
                )
                WHERE lower(trim(COALESCE(u.email, ''))) = %s
                  AND al.status = 'activated'
                  AND upper(trim(COALESCE(al.license_key, ''))) LIKE 'ST-%%'
                  AND (
                        al.hardware_id = %s
                        OR substring(al.hardware_id from 1 for 64) = %s
                  )
                LIMIT 1;
                """,
                (em, hid, hid64),
            )
            if row:
                lk = str(
                    row.get("license_key") if isinstance(row, dict) else row[0] or ""
                ).strip()
                bound = str(
                    row.get("hardware_id") if isinstance(row, dict) else row[1] or ""
                ).strip()
                if lk and _hw_matches(bound):
                    return True, lk
        row2 = pg_fetchone(
            conn,
            """
            SELECT license_key FROM assigned_licenses
            WHERE status = 'activated'
              AND upper(trim(COALESCE(license_key, ''))) LIKE 'ST-%%'
              AND (hardware_id = %s OR substring(hardware_id from 1 for 64) = %s)
            LIMIT 1;
            """,
            (hid, hid64),
        )
        if row2:
            lk2 = str(
                row2.get("license_key") if isinstance(row2, dict) else row2[0] or ""
            ).strip()
            if lk2:
                return True, lk2
    except Exception as exc_pg:  # noqa: BLE001
        if conn is not None:
            _pg_rollback(conn)
        _server_log_line(f"[license] email_hwid PG check failed: {exc_pg!s}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return False, ""


def _pg_bind_license_to_hardware(
    email: str,
    hardware_id: str,
    license_key: str,
    pilot_name: str = "",
) -> None:
    """PostgreSQL: Lizenz dauerhaft an HWID + E-Mail koppeln."""
    em = str(email or "").strip().lower()[:200]
    hid = str(hardware_id or "").strip()[:128]
    hid64 = hid[:64]
    lk = str(license_key or "").strip()[:80]
    pilot = str(pilot_name or "").strip()[:120] or hid[:16] or "Pilot"
    if not hid64 or not lk:
        return
    conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO users (hardware_id, username, email, money, credits, license_status)
                VALUES (%s, %s, NULLIF(%s, ''), 0, 0, 'activated')
                ON CONFLICT (hardware_id) DO UPDATE SET
                    email = CASE
                        WHEN COALESCE(users.email, '') = '' AND EXCLUDED.email IS NOT NULL
                        THEN EXCLUDED.email ELSE users.email END,
                    license_status = 'activated',
                    username = CASE
                        WHEN users.username = '' OR users.username = 'Pilot'
                        THEN EXCLUDED.username ELSE users.username END;
                """,
                (hid64, pilot, em),
            )
            cur.execute(
                """
                INSERT INTO assigned_licenses (
                    license_key, hardware_id, target_user, license_type,
                    module_key, status, assigned_by, created_ts
                ) VALUES (%s, %s, %s, 'lifetime', 'core', 'activated', 'desktop_activate', %s)
                ON CONFLICT (license_key) DO UPDATE SET
                    hardware_id = EXCLUDED.hardware_id,
                    target_user = EXCLUDED.target_user,
                    status = 'activated';
                """,
                (lk, hid, pilot, time.time()),
            )
        pg_commit(conn)
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[license] PG bind failed: {exc_pg!s}")
    finally:
        conn.close()


def _shop_license_placeholder_hid(email: str) -> str:
    em = (email or "").strip().lower()
    return f"shop-{hashlib.sha256(em.encode('utf-8')).hexdigest()[:24]}"


def _pg_bind_license_to_email_account(
    email: str,
    license_key: str,
    pilot_name: str = "",
    hardware_id: str = "",
    *,
    license_row_status: str = "unused",
    selected_language: str = "",
) -> None:
    """PostgreSQL: ST-Key sofort an E-Mail (+ optional HWID) koppeln und committen."""
    em = str(email or "").strip().lower()[:200]
    lk = str(license_key or "").strip()[:80]
    pilot = str(pilot_name or "").strip()[:120]
    if not em or "@" not in em or not lk:
        return
    hid = str(hardware_id or "").strip()[:128] or _shop_license_placeholder_hid(em)
    hid64 = hid[:64]
    ls_user = "activated" if license_row_status == "activated" else "purchased"
    ls_al = "activated" if license_row_status == "activated" else "unused"
    lang = (selected_language or "de").strip().lower()[:8]
    if lang not in ("de", "en"):
        lang = "de"
    conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO users (
                    hardware_id, username, email, money, credits,
                    license_status, selected_language
                ) VALUES (%s, %s, %s, 0, 0, %s, %s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    email = CASE
                        WHEN COALESCE(users.email, '') = '' AND EXCLUDED.email IS NOT NULL
                        THEN EXCLUDED.email ELSE users.email END,
                    username = CASE
                        WHEN users.username = '' OR users.username = 'Pilot'
                        THEN EXCLUDED.username ELSE users.username END,
                    license_status = EXCLUDED.license_status,
                    selected_language = COALESCE(
                        NULLIF(EXCLUDED.selected_language, ''), users.selected_language
                    );
                """,
                (hid64, pilot or em.split("@", 1)[0][:120], em, ls_user, lang),
            )
            cur.execute(
                """
                INSERT INTO assigned_licenses (
                    license_key, hardware_id, target_user, license_type,
                    module_key, status, assigned_by, created_ts
                ) VALUES (%s, %s, %s, 'lifetime', 'core', %s, 'purchase_autopilot', %s)
                ON CONFLICT (license_key) DO UPDATE SET
                    hardware_id = EXCLUDED.hardware_id,
                    target_user = EXCLUDED.target_user,
                    status = EXCLUDED.status;
                """,
                (lk, hid, pilot or em.split("@", 1)[0][:120], ls_al, time.time()),
            )
        pg_commit(conn)
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[autopilot] PG email bind failed: {exc_pg!s}")
    finally:
        conn.close()


def _paypal_pg_mark_account_active(
    email: str, license_key: str, pilot_name: str = ""
) -> None:
    """PayPal-Capture: PostgreSQL sofort aktiv (is_active / license_status)."""
    em = str(email or "").strip().lower()[:200]
    lk = str(license_key or "").strip()[:80]
    pilot = str(pilot_name or "").strip()[:120] or em.split("@", 1)[0][:120]
    if not em or "@" not in em or not lk:
        return
    hid = _shop_license_placeholder_hid(em)
    conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO users (
                    hardware_id, username, email, money, credits,
                    license_status, selected_language
                ) VALUES (%s, %s, %s, 0, 0, 'purchased', 'de')
                ON CONFLICT (hardware_id) DO UPDATE SET
                    email = EXCLUDED.email,
                    username = CASE
                        WHEN users.username = '' OR users.username = 'Pilot'
                        THEN EXCLUDED.username ELSE users.username END,
                    license_status = 'purchased';
                """,
                (hid[:64], pilot, em),
            )
            cur.execute(
                """
                INSERT INTO assigned_licenses (
                    license_key, hardware_id, target_user, license_type,
                    module_key, status, assigned_by, created_ts
                ) VALUES (%s, %s, %s, 'lifetime', 'core', 'purchased', 'paypal_capture', %s)
                ON CONFLICT (license_key) DO UPDATE SET
                    status = 'purchased',
                    target_user = EXCLUDED.target_user;
                """,
                (lk, hid, pilot, time.time()),
            )
        pg_commit(conn)
    except Exception as exc_act:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[paypal] instant PG activate: {exc_act!s}")
    finally:
        conn.close()


