def _load_env_file_into_osenviron(path: Path, *, key_prefix: str | None = None) -> None:
    """Lädt KEY=value aus einer .env-Datei (setzt nur leere/fehlende os.environ-Keys)."""
    if not path.is_file():
        return
    try:
        raw = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return
    for line in raw.splitlines():
        s = line.strip()
        if not s or s.startswith("#") or "=" not in s:
            continue
        key, _, val = s.partition("=")
        key = key.strip()
        if not key:
            continue
        if key_prefix and not key.startswith(key_prefix):
            continue
        if (os.environ.get(key) or "").strip():
            continue
        v = val.strip().strip('"').strip("'")
        if v:
            os.environ[key] = v


