def _discord_oauth_configured() -> bool:
    cid = _discord_oauth_client_id()
    secret = _discord_oauth_client_secret()
    if not cid or not secret:
        return False
    if "DEIN_KOPIERTES" in secret or "HIER_DEINE" in secret:
        return False
    return True


def _discord_oauth_redirect_uri() -> str:
    """Immer HTTPS-Produktions-Origin — ignoriert http/localhost/env-Overrides."""
    for env_key in ("SKYTYCOON_DISCORD_REDIRECT_URI", "DISCORD_REDIRECT_URI", "SKYTYCOON_PUBLIC_URL", "SKYTYCOON_PUBLIC_BASE_URL"):
        raw = (os.environ.get(env_key) or "").strip()
        if not raw:
            continue
        low = raw.lower()
        if any(tok in low for tok in ("localhost", "127.0.0.1", "http://", ":8000", ":3000")):
            _server_log_line(f"[discord] ignored unsafe {env_key}={raw!r}")
            continue
        if low.startswith("https://skytycoon.info"):
            return raw.split("?")[0].rstrip("/")
    return DISCORD_OAUTH_HTTPS_ORIGIN


def _public_origin() -> str:
    return DISCORD_OAUTH_HTTPS_ORIGIN

