def _web_lang(request: Request) -> str:
    v = (request.cookies.get(WEB_LANG_COOKIE) or "de").lower()
    return "en" if v.startswith("en") else "de"


def _api_lang_from_request(request: Request | None, body: dict | None = None) -> str:
    """M197: Sprache für JSON-API-Fehler (Accept-Language, Profil, Cookie)."""
    if request is not None:
        al = (request.headers.get("accept-language") or "").strip().lower()
        if al.startswith("en"):
            return "en"
        if al.startswith("de"):
            return "de"
        for part in al.split(","):
            p = part.strip().split(";")[0]
            if p.startswith("en"):
                return "en"
            if p.startswith("de"):
                return "de"
    if isinstance(body, dict):
        ul = str(body.get("ui_lang", body.get("app_language", "")) or "").lower()
        if ul.startswith("en"):
            return "en"
        if ul.startswith("de"):
            return "de"
    if request is not None:
        return _web_lang(request)
    return "de"


