def _api_msg(
    request: Request | None,
    key: str,
    *,
    body: dict | None = None,
    default_de: str = "",
) -> str:
    lang = _api_lang_from_request(request, body)
    bucket = WEB_I18N_POOL.get(lang) or WEB_I18N_POOL["de"]
    return bucket.get(key) or WEB_I18N_POOL["de"].get(key) or default_de or key


def _web_tx(lang: str, key: str) -> str:
    tab = WEB_UI.get(lang) or WEB_UI["de"]
    return tab.get(key) or WEB_UI["de"].get(key) or key


def _safe_next(raw: str | None, default: str = "/") -> str:
    p = (raw or default).strip() or default
    if not p.startswith("/") or p.startswith("//"):
        return default
    return p[:300]


# -----------------------------------------------------------------------------
# SMTP (IONOS & Co.): echte Zugangsdaten per Umgebungsvariable — nicht im Quelltext hardcoden.
# Beispiel IONOS (Ausgangsserver):
#   SKYTYCOON_SMTP_HOST=smtp.ionos.de
#   SKYTYCOON_SMTP_PORT=587
#   SKYTYCOON_SMTP_USER=info@skytycoon.info
#   SKYTYCOON_SMTP_PASSWORD=…
#   SKYTYCOON_SMTP_FROM=info@skytycoon.info   (optional, sonst = USER)
# -----------------------------------------------------------------------------

def _refresh_smtp_env() -> None:
    """smtp.env erneut einlesen (systemd + Hotfix-Deploy)."""
    _load_env_file_into_osenviron(APP_ROOT / "smtp.env")


def _public_contact_email() -> str:
    """Öffentliche Kontaktadresse — nur aus ENV, keine Hardcodes."""
    return (
        os.environ.get("SKYTYCOON_CONTACT_EMAIL")
        or os.environ.get("SKYTYCOON_SMTP_FROM")
        or os.environ.get("SKYTYCOON_SMTP_USER")
        or "support@skytycoon.local"
    ).strip()


def _smtp_settings() -> tuple[str, int, str, str, str]:
    _refresh_smtp_env()
    host = (os.environ.get("SKYTYCOON_SMTP_HOST") or "smtp.ionos.de").strip()
    port = int(os.environ.get("SKYTYCOON_SMTP_PORT") or "587")
    user = (os.environ.get("SKYTYCOON_SMTP_USER") or "").strip()
    password = (os.environ.get("SKYTYCOON_SMTP_PASSWORD") or "").strip()
    mail_from = (
        os.environ.get("SKYTYCOON_SMTP_FROM") or user or "noreply@skytycoon.local"
    ).strip()
    return host, port, user, password, mail_from


SMTP_HOST = (os.environ.get("SKYTYCOON_SMTP_HOST") or "smtp.ionos.de").strip()
SMTP_PORT = int(os.environ.get("SKYTYCOON_SMTP_PORT") or "587")
SMTP_USER = (os.environ.get("SKYTYCOON_SMTP_USER") or "").strip()
