def _sky_api_error_message(lang: str, detail: Any) -> str:
    l = "en" if str(lang or "").lower().startswith("en") else "de"
    code = str(detail or "generic").strip()[:80]
    key = _SKY_DETAIL_ALIASES.get(code, code)
    return _SKY_API_ERROR_I18N.get(l, _SKY_API_ERROR_I18N["de"]).get(
        key, _SKY_API_ERROR_I18N[l]["generic"]
    )


def _sky_wants_json(request: Request) -> bool:
    path = request.url.path or ""
    if path.startswith("/api/"):
        return True
    accept = (request.headers.get("accept") or "").lower()
    if "application/json" in accept:
        return True
    if request.headers.get("x-requested-with", "").lower() == "xmlhttprequest":
        return True
    return False


def _sky_json_error_response(
    request: Request,
    detail: Any = "generic",
    *,
    status_code: int = 503,
    extra: dict[str, Any] | None = None,
) -> JSONResponse:
    lang = _web_lang(request)
    payload: dict[str, Any] = {
        "status": "error",
        "message": _sky_api_error_message(lang, detail),
        "code": str(detail or "generic")[:80],
    }
    if extra:
        payload.update(extra)
    code = int(status_code)
    if code >= 500:
        code = 503
    return JSONResponse(payload, status_code=code)


def _sky_html_error_response(request: Request, detail: Any = "generic") -> Response:
    lang = _web_lang(request)
    msg = _sky_api_error_message(lang, detail)
    path = (request.url.path or "").lower()
    if path in ("/login", "/register") or path.startswith("/login"):
        try:
            return _web_page_html("login.html", request, error=msg)
        except Exception:
            pass
    if path.startswith("/dashboard"):
        return RedirectResponse(
            "/login?err=server", status_code=http_status.HTTP_303_SEE_OTHER
        )
    return HTMLResponse(
        f"<body style='background:#070a0e;color:#e3e7ed;font-family:Segoe UI;padding:32px'>"
        f"<h2 style='color:#d4af37'>SkyTycoon</h2><p>{html.escape(msg)}</p>"
        f"<p><a style='color:#d4af37' href='/login'>Login</a></p></body>",
        status_code=200,
    )


def _sky_http_exception_to_response(request: Request, exc: HTTPException) -> Response:
    status = int(exc.status_code or 400)
    detail = exc.detail
    if status >= 500:
        _server_log_line(
            f"[shield] HTTP {status} {request.method} {request.url.path}: {detail!r}"
        )
        status = 503
        detail = detail or "server_busy"
    if _sky_wants_json(request):
        return _sky_json_error_response(request, detail, status_code=status)
    if status in (401, 403):
        return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
    return _sky_html_error_response(request, detail)


@app.exception_handler(HTTPException)
async def _sky_global_http_exception_handler(
    request: Request, exc: HTTPException
) -> Response:
    _pg_rollback_safeguard_request()
    return _sky_http_exception_to_response(request, exc)


@app.exception_handler(Exception)
async def _sky_global_exception_handler(request: Request, exc: Exception) -> Response:
    _pg_rollback_safeguard_request()
    _server_log_line(
        f"[shield] unhandled {request.method} {request.url.path}: {type(exc).__name__}: {exc!r}"
    )
    path = (request.url.path or "").lower()
    if path in ("/login", "/register") or path.startswith("/login"):
        lang = _web_lang(request)
        try:
            msg = (
                "Ihr Konto wurde gelöscht oder existiert nicht. "
                "Bitte neu registrieren oder mit gültigen Zugangsdaten anmelden."
                if lang == "de"
                else "Your account was deleted or does not exist. "
                "Please register again or sign in with valid credentials."
            )
            resp = _web_page_html("login.html", request, error=msg)
            _web_clear_session_cookies(resp)
            return resp
        except Exception:
            pass
    if _sky_wants_json(request):
        return _sky_json_error_response(request, "generic", status_code=503)
    return _sky_html_error_response(request, "generic")


try:
    from fastapi.exceptions import RequestValidationError as _RequestValidationError
except ImportError:
    _RequestValidationError = None  # type: ignore[misc, assignment]

if _RequestValidationError is not None:

    @app.exception_handler(_RequestValidationError)
    async def _sky_json_request_guard(
        request: Request, exc: _RequestValidationError
    ) -> JSONResponse:
        """Einheitliche JSON-Fehler bei kaputten API-Bodies (z. B. Desktop-Login)."""
        _pg_rollback_safeguard_request()
        errs = exc.errors()
        if any(e.get("type") == "json_invalid" for e in errs):
            return JSONResponse(
                {"status": "error", "message": "invalid JSON", "code": "json_invalid"},
                status_code=400,
            )
        lang = _web_lang(request)
        msg = _sky_api_error_message(lang, "bad_input")
        return JSONResponse(
            {"status": "error", "message": msg, "code": "validation_error", "detail": errs},
            status_code=422,
        )


