def _regenerate_cloud_scrapyard_market(min_count: int = 260) -> int:
    """M189: Mega-Markt — ≥260 Teile (USED_SCRAPYARD 30–85 % + NEW_PART 100 %)."""
    _ensure_mmo_economy_tables()
    rng = random.Random(int(time.time()) // 43_200)
    target = max(260, int(min_count))
    rows: list[tuple[str, str, float, float]] = []
    while len(rows) < target:
        ac = rng.choice(SCRAPYARD_AIRCRAFT_TYPES)
        part_base = rng.choice(SCRAPYARD_PART_NAMES)
        part_full_name = f"{ac} - {part_base}"
        is_new = rng.choice((True, False))
        if is_new:
            condition = 100.0
            price = float(rng.randint(15_000, 75_000))
            p_type = "NEW_PART"
        else:
            condition = round(rng.uniform(30.0, 85.0), 1)
            price = float(rng.randint(3_500, 14_500))
            p_type = "USED_SCRAPYARD"
        rows.append((p_type, part_full_name, condition, price))
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            DELETE FROM cloud_scrapyard
            WHERE buyer_hw_id IS NULL
              AND (seller_hw_id IS NULL OR trim(seller_hw_id) = '');
            """
        )
        conn.executemany(
            """
            INSERT INTO cloud_scrapyard (part_type, part_name, condition, price, seller_hw_id)
            VALUES (?, ?, ?, ?, NULL);
            """,
            rows,
        )
        conn.commit()
        return len(rows)
    finally:
        conn.close()


async def _cloud_scrapyard_rotation_loop() -> None:
    """Alle 12 Stunden: Schrottplatz-Mega-Refresh."""
    while True:
        await asyncio.sleep(12 * 3600)
        try:
            n = await asyncio.to_thread(_regenerate_cloud_scrapyard_market, 260)
            _server_log_line(f"[scrapyard] 12h rotation: {n} Teile.")
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[scrapyard] rotation failed: {exc!s}")


class AcarsChatConnectionManager:
    """Live-ACARS-Funk (WebSocket) ohne Verbindungs-Leak."""

    def __init__(self) -> None:
        self.active_connections: list[WebSocket] = []
        self.chat_history: list[dict[str, Any]] = []

    async def connect(self, websocket: WebSocket) -> None:
        await websocket.accept()
        self.active_connections.append(websocket)
        for msg in self.chat_history[-30:]:
            try:
                await websocket.send_json(msg)
            except Exception:  # noqa: BLE001
                break

    def disconnect(self, websocket: WebSocket) -> None:
        try:
            self.active_connections.remove(websocket)
        except ValueError:
            pass

    async def broadcast_message(self, message: dict[str, Any]) -> None:
        self.chat_history.append(message)
        if len(self.chat_history) > 100:
            self.chat_history = self.chat_history[-100:]
        dead: list[WebSocket] = []
        for connection in list(self.active_connections):
            try:
                await connection.send_json(message)
            except Exception:  # noqa: BLE001
                dead.append(connection)
        for ws in dead:
            self.disconnect(ws)


ACARS_CHAT_MANAGER = AcarsChatConnectionManager()


