def _pw_hash(pw: str, salt: str) -> str:
    raw = f"{salt}|{pw}".encode("utf-8", errors="replace")
    return hashlib.sha256(raw).hexdigest()


def _password_hash_store(pw: str) -> tuple[str, str]:
    """(salt_or_marker, hash) für ``license_keys``."""
    if _PWD_CTX is not None:
        try:
            return ("bcrypt", _PWD_CTX.hash(pw))
        except Exception:  # noqa: BLE001 — u.a. passlib+bcrypt>=4.1 („72 bytes“)
            pass
    s = secrets.token_hex(8)
    return (s, _pw_hash(pw, s))


def _password_verify_db(salt: str, stored_hash: str, pw: str) -> bool:
    s = (salt or "").strip()
    h = stored_hash or ""
    if s.lower() == "bcrypt" or h.startswith("$2"):
        if _PWD_CTX is None:
            return False
        try:
            return bool(_PWD_CTX.verify(pw, h))
        except Exception:  # noqa: BLE001
            return False
    return _pw_hash(pw, s) == h


def _parse_iso_timestamp_utc(raw: str) -> datetime | None:
    """ISO-Zeitstempel (z. B. ``last_hardware_reset``) → aware UTC oder ``None``."""
    s = (raw or "").strip()
    if not s:
        return None
    try:
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except (TypeError, ValueError):
        return None


def _login_placeholder_hardware_for_bonding(stored_hw: str) -> bool:
    """
    True, wenn die in ``license_keys`` hinterlegte ID eine Web-/Platzhalter-ID ist
    und beim ersten Desktop-Login durch die echte PC-UUID ersetzt werden darf.
    """
    h = (stored_hw or "").strip()
    if not h:
        return True
    low = h.lower()
    if low.startswith("web_") or low.startswith("web-"):
        return True
    if low.startswith("portal_") or low.startswith("portal-"):
        return True
    if low.startswith("pending_") or low.startswith("pending-"):
        return True
    if low.startswith("prod_mobile_push_token"):
        return True
    if low in {"null", "none", "undefined", "web", "website", "mobile"}:
        return True
    return False


def _web_issue_token(hid: str) -> str:
    if jose_jwt is not None and JWT_SECRET:
        exp = int(time.time()) + WEB_SESSION_MAX_AGE_SEC
        return str(
            jose_jwt.encode({"sub": hid, "exp": exp}, JWT_SECRET, algorithm=JWT_ALG)
        )
    return _session_sign(hid)


def _web_raw_session_cookie(request: Request) -> str | None:
    """Primär skytycoon_session; Fallback access_token / skytycoon_web_session."""
    raw = request.cookies.get(WEB_COOKIE_NAME)
    if raw:
        return raw
    for legacy_key in WEB_COOKIE_LEGACY_READ:
        raw = request.cookies.get(legacy_key)
        if raw:
            return raw
    return None


def _web_session_hid(request: Request) -> str | None:
    """Hardware-ID aus HTTP-Only Session-Cookie (OAuth2 + Dashboard)."""
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if hid:
        return hid[:128]
    return _web_token_from_request(request)


def _web_https_request(request: Request) -> bool:
    if request.url.scheme == "https":
        return True
    return (request.headers.get("x-forwarded-proto") or "").lower() == "https"


def _web_set_session_cookie(response: Response, token: str, request: Request) -> None:
    """30d HTTP-Only Secure Session — SameSite=lax für OAuth2-Redirects."""
    secure = _web_https_request(request)
    host = (request.headers.get("host") or "").lower()
    if "skytycoon.info" in host:
        secure = True
    response.set_cookie(
        key=WEB_COOKIE_NAME,
        value=token,
        max_age=WEB_SESSION_COOKIE_MAX_AGE_SEC,
        path="/",
        httponly=True,
        secure=secure,
        samesite="lax",
    )


def _web_clear_session_cookies(response: Response) -> None:
    """Logout — alle Session-Cookie-Varianten löschen."""
    for key in (WEB_COOKIE_NAME, *WEB_COOKIE_LEGACY_READ, WEB_COOKIE_LEGACY_NAME):
        response.delete_cookie(key=key, path="/")


def _pg_new_account_starter_credits() -> float:
    try:
        return float(os.environ.get("SKYTYCOON_STARTER_CREDITS", "50000") or "50000")
    except (TypeError, ValueError):
        return 50_000.0


def _desktop_stale_pilot_aliases() -> frozenset[str]:
    return frozenset(
        x.strip().lower()[:200]
        for x in (os.environ.get("SKYTYCOON_STALE_PILOT_ALIASES") or "")
        .replace(";", ",")
        .split(",")
        if x.strip()
    )


def _sanitize_desktop_api_str(val: Any, *, max_len: int = 200) -> str:
    """Control-Zeichen / JSON-Trümmer entfernen — sterile API-Strings."""
    if val is None or isinstance(val, (dict, list, tuple, bytes, bytearray)):
        return ""
    s = str(val)
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "\"'":
        s = s[1:-1].strip()
    s = "".join(ch for ch in s if ord(ch) >= 32 or ch in "\t")
    return s.strip()[:max_len]


async def _parse_desktop_api_json_body(request: Request) -> dict[str, Any] | JSONResponse:
    """JSON, Form oder Roh-Body — verhindert Desktop-Deadlocks bei kaputtem Content-Type."""
    ct = (request.headers.get("content-type") or "").lower()
    try:
        if "application/json" in ct:
            data = await request.json()
            return data if isinstance(data, dict) else {}
        if "application/x-www-form-urlencoded" in ct or "multipart/form-data" in ct:
            form = await request.form()
            return {k: form.get(k) for k in form.keys()}
        raw = await request.body()
        if not raw or not raw.strip():
            return {}
        return json.loads(raw.decode("utf-8", errors="replace"))
    except json.JSONDecodeError:
        return JSONResponse(
            {"status": "error", "error": "invalid JSON", "code": "json_invalid"},
            status_code=400,
        )
    except Exception:
        return JSONResponse(
            {"status": "error", "error": "invalid JSON", "code": "json_invalid"},
            status_code=400,
        )


def _sanitize_profile_cloud_sync_body(body: dict[str, Any]) -> dict[str, Any]:
    """cloud_sync: nur sterile Felder — kein verschachteltes Müll-JSON."""
    clean = dict(body) if isinstance(body, dict) else {}
    pc_hid = _sanitize_desktop_api_str(
        clean.get("pc_hardware_id")
        or clean.get("incoming_pc_hardware_id")
        or clean.get("hardware_id"),
        max_len=128,
    )
    pilot = _sanitize_desktop_api_str(
        clean.get("username") or clean.get("pilot_name"), max_len=120
    )
    pw = _sanitize_desktop_api_str(clean.get("password"), max_len=256)
    em = _sanitize_desktop_api_str(
        clean.get("email")
        or clean.get("portal_email")
        or clean.get("customer_email"),
        max_len=200,
    ).lower()
    lk = _sanitize_desktop_api_str(clean.get("license_key"), max_len=256)
    out: dict[str, Any] = {
        "pc_hardware_id": pc_hid,
        "incoming_pc_hardware_id": pc_hid,
        "hardware_id": pc_hid,
        "username": pilot,
        "pilot_name": pilot,
        "password": pw,
        "email": em,
        "portal_email": em,
        "license_key": lk,
    }
    for lang_k in ("selected_language", "ui_lang"):
        lg = _sanitize_desktop_api_str(clean.get(lang_k), max_len=8).lower()
        if lg in ("de", "en"):
            out[lang_k] = lg
    if clean.get("pull_only"):
        out["pull_only"] = True
    return out


def _purge_desktop_server_session_ram(
    pc_hardware_id: str, email: str = "", pilot_name: str = ""
) -> None:
    """Gleicher PC, neuer Pilot: alte Session-Reste aus RAM/DB löschen."""
    pc = str(pc_hardware_id or "").strip()[:128]
    em = str(email or "").strip().lower()[:200]
    pilot = str(pilot_name or "").strip()[:120]
    pilot_l = pilot.lower()
    em_l = em.lower() if em else ""
    active_tokens = {pilot_l, em_l, em_l.split("@", 1)[0] if "@" in em_l else ""}
    active_tokens.discard("")
    for stale in _desktop_stale_pilot_aliases():
        if stale in active_tokens:
            continue
        stale_pilot = stale.split("@", 1)[0] if "@" in stale else stale
        if pc:
            _pg_radar_purge_pilot(pc, stale_pilot)
            if len(pc) > 16:
                _pg_radar_purge_pilot(pc[:64], stale_pilot)
        _server_kv_delete(f"desktop_session:{pc[:64]}:{stale_pilot}")
        _server_kv_delete(f"msfs_command:{stale_pilot[:64]}")
    if pc:
        _server_kv_delete(f"desktop_session:{pc[:64]}:active")
        _server_kv_delete(f"flight_arrived:{pc[:64]}")


def _account_canonical_hardware_id(
    pc_hardware_id: str, email: str = "", pilot_name: str = ""
) -> tuple[str, str]:
    """Eindeutiger PostgreSQL-Schlüssel pro E-Mail (kein Daten-Bleed auf gleichem PC)."""
    pc = str(pc_hardware_id or "").strip()[:128]
    em = str(email or "").strip().lower()[:200]
    if em and "@" in em:
        digest = hashlib.sha256(em.encode("utf-8")).hexdigest()[:22]
        base = pc[:64] if pc else digest[:16]
        canon = f"{base}__{digest}"[:128]
        return canon, pc or base
    return (pc or "")[:128], pc


def _desktop_atomic_pc_hardware_id(raw: str) -> str:
    """PC-HWID 1:1 vom Client (Mainboard-UUID/MAC, max 128) — keine Kürzung."""
    hid = str(raw or "").strip()
    if len(hid) >= 2 and hid[0] == hid[-1] and hid[0] in "\"'":
        hid = hid[1:-1].strip()
    return hid[:128]


def _web_display_hardware_id(stored_hid: str, pc_hint: str = "") -> str:
    """Öffentliche Web-ID = Desktop-PC-UUID (Basis vor E-Mail-Suffix)."""
    pc = _desktop_atomic_pc_hardware_id(pc_hint)
    if pc:
        return pc
    s = _desktop_atomic_pc_hardware_id(stored_hid)
    if "__" in s:
        base = s.split("__", 1)[0].strip()
        if base:
            return base[:128]
    return s


def _api_hardware_id_symmetry(
    pc_hid: str, email: str = "", pilot_name: str = ""
) -> dict[str, str]:
    """Atomare ID-Felder: Web, Desktop und Roster zeigen dieselbe PC-HWID."""
    pc = _desktop_atomic_pc_hardware_id(pc_hid)
    canon, _raw = _account_canonical_hardware_id(pc, email, pilot_name)
    web_id = _web_display_hardware_id(canon, pc)
    primary = (canon or web_id)[:128]
    return {
        "hardware_id": primary,
        "pc_hardware_id": web_id[:128],
        "incoming_pc_hardware_id": web_id[:128],
        "web_id": web_id[:128],
    }


def _hwid_accounts_match(
    stored_hw: str, incoming_hw: str, email: str = ""
) -> bool:
    """
    True wenn gespeicherte und aktuelle PC-HWID dieselbe Identität meinen
    (inkl. kanonisch ``pc__emailhash`` vs. rohe Windows-UUID).
    """
    s = str(stored_hw or "").strip()[:128]
    i = str(incoming_hw or "").strip()[:128]
    if not s or not i:
        return not bool(s) and not bool(i)
    if s == i or s[:64] == i[:64]:
        return True
    if _login_placeholder_hardware_for_bonding(s) or _login_placeholder_hardware_for_bonding(i):
        return True
    em = str(email or "").strip().lower()[:200]
    if em and "@" in em:
        canon_in, _pc = _account_canonical_hardware_id(i, em, "")
        if canon_in and (s == canon_in or s[:64] == canon_in[:64]):
            return True
        canon_st, _pc2 = _account_canonical_hardware_id(s, em, "")
        if canon_st and (i == canon_st or i[:64] == canon_st[:64]):
            return True
    if "__" in s:
        base = s.split("__", 1)[0].strip()[:64]
        if base and (base == i[:64] or i.startswith(base)):
            return True
    if "__" in i:
        base = i.split("__", 1)[0].strip()[:64]
        if base and (base == s[:64] or s.startswith(base)):
            return True
    return False


def _pg_apply_new_account_starter_autopilot(
    canonical_hid: str,
    email: str = "",
    pilot_name: str = "",
    *,
    conn: Any | None = None,
) -> None:
    """Frische Konten: exakt 50.000 CR, XP 0 — transaktional mit rollback."""
    canon = str(canonical_hid or "").strip()[:128]
    em = str(email or "").strip().lower()[:200]
    pilot = str(pilot_name or "").strip()[:160] or "Pilot"
    if not canon:
        return
    own_conn = conn is None
    if own_conn:
        conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            if em and "@" in em:
                cur.execute(
                    """
                    SELECT COALESCE(credits, 0) + COALESCE(money, 0) AS cred,
                           COALESCE(xp, 0) AS xp,
                           COALESCE(username, '') AS uname,
                           hardware_id
                    FROM users
                    WHERE lower(trim(email)) = %s
                    LIMIT 1 FOR UPDATE;
                    """,
                    (em,),
                )
            else:
                cur.execute(
                    """
                    SELECT COALESCE(credits, 0) + COALESCE(money, 0),
                           COALESCE(xp, 0),
                           COALESCE(username, ''),
                           hardware_id
                    FROM users
                    WHERE hardware_id = %s
                    LIMIT 1 FOR UPDATE;
                    """,
                    (canon,),
                )
            row = cur.fetchone()
            if not row:
                cur.execute(
                    """
                    INSERT INTO users (
                        hardware_id, username, email, money, credits, xp, license_status
                    ) VALUES (%s, %s, NULLIF(%s, ''), %s, %s, 0, 'portal_free')
                    ON CONFLICT (hardware_id) DO NOTHING;
                    """,
                    (
                        canon,
                        pilot,
                        em,
                        _pg_new_account_starter_credits(),
                        _pg_new_account_starter_credits(),
                    ),
                )
                conn.commit()
                if own_conn:
                    pg_commit(conn)
                return
            cred = float(row[0] or 0)
            xp = float(row[1] or 0)
            uname = str(row[2] or "").strip()
            hid_row = str(row[3] or canon).strip()[:128]
            cur.execute(
                """
                SELECT COUNT(*)::int FROM fleet
                WHERE owner_username = %s
                   OR lower(trim(owner_username)) = lower(trim(%s))
                   OR owner_username = %s;
                """,
                (hid_row, uname or pilot, canon),
            )
            fleet_n = int((cur.fetchone() or (0,))[0] or 0)
            if cred < 1.0 and xp < 1.0 and fleet_n == 0:
                if em and "@" in em:
                    cur.execute(
                        """
                        UPDATE users
                        SET credits = %s, money = %s, xp = 0
                        WHERE lower(trim(email)) = %s;
                        """,
                        (_pg_new_account_starter_credits(), _pg_new_account_starter_credits(), em),
                    )
                else:
                    cur.execute(
                        """
                        UPDATE users
                        SET credits = %s, money = %s, xp = 0
                        WHERE hardware_id = %s;
                        """,
                        (
                            _pg_new_account_starter_credits(),
                            _pg_new_account_starter_credits(),
                            canon,
                        ),
                    )
        conn.commit()
        if own_conn:
            pg_commit(conn)
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[PG starter] autopilot failed: {exc_pg!s}")
    finally:
        if own_conn:
            conn.close()


def _pg_desktop_session_isolate_and_sync(
    pc_hardware_id: str,
    email: str,
    pilot_name: str,
    *,
    license_active: bool = True,
) -> str:
    """Login/cloud_sync: alte Session-Identität verwerfen, Konto strikt an E-Mail binden."""
    pc = str(pc_hardware_id or "").strip()[:128]
    em = str(email or "").strip().lower()[:200]
    pilot = str(pilot_name or "").strip()[:160] or (
        em.split("@", 1)[0][:120] if em and "@" in em else "Pilot"
    )
    canon, _pc = _account_canonical_hardware_id(pc, em, pilot)
    if not canon:
        return ""
    _purge_desktop_server_session_ram(pc, em, pilot)
    conn = get_db_connection()
    try:
        _web_postgres_sync_login_profile(
            canon,
            email=em,
            pilot_name=pilot,
            license_active=license_active,
            conn=conn,
        )
        _pg_apply_new_account_starter_autopilot(canon, em, pilot, conn=conn)
        conn.commit()
        pg_commit(conn)
    except Exception as exc_iso:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[PG session] isolate failed: {exc_iso!s}")
    finally:
        conn.close()
    return canon


def _desktop_api_json_response(payload: dict[str, Any]) -> JSONResponse:
    """Desktop-API: Session-Cookies vor neuer Antwort radikal löschen."""
    resp = JSONResponse(payload)
    _web_clear_session_cookies(resp)
    return resp


def _web_parse_token(raw: str | None) -> str | None:
    if not raw:
        return None
    if jose_jwt is not None and JWT_SECRET:
        try:
            payload = jose_jwt.decode(raw, JWT_SECRET, algorithms=[JWT_ALG])
            return str(payload.get("sub", "")).strip()[:128] or None
        except JWTError:
            return None
    return _session_parse(raw)


def _web_token_from_request(request: Request) -> str | None:
    """Cookie, MSFS iframe query (?efb_token=), or Authorization: Bearer."""
    cookie = _web_parse_token(_web_raw_session_cookie(request))
    if cookie:
        return cookie
    auth = (request.headers.get("Authorization") or "").strip()
    if auth.lower().startswith("bearer "):
        bearer = _web_parse_token(auth[7:].strip())
        if bearer:
            return bearer
    for key in ("efb_token", "access_token", "token"):
        raw_q = request.query_params.get(key)
        if raw_q:
            parsed = _web_parse_token(str(raw_q))
            if parsed:
                return parsed
    auth = (request.headers.get("Authorization") or "").strip()
    if auth.lower().startswith("bearer "):
        return _web_parse_token(auth[7:].strip())
    return None


def _web_postgres_user_is_stub(
    username: str, hardware_id: str, credits: float | None, money: float | None
) -> bool:
    """Dashboard auto-inserts used hid[:16] as username with zero balance — not a real account."""
    hid = str(hardware_id or "").strip()
    if not hid:
        return False
    cred = float(credits or 0) + float(money or 0)
    if cred > 0.01:
        return False
    un = str(username or "").strip()
    if not un or un == "Pilot":
        return True
    return un == hid[:16]


def _web_resolve_postgres_hardware_id(
    email: str = "", sqlite_hid: str = "", pilot_name: str = ""
) -> str:
    """Map SQLite login / JWT hardware_id to the canonical PostgreSQL account."""
    email_c = str(email or "").strip().lower()[:200]
    cand = str(sqlite_hid or "").strip()[:128]
    try:
        conn = get_db_connection()
    except Exception as exc_pg:
        _server_log_line(f"[web] resolve_postgres_hid connect failed: {exc_pg!s}")
        if email_c and "@" in email_c and cand:
            canon, _pc = _account_canonical_hardware_id(cand, email_c, pilot_name)
            return canon
        return cand
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            if email_c and "@" in email_c:
                try:
                    cur.execute(
                        """
                        SELECT hardware_id, username, credits, money
                        FROM users
                        WHERE lower(trim(email)) = %s
                        ORDER BY COALESCE(credits, money, 0) DESC NULLS LAST
                        LIMIT 1;
                        """,
                        (email_c,),
                    )
                except Exception:
                    _pg_rollback(conn)
                    cur.execute(
                        """
                        SELECT hardware_id, username, credits, money
                        FROM users
                        WHERE lower(trim(email)) = %s
                        LIMIT 1;
                        """,
                        (email_c,),
                    )
                row = cur.fetchone()
                if row and row["hardware_id"]:
                    return str(row["hardware_id"]).strip()[:128]
                if cand:
                    canon, _pc = _account_canonical_hardware_id(cand, email_c, pilot_name)
                    return canon

            if cand:
                cur.execute(
                    """
                    SELECT hardware_id, username, credits, money
                    FROM users
                    WHERE hardware_id = %s
                    LIMIT 1;
                    """,
                    (cand,),
                )
                row = cur.fetchone()
                if row and row["hardware_id"]:
                    hid = str(row["hardware_id"]).strip()[:128]
                    if pilot_name and str(row["username"] or "").strip().lower() == str(
                        pilot_name
                    ).strip().lower():
                        return hid
                    if not _web_postgres_user_is_stub(
                        str(row["username"] or ""),
                        hid,
                        row["credits"],
                        row["money"],
                    ):
                        return hid
                cur.execute(
                    """
                    SELECT hardware_id, username, credits, money
                    FROM users
                    WHERE substring(hardware_id from 1 for 64) = %s;
                    """,
                    (cand[:64],),
                )
                rows = cur.fetchall() or []
                if len(rows) == 1 and rows[0]["hardware_id"]:
                    return str(rows[0]["hardware_id"]).strip()[:128]

    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[web] resolve_postgres_hid failed: {exc_pg!s}")
    finally:
        conn.close()
    if email_c and "@" in email_c and cand:
        canon, _pc = _account_canonical_hardware_id(cand, email_c, pilot_name)
        return canon
    return cand


def _web_postgres_sync_login_profile(
    hardware_id: str,
    email: str = "",
    pilot_name: str = "",
    license_active: bool = False,
    *,
    conn: Any | None = None,
) -> None:
    """Keep PostgreSQL user row aligned with web login (email, display name, license)."""
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return
    email_c = str(email or "").strip().lower()[:200]
    pilot = str(pilot_name or "").strip()[:160] or hid[:16] or "Pilot"
    lic = "activated" if license_active else "portal_free"
    own_conn = conn is None
    if own_conn:
        conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO users (hardware_id, username, email, money, credits, xp, license_status)
                VALUES (%s, %s, NULLIF(%s, ''), %s, %s, 0, %s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    username = CASE
                        WHEN users.username = '' OR users.username = substring(users.hardware_id from 1 for 16)
                             OR users.username = 'Pilot'
                        THEN EXCLUDED.username
                        ELSE users.username
                    END,
                    email = CASE
                        WHEN COALESCE(users.email, '') = '' AND EXCLUDED.email IS NOT NULL
                        THEN EXCLUDED.email
                        ELSE users.email
                    END,
                    license_status = CASE
                        WHEN EXCLUDED.license_status = 'activated' THEN 'activated'
                        WHEN EXCLUDED.license_status = 'portal_free' THEN 'portal_free'
                        ELSE users.license_status
                    END;
                """,
                (
                    hid,
                    pilot,
                    email_c,
                    _pg_new_account_starter_credits(),
                    _pg_new_account_starter_credits(),
                    lic,
                ),
            )
        if own_conn:
            pg_commit(conn)
        if email_c and "@" in email_c and own_conn:
            _pg_apply_new_account_starter_autopilot(hid, email_c, pilot)
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[web] sync_login_profile failed hid={hid[:16]!r}: {exc_pg!s}")
    finally:
        if own_conn:
            conn.close()


def _license_keys_hardware_by_email(email: str) -> str:
    """Desktop-HWID aus aktivierter Lizenz (nicht Web-Platzhalter)."""
    em = str(email or "").strip().lower()[:200]
    if not em or "@" not in em:
        return ""
    try:
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            row = conn.execute(
                """
                SELECT hardware_id FROM license_keys
                WHERE lower(trim(customer_email)) = ?
                  AND status = 'activated'
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (em,),
            ).fetchone()
            if row:
                hid = str(row[0] or "").strip()[:128]
                if hid and not _login_placeholder_hardware_for_bonding(hid):
                    return hid
        finally:
            conn.close()
    except sqlite3.Error:
        pass
    return ""


def _web_postgres_session_refresh(request: Request, hid_raw: str | None = None) -> tuple[str | None, bool]:
    """Resolve every web request against PostgreSQL and replace stale SQLite-era sessions."""
    parsed = hid_raw if hid_raw is not None else _web_token_from_request(request)
    candidate = str(parsed or "").strip()[:128]
    email = _portal_email_for_hardware(candidate[:64]) if candidate else ""
    if not email and candidate:
        try:
            conn = sqlite3.connect(str(SERVER_DB_PATH))
            try:
                row = conn.execute(
                    """
                    SELECT customer_email FROM license_keys
                    WHERE hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (candidate, candidate[:64]),
                ).fetchone()
                if row and row[0]:
                    email = str(row[0]).strip().lower()[:200]
            finally:
                conn.close()
        except sqlite3.Error:
            pass
    if _login_placeholder_hardware_for_bonding(candidate) and email:
        lk_hid = _license_keys_hardware_by_email(email)
        if lk_hid:
            candidate = lk_hid
    canonical = _web_resolve_postgres_hardware_id(
        email=email, sqlite_hid=candidate
    )
    if _login_placeholder_hardware_for_bonding(canonical) and email:
        lk_hid = _license_keys_hardware_by_email(email)
        if lk_hid:
            canonical = _web_resolve_postgres_hardware_id(
                email=email, sqlite_hid=lk_hid
            )
        else:
            canon_em, _pc = _account_canonical_hardware_id(
                candidate or lk_hid or "", email, ""
            )
            if canon_em:
                canonical = canon_em
    if not canonical:
        return None, False
    return canonical, canonical != candidate


def _web_apply_session_refresh(response: Response, request: Request, hid: str | None) -> None:
    if not hid:
        return
    _web_set_session_cookie(response, _web_issue_token(hid), request)


def _auth_login_json_response(
    request: Request, payload: dict[str, Any], hardware_id: str = ""
) -> JSONResponse:
    """POST /api/v1/auth/login — Session-Nuke + isolierte user_id + Cookie."""
    out = dict(payload)
    pc_hid = str(
        hardware_id
        or out.get("hardware_id")
        or out.get("pc_hardware_id")
        or ""
    ).strip()[:128]
    em = str(
        out.get("email")
        or out.get("portal_email")
        or out.get("customer_email")
        or ""
    ).strip().lower()[:200]
    pilot = str(out.get("pilot_name") or out.get("username") or "").strip()[:120]
    success = str(out.get("status") or "") == "login_success"
    hid = pc_hid
    if success and pc_hid:
        lic_on = bool(out.get("has_license") or out.get("license_status"))
        if em and "@" in em:
            canon = _pg_desktop_session_isolate_and_sync(
                pc_hid, em, pilot, license_active=lic_on
            )
            if canon:
                hid = canon
        else:
            canon = _pg_desktop_session_isolate_and_sync(
                pc_hid, "", pilot, license_active=lic_on
            )
            if canon:
                hid = canon
        sym = _api_hardware_id_symmetry(pc_hid, em, pilot)
        out.update(sym)
        hid = sym["hardware_id"] or hid
        tok = _web_issue_token(hid)
        out["access_token"] = tok
        resp = JSONResponse(out)
        _web_clear_session_cookies(resp)
        _web_set_session_cookie(resp, tok, request)
        return resp
    return JSONResponse(out)


def _web_discord_oauth_finish(request: Request, hid: str) -> RedirectResponse:
    """Nach Discord-OAuth: Session erneuern, Dashboard ohne Re-Login."""
    hid_use = str(hid or "").strip()[:128]
    resp = RedirectResponse(
        f"{_public_origin()}/dashboard?discord_oauth=ok",
        status_code=http_status.HTTP_303_SEE_OTHER,
    )
    if hid_use:
        _web_apply_session_refresh(resp, request, hid_use)
    return resp


