def _safe_alter(conn: sqlite3.Connection, sql: str) -> None:
    try:
        conn.execute(sql)
    except sqlite3.OperationalError:
        pass


def _m202_repair_radar_positions(conn: sqlite3.Connection) -> None:
    """Meilenstein 202: FIDS-Tabelle — fehlende Spalten oder Legacy-Layout reparieren."""
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='radar_positions';"
    ).fetchone()
    if not row:
        return
    cols = {
        str(r[1])
        for r in conn.execute("PRAGMA table_info(radar_positions);").fetchall()
    }
    needed = {
        "hardware_id",
        "pilot_name",
        "lat",
        "lon",
        "alt",
        "hdg",
        "route",
        "aircraft",
        "ts",
        "flight_phase",
        "ground_speed",
    }
    if needed.issubset(cols):
        for alt in (
            "ALTER TABLE radar_positions ADD COLUMN flight_phase TEXT NOT NULL DEFAULT 'Unknown';",
            "ALTER TABLE radar_positions ADD COLUMN ground_speed REAL NOT NULL DEFAULT 0;",
            "ALTER TABLE radar_positions ADD COLUMN route TEXT NOT NULL DEFAULT '';",
            "ALTER TABLE radar_positions ADD COLUMN aircraft TEXT NOT NULL DEFAULT '';",
            "ALTER TABLE radar_positions ADD COLUMN status TEXT NOT NULL DEFAULT 'ONLINE';",
            "ALTER TABLE radar_positions ADD COLUMN origin_icao TEXT NOT NULL DEFAULT '';",
            "ALTER TABLE radar_positions ADD COLUMN destination_icao TEXT NOT NULL DEFAULT '';",
            "ALTER TABLE radar_positions ADD COLUMN offline_start_ts REAL NOT NULL DEFAULT 0;",
            "ALTER TABLE radar_positions ADD COLUMN last_online_ts REAL NOT NULL DEFAULT 0;",
        ):
            _safe_alter(conn, alt)
        return
    conn.execute("DROP TABLE IF EXISTS radar_positions_m202_legacy;")
    try:
        conn.execute(
            "ALTER TABLE radar_positions RENAME TO radar_positions_m202_legacy;"
        )
    except sqlite3.OperationalError:
        conn.execute("DROP TABLE IF EXISTS radar_positions;")
    conn.execute(
        """
        CREATE TABLE radar_positions (
            hardware_id TEXT PRIMARY KEY,
            pilot_name TEXT NOT NULL DEFAULT '',
            lat REAL NOT NULL DEFAULT 0,
            lon REAL NOT NULL DEFAULT 0,
            alt REAL NOT NULL DEFAULT 0,
            hdg REAL NOT NULL DEFAULT 0,
            route TEXT NOT NULL DEFAULT '',
            aircraft TEXT NOT NULL DEFAULT '',
            ts REAL NOT NULL DEFAULT 0,
            flight_phase TEXT NOT NULL DEFAULT 'Unknown',
            ground_speed REAL NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'ONLINE',
            origin_icao TEXT NOT NULL DEFAULT '',
            destination_icao TEXT NOT NULL DEFAULT '',
            offline_start_ts REAL NOT NULL DEFAULT 0,
            last_online_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute("DROP TABLE IF EXISTS radar_positions_m202_legacy;")
    try:
        _server_log_line("[M202] radar_positions neu aufgebaut (Legacy-Schema verworfen).")
    except NameError:
        pass


