def _append_server_live_ticker(message_text: str) -> None:
    """M215: Echten Live-Ticker-Eintrag persistieren (letzte 200 behalten)."""
    msg = str(message_text or "").strip()[:500]
    if not msg:
        return
    ts = datetime.utcnow().isoformat()
    try:
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            conn.execute(
                """
                INSERT INTO server_live_ticker (message_text, timestamp)
                VALUES (?, ?);
                """,
                (msg, ts),
            )
            conn.execute(
                """
                DELETE FROM server_live_ticker
                WHERE id NOT IN (
                    SELECT id FROM server_live_ticker
                    ORDER BY id DESC LIMIT 200
                );
                """
            )
            conn.commit()
        finally:
            conn.close()
    except sqlite3.Error:
        pass


def _server_live_ticker_recent(limit: int = 5) -> list[str]:
    """Neueste Ticker-Meldungen (älteste zuerst für Marquee-Leserichtung)."""
    n = max(1, min(int(limit), 20))
    try:
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            cur = conn.execute(
                """
                SELECT message_text FROM server_live_ticker
                ORDER BY id DESC LIMIT ?;
                """,
                (n,),
            )
            rows = [str(r[0] or "").strip() for r in cur.fetchall() if r and r[0]]
        finally:
            conn.close()
    except sqlite3.Error:
        return []
    rows.reverse()
    return [m for m in rows if m]


def _radar_phase_is_cruise(phase: str) -> bool:
    p = str(phase or "").strip().lower()
    return p in ("reiseflug", "cruise")


def _radar_phase_is_standby(phase: str) -> bool:
    p = str(phase or "").strip().lower()
    if not p or p in ("unknown", "?", "-"):
        return True
    markers = (
        "gate",
        "parking",
        "standby",
        "parked",
        "boarding",
        "vorber",
        "am gate",
        "am_gate",
    )
    return any(m in p for m in markers)


def _radar_phase_is_in_flight(phase: str) -> bool:
    p = str(phase or "").strip().lower()
    if _radar_phase_is_standby(p):
        return False
    if p in ("in_flight", "in-flight", "in flight"):
        return True
    return p in (
        "reiseflug",
        "cruise",
        "climb",
        "steigflug",
        "approach",
        "endanflug",
        "descent",
        "sinkflug",
        "taxi",
    ) or "flight" in p


def _ensure_pg_live_flights_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS live_flights (
                id SERIAL PRIMARY KEY,
                username TEXT NOT NULL DEFAULT '',
                hardware_id VARCHAR(128) NOT NULL DEFAULT '',
                route TEXT NOT NULL DEFAULT '',
                aircraft TEXT NOT NULL DEFAULT '',
                status VARCHAR(64) NOT NULL DEFAULT 'ONLINE',
                flight_phase TEXT NOT NULL DEFAULT '',
                ts DOUBLE PRECISION NOT NULL DEFAULT 0,
                last_heartbeat DOUBLE PRECISION NOT NULL DEFAULT 0
            );
            """
        )
        try:
            cur.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS idx_live_flights_hardware_id
                ON live_flights (hardware_id);
                """
            )
        except psycopg2.Error:
            conn.rollback()
        for stmt in (
            "ALTER TABLE live_flights ADD COLUMN IF NOT EXISTS flight_phase TEXT NOT NULL DEFAULT '';",
            "ALTER TABLE live_flights ADD COLUMN IF NOT EXISTS status VARCHAR(64) NOT NULL DEFAULT 'ONLINE';",
            "ALTER TABLE live_flights ADD COLUMN IF NOT EXISTS last_heartbeat DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE live_flights ADD COLUMN IF NOT EXISTS lat DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE live_flights ADD COLUMN IF NOT EXISTS lon DOUBLE PRECISION NOT NULL DEFAULT 0;",
        ):
            try:
                cur.execute(stmt)
            except psycopg2.Error:
                conn.rollback()
        try:
            conn.commit()
        except psycopg2.Error:
            conn.rollback()


def _persist_live_flight_postgres(
    *,
    username: str,
    hardware_id: str,
    route: str,
    aircraft: str,
    status: str,
    flight_phase: str,
    ts: float,
    lat: float | None = None,
    lon: float | None = None,
) -> None:
    uname = str(username or "").strip()[:80]
    if not uname or uname in {"?", "Pilot", "pilot"}:
        uname = _pilot_display_name_for_hid(str(hardware_id or "")[:64]) or uname or "Pilot"
    conn = get_db_connection()
    try:
        _ensure_pg_live_flights_table(conn)
        hid_key = str(hardware_id or "").strip()[:128]
        with conn.cursor() as cur:
            if hid_key:
                cur.execute(
                    "DELETE FROM live_flights WHERE hardware_id = %s OR lower(trim(username)) = lower(trim(%s));",
                    (hid_key, uname),
                )
            hb = float(ts or time.time())
            la_v = float(lat) if lat is not None else 0.0
            lo_v = float(lon) if lon is not None else 0.0
            if not _radar_coords_valid(la_v, lo_v):
                la_v, lo_v = 0.0, 0.0
            cur.execute(
                """
                INSERT INTO live_flights (
                    username, hardware_id, route, aircraft, status, flight_phase,
                    ts, last_heartbeat, lat, lon
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s);
                """,
                (
                    uname,
                    hid_key,
                    str(route or "")[:160],
                    str(aircraft or "None")[:160],
                    str(status or "ONLINE")[:32],
                    str(flight_phase or "")[:64],
                    hb,
                    hb,
                    la_v,
                    lo_v,
                ),
            )
            conn.commit()
    finally:
        conn.close()


def _alliance_hubs_icaos(alliance_id: str) -> list[str]:
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT icao FROM alliance_hubs
                WHERE alliance_id = %s ORDER BY bought_ts ASC;
                """,
                (alliance_id,),
            )
            return [str(r["icao"] or "").strip().upper()[:4] for r in cur.fetchall() if r["icao"]]
    finally:
        conn.close()


def _alliance_hubs_public_string(alliance_id: str) -> str:
    hubs = _alliance_hubs_icaos(alliance_id)
    return ", ".join(hubs) if hubs else "—"


def _alliance_record_investment(alliance_id: str, hardware_id: str, amount: float) -> None:
    if amount <= 0:
        return
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            INSERT INTO alliance_investments (alliance_id, hardware_id, total_contributed)
            VALUES (?, ?, ?)
            ON CONFLICT(alliance_id, hardware_id) DO UPDATE SET
                total_contributed = total_contributed + excluded.total_contributed;
            """,
            (alliance_id, hardware_id[:64], float(amount)),
        )
        conn.commit()
    finally:
        conn.close()


def _alliance_mega_state_payload(alliance_id: str, hid64: str) -> dict[str, Any]:
    hubs: list[dict[str, Any]] = []
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        for icao, ts in conn.execute(
            """
            SELECT icao, bought_ts FROM alliance_hubs
            WHERE alliance_id = ? ORDER BY bought_ts DESC;
            """,
            (alliance_id,),
        ).fetchall():
            hubs.append(
                {
                    "icao": str(icao or "").upper()[:4],
                    "bought_at": time.strftime(
                        "%Y-%m-%d %H:%M UTC",
                        time.gmtime(float(ts or 0)),
                    ),
                    "bought_ts": float(ts or 0),
                }
            )
        investments: list[dict[str, Any]] = []
        inv_rows = conn.execute(
            """
            SELECT hardware_id, total_contributed FROM alliance_investments
            WHERE alliance_id = ? ORDER BY total_contributed DESC;
            """,
            (alliance_id,),
        ).fetchall()
        total_inv = sum(float(r[1] or 0) for r in inv_rows)
        for hw, contrib in inv_rows:
            c = float(contrib or 0)
            pct = (c / total_inv * 100.0) if total_inv > 0 else 0.0
            investments.append(
                {
                    "hardware_id": str(hw),
                    "pilot_name": _pilot_display_name_for_hid(str(hw)),
                    "total_contributed": c,
                    "share_pct": round(pct, 2),
                }
            )
        fleet: list[dict[str, Any]] = []
        for fid, donor, model, health, fee, lessee in conn.execute(
            """
            SELECT id, donor_hardware_id, aircraft_model, health,
                   daily_lease_fee, current_lessee_hardware_id
            FROM alliance_fleet WHERE alliance_id = ? ORDER BY id DESC;
            """,
            (alliance_id,),
        ).fetchall():
            fleet.append(
                {
                    "id": int(fid),
                    "donor_hardware_id": str(donor),
                    "donor_name": _pilot_display_name_for_hid(str(donor)),
                    "aircraft_model": str(model),
                    "health": int(health or 0),
                    "daily_lease_fee": float(fee or 0),
                    "lessee_hardware_id": str(lessee or ""),
                    "lessee_name": _pilot_display_name_for_hid(str(lessee or "")),
                    "available": not str(lessee or "").strip(),
                }
            )
        claims: list[dict[str, Any]] = []
        for cid, ahid, pname, req, reason, st, cts in conn.execute(
            """
            SELECT id, applicant_hardware_id, applicant_name, requested_credits,
                   reason, status, created_ts
            FROM alliance_insurance_claims
            WHERE alliance_id = ? ORDER BY created_ts DESC LIMIT 40;
            """,
            (alliance_id,),
        ).fetchall():
            claims.append(
                {
                    "id": int(cid),
                    "applicant_hardware_id": str(ahid),
                    "applicant_name": str(pname or _pilot_display_name_for_hid(str(ahid))),
                    "requested_credits": float(req or 0),
                    "reason": str(reason or "")[:500],
                    "status": str(st or "pending"),
                    "created_ts": float(cts or 0),
                }
            )
        raids: list[dict[str, Any]] = []
        for rid, title, target, pooled, rst, cts in conn.execute(
            """
            SELECT id, title, target_credits, pooled_credits, status, created_ts
            FROM alliance_raids WHERE alliance_id = ? ORDER BY created_ts DESC LIMIT 20;
            """,
            (alliance_id,),
        ).fetchall():
            raids.append(
                {
                    "id": int(rid),
                    "title": str(title or ""),
                    "target_credits": float(target or 0),
                    "pooled_credits": float(pooled or 0),
                    "status": str(rst or "open"),
                    "created_ts": float(cts or 0),
                }
            )
        pool_row = conn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        pool = float(pool_row[0] or 0) if pool_row else 0.0
    finally:
        conn.close()
    mem = _alliance_member_row(hid64)
    role = str(mem[1]) if mem else ""
    return {
        "ok": True,
        "alliance_id": alliance_id,
        "alliance_credits": pool,
        "role": role,
        "hubs": hubs,
        "hub_icaos": [h["icao"] for h in hubs],
        "investments": investments,
        "investment_total": total_inv,
        "fleet": fleet,
        "insurance_claims": claims,
        "raids": raids,
    }


def _alliance_ceo_or_co(hid64: str, alliance_id: str) -> bool:
    mem = _alliance_member_row(hid64)
    return bool(mem and mem[0] == alliance_id and str(mem[1]) in ("ceo", "co_leader"))


_UUID_LICENSE_KEY_RE = re.compile(
    r"^[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}$",
    re.IGNORECASE,
)


def _is_auto_portal_license_key(license_key: str) -> bool:
    """Freie Web-Registrierung erzeugte fälschlich UUID-Keys — keine echte Lifetime-Lizenz."""
    return bool(_UUID_LICENSE_KEY_RE.match((license_key or "").strip()))


def _license_key_is_purchased(conn: sqlite3.Connection, license_key: str) -> bool:
    """True nur bei PayPal-Kauf, Promo-Gutschein oder echtem Shop-Key — nicht bei Portal-UUID."""
    lk = (license_key or "").strip()
    if not lk or _is_auto_portal_license_key(lk):
        return False
    row = conn.execute(
        """
        SELECT paypal_order_id, paypal_capture_id FROM keys
        WHERE license_key = ? LIMIT 1;
        """,
        (lk,),
    ).fetchone()
    if row:
        oid = str(row[0] or "").strip()
        cap = str(row[1] or "").strip()
        if cap:
            return True
        if oid:
            return True
        return False
    lkrow = conn.execute(
        "SELECT status FROM license_keys WHERE license_key = ? LIMIT 1;",
        (lk,),
    ).fetchone()
    if lkrow and str(lkrow[0] or "") == "activated":
        return True
    return False


def _email_has_purchased_license(conn: sqlite3.Connection, email_norm: str) -> bool:
    em = email_norm.strip().lower()
    if "@" not in em:
        return False
    cur = conn.execute(
        """
        SELECT license_key FROM license_keys
        WHERE lower(trim(customer_email)) = ? AND status = 'activated';
        """,
        (em,),
    )
    for (lk_raw,) in cur.fetchall():
        if _license_key_is_purchased(conn, str(lk_raw or "")):
            return True
    return False


def _email_has_portal_account(conn: sqlite3.Connection, email_norm: str) -> bool:
    em = email_norm.strip().lower()
    if "@" not in em:
        return False
    row = conn.execute(
        "SELECT 1 FROM web_pending_users WHERE lower(trim(email)) = ? LIMIT 1;",
        (em,),
    ).fetchone()
    return bool(row)


def _hardware_has_purchased_license(conn: sqlite3.Connection, hardware_id: str) -> bool:
    hk = (hardware_id or "").strip()[:128]
    if not hk:
        return False
    cur = conn.execute(
        """
        SELECT license_key FROM license_keys
        WHERE hardware_id = ? AND status = 'activated';
        """,
        (hk,),
    )
    for (lk_raw,) in cur.fetchall():
        if _license_key_is_purchased(conn, str(lk_raw or "")):
            return True
    return False


def _repair_spurious_portal_licenses() -> int:
    """Entfernt fälschlich als „aktiviert“ markierte UUID-Lizenzen (kostenlose Registrierung)."""
    fixed = 0
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        rows = conn.execute(
            """
            SELECT license_key, hardware_id, customer_email, pilot_name,
                   password_salt, password_hash
            FROM license_keys
            WHERE status = 'activated';
            """
        ).fetchall()
        for lk, hid, email, pilot, salt, ph in rows:
            lk_s = str(lk or "").strip()
            if not _is_auto_portal_license_key(lk_s):
                continue
            if _license_key_is_purchased(conn, lk_s):
                continue
            em = str(email or "").strip()[:200]
            em_l = em.lower()
            hid_s = str(hid or "").strip()[:128]
            if em_l and "@" in em_l:
                conn.execute(
                    """
                    INSERT OR REPLACE INTO web_pending_users (
                        email, password_salt, password_hash, pilot_name,
                        hardware_id, created_ts, is_verified
                    ) VALUES (?, ?, ?, ?, ?, ?, 1);
                    """,
                    (
                        em,
                        str(salt or ""),
                        str(ph or ""),
                        str(pilot or "")[:120],
                        hid_s,
                        time.time(),
                    ),
                )
            conn.execute("DELETE FROM keys WHERE license_key = ?;", (lk_s,))
            conn.execute("DELETE FROM license_keys WHERE license_key = ?;", (lk_s,))
            hid64 = hid_s[:64]
            if hid64:
                uconn.execute(
                    """
                    UPDATE users SET license_key = '', license_activated = 0,
                    has_license = 0
                    WHERE hardware_id = ?;
                    """,
                    (hid64,),
                )
            fixed += 1
        conn.commit()
        uconn.commit()
    finally:
        conn.close()
        uconn.close()
    if fixed:
        try:
            _server_log_line(
                f"[LICENSE REPAIR] {fixed} fälschliche Portal-„Lizenzen“ bereinigt."
            )
        except NameError:
            print(f"[LICENSE REPAIR] {fixed} fälschliche Portal-Lizenzen bereinigt.")
    return fixed


def _sync_user_license_flags(hid64: str) -> tuple[int, int]:
    """(is_verified, has_license) — has_license nur bei echter ST-/Shop-Lizenz."""
    hk = hid64[:64]
    has_license = 1 if _has_purchased_lifetime_license(hk, hk) else 0
    is_verified = 1
    conn = None
    try:
        conn = get_db_connection()
        if has_license:
            pg_execute(
                conn,
                """
                UPDATE users SET license_status = 'activated'
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (hk, hk),
            )
        else:
            pg_execute(
                conn,
                """
                UPDATE users SET license_status = 'portal_free'
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (hk, hk),
            )
        pg_commit(conn)
    except Exception:
        if conn is not None:
            _pg_rollback(conn)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            """
            UPDATE users SET license_activated = ?, has_license = ?, is_verified = 1
            WHERE hardware_id = ?;
            """,
            (1 if has_license else 0, 1 if has_license else 0, hk),
        )
        uconn.commit()
    finally:
        uconn.close()
    return is_verified, has_license


def _web_visitor_alliance_context(
    request: Request, *, hid_raw: str | None = None
) -> dict[str, Any]:
    if hid_raw is None:
        try:
            hid_raw, _needs_refresh = _web_postgres_session_refresh(request)
        except Exception as exc_ctx:
            _server_log_line(f"[web] alliance visitor session: {exc_ctx!s}")
            hid_raw = _web_session_hid(request)
    logged_in = bool(hid_raw)
    hid64 = str(hid_raw or "").strip()[:64]
    is_verified, has_license = (0, 0)
    in_alliance = False
    pilot_name = ""
    if logged_in and hid64:
        is_verified, has_license = _sync_user_license_flags(hid64)
        pilot_name = _pilot_display_name_for_hid(hid64)
        in_alliance = _alliance_member_row(hid64) is not None
    can_apply = bool(
        logged_in and is_verified == 1 and has_license == 1 and not in_alliance
    )
    return {
        "logged_in": logged_in,
        "hardware_id": hid64,
        "pilot_name": pilot_name,
        "is_verified": is_verified,
        "has_license": has_license,
        "in_alliance": in_alliance,
        "can_apply": can_apply,
    }


def _alliances_hubs_by_id() -> dict[str, list[str]]:
    """Alle Hub-ICAOs in einer PG-Abfrage (kein N+1 pro Allianz)."""
    hubs_map: dict[str, list[str]] = {}
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT alliance_id, icao
                FROM alliance_hubs
                ORDER BY alliance_id, bought_ts ASC;
                """
            )
            for row in cur.fetchall():
                aid = str(row["alliance_id"] or "").strip()
                icao = str(row["icao"] or "").strip().upper()[:4]
                if not aid or not icao:
                    continue
                hubs_map.setdefault(aid, []).append(icao)
    except Exception as exc_h:
        _server_log_line(f"[web] alliance hubs batch load: {exc_h!s}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return hubs_map


def _alliances_public_leaderboard(limit: int = 100) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    conn = None
    try:
        hubs_map = _alliances_hubs_by_id()
        conn = get_db_connection()
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT a.alliance_id, a.name, COALESCE(a.credits, 0) AS credits, a.ceo_hardware_id,
                       (SELECT COUNT(*) FROM alliance_members m
                        WHERE m.alliance_id = a.alliance_id AND m.role != 'pending') AS members,
                       0::double precision AS tax_collected_total,
                       0::integer AS tax_payment_count
                FROM alliances a
                ORDER BY COALESCE(a.credits, 0) DESC, a.name ASC
                LIMIT %s;
                """,
                (int(limit),),
            )
            rows = cur.fetchall()
        for rank, row in enumerate(rows, start=1):
            aid_s = str(row["alliance_id"] or "")
            hubs = hubs_map.get(aid_s, [])
            out.append(
                {
                    "rank": rank,
                    "alliance_id": aid_s,
                    "name": str(row["name"] or ""),
                    "credits": float(row["credits"] or 0),
                    "ceo_name": _pilot_display_name_for_hid(str(row["ceo_hardware_id"] or "")),
                    "members": int(row["members"] or 0),
                    "hubs_count": len(hubs),
                    "hubs_string": ", ".join(hubs) if hubs else "—",
                    "tax_collected_total": float(row["tax_collected_total"] or 0),
                    "tax_payment_count": int(row["tax_payment_count"] or 0),
                }
            )
    except Exception as exc_lb:
        _server_log_line(f"[web] alliances leaderboard: {exc_lb!s}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return out


