def _looks_like_opaque_hardware_token(label: str) -> bool:
    """Erkennt Hex/UUID-ähnliche IDs, die keine echten Pilotennamen sind."""
    t = str(label or "").strip()
    if not t or " " in t or "@" in t:
        return False
    core = t.rstrip("…").rstrip("...").replace("-", "")
    if len(core) < 8:
        return False
    return all(c in "0123456789abcdefABCDEF" for c in core)


def _sanitize_pilot_display_label(label: str) -> str:
    """Nur echte Anzeigenamen — keine Hardware-ID als Pilot."""
    n = str(label or "").strip()
    if not n:
        return ""
    low = n.lower()
    if low in ("unknown", "pilot", "?", "—", "-"):
        return ""
    if _looks_like_opaque_hardware_token(n):
        return ""
    return n[:80]


def _pilot_display_name_for_hid(hid64: str, portal_email: str = "") -> str:
    """Pilotenname: Portal-DB, Lizenz, Radar, Allianz, Web-Registrierung."""
    hk = str(hid64 or "").strip()[:128]
    if not hk:
        return "Pilot"
    em = str(portal_email or "").strip().lower()[:200]
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT username, email FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                LIMIT 1;
                """,
                (hk, hk[:64]),
            )
            urow = cur.fetchone()
            if urow:
                lbl = _sanitize_pilot_display_label(str(urow["username"] or ""))
                if lbl:
                    return lbl
                if not em and urow["email"]:
                    em = str(urow["email"]).strip().lower()[:200]
            cur.execute(
                """
                SELECT username FROM alliance_members
                WHERE (hardware_id = %s OR substring(hardware_id from 1 for 64) = %s)
                  AND trim(coalesce(username, '')) != ''
                LIMIT 1;
                """,
                (hk, hk[:64]),
            )
            mrow = cur.fetchone()
            if mrow:
                lbl = _sanitize_pilot_display_label(str(mrow["username"] or ""))
                if lbl:
                    return lbl
    finally:
        conn.close()
    if em and "@" in em:
        local = em.split("@", 1)[0].replace(".", " ").replace("_", " ").strip()
        if local and not _looks_like_opaque_hardware_token(local):
            return local.title()[:80]
    return "Captain"


def _account_hardware_aliases(
    hid64: str, portal_email: str = "", license_key: str = ""
) -> list[str]:
    """Alle bekannten IDs eines Kontos (Web-Portal, Desktop, Lizenz)."""
    out: list[str] = []

    def _add(x: str) -> None:
        s = str(x or "").strip()[:64]
        if s and s not in out:
            out.append(s)

    _add(hid64)
    em = (portal_email or "").strip().lower()[:200]
    lk = (license_key or "").strip()
    conn = get_db_connection()
    try:
        if em and "@" in em:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    """
                    SELECT hardware_id FROM users
                    WHERE lower(trim(email)) = %s
                    ORDER BY created_at DESC LIMIT 1;
                    """,
                    (em,),
                )
                row = cur.fetchone()
                if row:
                    _add(str(row["hardware_id"]))
        if lk:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    """
                    SELECT hardware_id FROM assigned_licenses
                    WHERE license_key = %s AND status = 'activated' LIMIT 1;
                    """,
                    (lk,),
                )
                row = cur.fetchone()
                if row:
                    _add(str(row["hardware_id"]))
        if hid64:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    "SELECT hardware_id FROM users WHERE hardware_id = %s LIMIT 1;",
                    (hid64[:64],),
                )
                row = cur.fetchone()
                if row:
                    _add(str(row["hardware_id"]))
    finally:
        conn.close()
    return out


def _alliance_member_row_resolved(
    hid64: str, portal_email: str = "", license_key: str = ""
) -> tuple[tuple[str, str, str, float] | None, str]:
    canonical = str(hid64 or "").strip()[:64]
    for hk in _account_hardware_aliases(hid64, portal_email, license_key):
        row = _alliance_member_row(hk)
        if row:
            return row, hk
    return None, canonical


def _alliance_full_payload(
    hid64: str, portal_email: str = "", license_key: str = ""
) -> dict[str, Any]:
    mem, canonical = _alliance_member_row_resolved(hid64, portal_email, license_key)
    public = _alliance_public_list(10)
    if not mem:
        return {
            "in_alliance": False,
            "public_alliances": public,
            "canonical_hardware_id": canonical,
        }
    alliance_id, role, aname, pool = mem[0], mem[1], mem[2], float(mem[3])
    tax_pct = _alliance_tax_pct(alliance_id)
    members = _alliance_members_detail(alliance_id)
    for m in members:
        ph = str(m.get("hardware_id", ""))
        m["pilot_name"] = _pilot_display_name_for_hid(ph)
        m["airline"] = m["pilot_name"]
        m["online"] = False
    conn = get_db_connection()
    ceo_name = ""
    leases: list[dict[str, Any]] = []
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT ceo_hardware_id FROM alliances WHERE alliance_id = %s;", (alliance_id,))
            row = cur.fetchone()
            if row:
                ceo_name = _pilot_display_name_for_hid(str(row["ceo_hardware_id"] or ""))
            now = time.time()
            cur.execute(
                """
                SELECT icao, lessee_hardware_id, credits, expires_ts
                FROM alliance_route_leases
                WHERE alliance_id = %s AND expires_ts > %s
                ORDER BY expires_ts ASC LIMIT 80;
                """,
                (alliance_id, now),
            )
            for r in cur.fetchall():
                leases.append(
                    {
                        "icao": str(r["icao"] or ""),
                        "lessee_hardware_id": str(r["lessee_hardware_id"] or ""),
                        "credits": float(r["credits"] or 0),
                        "expires_ts": float(r["expires_ts"] or 0),
                    }
                )
    finally:
        conn.close()
    hub_icaos = _alliance_hubs_icaos(alliance_id)
    return {
        "in_alliance": True,
        "alliance_id": alliance_id,
        "alliance_name": aname,
        "role": role,
        "alliance_credits": pool,
        "tax_pct": tax_pct,
        "ceo_name": ceo_name,
        "members": members,
        "route_leases": leases,
        "public_alliances": public,
        "alliance_hubs": hub_icaos,
        "hub_icaos": hub_icaos,
        "canonical_hardware_id": canonical,
    }


def _alliance_create_for_hid(hid64: str, name: str) -> dict[str, Any]:
    if _alliance_member_row(hid64):
        return {"ok": False, "error": "already_member"}
    name = (name or "").strip()[:80]
    if len(name) < 3:
        return {"ok": False, "error": "bad_name"}
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT credits FROM users WHERE hardware_id = %s;", (hid64,))
            row = cur.fetchone()
        if not row:
            return {"ok": False, "error": "no_user"}
        cr = float(row["credits"] or 0)
        if cr + 1e-6 < ALLIANCE_CREATE_COST:
            return {"ok": False, "error": "insufficient_credits"}
        aid = f"AL-{uuid.uuid4().hex[:10].upper()}"
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("UPDATE users SET credits = credits - %s, money = money - %s WHERE hardware_id = %s;", (ALLIANCE_CREATE_COST, ALLIANCE_CREATE_COST, hid64))
            cur.execute(
                """
                INSERT INTO alliances (alliance_id, name, ceo_hardware_id, credits)
                VALUES (%s, %s, %s, 0);
                """,
                (aid, name, hid64),
            )
            cur.execute(
                """
                INSERT INTO alliance_members (
                    alliance_id, hardware_id, username, role, contributed_credits, joined_ts
                ) VALUES (%s, %s, %s, 'ceo', %s, %s);
                """,
                (aid, hid64, _pilot_display_name_for_hid(hid64), ALLIANCE_CREATE_COST, time.time()),
            )
            cur.execute(
                """
                INSERT INTO alliance_tax (alliance_id, tax_pct)
                VALUES (%s, 0)
                ON CONFLICT (alliance_id) DO NOTHING;
                """,
                (aid,),
            )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return {"ok": True, "alliance_id": aid, "name": name}


