def _ensure_pg_site_news_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS site_news (
                id SERIAL PRIMARY KEY,
                message_de TEXT NOT NULL DEFAULT '',
                message_en TEXT NOT NULL DEFAULT '',
                is_active BOOLEAN NOT NULL DEFAULT TRUE,
                created_ts DOUBLE PRECISION NOT NULL DEFAULT 0,
                published_by VARCHAR(64) NOT NULL DEFAULT 'admin'
            );
            """
        )
        conn.commit()


def _active_site_news_bilingual() -> dict[str, str]:
    """Aktive News aus PostgreSQL (Fallback: RAM-Key active_global_news)."""
    conn = None
    try:
        conn = get_db_connection()
        _ensure_pg_site_news_table(conn)
        row = pg_fetchone(
            conn,
            """
            SELECT message_de, message_en FROM site_news
            WHERE is_active = TRUE
            ORDER BY created_ts DESC LIMIT 1;
            """,
        )
        if row:
            de = str(row.get("message_de") if isinstance(row, dict) else row[0] or "").strip()
            en = str(row.get("message_en") if isinstance(row, dict) else row[1] or "").strip()
            if de or en:
                return {"message_de": de, "message_en": en}
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[site_news] read: {exc!r}")
    finally:
        if conn is not None:
            conn.close()
    legacy = _active_global_news_get()
    return {"message_de": legacy, "message_en": legacy}


def _pg_publish_site_news(message_de: str, message_en: str) -> int:
    conn = None
    news_id = 0
    try:
        conn = get_db_connection()
        _ensure_pg_site_news_table(conn)
        ts = time.time()
        with conn.cursor() as cur:
            cur.execute("UPDATE site_news SET is_active = FALSE WHERE is_active = TRUE;")
            cur.execute(
                """
                INSERT INTO site_news (message_de, message_en, is_active, created_ts, published_by)
                VALUES (%s, %s, TRUE, %s, 'admin')
                RETURNING id;
                """,
                (message_de[:12000], message_en[:12000], ts),
            )
            row = cur.fetchone()
            if isinstance(row, dict):
                news_id = int(row.get("id") or 0)
            else:
                news_id = int(row[0] if row else 0)
        conn.commit()
        _active_global_news_set(message_de or message_en)
    except Exception:
        if conn is not None:
            _pg_rollback(conn)
        raise
    finally:
        if conn is not None:
            conn.close()
    return news_id


def _news_broadcast_worker(message_de: str, message_en: str) -> dict[str, Any]:
    sent = failed = 0
    for r in _pg_marketing_recipients():
        lg = r.get("lang") or "de"
        body = message_en if lg == "en" else message_de
        if not body.strip():
            body = message_de or message_en
        subj = (
            "📢 SkyTycoon — News & Patch Notes"
            if lg == "en"
            else "📢 SkyTycoon — News & Patch Notes"
        )
        plain = f"{r.get('pilot_name', 'Captain')},\n\n{body}\n\nhttps://skytycoon.info/\n"
        html_body = f"""<html><body style="background:#05070a;color:#e3e7ed;padding:24px;">
<h2 style="color:#d4af37;">📢 SkyTycoon News</h2>
<p>{html.escape(body, quote=True).replace(chr(10), '<br/>')}</p>
<p><a href="https://skytycoon.info/" style="color:#64b5f6;">skytycoon.info</a></p></body></html>"""
        if _mail_guard_send_simple(r["email"], r.get("pilot_name", ""), subj, plain, html_body):
            sent += 1
        else:
            failed += 1
    _append_admin_log(f"[news] broadcast {sent} OK / {failed} FAIL")
    return {"sent": sent, "failed": failed}


def _sync_profile_branches_for_hid(hid64: str) -> list[dict[str, Any]]:
    """Liest ``branches_json`` für Profil-Pull (Immobilienmakler / Karriere-Sync)."""
    hk = str(hid64 or "").strip()[:64]
    if not hk:
        return []
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT branches_json FROM users WHERE hardware_id = ?;",
            (hk,),
        ).fetchone()
    finally:
        conn.close()
    if not row or row[0] is None:
        return []
    raw = row[0]
    if isinstance(raw, (bytes, bytearray)):
        raw = raw.decode("utf-8", errors="replace")
    try:
        data = json.loads(str(raw or "[]"))
    except (json.JSONDecodeError, TypeError, ValueError):
        return []
    if not isinstance(data, list):
        return []
    return [b for b in data if isinstance(b, dict)]


