def _portal_email_for_hardware(hid64: str) -> str:
    hk = str(hid64 or "").strip()[:64]
    if not hk:
        return ""
    em = ""
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT email FROM users
                WHERE hardware_id = %s AND trim(coalesce(email, '')) != ''
                LIMIT 1;
                """,
                (hk,),
            )
            row = cur.fetchone()
            if row and row["email"]:
                em = str(row["email"]).strip()[:200]
            if not em:
                cur.execute(
                    """
                    SELECT email FROM users
                    WHERE substring(hardware_id from 1 for 64) = %s
                      AND trim(coalesce(email, '')) != ''
                    LIMIT 1;
                    """,
                    (hk,),
                )
                row2 = cur.fetchone()
                if row2 and row2["email"]:
                    em = str(row2["email"]).strip()[:200]
    except Exception:
        if conn is not None:
            _pg_rollback(conn)
    finally:
        conn.close()
    if em and "@" in em:
        return em
    try:
        sconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            prow = sconn.execute(
                """
                SELECT email FROM web_pending_users
                WHERE hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (hk, hk),
            ).fetchone()
            if prow and prow[0] and "@" in str(prow[0]):
                return str(prow[0]).strip().lower()[:200]
            lrow = sconn.execute(
                """
                SELECT customer_email FROM license_keys
                WHERE (hardware_id = ? OR substr(hardware_id, 1, 64) = ?)
                  AND trim(coalesce(customer_email, '')) != ''
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (hk, hk),
            ).fetchone()
            if lrow and lrow[0] and "@" in str(lrow[0]):
                return str(lrow[0]).strip().lower()[:200]
        finally:
            sconn.close()
    except sqlite3.Error:
        pass
    return ""


def _resolve_web_user_email(request: Request, body: dict[str, Any] | None = None) -> str:
    """E-Mail für Web-Support — Body, Session-Cookie, PostgreSQL, SQLite."""
    payload = body if isinstance(body, dict) else {}
    for key in ("user_email", "email", "portal_email"):
        em = str(payload.get(key) or "").strip().lower()[:200]
        if em and "@" in em:
            return em
    hid = _authenticated_hid_from_request(request)
    if not hid:
        return ""
    em = _portal_email_for_hardware(str(hid).strip()[:64])
    if em and "@" in em:
        return em
    hk = str(hid).strip()[:128]
    try:
        sconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            for sql, args in (
                (
                    """
                    SELECT customer_email FROM license_keys
                    WHERE (hardware_id = ? OR substr(hardware_id, 1, 64) = ?)
                      AND trim(coalesce(customer_email, '')) != ''
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (hk, hk[:64]),
                ),
                (
                    """
                    SELECT email FROM web_pending_users
                    WHERE hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (hk, hk[:64]),
                ),
            ):
                row = sconn.execute(sql, args).fetchone()
                if row and row[0] and "@" in str(row[0]):
                    return str(row[0]).strip().lower()[:200]
        finally:
            sconn.close()
    except sqlite3.Error:
        pass
    return ""


def _pg_ensure_user_prefs_columns(conn) -> None:
    with conn.cursor() as cur:
        for stmt in (
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS has_seen_welcome INTEGER NOT NULL DEFAULT 0;",
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS selected_language VARCHAR(8) NOT NULL DEFAULT 'de';",
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS fuel_storage INTEGER NOT NULL DEFAULT 0;",
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS fuel_max_capacity INTEGER NOT NULL DEFAULT 50000;",
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS weather_risk INTEGER NOT NULL DEFAULT 0;",
        ):
            try:
                cur.execute(stmt)
                conn.commit()
            except psycopg2.Error:
                conn.rollback()


def _pg_ensure_discount_codes_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS discount_codes (
                code VARCHAR(64) PRIMARY KEY,
                discount_percent INTEGER NOT NULL DEFAULT 0,
                discount_eur NUMERIC(12,2) NOT NULL DEFAULT 0,
                max_uses INTEGER NOT NULL DEFAULT 1,
                uses INTEGER NOT NULL DEFAULT 0,
                valid_from VARCHAR(64) NOT NULL DEFAULT '',
                valid_until VARCHAR(64) NOT NULL DEFAULT '',
                status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
                created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
            );
            """
        )
        cur.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_discount_codes_status
            ON discount_codes (status);
            """
        )
        conn.commit()


def _pg_upsert_discount_code_active(
    code_u: str,
    *,
    discount_percent: int,
    discount_eur: float,
    max_uses: int,
    valid_from: str = "",
    valid_until: str = "",
) -> None:
    conn = None
    try:
        conn = get_db_connection()
        _pg_ensure_discount_codes_table(conn)
        pg_execute(
            conn,
            """
            INSERT INTO discount_codes (
                code, discount_percent, discount_eur, max_uses, uses,
                valid_from, valid_until, status, updated_at
            ) VALUES (%s, %s, %s, %s, 0, %s, %s, 'ACTIVE', NOW())
            ON CONFLICT (code) DO UPDATE SET
                discount_percent = EXCLUDED.discount_percent,
                discount_eur = EXCLUDED.discount_eur,
                max_uses = EXCLUDED.max_uses,
                valid_from = EXCLUDED.valid_from,
                valid_until = EXCLUDED.valid_until,
                status = 'ACTIVE',
                updated_at = NOW();
            """,
            (
                code_u,
                int(discount_percent),
                float(discount_eur),
                int(max_uses),
                valid_from,
                valid_until,
            ),
        )
        pg_commit(conn)
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[PG] discount_codes upsert {code_u!r}: {exc!r}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _pg_discount_code_kill(code_u: str) -> bool:
    """Status EXPIRED — Gutschein sofort von der Website entfernt."""
    conn = None
    try:
        conn = get_db_connection()
        _pg_ensure_discount_codes_table(conn)
        chk = pg_fetchone(
            conn,
            """
            SELECT 1 FROM discount_codes
            WHERE upper(trim(code)) = upper(trim(%s))
            LIMIT 1;
            """,
            (code_u,),
        )
        if not chk:
            _pg_rollback(conn)
            return False
        pg_execute(
            conn,
            """
            UPDATE discount_codes
            SET status = 'EXPIRED', updated_at = NOW()
            WHERE upper(trim(code)) = upper(trim(%s));
            """,
            (code_u,),
        )
        pg_commit(conn)
        return True
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[PG] discount kill FEHLER {code_u!r}: {exc!r}")
        raise
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _pg_list_active_discount_codes() -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    conn = None
    try:
        conn = get_db_connection()
        _pg_ensure_discount_codes_table(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT code, discount_percent, discount_eur, max_uses, uses,
                       valid_from, valid_until, status
                FROM discount_codes
                WHERE upper(trim(status)) = 'ACTIVE'
                ORDER BY updated_at DESC;
                """
            )
            for row in cur.fetchall() or []:
                code = str(row.get("code") or "").strip().upper()
                vf = str(row.get("valid_from") or "")
                vu = str(row.get("valid_until") or "")
                if not _promo_calendar_active(vf, vu):
                    continue
                us = int(row.get("uses") or 0)
                mx = int(row.get("max_uses") or 0)
                if mx > 0 and us >= mx:
                    continue
                out.append(
                    {
                        "code": code,
                        "discount_percent": int(row.get("discount_percent") or 0),
                        "discount_eur": float(row.get("discount_eur") or 0),
                    }
                )
        pg_commit(conn)
    except Exception:
        if conn is not None:
            _pg_rollback(conn)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return out


def _discount_code_validate_for_checkout(code_raw: str) -> tuple[dict[str, Any] | None, str]:
    """
    PostgreSQL discount_codes (status ACTIVE) + SQLite-Fallback.
    Rückgabe: (row-dict, '') bei OK; (None, detail_key) bei Fehler.
    """
    pr = (code_raw or "").strip().upper()
    if not pr:
        return {}, ""
    conn = None
    try:
        conn = get_db_connection()
        _pg_ensure_discount_codes_table(conn)
        row = pg_fetchone(
            conn,
            """
            SELECT code, discount_percent, discount_eur, max_uses, uses,
                   valid_from, valid_until, status
            FROM discount_codes
            WHERE upper(trim(code)) = %s
            LIMIT 1;
            """,
            (pr,),
        )
        if row:
            st = str(row.get("status") or "").upper()
            if st != "ACTIVE":
                return None, "promo_invalid_expired"
            disc = int(row.get("discount_percent") or 0)
            mx = int(row.get("max_uses") or 0)
            us = int(row.get("uses") or 0)
            discount_eur = float(row.get("discount_eur") or 0)
            vf = str(row.get("valid_from") or "")
            vu = str(row.get("valid_until") or "")
            if us >= mx or not _promo_calendar_active(vf, vu):
                return None, "promo_invalid_expired"
            return {
                "code": pr,
                "discount_percent": disc,
                "discount_eur": discount_eur,
                "max_uses": mx,
                "uses": us,
                "valid_from": vf,
                "valid_until": vu,
            }, ""
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[PG] discount validate: {exc!r}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        srow = sconn.execute(
            """
            SELECT discount_percent, max_uses, uses,
                   coalesce(discount_eur, 0),
                   coalesce(valid_from, ''), coalesce(valid_until, '')
            FROM promo_codes WHERE upper(code) = upper(?);
            """,
            (pr,),
        ).fetchone()
    finally:
        sconn.close()
    if not srow:
        return None, "promo_invalid_expired"
    disc = int(srow[0] or 0)
    mx = int(srow[1] or 0)
    us = int(srow[2] or 0)
    discount_eur = float(srow[3] or 0)
    vf, vu = str(srow[4] or ""), str(srow[5] or "")
    if us >= mx or not _promo_calendar_active(vf, vu):
        return None, "promo_invalid_expired"
    return {
        "code": pr,
        "discount_percent": disc,
        "discount_eur": discount_eur,
        "max_uses": mx,
        "uses": us,
        "valid_from": vf,
        "valid_until": vu,
    }, ""


def _promo_checkout_error_message(request: Request, detail: str) -> str:
    lang = _web_lang(request)
    key = (detail or "promo_invalid").strip()
    if key == "promo_invalid_expired":
        return _web_tx(lang, "promo_err_invalid_expired")
    if key == "promo_expired":
        return _web_tx(lang, "promo_err_expired")
    if key == "promo_invalid":
        return _web_tx(lang, "promo_err_invalid")
    return _web_tx(lang, "promo_err_invalid_expired")


def _pg_export_all_user_emails() -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT lower(trim(email)) AS email,
                       trim(username) AS username,
                       trim(hardware_id) AS hardware_id,
                       lower(trim(COALESCE(selected_language, 'de'))) AS selected_language
                FROM users
                WHERE email IS NOT NULL AND trim(email) <> ''
                ORDER BY lower(trim(email));
                """
            )
            for r in cur.fetchall() or []:
                em = str(r.get("email") or "").strip()
                if "@" not in em:
                    continue
                rows.append(
                    {
                        "email": em[:200],
                        "username": str(r.get("username") or "")[:120],
                        "hardware_id": str(r.get("hardware_id") or "")[:128],
                        "lang": str(r.get("selected_language") or "de")[:8],
                    }
                )
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[export] PG emails: {exc!r}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    try:
        pconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            for em, pn, hw in pconn.execute(
                """
                SELECT lower(trim(email)), trim(pilot_name), trim(hardware_id)
                FROM web_pending_users
                WHERE email IS NOT NULL AND trim(email) <> '';
                """
            ).fetchall():
                em_s = str(em or "").strip()
                if "@" not in em_s:
                    continue
                if any(x["email"] == em_s for x in rows):
                    continue
                rows.append(
                    {
                        "email": em_s[:200],
                        "username": str(pn or "")[:120],
                        "hardware_id": str(hw or "")[:128],
                        "lang": "de",
                    }
                )
        finally:
            pconn.close()
    except sqlite3.Error:
        pass
    return rows


def _pg_canonical_user_hid(hardware_id: str, email: str = "") -> str:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return ""
    resolved = _web_resolve_postgres_hardware_id(email=email, sqlite_hid=hid)
    return str(resolved or hid).strip()[:128]


def _pg_read_has_seen_welcome(hardware_id: str, email: str = "") -> int:
    """1 = Intro bereits gesehen (nicht mehr anzeigen), 0 = einmalig anzeigen."""
    hid = _pg_canonical_user_hid(hardware_id, email)
    hid64 = hid[:64] if hid else ""
    if not hid64:
        return 1
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT COALESCE(has_seen_welcome, 0) AS has_seen_welcome
                FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                LIMIT 1;
                """,
                (hid, hid64),
            )
            row = cur.fetchone()
            if row is not None:
                return 1 if int(row["has_seen_welcome"] or 0) != 0 else 0
            em = str(email or "").strip().lower()[:200]
            if em and "@" in em:
                cur.execute(
                    """
                    SELECT COALESCE(has_seen_welcome, 0) AS has_seen_welcome
                    FROM users
                    WHERE lower(trim(email)) = %s
                    ORDER BY COALESCE(credits, money, 0) DESC NULLS LAST
                    LIMIT 1;
                    """,
                    (em,),
                )
                row = cur.fetchone()
                if row is not None:
                    return 1 if int(row["has_seen_welcome"] or 0) != 0 else 0
        return 0
    except psycopg2.Error:
        return 1
    finally:
        conn.close()


def _pg_set_has_seen_welcome(hardware_id: str, email: str = "", pilot_name: str = "") -> bool:
    hid = _pg_canonical_user_hid(hardware_id, email)
    if not hid:
        return False
    hid64 = hid[:64]
    em = str(email or "").strip().lower()[:200]
    pilot = str(pilot_name or "").strip()[:160] or hid[:16] or "Pilot"
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE users SET has_seen_welcome = 1
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (hid, hid64),
            )
            if cur.rowcount < 1 and em and "@" in em:
                cur.execute(
                    """
                    UPDATE users SET has_seen_welcome = 1
                    WHERE lower(trim(email)) = %s;
                    """,
                    (em,),
                )
            if cur.rowcount < 1:
                cur.execute(
                    """
                    INSERT INTO users (hardware_id, username, email, money, credits, license_status, has_seen_welcome)
                    VALUES (%s, %s, NULLIF(%s, ''), 0, 0, 'inactive', 1)
                    ON CONFLICT (hardware_id) DO UPDATE SET has_seen_welcome = 1;
                    """,
                    (hid, pilot, em),
                )
        conn.commit()
        return True
    except psycopg2.Error:
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        conn.close()


def _pg_user_prefs(hardware_id: str, email: str = "") -> dict[str, Any]:
    hid = _pg_canonical_user_hid(hardware_id, email)
    hid64 = hid[:64] if hid else ""
    if not hid64:
        return {"has_seen_welcome": 1, "selected_language": "de"}
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT COALESCE(has_seen_welcome, 0) AS has_seen_welcome,
                       COALESCE(NULLIF(trim(selected_language), ''), 'de') AS selected_language
                FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                LIMIT 1;
                """,
                (hid, hid64),
            )
            row = cur.fetchone()
            if not row:
                em = str(email or "").strip().lower()[:200]
                if em and "@" in em:
                    cur.execute(
                        """
                        SELECT COALESCE(has_seen_welcome, 0) AS has_seen_welcome,
                               COALESCE(NULLIF(trim(selected_language), ''), 'de') AS selected_language
                        FROM users
                        WHERE lower(trim(email)) = %s
                        LIMIT 1;
                        """,
                        (em,),
                    )
                    row = cur.fetchone()
        if not row:
            return {"has_seen_welcome": 0, "selected_language": "de"}
        lang = str(row["selected_language"] or "de").strip().lower()
        if lang not in ("de", "en"):
            lang = "de"
        seen = 1 if int(row["has_seen_welcome"] or 0) != 0 else 0
        return {
            "has_seen_welcome": seen,
            "selected_language": lang,
        }
    except psycopg2.Error:
        return {"has_seen_welcome": 1, "selected_language": "de"}
    finally:
        conn.close()


def _profile_snapshot_payload_extended(hid64: str, row: tuple[Any, ...]) -> dict[str, Any]:
    out = _profile_snapshot_payload(row)
    out["alliance"] = _user_alliance_summary(hid64)
    out["email"] = _portal_email_for_hardware(hid64)
    out["access_token"] = _web_issue_token(hid64)
    prefs = _pg_user_prefs(hid64)
    out["selected_language"] = prefs.get("selected_language", "de")
    out["has_seen_welcome"] = prefs.get("has_seen_welcome", 0)
    return out


def _sync_profile_full_pull_payload(
    hid64: str,
    row: tuple[Any, ...],
    body: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Vollständiges Desktop-Profilpaket (Meilenstein 181 — Daten-Vollstrom)."""
    hk = str(hid64 or "").strip()[:64]
    base = _profile_snapshot_payload(row)
    is_verified, has_license = _sync_user_license_flags(hk)
    portal_em = ""
    lic_key = ""
    if isinstance(body, dict):
        portal_em = str(
            body.get("portal_email") or body.get("customer_email") or body.get("email") or ""
        ).strip().lower()
        lic_key = str(body.get("license_key", "") or "").strip()
    pilot_name = _pilot_display_name_for_hid(hk, portal_em)
    email = _portal_email_for_hardware(hk)
    if portal_em and "@" in portal_em:
        email = portal_em
    alliance_full = _alliance_full_payload(hk, portal_em, lic_key)
    canonical_hid = str(alliance_full.get("canonical_hardware_id") or hk).strip()[:64]
    alliance_out: dict[str, Any] = {
        "in_alliance": bool(alliance_full.get("in_alliance")),
        "alliance_name": "",
        "role": "",
        "credits": 0.0,
        "alliance_credits": 0.0,
        "tax_rate": 0,
        "tax_pct": 0,
    }
    if alliance_full.get("in_alliance"):
        tax_v = int(float(alliance_full.get("tax_pct", 0) or 0))
        pool = float(alliance_full.get("alliance_credits", 0) or 0)
        hub_icaos = list(alliance_full.get("alliance_hubs") or [])
        alliance_out = {
            "in_alliance": True,
            "alliance_id": str(alliance_full.get("alliance_id", "")),
            "alliance_name": str(alliance_full.get("alliance_name", "")),
            "role": str(alliance_full.get("role", "")),
            "credits": pool,
            "alliance_credits": pool,
            "tax_rate": tax_v,
            "tax_pct": tax_v,
            "ceo_name": str(alliance_full.get("ceo_name", "")),
            "members": alliance_full.get("members") or [],
            "route_leases": alliance_full.get("route_leases") or [],
            "public_alliances": alliance_full.get("public_alliances") or [],
            "alliance_hubs": hub_icaos,
            "hub_icaos": hub_icaos,
        }
    else:
        alliance_out["public_alliances"] = alliance_full.get("public_alliances") or []
    scrapyard_open = 0
    scrapyard_count = 0
    try:
        sconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            scrapyard_count = int(
                sconn.execute(
                    "SELECT COUNT(*) FROM cloud_scrapyard WHERE buyer_hw_id IS NULL;"
                ).fetchone()[0]
                or 0
            )
            scrapyard_open = 1 if scrapyard_count > 0 else 0
        finally:
            sconn.close()
    except Exception:
        pass
    traffic_peers: list[dict[str, Any]] = []
    lat_q = body.get("lat") if isinstance(body, dict) else None
    lon_q = body.get("lon") if isinstance(body, dict) else None
    if lat_q is not None and lon_q is not None:
        try:
            la0 = float(lat_q)
            lo0 = float(lon_q)
            cutoff = time.time() - RADAR_FIDS_TTL_SEC
            rconn = sqlite3.connect(str(SERVER_DB_PATH))
            try:
                cur = rconn.execute(
                    """
                    SELECT hardware_id, pilot_name, lat, lon, alt, hdg, route, aircraft, ts
                    FROM radar_positions
                    WHERE ts >= ? AND hardware_id != ?;
                    """,
                    (cutoff, hk[:64]),
                )
                for r in cur.fetchall():
                    try:
                        dnm = _haversine_nm(la0, lo0, float(r[2]), float(r[3]))
                    except Exception:
                        continue
                    if dnm <= 50.0:
                        traffic_peers.append(
                            {
                                "id": str(r[0] or ""),
                                "pilot": str(r[1] or ""),
                                "lat": float(r[2] or 0),
                                "lon": float(r[3] or 0),
                                "alt": float(r[4] or 0),
                                "hdg": float(r[5] or 0),
                                "route": str(r[6] or ""),
                                "aircraft": str(r[7] or ""),
                                "dist_nm": round(dnm, 1),
                            }
                        )
            finally:
                rconn.close()
        except (TypeError, ValueError):
            pass
    branches_list = _sync_profile_branches_for_hid(hk)
    return {
        "status": "success",
        "ok": True,
        "pilot_name": pilot_name,
        "username": pilot_name,
        "pilot_display_name": pilot_name,
        "email": email,
        "hardware_id": canonical_hid,
        "credits": float(base.get("credits", 0) or 0),
        "xp": float(base.get("xp", 0) or 0),
        "reputation": float(base.get("reputation", 0) or 0),
        "has_license": int(has_license),
        "is_verified": int(is_verified),
        "bank_loans": float(base.get("bank_loans", 0) or 0),
        "anti_cheat_strikes": int(base.get("anti_cheat_strikes", 0) or 0),
        "credit_score": float(base.get("credit_score", 0) or 0),
        "active_global_news": str(base.get("active_global_news", "") or ""),
        "alliance": alliance_out,
        "access_token": _web_issue_token(hk),
        "logo_url": f"/api/v1/user/profile/download_logo/{hk}",
        "scrapyard": {
            "open": scrapyard_open,
            "listings_available": scrapyard_count,
        },
        "traffic_3d_peers": traffic_peers,
        "msfs_pro_unlock": bool(has_license),
        "branches": branches_list,
        "branches_json": json.dumps(branches_list, ensure_ascii=False),
    }


