def _job_board_payout(distance_nm: float, cargo_lbs: int, dep: str, arr: str) -> float:
    pay = float(distance_nm) * 12.5 + float(cargo_lbs) * 0.05
    if dep in JOB_BOARD_HUB_ICAOS or arr in JOB_BOARD_HUB_ICAOS:
        pay *= JOB_BOARD_HUB_PAY_MULT
    return max(250.0, round(pay, 0))


def _icao_coord_map() -> dict[str, tuple[float, float]]:
    import sky_dispatch_engine as dispatch_eng

    merged = dict(GLOBAL_AIRPORT_COORDS)
    merged.update(dispatch_eng.NAV_NODES)
    return merged


def _custom_route_distance_nm(dep: str, arr: str) -> tuple[float, list[str], str]:
    """Seemeilen + Wegpunkte (A* oder Direktstrecke zwischen bekannten ICAOs)."""
    import sky_dispatch_engine as dispatch_eng

    dep_u = str(dep or "").strip().upper()[:4]
    arr_u = str(arr or "").strip().upper()[:4]
    if not dep_u or not arr_u:
        return 0.0, [], "missing"
    if dep_u == arr_u:
        return 0.0, [dep_u], "same"
    routed = dispatch_eng.astar_route(dep_u, arr_u)
    if routed:
        path, dist = routed
        return float(dist), list(path), "astar"
    coords = _icao_coord_map()
    if dep_u in coords and arr_u in coords:
        la1, lo1 = coords[dep_u]
        la2, lo2 = coords[arr_u]
        dist = dispatch_eng.haversine_nm(la1, lo1, la2, lo2)
        return float(dist), [dep_u, arr_u], "direct"
    return 0.0, [], "unknown"


def _custom_route_rewards(
    distance_nm: float,
    *,
    aircraft_model: str = "",
    passengers: int = 78,
    dep: str = "",
    arr: str = "",
) -> dict[str, float]:
    import sky_dispatch_pro as sdp

    dist = max(0.0, float(distance_nm))
    pax = max(0, min(400, int(passengers or 78)))
    profile = sdp.aircraft_profile_for_model(aircraft_model)
    cls = str(profile.get("class", "jet"))
    class_mult = {
        "jet": 1.0,
        "turboprop": 0.82,
        "piston": 0.55,
        "heli": 0.45,
        "cargo": 1.05,
    }.get(cls, 1.0)
    cargo_lbs = pax * 180
    base_credits = _job_board_payout(dist, cargo_lbs, dep, arr) * class_mult
    credits = max(250.0, round(base_credits, 2))
    xp_miles = round(dist, 2)
    return {
        "credits_base": credits,
        "xp_miles_base": xp_miles,
        "credits_with_bonus": round(credits * 1.15, 2),
        "xp_miles_with_bonus": round(xp_miles * 1.15, 2),
        "dispatch_bonus_pct": 15.0,
    }


