def _archive_ofp_history_pg(
    conn,
    *,
    hardware_id: str,
    username: str,
    plan: dict[str, Any],
) -> int:
    _ensure_sky_ofp_history_table(conn)
    payload = json.dumps(plan, ensure_ascii=False)[:500_000]
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO sky_ofp_history (
                hardware_id, username, dep_icao, arr_icao, distance_nm, payload_json, created_ts
            ) VALUES (%s,%s,%s,%s,%s,%s,%s)
            RETURNING id;
            """,
            (
                str(hardware_id)[:128],
                str(username or "Pilot")[:80],
                str(plan.get("dep_icao") or "")[:8],
                str(plan.get("arr_icao") or "")[:8],
                float(plan.get("distance_nm") or 0),
                payload,
                time.time(),
            ),
        )
        row = cur.fetchone()
    conn.commit()
    return int(row[0]) if row else 0


def _enroute_alternates_for_path(
    path: list[str], *, interval_nm: float = 200.0
) -> list[dict[str, Any]]:
    import sky_dispatch_engine as dispatch_eng

    if len(path) < 2:
        return []
    coords = _icao_coord_map()
    alts: list[dict[str, Any]] = []
    acc = 0.0
    for i in range(len(path) - 1):
        a, b = path[i], path[i + 1]
        if a in coords and b in coords:
            acc += dispatch_eng.haversine_nm(coords[a][0], coords[a][1], coords[b][0], coords[b][1])
        while acc >= interval_nm:
            acc -= interval_nm
            best_icao = ""
            best_nm = 1e9
            ref = coords.get(b) or coords.get(a)
            if not ref:
                continue
            for icao, (la, lo) in coords.items():
                if icao in (a, b):
                    continue
                d = dispatch_eng.haversine_nm(ref[0], ref[1], la, lo)
                if d < best_nm:
                    best_nm = d
                    best_icao = icao
            if best_icao:
                alts.append(
                    {
                        "icao": best_icao,
                        "distance_nm": round(best_nm, 1),
                        "at_waypoint": b,
                        "cumulative_nm": round(interval_nm * (len(alts) + 1), 1),
                    }
                )
    return alts


def _ensure_route_statistics_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS route_statistics (
                route_key VARCHAR(16) PRIMARY KEY,
                origin VARCHAR(8) NOT NULL DEFAULT '',
                destination_icao VARCHAR(8) NOT NULL DEFAULT '',
                flight_count INTEGER NOT NULL DEFAULT 0
            );
            """
        )
        cur.execute(
            "CREATE INDEX IF NOT EXISTS idx_route_statistics_count ON route_statistics (flight_count DESC);"
        )
    conn.commit()


def _route_statistics_key(dep: str, arr: str) -> str:
    return f"{str(dep or '').upper()[:4]}-{str(arr or '').upper()[:4]}"


def _bump_route_statistics(conn, dep: str, arr: str) -> None:
    dep_u = str(dep or "").upper()[:4]
    arr_u = str(arr or "").upper()[:4]
    if not dep_u or not arr_u:
        return
    _ensure_route_statistics_table(conn)
    key = _route_statistics_key(dep_u, arr_u)
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO route_statistics (route_key, origin, destination_icao, flight_count)
            VALUES (%s, %s, %s, 1)
            ON CONFLICT (route_key) DO UPDATE SET
                flight_count = route_statistics.flight_count + 1,
                origin = EXCLUDED.origin,
                destination_icao = EXCLUDED.destination_icao;
            """,
            (key, dep_u, arr_u),
        )
    conn.commit()


def _popular_routes_json(limit: int = 10) -> list[dict[str, Any]]:
    conn = get_db_connection()
    try:
        _ensure_route_statistics_table(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT route_key, origin, destination_icao, flight_count
                FROM route_statistics
                ORDER BY flight_count DESC, route_key ASC
                LIMIT %s;
                """,
                (max(1, min(50, int(limit))),),
            )
            rows = cur.fetchall()
        return [
            {
                "route_key": str(r["route_key"]),
                "origin": str(r["origin"]),
                "destination_icao": str(r["destination_icao"]),
                "flight_count": int(r["flight_count"] or 0),
            }
            for r in rows
        ]
    finally:
        conn.close()


def _ensure_global_job_board_minimum_open(minimum: int = 280) -> int:
    """Regeneriert den Markt, wenn zu wenige offene Cloud-Jobs existieren."""
    open_n = _global_job_board_open_count()
    if open_n >= minimum:
        return open_n
    return _regenerate_global_job_board(max(minimum, 400))


def _regenerate_global_job_board(count: int = 400) -> int:
    """Löscht offene Jobs und generiert weltweite Cloud-Aufträge (Bulk-Insert, eine Verbindung)."""
    _ensure_global_job_board_table()
    europe_focus = ["EDDF", "LEPA", "EGLL", "LSZH"]
    hub_pool = list(JOB_BOARD_HUB_ICAOS) + [
        "EDDF",
        "LEPA",
        "EGLL",
        "LSZH",
        "LSZH",
        "EDDF",
        "EGLL",
        "KJFK",
        "LOWW",
        "LFPG",
        "EDDM",
        "EHAM",
    ]
    icaos = list(dict.fromkeys(hub_pool + list(GLOBAL_AIRPORT_COORDS.keys())))
    if len(icaos) < 4:
        return 0
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    target = max(280, int(count))
    rng = random.Random(int(time.time()) // 86400)
    rows: list[tuple[str, str, float, int, float, str, str]] = []
    tries_cap = target * 4
    while len(rows) < target and tries_cap > 0:
        tries_cap -= 1
        roll = rng.random()
        if roll < 0.18:
            jtype = "VIP_HUB"
            dep = rng.choice(europe_focus if rng.random() < 0.55 else list(JOB_BOARD_HUB_ICAOS))
            arr_choices = [h for h in hub_pool if h != dep]
            arr = rng.choice(arr_choices) if arr_choices else rng.choice(icaos)
        elif roll < 0.55:
            jtype = "PAX"
            dep = rng.choice(europe_focus if rng.random() < 0.45 else icaos)
            arr = dep
            t = 0
            while arr == dep and t < 25:
                arr = rng.choice(europe_focus if rng.random() < 0.45 else icaos)
                t += 1
        else:
            jtype = "CARGO"
            dep = rng.choice(europe_focus if rng.random() < 0.35 else icaos)
            arr = dep
            t = 0
            while arr == dep and t < 25:
                arr = rng.choice(icaos)
                t += 1
        if dep not in GLOBAL_AIRPORT_COORDS or arr not in GLOBAL_AIRPORT_COORDS:
            continue
        la1, lo1 = GLOBAL_AIRPORT_COORDS[dep]
        la2, lo2 = GLOBAL_AIRPORT_COORDS[arr]
        dist = _haversine_nm(la1, lo1, la2, lo2)
        if dist < 45.0:
            continue
        if jtype == "VIP_HUB":
            cargo_lbs = rng.randint(390, 2340)
            pay = max(250.0, round(dist * 25.0 + 5000.0, 0))
        elif jtype == "CARGO":
            cargo_lbs = rng.randint(5_000, 45_000)
            pay = max(250.0, round(dist * 8.5 + cargo_lbs * 0.08, 0))
            if dep in JOB_BOARD_HUB_ICAOS or arr in JOB_BOARD_HUB_ICAOS:
                pay = round(pay * JOB_BOARD_HUB_PAY_MULT, 0)
        else:
            pax = rng.randint(40, 180)
            cargo_lbs = int(pax * 195)
            pay = _job_board_payout(dist, cargo_lbs, dep, arr)
        rows.append((dep, arr, round(dist, 1), cargo_lbs, pay, jtype, now))
    # Mindestens 6 Abflüge pro großem Hub — damit lokale ICAO-Suche nicht leer bleibt
    for hub in list(JOB_BOARD_HUB_ICAOS) + ["EDDF", "LEPA", "EGLL", "LSZH", "KJFK"]:
        if hub not in GLOBAL_AIRPORT_COORDS:
            continue
        for _ in range(6):
            arr = rng.choice([c for c in icaos if c != hub])
            if arr not in GLOBAL_AIRPORT_COORDS:
                continue
            la1, lo1 = GLOBAL_AIRPORT_COORDS[hub]
            la2, lo2 = GLOBAL_AIRPORT_COORDS[arr]
            dist = _haversine_nm(la1, lo1, la2, lo2)
            if dist < 45.0:
                continue
            jtype = rng.choice(["PAX", "CARGO", "VIP_HUB"])
            if jtype == "VIP_HUB":
                cargo_lbs = rng.randint(390, 2340)
                pay = max(250.0, round(dist * 25.0 + 5000.0, 0))
            elif jtype == "CARGO":
                cargo_lbs = rng.randint(5_000, 45_000)
                pay = max(250.0, round(dist * 8.5 + cargo_lbs * 0.08, 0))
            else:
                pax = rng.randint(40, 180)
                cargo_lbs = int(pax * 195)
                pay = _job_board_payout(dist, cargo_lbs, hub, arr)
            rows.append((hub, arr, round(dist, 1), cargo_lbs, pay, jtype, now))
    if not rows:
        return 0
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE;")
        conn.execute("DELETE FROM global_job_board WHERE status = 'open';")
        conn.executemany(
            """
            INSERT INTO global_job_board (
                departure_icao, arrival_icao, distance_nm, cargo_weight_lbs,
                payout_credits, job_type, generated_at, status
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 'open');
            """,
            rows,
        )
        conn.commit()
        return len(rows)
    except sqlite3.Error:
        conn.rollback()
        raise
    finally:
        conn.close()


def _seconds_until_next_utc_midnight() -> float:
    now = datetime.now(timezone.utc)
    nxt = (now + timedelta(days=1)).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    return max(60.0, (nxt - now).total_seconds())


async def _global_job_board_daily_loop() -> None:
    while True:
        await asyncio.sleep(_seconds_until_next_utc_midnight())
        try:
            n = await asyncio.to_thread(_regenerate_global_job_board, 120)
            _append_admin_log(f"[job_board] UTC-Tages-Refresh: {n} Aufträge.")
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[job_board] daily refresh failed: {exc!s}")


PLATIN_HAUL_NM_THRESHOLD = 1500.0
_CRISIS_TYPES = (
    ("snowstorm", "Schneesturm", "Snow storm"),
    ("typhoon", "Taifun", "Typhoon"),
    ("ash_cloud", "Aschewolke", "Ash cloud"),
)


def _ensure_pg_short_haul_job_board_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS short_haul_job_board (
                job_id SERIAL PRIMARY KEY,
                departure_icao VARCHAR(8) NOT NULL,
                arrival_icao VARCHAR(8) NOT NULL,
                distance_nm DOUBLE PRECISION NOT NULL,
                cargo_weight_lbs INTEGER NOT NULL DEFAULT 0,
                payout_credits DOUBLE PRECISION NOT NULL,
                job_type VARCHAR(32) NOT NULL,
                title_de TEXT NOT NULL DEFAULT '',
                title_en TEXT NOT NULL DEFAULT '',
                generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                status VARCHAR(16) NOT NULL DEFAULT 'open',
                accepted_by VARCHAR(128) NOT NULL DEFAULT ''
            );
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS long_haul_job_board (
                job_id SERIAL PRIMARY KEY,
                departure_icao VARCHAR(8) NOT NULL,
                arrival_icao VARCHAR(8) NOT NULL,
                distance_nm DOUBLE PRECISION NOT NULL,
                cargo_weight_lbs INTEGER NOT NULL DEFAULT 0,
                payout_credits DOUBLE PRECISION NOT NULL,
                job_type VARCHAR(32) NOT NULL,
                title_de TEXT NOT NULL DEFAULT '',
                title_en TEXT NOT NULL DEFAULT '',
                generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                status VARCHAR(16) NOT NULL DEFAULT 'open',
                accepted_by VARCHAR(128) NOT NULL DEFAULT ''
            );
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS global_crisis_events (
                id SERIAL PRIMARY KEY,
                airport_icao VARCHAR(8) NOT NULL,
                crisis_type VARCHAR(64) NOT NULL,
                intensity DOUBLE PRECISION NOT NULL DEFAULT 1.0,
                expires_at TIMESTAMPTZ NOT NULL,
                language VARCHAR(8) NOT NULL DEFAULT 'de',
                title_de TEXT NOT NULL DEFAULT '',
                title_en TEXT NOT NULL DEFAULT '',
                created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
            );
            """
        )
    conn.commit()


def _regenerate_short_haul_pg(count: int = 220) -> int:
    """Kurzstrecke < 1500 NM — PostgreSQL, i18n-Titel."""
    conn = get_db_connection()
    try:
        _ensure_pg_short_haul_job_board_table(conn)
        rng = random.Random(int(time.time()) // 86400)
        icaos = list(GLOBAL_AIRPORT_COORDS.keys())
        rows: list[tuple[Any, ...]] = []
        tries = max(400, count * 4)
        now = datetime.now(timezone.utc)
        while len(rows) < count and tries > 0:
            tries -= 1
            dep = rng.choice(icaos)
            arr = rng.choice(icaos)
            if dep == arr:
                continue
            la1, lo1 = GLOBAL_AIRPORT_COORDS[dep]
            la2, lo2 = GLOBAL_AIRPORT_COORDS[arr]
            dist = _haversine_nm(la1, lo1, la2, lo2)
            if dist < 45.0 or dist >= PLATIN_HAUL_NM_THRESHOLD:
                continue
            jtype = rng.choice(["PAX", "CARGO", "PAX"])
            if jtype == "CARGO":
                cargo_lbs = rng.randint(3_000, 28_000)
                pay = max(250.0, round(dist * 9.0 + cargo_lbs * 0.07, 0))
            else:
                cargo_lbs = rng.randint(40, 160) * 195
                pay = _job_board_payout(dist, cargo_lbs, dep, arr)
            title_de = f"{dep}→{arr} · {int(dist)} NM · Kurzstrecke"
            title_en = f"{dep}→{arr} · {int(dist)} NM · Short haul"
            rows.append(
                (
                    dep,
                    arr,
                    round(dist, 1),
                    int(cargo_lbs),
                    float(pay),
                    jtype,
                    title_de,
                    title_en,
                    now,
                )
            )
        with conn.cursor() as cur:
            cur.execute("DELETE FROM short_haul_job_board WHERE status = 'open';")
            if rows:
                cur.executemany(
                    """
                    INSERT INTO short_haul_job_board (
                        departure_icao, arrival_icao, distance_nm, cargo_weight_lbs,
                        payout_credits, job_type, title_de, title_en, generated_at, status
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, 'open');
                    """,
                    rows,
                )
        conn.commit()
        return len(rows)
    except Exception as exc:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:  # noqa: BLE001
            pass
        _server_log_line(f"[short_haul] regenerate failed: {exc!s}")
        return 0
    finally:
        conn.close()


