def _platin_midnight_utc_reset() -> tuple[int, int, int]:
    """00:00 UTC — Kurz- + Langstrecken-Boards + Krisen."""
    n_short = _regenerate_short_haul_pg(240)
    n_long = _regenerate_long_haul_pg(180)
    crises = _spawn_global_crisis_events(5)
    _dispatch_crisis_alerts(crises)
    return n_short, n_long, len(crises)


def _spawn_global_crisis_events(count: int = 4) -> list[dict[str, Any]]:
    conn = get_db_connection()
    out: list[dict[str, Any]] = []
    try:
        _ensure_pg_short_haul_job_board_table(conn)
        rng = random.Random()
        icaos = list(GLOBAL_AIRPORT_COORDS.keys())
        now = datetime.now(timezone.utc)
        with conn.cursor() as cur:
            for _ in range(max(1, min(8, count))):
                icao = rng.choice(icaos)
                ctype, de_t, en_t = rng.choice(_CRISIS_TYPES)
                intensity = round(rng.uniform(0.55, 1.0), 2)
                exp = now + timedelta(hours=rng.randint(6, 36))
                cur.execute(
                    """
                    INSERT INTO global_crisis_events (
                        airport_icao, crisis_type, intensity, expires_at,
                        language, title_de, title_en
                    ) VALUES (%s, %s, %s, %s, 'de', %s, %s)
                    RETURNING id, airport_icao, crisis_type, intensity, expires_at, title_de, title_en;
                    """,
                    (
                        icao,
                        ctype,
                        intensity,
                        exp,
                        f"{de_t} @ {icao}",
                        f"{en_t} @ {icao}",
                    ),
                )
                row = cur.fetchone()
                if row:
                    out.append(
                        {
                            "id": row[0],
                            "airport_icao": row[1],
                            "crisis_type": row[2],
                            "intensity": float(row[3]),
                            "expires_at": row[4].isoformat()
                            if hasattr(row[4], "isoformat")
                            else str(row[4]),
                            "title_de": row[5],
                            "title_en": row[6],
                        }
                    )
        conn.commit()
    except Exception as exc:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:  # noqa: BLE001
            pass
        _server_log_line(f"[crisis] spawn failed: {exc!s}")
    finally:
        conn.close()
    return out


def _dispatch_crisis_alerts(events: list[dict[str, Any]]) -> None:
    if not events:
        return
    queue = APP_ROOT / "server_logs" / "crisis_discord_queue.jsonl"
    try:
        queue.parent.mkdir(parents=True, exist_ok=True)
        with queue.open("a", encoding="utf-8") as fh:
            for ev in events:
                fh.write(json.dumps(ev, ensure_ascii=False) + "\n")
    except OSError as exc:
        _server_log_line(f"[crisis] queue write: {exc!s}")
    try:
        host, port, user, pw, sender = _smtp_settings()
        if not host or not user:
            return
        subj = "SkyTycoon KRISEN-ALARM / CRISIS ALERT"
        lines = []
        for ev in events:
            lines.append(
                f"{ev.get('title_de')} / {ev.get('title_en')} "
                f"(ICAO {ev.get('airport_icao')}, Intensität {ev.get('intensity')})"
            )
        body = "\n".join(lines)
        msg = (
            f"From: {sender}\r\nTo: info@skytycoon.info\r\n"
            f"Subject: {subj}\r\n\r\n{body}\r\n"
        )
        with smtplib.SMTP(host, port, timeout=20) as smtp:
            smtp.starttls()
            smtp.login(user, pw)
            smtp.sendmail(sender, ["info@skytycoon.info"], msg.encode("utf-8"))
    except Exception as exc:  # noqa: BLE001
        _server_log_line(f"[crisis] smtp: {exc!s}")


async def _short_haul_midnight_utc_loop() -> None:
    """00:00 UTC: Kurzstrecken + Langstrecken + Krisen (PostgreSQL)."""
    while True:
        await asyncio.sleep(_seconds_until_next_utc_midnight())
        try:
            n_short, n_long, n_cr = await asyncio.to_thread(_platin_midnight_utc_reset)
            _append_admin_log(
                f"[job_board] UTC 00:00 reset: {n_short} short, {n_long} long, "
                f"{n_cr} crises."
            )
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[job_board] midnight UTC failed: {exc!s}")


def _fetch_active_crisis_events() -> list[dict[str, Any]]:
    conn = get_db_connection()
    try:
        _ensure_pg_short_haul_job_board_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, airport_icao, crisis_type, intensity, expires_at,
                       title_de, title_en
                FROM global_crisis_events
                WHERE expires_at > NOW()
                ORDER BY intensity DESC, expires_at ASC
                LIMIT 80;
                """
            )
            rows = cur.fetchall() or []
        out: list[dict[str, Any]] = []
        coords = _icao_coord_map()
        for row in rows:
            icao = str(row[1] or "").upper()[:4]
            lat_lon = coords.get(icao)
            if not lat_lon:
                continue
            la, lo = lat_lon
            out.append(
                {
                    "id": int(row[0]),
                    "airport_icao": icao,
                    "crisis_type": str(row[2] or ""),
                    "intensity": float(row[3] or 0),
                    "expires_at": row[4].isoformat()
                    if hasattr(row[4], "isoformat")
                    else str(row[4]),
                    "title_de": str(row[5] or ""),
                    "title_en": str(row[6] or ""),
                    "lat": la,
                    "lon": lo,
                    "radius_km": int(40 + 90 * float(row[3] or 0.5)),
                }
            )
        return out
    except Exception as exc:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:  # noqa: BLE001
            pass
        _server_log_line(f"[crisis] fetch active: {exc!s}")
        return []
    finally:
        conn.close()


def _job_board_row_to_client(row: tuple[Any, ...]) -> dict[str, Any]:
    """Desktop-Job-Zeile mit allen JSON-Key-Varianten (dep/departure_icao/origin …)."""
    jid, dep, arr, dist, cargo_lbs, pay, jtype = row[:7]
    dist_f = float(dist or 0)
    cargo_i = int(cargo_lbs or 0)
    jtype_u = str(jtype or "").upper()
    is_cargo = jtype_u in ("CARGO", "AIRCARGO")
    is_vip = "VIP" in jtype_u
    req = random.choice(JOB_BOARD_MODELS)
    lvl = 1 if dist_f < 800 else 2 if dist_f < 3500 else 3
    dep_c = str(dep or "").upper()[:4]
    arr_c = str(arr or "").upper()[:4]
    pay_f = float(pay or 0)
    out: dict[str, Any] = {
        "id": f"GJ-{int(jid)}",
        "job_id": int(jid),
        "server_job_id": int(jid),
        "typ": "CARGO" if is_cargo else "PAX",
        "job_type": jtype_u,
        "type": jtype_u,
        "dep": dep_c,
        "arr": arr_c,
        "departure_icao": dep_c,
        "arrival_icao": arr_c,
        "origin": dep_c,
        "destination": arr_c,
        "dist_nm": round(dist_f, 1),
        "distance_nm": round(dist_f, 1),
        "reward": pay_f,
        "reward_base": pay_f,
        "payout_credits": pay_f,
        "credits": pay_f,
        "cargo_weight_lbs": cargo_i,
        "weight": cargo_i,
        "min_level": lvl,
        "req_model": req,
        "express": bool(is_vip),
        "hub_exclusive": bool(is_vip),
        "cloud_job": True,
    }
    if is_cargo:
        out["cargo_kg"] = round(cargo_i * 0.453592, 0)
        out["pax"] = 0
    else:
        out["pax"] = max(1, int(cargo_i / 195))
        out["cargo_kg"] = 0.0
    return out


def _apply_top5_premium_bonus(jobs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    top_ids = {
        int(j.get("job_id") or j.get("server_job_id") or 0)
        for j in sorted(
            jobs,
            key=lambda x: float(x.get("payout_credits") or x.get("reward") or 0),
            reverse=True,
        )[:5]
    }
    out: list[dict[str, Any]] = []
    for j in jobs:
        row = dict(j)
        jid = int(row.get("job_id") or row.get("server_job_id") or 0)
        if jid in top_ids:
            base = float(row.get("reward_base") or row.get("payout_credits") or 0)
            premium = round(base * 1.30, 0)
            row.update(
                {
                    "top5_premium_event": True,
                    "event_label": "⭐ TOP 5 PREMIUM EVENT",
                    "premium_bonus_pct": 30,
                    "reward_base": base,
                    "reward": premium,
                    "payout_credits": premium,
                    "credits": premium,
                }
            )
        else:
            row["top5_premium_event"] = False
        out.append(row)
    return out


def _append_admin_log(line: str) -> None:
    try:
        ADMIN_ACTIONS_LOG.parent.mkdir(parents=True, exist_ok=True)
        with ADMIN_ACTIONS_LOG.open("a", encoding="utf-8", errors="replace") as lf:
            lf.write(line.rstrip() + "\n")
    except OSError:
        pass


def _server_log_line(line: str) -> None:
    """Kurze Zeile in ``server_logs/server.log`` (IONOS-Mail-/SMTP-Diagnose)."""
    p = APP_ROOT / "server_logs" / "server.log"
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        with p.open("a", encoding="utf-8", errors="replace") as lf:
            lf.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} {line.rstrip()}\n")
    except OSError:
        pass


def _smtp_open_connection(
    smtp_host: str,
    smtp_port: int,
    smtp_user: str,
    smtp_password: str,
    *,
    timeout: int = 10,
) -> smtplib.SMTP | smtplib.SMTP_SSL:
    """IONOS-Ausweichkanal: Port 587 + STARTTLS (465 oft für vServer-IPs gesperrt)."""
    host = (smtp_host or "smtp.ionos.de").strip()
    port = int(smtp_port or 587)
    ctx = ssl.create_default_context()
    if port == 465:
        srv_ssl = smtplib.SMTP_SSL(host, 465, timeout=timeout, context=ctx)
        srv_ssl.login(smtp_user, smtp_password)
        return srv_ssl
    use_port = port if port not in (0, 25) else 587
    srv = smtplib.SMTP(host, use_port, timeout=timeout)
    srv.ehlo()
    srv.starttls(context=ctx)
    srv.ehlo()
    srv.login(smtp_user, smtp_password)
    return srv


def _smtp_deliver_message(
    msg: MIMEMultipart, mail_from: str, recipients: list[str]
) -> None:
    """IONOS: bevorzugt Port 587 + STARTTLS (umgeht vServer-Block auf 465)."""
    smtp_host, smtp_port, smtp_user, smtp_password, smtp_from_default = _smtp_settings()
    if not smtp_host or not smtp_user or not smtp_password:
        print("[SMTP ERROR] Keine Zugangsdaten (SKYTYCOON_SMTP_* / smtp.env)!")
        raise RuntimeError("smtp_missing_config")
    if not (mail_from or "").strip():
        mail_from = smtp_from_default
    srv: smtplib.SMTP | smtplib.SMTP_SSL | None = None
    try:
        srv = _smtp_open_connection(
            smtp_host, int(smtp_port), smtp_user, smtp_password, timeout=10
        )
        srv.sendmail(mail_from, recipients, msg.as_string())
    finally:
        if srv is not None:
            try:
                srv.quit()
            except Exception:
                try:
                    srv.close()
                except Exception:
                    pass


def _smtp_deliver_message_ok(
    msg: MIMEMultipart, mail_from: str, recipients: list[str]
) -> bool:
    try:
        _smtp_deliver_message(msg, mail_from, recipients)
        return True
    except Exception:
        return False


