_SMTP_RETRY_DELAYS_SEC = (5.0, 15.0, 30.0)


def _run_email_with_retry(send_fn, *args, **kwargs) -> bool:
    """M191/M192: bis zu drei SMTP-Versuche (5 s / 15 s / 30 s Pause)."""
    label = getattr(send_fn, "__name__", "email")
    delays = _SMTP_RETRY_DELAYS_SEC
    for attempt, delay_before in enumerate(delays, start=1):
        if delay_before > 0 and attempt > 1:
            time.sleep(delay_before)
        try:
            if bool(send_fn(*args, **kwargs)):
                if attempt > 1:
                    print(f"[SMTP RETRY OK] {label} (Versuch {attempt})")
                    _append_admin_log(f"[email] Retry OK ({label}, Versuch {attempt})")
                return True
        except Exception as exc:  # noqa: BLE001
            _server_log_line(
                f"[email] {label} Versuch {attempt} Exception: {exc!r}"
            )
    print(f"[SMTP RETRY FAIL] {label} (alle Versuche)")
    _append_admin_log(f"[email] endgültig fehlgeschlagen ({label})")
    return False


