def _purchase_email_language(
    to_email: str, hardware_id: str = "", lang_hint: str = ""
) -> str:
    """DE/EN: Request-Hint zuerst, dann PostgreSQL ``selected_language``."""
    hint = str(lang_hint or "").strip().lower()[:8]
    if hint in ("de", "en"):
        return hint
    prefs = _pg_user_prefs(hardware_id, to_email)
    lang = str(prefs.get("selected_language") or "de").strip().lower()
    return "en" if lang.startswith("en") else "de"


def _bind_unused_shop_license_to_hwid(
    email: str,
    hardware_id: str,
    pilot_name: str = "",
    password: str = "",
) -> tuple[bool, str]:
    """
    Shop-Key (status unused, leere HWID) → sofort activated + HWID-Bindung (SQLite + PG).
    """
    em = str(email or "").strip().lower()[:200]
    hid_use = str(hardware_id or "").strip()[:128]
    hid64 = hid_use[:64]
    pilot = str(pilot_name or "").strip()[:120]
    if not em or "@" not in em or not hid64:
        return False, ""
    if not _email_registered_on_hwid(em, hid_use):
        slot_ok, _slot_err = _hwid_triple_slot_allows(em, hid_use)
        if not slot_ok:
            return False, ""
    if not pilot:
        pilot = em.split("@", 1)[0][:120]
    lk_out = ""
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = sconn.execute(
            """
            SELECT license_key, status, hardware_id, password_salt, password_hash, pilot_name
            FROM license_keys
            WHERE lower(trim(customer_email)) = ?
              AND upper(trim(license_key)) LIKE 'ST-%'
            ORDER BY CASE lower(trim(status)) WHEN 'unused' THEN 0 ELSE 1 END,
                     created_ts DESC
            LIMIT 1;
            """,
            (em,),
        ).fetchone()
        if not row:
            return False, ""
        lk_out = str(row[0] or "").strip()
        st = str(row[1] or "").strip().lower()
        bound = str(row[2] or "").strip()
        salt_old = str(row[3] or "")
        ph_old = str(row[4] or "")
        pilot_db = str(row[5] or pilot).strip()[:120] or pilot
        if not lk_out:
            return False, ""
        if st == "activated":
            if bound and bound != hid_use and bound[:64] != hid64:
                if not _login_placeholder_hardware_for_bonding(bound):
                    ok_hw, _ = _email_hwid_has_active_license(em, hid_use)
                    return (ok_hw, lk_out) if ok_hw else (False, "")
            if bound != hid_use:
                sconn.execute(
                    """
                    UPDATE license_keys SET hardware_id = ?, pilot_name = ?
                    WHERE license_key = ?;
                    """,
                    (hid_use, pilot_db, lk_out),
                )
                sconn.commit()
            return True, lk_out
        if st != "unused":
            return False, ""
        if bound and not _login_placeholder_hardware_for_bonding(bound):
            return False, ""
        salt, ph = salt_old, ph_old
        if password:
            salt, ph = _password_hash_store(password)
        sconn.execute(
            """
            UPDATE license_keys SET status = 'activated', hardware_id = ?,
            pilot_name = ?, password_salt = ?, password_hash = ?,
            customer_email = ?
            WHERE license_key = ?;
            """,
            (hid_use, pilot_db, salt, ph, em, lk_out),
        )
        sconn.execute(
            """
            UPDATE keys SET status = 'activated', customer_email = ?
            WHERE license_key = ?;
            """,
            (em, lk_out),
        )
        sconn.commit()
    except Exception as exc_sql:  # noqa: BLE001
        try:
            sconn.rollback()
        except Exception:
            pass
        _server_log_line(f"[license] auto-bind SQLite failed: {exc_sql!s}")
        return False, ""
    finally:
        sconn.close()
    try:
        lang = _purchase_email_language(em, hid_use)
        _pg_bind_license_to_email_account(
            em, lk_out, pilot_db, hid_use, license_row_status="activated", selected_language=lang
        )
        _pg_bind_license_to_hardware(em, hid_use, lk_out, pilot_db)
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[license] auto-bind PG failed: {exc_pg!s}")
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hid64,),
        )
        uconn.execute(
            """
            UPDATE users SET license_key = ?, license_activated = 1, has_license = 1,
            is_verified = 1
            WHERE hardware_id = ?;
            """,
            (lk_out, hid64),
        )
        uconn.commit()
    finally:
        uconn.close()
    try:
        _sync_user_license_flags(hid64)
    except Exception:
        pass
    _append_admin_log(
        f"[license] auto-bind email={em!r} hid={hid64!r} key={lk_out}"
    )
    return True, lk_out


def _attach_pdf_to_mime_message(
    msg: Any, pdf_bytes: bytes | None, pdf_fname: str, *, pdf_path: Path | None = None
) -> bool:
    """PDF als application/pdf anhängen (MIMEBase + Retry bei Dateisperre)."""
    from email import encoders
    from email.mime.base import MIMEBase

    data = pdf_bytes
    if (not data or len(data) < 32) and pdf_path is not None and pdf_path.is_file():
        for _ in range(6):
            try:
                with open(pdf_path, "rb") as fh:
                    data = fh.read()
                break
            except (PermissionError, OSError):
                time.sleep(0.05)
    if not data or len(data) < 32:
        return False
    part = MIMEBase("application", "pdf")
    part.set_payload(data)
    try:
        del data
    except Exception:
        pass
    encoders.encode_base64(part)
    part.add_header(
        "Content-Disposition",
        "attachment",
        filename=(pdf_fname or "invoice.pdf"),
    )
    part.add_header("Content-Type", "application/pdf", name=(pdf_fname or "invoice.pdf"))
    msg.attach(part)
    return True


def _license_key_exists_sqlite(license_key: str) -> bool:
    lk = (license_key or "").strip()
    if not lk:
        return True
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        for tbl in ("license_keys", "keys"):
            row = conn.execute(
                f"SELECT 1 FROM {tbl} WHERE license_key = ? LIMIT 1;",
                (lk,),
            ).fetchone()
            if row:
                return True
    finally:
        conn.close()
    return False


def _generate_unique_st_license_key() -> str:
    for _ in range(48):
        candidate = _admin_generate_st_license_key()
        if not _license_key_exists_sqlite(candidate):
            return candidate
    return _admin_generate_st_license_key()


