@app.post("/api/v1/admin/payout/execute")
async def admin_payout_execute(request: Request) -> JSONResponse:
    """PayPal Payouts — Admin Commander (freie Empfänger-E-Mail)."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    if not _admin_auth_ok(request, body=body):
        return JSONResponse(
            {"ok": False, "status": "error", "message": "admin_denied"},
            status_code=403,
        )
    try:
        result = _paypal_execute_admin_payout(
            str(body.get("recipient_email") or ""),
            float(body.get("amount") or 0),
            currency=str(body.get("currency") or "EUR"),
            note=str(
                body.get("note") or "SkyTycoon Co-Founder Profit Split"
            ),
        )
        return JSONResponse({"ok": True, **result})
    except ValueError as exc_val:
        return JSONResponse(
            {"ok": False, "status": "error", "message": str(exc_val)},
            status_code=400,
        )
    except Exception as exc_pay:  # noqa: BLE001
        _server_log_line(f"[admin] payout failed: {exc_pay!s}")
        return JSONResponse(
            {"ok": False, "status": "error", "message": str(exc_pay)[:500]},
            status_code=400,
        )


@app.post("/api/v1/admin/resend_license_invoices")
async def admin_resend_license_invoices(
    request: Request, body: dict[str, Any] | None = None
) -> JSONResponse:
    """Nachträglich Kauf-Mail + bilingual PDF an alle license_keys mit E-Mail."""
    raw = body if isinstance(body, dict) else {}
    if not _admin_auth_ok(request, body=raw):
        return JSONResponse(
            {"ok": False, "status": "error", "message": "admin_auth_failed"},
            status_code=403,
        )
    dry_run = bool(raw.get("dry_run", True))
    limit = max(1, min(2000, int(raw.get("limit", 300) or 300)))
    amt = float(_paypal_product_eur_amount())
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        rows = conn.execute(
            """
            SELECT license_key, customer_email, pilot_name, status
            FROM license_keys
            WHERE trim(customer_email) LIKE '%@%'
              AND trim(license_key) != ''
              AND status IN ('activated', 'unused')
            ORDER BY created_ts DESC
            LIMIT ?;
            """,
            (limit,),
        ).fetchall()
    finally:
        conn.close()
    queued = 0
    preview: list[dict[str, str]] = []
    for lk, em, pilot, st in rows:
        em_s = str(em or "").strip().lower()
        lk_s = str(lk or "").strip()
        pilot_s = str(pilot or em_s.split("@", 1)[0]).strip() or "Captain"
        preview.append(
            {
                "email": em_s[:200],
                "license_key": lk_s[:80],
                "status": str(st or ""),
            }
        )
        if dry_run:
            continue
        _bg_send_license_purchase_confirmation_email_bilingual(
            em_s,
            pilot_s,
            lk_s,
            lang=str(raw.get("lang") or "de"),
            amount_eur=amt,
        )
        queued += 1
    return JSONResponse(
        {
            "ok": True,
            "dry_run": dry_run,
            "found": len(rows),
            "queued_send": queued,
            "preview": preview[:25],
        }
    )


