def _lookup_license_email_row(email_norm: str) -> tuple[str, str, str] | None:
    """(pilot_name, license_key, status) für aktivierte oder ungenutzte Lizenz."""
    em = (email_norm or "").strip().lower()
    if "@" not in em:
        return None
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT pilot_name, license_key, status FROM license_keys
            WHERE lower(trim(customer_email)) = ?
            ORDER BY CASE status WHEN 'activated' THEN 0 ELSE 1 END, created_ts DESC
            LIMIT 1;
            """,
            (em,),
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return None
    return str(row[0] or ""), str(row[1] or ""), str(row[2] or "")


