def _portal_account_profile_for_fulfill(
    hid: str,
) -> tuple[str, str, str, str, int] | None:
    """(email, pilot, salt, phash, is_verified) für PayPal/Promo-Freischaltung."""
    prof = _web_pending_profile_by_hid(hid)
    if prof:
        return prof
    hk = (hid or "").strip()[:128]
    if not hk:
        return None
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT customer_email, pilot_name, password_salt, password_hash
            FROM license_keys
            WHERE hardware_id = ? AND status = 'activated'
            ORDER BY created_ts DESC LIMIT 1;
            """,
            (hk,),
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return None
    em = str(row[0] or "").strip()
    if not em or "@" not in em:
        return None
    return (
        em,
        str(row[1] or "")[:120],
        str(row[2] or ""),
        str(row[3] or ""),
        1,
    )


def _web_pending_profile_by_hid(hid: str) -> tuple[str, str, str, str, int] | None:
    """(email, pilot, salt, phash, is_verified) aus ``web_pending_users``."""
    hk = (hid or "").strip()[:128]
    if not hk:
        return None
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT email, pilot_name, password_salt, password_hash,
                   COALESCE(is_verified, 1)
            FROM web_pending_users WHERE hardware_id = ? LIMIT 1;
            """,
            (hk,),
        ).fetchone()
        if not row:
            return None
        em, pn, s, h, iv = (
            str(row[0] or ""),
            str(row[1] or ""),
            str(row[2] or ""),
            str(row[3] or ""),
            int(row[4] or 1),
        )
        if "@" not in em:
            return None
        return (em, pn, s, h, iv)
    finally:
        conn.close()


