def _send_web_verification_email(to_email: str, token: str, lang: str) -> bool:
    """Double-opt-in nach Registrierung (Meilenstein 161)."""
    to_email = (to_email or "").strip()[:200]
    if "@" not in to_email or not token.strip():
        return False
    if not SMTP_HOST or not SMTP_USER or not SMTP_PASSWORD:
        _append_admin_log(f"[email] Verifikation übersprungen (kein SMTP): {to_email[:80]!r}")
        return False
    base = (os.environ.get("SKYTYCOON_PUBLIC_BASE_URL") or "https://skytycoon.info").rstrip(
        "/"
    )
    link = f"{base}/verify-email?t={quote(token, safe='')}"
    ml = "en" if (lang or "").lower().startswith("en") else "de"
    sub_de = "SkyTycoon Pro – Bitte E-Mail bestätigen"
    sub_en = "SkyTycoon Pro – Please confirm your email"
    subj = sub_en if ml == "en" else sub_de
    plain = (
        f"DE: Willkommen! Bitte Konto aktivieren:\n{link}\n\n"
        f"EN: Welcome! Please confirm your account:\n{link}\n"
    )
    html_body = f"""<!DOCTYPE html><html><head><meta charset="utf-8"/></head>
<body style="background:#0b0f14;color:#eceff1;font-family:Segoe UI,Arial,sans-serif;padding:24px;">
<p><a href="{html.escape(link, quote=True)}" style="color:#64b5f6;">{html.escape(link, quote=True)}</a></p>
</body></html>"""
    try:
        msg = MIMEMultipart("alternative")
        msg["Subject"] = subj
        msg["From"] = SMTP_FROM or SMTP_USER
        msg["To"] = to_email
        msg.attach(MIMEText(plain, "plain", "utf-8"))
        msg.attach(MIMEText(html_body, "html", "utf-8"))
        mail_from = SMTP_FROM or SMTP_USER
        _smtp_deliver_message(msg, mail_from, [to_email])
        return True
    except Exception as exc:  # noqa: BLE001
        _append_admin_log(f"[email] Verifikations-Mail FEHLER {to_email!r}: {exc!r}")
        return False


def _portal_promo_form_status(promo_raw: str) -> str:
    """Für kostenlosen Portal-Checkout (nur 100 %): invalid | expired | not100 | ok."""
    pr = (promo_raw or "").strip()
    if not pr:
        return "invalid"
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT discount_percent, max_uses, uses,
                   coalesce(discount_eur, 0),
                   coalesce(valid_from, ''), coalesce(valid_until, '')
            FROM promo_codes WHERE upper(code) = upper(?);
            """,
            (pr,),
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return "invalid"
    disc = int(row[0] or 0)
    mx = int(row[1] or 0)
    us = int(row[2] or 0)
    discount_eur = float(row[3] or 0)
    vf, vu = str(row[4] or ""), str(row[5] or "")
    if us >= mx or not _promo_calendar_active(vf, vu):
        return "expired"
    if disc < 100 and discount_eur < _paypal_product_eur_amount():
        return "not100"
    return "ok"


def _portal_grant_purchased_license(
    hid: str,
    background_tasks: BackgroundTasks | None,
    *,
    promo_code: str | None,
    paypal_capture_id: str,
    paypal_order_id: str,
    amount_value: float = 0.0,
    currency: str = "EUR",
    free_promo: bool = False,
) -> str | None:
    """Portal-Kauf: Key als ``unused`` ohne HW-Bindung; Anzeige über USER-DB ``license_key``."""
    hk = (hid or "").strip()[:128]
    if not hk or _portal_user_has_activated_license(hk):
        return None
    prof = _portal_account_profile_for_fulfill(hk)
    if not prof:
        _paypal_log().warning("Portal-Fulfill: kein Portal-Profil für hid=%r", hk[:32])
        return None
    email_c, pilot, salt, phash, verified = prof
    if int(verified) != 1:
        _paypal_log().warning("Portal-Fulfill: E-Mail nicht verifiziert hid=%r", hk[:32])
        return None
    if free_promo and not (promo_code or "").strip():
        return None
    promo_meta: dict[str, Any] | None = None
    paid_expected = _paypal_product_eur_amount()
    if not free_promo:
        promo_meta = _paypal_order_meta_peek((paypal_order_id or "").strip())
        if promo_meta and promo_meta.get("expected_eur") is not None:
            try:
                paid_expected = float(promo_meta["expected_eur"])
            except (TypeError, ValueError):
                paid_expected = _paypal_product_eur_amount()
        if abs(float(amount_value) - paid_expected) > 0.02 or str(
            currency or ""
        ).upper() != "EUR":
            _paypal_log().warning(
                "Portal-Fulfill: Betrag/Währung abgelehnt (%s %s, erwartet %.2f)",
                amount_value,
                currency,
                paid_expected,
            )
            return None
    cap = (paypal_capture_id or "").strip()[:128]
    if cap:
        idem_key = f"paypal_capture_done:{cap}"
        if _server_kv_get(idem_key).strip():
            return _server_kv_get(idem_key).strip()
    new_key = _generate_unique_st_license_key()
    ts = time.time()
    promo_raw = (promo_code or "").strip() or None
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        sconn.execute("BEGIN IMMEDIATE")
        if free_promo and promo_raw:
            row = sconn.execute(
                """
                SELECT discount_percent, max_uses, uses,
                       coalesce(discount_eur, 0),
                       coalesce(valid_from, ''), coalesce(valid_until, '')
                FROM promo_codes
                WHERE upper(code) = upper(?);
                """,
                (promo_raw,),
            ).fetchone()
            if (
                not row
                or (int(row[0]) < 100 and float(row[3] or 0) < _paypal_product_eur_amount())
                or int(row[2]) >= int(row[1])
                or not _promo_calendar_active(str(row[4] or ""), str(row[5] or ""))
            ):
                sconn.rollback()
                return None
            cur = sconn.execute(
                """
                UPDATE promo_codes SET uses = uses + 1
                WHERE upper(code) = upper(?) AND uses < max_uses;
                """,
                (promo_raw,),
            )
            if cur.rowcount != 1:
                sconn.rollback()
                return None
        elif not free_promo and promo_meta:
            pmc = str(promo_meta.get("promo") or "").strip()
            if pmc:
                curp = sconn.execute(
                    """
                    UPDATE promo_codes SET uses = uses + 1
                    WHERE upper(code) = upper(?) AND uses < max_uses;
                    """,
                    (pmc,),
                )
                if curp.rowcount != 1:
                    sconn.rollback()
                    return None
        sconn.execute(
            """
            INSERT OR REPLACE INTO license_keys (
                license_key, status, hardware_id, pilot_name,
                password_salt, password_hash, customer_email, created_ts
            ) VALUES (?, 'unused', '', ?, ?, ?, ?, ?);
            """,
            (new_key, pilot, salt, phash, email_c, ts),
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO keys (
                license_key, status, customer_email, created_ts,
                paypal_order_id, paypal_capture_id
            ) VALUES (?, 'unused', ?, ?, ?, ?);
            """,
            (
                new_key,
                email_c,
                ts,
                (paypal_order_id or "")[:80],
                cap[:128],
            ),
        )
        sconn.commit()
        if not free_promo:
            _paypal_order_meta_clear((paypal_order_id or "").strip())
    except Exception:
        sconn.rollback()
        raise
    finally:
        sconn.close()
    hid64 = hk[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hid64,),
        )
        uconn.execute(
            """
            UPDATE users SET license_key = ?, license_activated = 1,
            has_license = 1, is_verified = 1
            WHERE hardware_id = ?;
            """,
            (new_key, hid64),
        )
        uconn.commit()
    finally:
        uconn.close()
    try:
        _sync_user_license_flags(hid64)
    except Exception:
        pass
    if cap:
        _server_kv_set(f"paypal_capture_done:{cap}", new_key)
    _paypal_clear_order_owner((paypal_order_id or "").strip())
    ml = _purchase_email_language(email_c, hk)
    try:
        _pg_bind_license_to_email_account(
            email_c,
            new_key,
            pilot,
            hk,
            license_row_status="purchased",
            selected_language=ml,
        )
        _paypal_pg_mark_account_active(email_c, new_key, pilot)
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[portal] PG bind: {exc_pg!s}")
    _append_admin_log(
        f"[portal] Kauf abgeschlossen (unused, ohne HW) hid={hk[:32]!r} email={email_c!r} key={new_key} promo={promo_raw!r}"
    )
    _autopilot_dispatch_license_emails(
        email_c,
        pilot,
        new_key,
        lang=ml,
        background_tasks=background_tasks,
        amount_eur=float(amount_value),
        paypal_capture_id=cap,
        paypal_order_id=(paypal_order_id or "")[:80],
        free_promo=free_promo,
    )
    return new_key


def _web_index_ticker_rows() -> list[dict[str, Any]]:
    """Letzte P2P-Inserate für Landing-Ticker (Meilenstein 161)."""
    out: list[dict[str, Any]] = []
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT id, seller_id, payload_json, price_credits, created_ts, lock_until
            FROM market_listings ORDER BY created_ts DESC LIMIT 3;
            """
        )
        for r in cur.fetchall():
            try:
                payload = json.loads(r[2] or "{}")
            except json.JSONDecodeError:
                payload = {}
            model = str(
                payload.get("model")
                or payload.get("aircraft")
                or payload.get("title")
                or "—"
            )[:80]
            cond = payload.get("condition_pct")
            try:
                cond_f = float(cond) if cond is not None else 0.0
            except (TypeError, ValueError):
                cond_f = 0.0
            lock_until = float(r[5] or 0)
            out.append(
                {
                    "id": str(r[0] or ""),
                    "model": model,
                    "condition_pct": cond_f,
                    "price_credits": float(r[3] or 0),
                    "lock_until": lock_until,
                }
            )
    finally:
        conn.close()
    return out


