def _paypal_api_base() -> str:
    """PayPal REST — Standard: PAYPAL_BASE_URL (Live). Sandbox nur mit PAYPAL_ALLOW_SANDBOX=1."""
    allow_sb = (os.environ.get("PAYPAL_ALLOW_SANDBOX") or "").strip().lower()
    if allow_sb in ("1", "true", "yes", "on"):
        mode = (os.environ.get("PAYPAL_MODE") or "live").strip().lower()
        if mode == "sandbox":
            return "https://api-m.sandbox.paypal.com"
        sb = (os.environ.get("PAYPAL_SANDBOX") or "").strip().lower()
        if sb in ("1", "true", "yes", "on"):
            return "https://api-m.sandbox.paypal.com"
    return (PAYPAL_BASE_URL or "https://api-m.paypal.com").strip().rstrip("/")


