def _parse_iso_utc(s: str) -> datetime | None:
    raw = (s or "").strip()
    if not raw:
        return None
    if raw.endswith("Z"):
        raw = raw[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except ValueError:
        return None


def _promo_calendar_active(valid_from: str, valid_until: str) -> bool:
    vf_s = (valid_from or "").strip()
    vu_s = (valid_until or "").strip()
    if not vf_s and not vu_s:
        return True
    vf = _parse_iso_utc(vf_s) if vf_s else None
    vu = _parse_iso_utc(vu_s) if vu_s else None
    if vf_s and vf is None:
        return False
    if vu_s and vu is None:
        return False
    now = datetime.now(timezone.utc)
    if vf and now < vf:
        return False
    if vu and now > vu:
        return False
    return True


def _active_calendar_promo_best() -> tuple[str, int] | None:
    """Meilenstein 163: UTC-Zeitfenster (valid_from + valid_until), höchster Rabatt gewinnt."""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT code, discount_percent, max_uses, uses,
                   coalesce(valid_from, ''), coalesce(valid_until, '')
            FROM promo_codes;
            """
        )
        best: tuple[str, int] | None = None
        for r in cur.fetchall():
            code = str(r[0] or "")
            disc = int(r[1] or 0)
            mx = int(r[2] or 0)
            us = int(r[3] or 0)
            vf, vu = str(r[4] or ""), str(r[5] or "")
            if not vf.strip() or not vu.strip():
                continue
            if us >= mx or disc < 1:
                continue
            if not _promo_calendar_active(vf, vu):
                continue
            if best is None or disc > best[1]:
                best = (code, disc)
    finally:
        conn.close()
    return best


def _dashboard_default_checkout_eur() -> float:
    """Shop-/PayPal-Standardbetrag: Basispreis aus server_config, minus aktiver Kalender-Rabatt."""
    base = _paypal_product_eur_amount()
    best = _active_calendar_promo_best()
    if best is None:
        return round(float(base), 2)
    _code, disc = best
    if disc >= 100:
        return round(float(base), 2)
    return round(float(base) * (1.0 - disc / 100.0), 2)


def _format_shop_price_de(price: float) -> str:
    """Anzeige DE: Komma als Dezimaltrenner."""
    return f"{float(price):.2f}".replace(".", ",")


def _format_shop_price_en(price: float) -> str:
    return f"{float(price):.2f}"


PRODUCT_PRICE_SETTING_KEY = "product_price"


def _ensure_pg_system_settings_table(conn=None) -> None:
    own = conn is None
    if own:
        conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS system_settings (
                    setting_key VARCHAR(128) PRIMARY KEY,
                    setting_value VARCHAR(512) NOT NULL DEFAULT ''
                );
                """
            )
            cur.execute(
                """
                INSERT INTO system_settings (setting_key, setting_value)
                VALUES (%s, %s)
                ON CONFLICT (setting_key) DO NOTHING;
                """,
                (PRODUCT_PRICE_SETTING_KEY, "25.00"),
            )
        conn.commit()
    finally:
        if own:
            conn.close()


def _pg_system_setting_get(key: str, default: str = "") -> str:
    try:
        _ensure_pg_system_settings_table()
        conn = get_db_connection()
        try:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    "SELECT setting_value FROM system_settings WHERE setting_key = %s;",
                    (key,),
                )
                row = cur.fetchone()
            return str(row["setting_value"] if row else default or "").strip()
        finally:
            conn.close()
    except Exception:
        return default


def _pg_system_setting_set(key: str, value: str) -> None:
    _ensure_pg_system_settings_table()
    conn = get_db_connection()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO system_settings (setting_key, setting_value)
                VALUES (%s, %s)
                ON CONFLICT (setting_key) DO UPDATE
                SET setting_value = EXCLUDED.setting_value;
                """,
                (key, str(value)[:512]),
            )
        conn.commit()
    finally:
        conn.close()


def _web_current_shop_price_display() -> str:
    """Live-Preis (PostgreSQL product_price + Kalender-Promo)."""
    return _format_shop_price_de(_dashboard_default_checkout_eur())


def _paypal_product_eur_amount() -> float:
    pgv = _pg_system_setting_get(PRODUCT_PRICE_SETTING_KEY, "").replace(",", ".")
    if pgv:
        try:
            v = float(pgv)
            if v >= 0:
                return v
        except ValueError:
            pass
    dbv = _server_config_get("base_product_price", "").replace(",", ".")
    if dbv:
        try:
            v = float(dbv)
            if v >= 0:
                return v
        except ValueError:
            pass
    raw = (os.environ.get("PAYPAL_PRODUCT_EUR") or "25.00").strip().replace(",", ".")
    try:
        return float(raw)
    except ValueError:
        return 25.00


def _portal_checkout_eur_from_promo(promo_raw: str | None) -> tuple[float, str | None]:
    """PayPal-Betrag in EUR; Promo gegen PostgreSQL discount_codes (ACTIVE) validieren."""
    base = _paypal_product_eur_amount()
    pr = (promo_raw or "").strip()
    if not pr:
        return _dashboard_default_checkout_eur(), None
    row, err = _discount_code_validate_for_checkout(pr)
    if err:
        raise HTTPException(status_code=400, detail=err)
    if not row:
        raise HTTPException(status_code=400, detail="promo_invalid_expired")
    disc = int(row.get("discount_percent") or 0)
    discount_eur = float(row.get("discount_eur") or 0)
    if disc >= 100 or discount_eur >= base:
        raise HTTPException(status_code=400, detail="promo_free_checkout")
    if disc < 1 and discount_eur <= 0:
        raise HTTPException(status_code=400, detail="promo_invalid_expired")
    final = (
        round(base - discount_eur, 2)
        if discount_eur > 0
        else round(base * (1.0 - disc / 100.0), 2)
    )
    if final < 0.01:
        final = 0.01
    return final, str(row.get("code") or pr).upper()


def _paypal_order_meta_key(order_id: str) -> str:
    return f"paypal_order_meta:{(order_id or '').strip()[:80]}"


def _paypal_order_meta_save(order_id: str, expected_eur: float, promo: str) -> None:
    oid = (order_id or "").strip()[:80]
    if not oid:
        return
    _server_kv_set(
        _paypal_order_meta_key(oid),
        json.dumps(
            {"expected_eur": float(expected_eur), "promo": (promo or "").strip().upper()},
            ensure_ascii=False,
        ),
    )


def _paypal_order_meta_peek(order_id: str) -> dict[str, Any] | None:
    oid = (order_id or "").strip()[:80]
    if not oid:
        return None
    raw = _server_kv_get(_paypal_order_meta_key(oid)).strip()
    if not raw:
        return None
    try:
        d = json.loads(raw)
    except json.JSONDecodeError:
        return None
    return d if isinstance(d, dict) else None


def _paypal_order_meta_clear(order_id: str) -> None:
    oid = (order_id or "").strip()[:80]
    if oid:
        _server_kv_delete(_paypal_order_meta_key(oid))


_PAYPAL_TOKEN: tuple[float, str] | None = None


def _paypal_client_credentials() -> tuple[str, str]:
    """Live Client-ID + Secret: fest im Code, Fallback paypal.env / os.environ."""
    cid = (
        (PAYPAL_CLIENT_ID or "").strip()
        or (os.environ.get("PAYPAL_CLIENT_ID") or "").strip()
        or (PAYPAL_LIVE_CLIENT_ID_DEFAULT or "").strip()
    )
    csec = (
        (PAYPAL_SECRET or "").strip()
        or (os.environ.get("PAYPAL_CLIENT_SECRET") or "").strip()
        or (os.environ.get("PAYPAL_SECRET") or "").strip()
    )
    return cid, csec


def get_paypal_oauth2_access_token(*, force_refresh: bool = False) -> str:
    """
    M205: Offizielles PayPal OAuth2 Bearer-Token (Client Credentials) via REST.
    Nutzt api-m.paypal.com (Live) bzw. api-m.sandbox.paypal.com.
    """
    global _PAYPAL_TOKEN
    cid, csec = _paypal_client_credentials()
    if not cid or not csec:
        raise RuntimeError(
            "PayPal Auth Failed: PAYPAL_CLIENT_ID oder PAYPAL_CLIENT_SECRET fehlt "
            "(paypal.env auf dem Server prüfen)"
        )
    now = time.time()
    if not force_refresh and _PAYPAL_TOKEN and now < _PAYPAL_TOKEN[0]:
        return _PAYPAL_TOKEN[1]
    url = f"{_paypal_api_base()}/v1/oauth2/token"
    headers = {"Accept": "application/json", "Accept-Language": "en_US"}
    data = {"grant_type": "client_credentials"}
    try:
        response = requests.post(
            url,
            headers=headers,
            data=data,
            auth=(cid, csec),
            timeout=30,
        )
    except requests.RequestException as exc:
        raise RuntimeError(f"PayPal Auth Failed: Netzwerk — {exc!s}") from exc
    if response.status_code != 200:
        err_txt = (response.text or "")[:800]
        print(
            f"[PAYPAL AUTH CRASH] Code {response.status_code}: {err_txt}",
            flush=True,
        )
        raise RuntimeError(
            f"PayPal Auth Failed: Status {response.status_code} - {err_txt[:400]}"
        )
    body = response.json()
    tok = str(body.get("access_token") or "").strip()
    if not tok:
        raise RuntimeError("PayPal Auth Failed: leeres access_token in Antwort")
    exp = float(body.get("expires_in") or 28800) - 120.0
    _PAYPAL_TOKEN = (now + max(300.0, exp), tok)
    return tok


def get_paypal_oauth2_access_token_live(*, force_refresh: bool = False) -> str:
    """M207/M212: Live-OAuth (api-m.paypal.com)."""
    return get_paypal_oauth2_access_token(force_refresh=force_refresh)


def get_paypal_oauth2_token_production(*, force_refresh: bool = False) -> str:
    """Alias: Produktions-OAuth2 (kein Sandbox ohne PAYPAL_ALLOW_SANDBOX)."""
    return get_paypal_oauth2_access_token_live(force_refresh=force_refresh)


def _paypal_execute_admin_payout(
    recipient_email: str,
    amount: float,
    *,
    currency: str = "EUR",
    note: str = "SkyTycoon Co-Founder Profit Split",
) -> dict[str, Any]:
    """PayPal Payouts API — Echtgeld an freie Empfänger-E-Mail."""
    em = str(recipient_email or "").strip()[:254]
    if not em or "@" not in em:
        raise ValueError("invalid_recipient_email")
    try:
        amt = float(amount)
    except (TypeError, ValueError) as exc:
        raise ValueError("invalid_amount") from exc
    if amt < 0.01 or amt > 10000.0:
        raise ValueError("amount_out_of_range")
    cur = str(currency or "EUR").strip().upper()[:3] or "EUR"
    token = get_paypal_oauth2_access_token_live()
    url = f"{_paypal_api_base()}/v1/payments/payouts"
    batch_id = f"ST-BATCH-{secrets.token_hex(4).upper()}"
    payout_body = {
        "sender_batch_header": {
            "sender_batch_id": batch_id,
            "email_subject": "Du hast Geld von SkyTycoon erhalten!",
            "email_message": "SkyTycoon Pro — Co-Founder Revenue Share",
            "recipient_type": "EMAIL",
        },
        "items": [
            {
                "recipient_type": "EMAIL",
                "amount": {"value": f"{amt:.2f}", "currency": cur},
                "note": str(note or "")[:255],
                "receiver": em,
                "sender_item_id": batch_id,
            }
        ],
    }
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}",
    }
    try:
        response = requests.post(url, json=payout_body, headers=headers, timeout=60)
    except requests.RequestException as exc:
        raise RuntimeError(f"payout_network: {exc!s}") from exc
    try:
        body = response.json() if response.content else {}
    except (ValueError, TypeError):
        body = {}
    if response.status_code not in (200, 201):
        err_txt = (response.text or "")[:800]
        raise RuntimeError(f"payout_failed_{response.status_code}: {err_txt}")
    batch_hdr = body.get("batch_header") if isinstance(body, dict) else {}
    payout_batch_id = ""
    if isinstance(batch_hdr, dict):
        payout_batch_id = str(batch_hdr.get("payout_batch_id") or "").strip()
    return {
        "status": "success",
        "paypal_batch_id": payout_batch_id or batch_id,
        "sender_batch_id": batch_id,
        "recipient_email": em,
        "amount": round(amt, 2),
        "currency": cur,
    }


def execute_native_paypal_order_creation_handshake(
    amount_eur: float,
    pilot_hw_id: str,
    *,
    description: str | None = None,
) -> str:
    """
    M205/M207: PayPal v2 REST — vollständiges Order-Payload inkl. application_context.
    """
    token = get_paypal_oauth2_token_production()
    amt = round(float(amount_eur), 2)
    if amt < 0.50:
        raise ValueError("amount_below_minimum")
    hid = (pilot_hw_id or "").strip()[:128]
    desc = (description or "").strip() or (
        f"SkyTycoon Pro v1.0 - Lifetime Addon Access for ID: {hid}"
    )
    site = _public_site_url()
    url = f"{PAYPAL_BASE_URL.rstrip('/')}/v2/checkout/orders"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}",
        "Prefer": "return=representation",
    }
    order_payload: dict[str, Any] = {
        "intent": "CAPTURE",
        "purchase_units": [
            {
                "reference_id": f"SK_TYCOON_{hid[:8]}",
                "amount": {
                    "currency_code": "EUR",
                    "value": f"{amt:.2f}",
                },
                "description": desc[:127],
            }
        ],
        "application_context": {
            "brand_name": "SkyTycoon Suite",
            "landing_page": "LOGIN",
            "user_action": "PAY_NOW",
            "return_url": site,
            "cancel_url": site,
        },
    }
    try:
        paypal_response = requests.post(
            url, headers=headers, json=order_payload, timeout=45
        )
    except requests.RequestException as exc:
        print(f"[PAYPAL SYSTEM FAILURE] Netzwerk: {exc!s}", flush=True)
        raise RuntimeError(f"PayPal Order Netzwerkfehler: {exc!s}") from exc
    if paypal_response.status_code == 201:
        try:
            pdata = paypal_response.json()
        except ValueError as exc:
            raise RuntimeError("PayPal Order: ungültige JSON-Antwort") from exc
        paypal_order_id = str(pdata.get("id") or "").strip()
        if not paypal_order_id:
            raise RuntimeError("PayPal Order: keine order id in Antwort")
        print(
            f"[PAYPAL LIVE] Echte Umsatz-Order generiert: ID {paypal_order_id}",
            flush=True,
        )
        _paypal_log().info(
            "[PAYPAL PRODUCTION] Order erfolgreich bei PayPal generiert. "
            "ID: %s für Pilot: %s…",
            paypal_order_id[:32],
            hid[:16],
        )
        return paypal_order_id
    if paypal_response.status_code == 200:
        _paypal_log().warning(
            "[PAYPAL] Order-API antwortete mit 200 statt 201 — bitte Payload prüfen"
        )
    err_body = (paypal_response.text or "")[:800]
    print(
        f"[PAYPAL API REJECTION] Code {paypal_response.status_code}: {err_body}",
        flush=True,
    )
    try:
        err_json = paypal_response.json()
        msg = str(
            err_json.get("message")
            or err_json.get("error_description")
            or err_body
        )
    except ValueError:
        msg = err_body or "Unbekannt"
    _paypal_log().warning(
        "[PAYPAL API ERROR] Code %s: %s",
        paypal_response.status_code,
        msg[:300],
    )
    raise RuntimeError(
        f"PayPal abgewiesen ({paypal_response.status_code}): {msg[:200]}"
    )


def _paypal_access_token() -> str | None:
    """OAuth2 (gecacht); None wenn Credentials fehlen oder Auth scheitert."""
    try:
        return get_paypal_oauth2_access_token()
    except RuntimeError as exc:
        _paypal_log().warning("%s", exc)
        return None


async def verify_paypal_webhook_signature(
    request: Request, webhook_event: dict[str, Any]
) -> bool:
    """Prüft die Webhook-Signatur über die PayPal-API (keine lokale Zertifikatskette)."""
    skip = (os.environ.get("PAYPAL_SKIP_WEBHOOK_VERIFY") or "").strip().lower()
    if skip in ("1", "true", "yes", "on"):
        _paypal_log().warning(
            "PayPal Webhook: PAYPAL_SKIP_WEBHOOK_VERIFY aktiv — Signaturprüfung nur simuliert (Testbetrieb)."
        )
        return True
    wid = (os.environ.get("PAYPAL_WEBHOOK_ID") or "").strip()
    if not wid:
        _paypal_log().error(
            "PayPal Webhook: PAYPAL_WEBHOOK_ID fehlt — Signaturprüfung abgelehnt (Produktion nicht scharf)."
        )
        return False
    tok = _paypal_access_token()
    if not tok:
        return False
    payload = {
        "auth_algo": (request.headers.get("PAYPAL-AUTH-ALGO") or "").strip(),
        "cert_url": (request.headers.get("PAYPAL-CERT-URL") or "").strip(),
        "transmission_id": (request.headers.get("PAYPAL-TRANSMISSION-ID") or "").strip(),
        "transmission_sig": (request.headers.get("PAYPAL-TRANSMISSION-SIG") or "").strip(),
        "transmission_time": (
            request.headers.get("PAYPAL-TRANSMISSION-TIME") or ""
        ).strip(),
        "webhook_id": wid,
        "webhook_event": webhook_event,
    }
    if not all(
        (
            payload["auth_algo"],
            payload["cert_url"],
            payload["transmission_id"],
            payload["transmission_sig"],
            payload["transmission_time"],
        )
    ):
        _paypal_log().warning(
            "PayPal Webhook: unvollständige Signatur-Header — Anfrage verworfen."
        )
        return False
    try:
        u = f"{_paypal_api_base()}/v1/notifications/verify-webhook-signature"
        r = requests.post(
            u,
            headers={
                "Authorization": f"Bearer {tok}",
                "Content-Type": "application/json",
            },
            json=payload,
            timeout=30,
        )
        data = r.json() if r.text else {}
        ok = data.get("verification_status") == "SUCCESS"
        if not ok:
            _paypal_log().warning(
                "PayPal Webhook-Signatur ungültig: status=%r HTTP=%s",
                data.get("verification_status"),
                r.status_code,
            )
        return ok
    except requests.RequestException as exc:
        _paypal_log().warning("PayPal Signatur-API nicht erreichbar: %s", exc)
        return False


def _paypal_order_id_from_resource(res: dict[str, Any]) -> str:
    sup = res.get("supplementary_data") if isinstance(res.get("supplementary_data"), dict) else {}
    rel = sup.get("related_ids") if isinstance(sup.get("related_ids"), dict) else {}
    oid = str(rel.get("order_id") or "").strip()
    if oid:
        return oid[:80]
    return str(res.get("invoice_id") or "").strip()[:80]


def _paypal_extract_capture_from_event(
    ev: dict[str, Any],
) -> tuple[str, str, float, str]:
    """(capture_id, payer_email, amount_value, currency) aus Event-Daten."""
    res = ev.get("resource") if isinstance(ev.get("resource"), dict) else {}
    cap_id = str(res.get("id") or "").strip()
    amount = res.get("amount") if isinstance(res.get("amount"), dict) else {}
    val_s = str(amount.get("value", "0")).replace(",", ".").strip()
    try:
        val_f = float(val_s)
    except ValueError:
        val_f = 0.0
    cur = str(amount.get("currency_code", "EUR") or "EUR").upper()
    em = ""
    payer = res.get("payer") if isinstance(res.get("payer"), dict) else {}
    em = str(payer.get("email_address") or "").strip()[:200]
    if not em:
        pu = res.get("payee") if isinstance(res.get("payee"), dict) else {}
        em = str(pu.get("email_address") or "").strip()[:200]
    return cap_id, em, val_f, cur


def _paypal_first_completed_capture(
    order_like: dict[str, Any],
) -> tuple[str, str, float, str, str] | None:
    """Erste COMPLETED-Capture: capture_id, payer_email, amount, currency, paypal_order_id."""
    order_id = str(order_like.get("id") or "").strip()[:80]
    payer = order_like.get("payer") if isinstance(order_like.get("payer"), dict) else {}
    payer_em = str(payer.get("email_address") or "").strip()[:200]
    for pu in order_like.get("purchase_units") or []:
        if not isinstance(pu, dict):
            continue
        pay = pu.get("payments") if isinstance(pu.get("payments"), dict) else {}
        for cap in pay.get("captures") or []:
            if not isinstance(cap, dict):
                continue
            if str(cap.get("status") or "").upper() != "COMPLETED":
                continue
            cid = str(cap.get("id") or "").strip()
            amt = cap.get("amount") if isinstance(cap.get("amount"), dict) else {}
            vs = str(amt.get("value", "0")).replace(",", ".").strip()
            try:
                vf = float(vs)
            except ValueError:
                vf = 0.0
            cur = str(amt.get("currency_code", "EUR") or "EUR").upper()
            return cid, payer_em, vf, cur, order_id
    return None


def _paypal_fulfill_lifetime_license(
    payer_email: str,
    capture_id: str,
    amount_value: float,
    currency: str,
    background_tasks: BackgroundTasks | None,
    paypal_order_id: str = "",
) -> str | None:
    """Legt Lizenz in ``license_keys`` + ``keys`` an, E-Mail; idempotent pro Capture. Rückgabe: Lizenzschlüssel."""
    expected = _paypal_product_eur_amount()
    if abs(float(amount_value) - expected) > 0.02:
        _paypal_log().warning(
            "PayPal Fulfillment abgelehnt: Betrag %s %s (erwartet %.2f EUR), capture=%r",
            amount_value,
            currency,
            expected,
            capture_id[:32],
        )
        return None
    if currency != "EUR":
        _paypal_log().warning(
            "PayPal Fulfillment: Währung %r statt EUR — abgelehnt.", currency
        )
        return None
    em = (payer_email or "").strip()[:200]
    if "@" not in em:
        _paypal_log().warning(
            "PayPal Fulfillment: keine gültige Käufer-E-Mail (capture=%r).",
            capture_id[:32],
        )
        return None
    cap = (capture_id or "").strip()
    if not cap:
        return None
    idem_key = f"paypal_capture_done:{cap}"
    existing_key = _server_kv_get(idem_key).strip()
    if existing_key:
        _paypal_log().info(
            "PayPal Fulfillment übersprungen (bereits verarbeitet): %s", cap[:24]
        )
        return existing_key
    new_key = _generate_unique_st_license_key()
    oid_log = (paypal_order_id or "").strip()[:80]
    ts = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE;")
        conn.execute(
            """
            INSERT OR REPLACE INTO license_keys (
                license_key, status, hardware_id, pilot_name,
                password_salt, password_hash, customer_email, created_ts
            ) VALUES (?, 'unused', '', '', '', '', ?, ?);
            """,
            (new_key, em, ts),
        )
        conn.execute(
            """
            INSERT OR REPLACE INTO keys (
                license_key, status, customer_email, created_ts,
                paypal_order_id, paypal_capture_id
            ) VALUES (?, 'unused', ?, ?, ?, ?);
            """,
            (new_key, em, ts, oid_log, cap[:128]),
        )
        conn.commit()
    finally:
        conn.close()
    _server_kv_set(idem_key, new_key)
    pilot_guess = em.split("@", 1)[0][:120] if "@" in em else ""
    mail_lang = _purchase_email_language(em)
    try:
        _pg_bind_license_to_email_account(
            em,
            new_key,
            pilot_guess,
            license_row_status="purchased",
            selected_language=mail_lang,
        )
        _paypal_pg_mark_account_active(em, new_key, pilot_guess)
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[paypal] PG bind: {exc_pg!s}")
    _append_admin_log(
        f"[paypal][buchhaltung] Geldeingang EUR {amount_value:.2f} "
        f"paypal_order_id={oid_log!r} capture_id={cap[:48]!r} "
        f"email={em!r} license_key={new_key}"
    )

    def _pp_mail_safe() -> None:
        try:
            _autopilot_dispatch_license_emails(
                em,
                pilot_guess,
                new_key,
                lang=mail_lang,
                amount_eur=float(amount_value),
                paypal_capture_id=cap,
                paypal_order_id=oid_log,
            )
        except Exception as exc:  # noqa: BLE001
            _append_admin_log(f"[email] PayPal Kauf-Mail Exception: {exc!r}")
            _server_log_line(f"[email] PayPal Kauf-Mail Exception: {exc!r}")

    if background_tasks is not None:
        background_tasks.add_task(_pp_mail_safe)
    else:
        _pp_mail_safe()
    try:
        threading.Thread(
            target=_notify_co_founder_revenue_discord,
            args=(float(amount_value), cap, em),
            kwargs={
                "license_key": new_key,
                "paypal_order_id": oid_log,
            },
            daemon=True,
        ).start()
    except Exception:
        pass
    return new_key


def _session_sign(hardware_id: str) -> str:
    hid = (hardware_id or "").strip()[:128]
    ts = int(time.time())
    msg = f"{hid}\n{ts}"
    sig = hmac.new(WEB_SESSION_SECRET, msg.encode("utf-8"), hashlib.sha256).hexdigest()
    inner = f"{msg}\n{sig}"
    return base64.urlsafe_b64encode(inner.encode("utf-8")).decode("ascii")


def _session_parse(token: str | None) -> str | None:
    if not token:
        return None
    try:
        raw = base64.urlsafe_b64decode(token.encode("ascii")).decode("utf-8")
        hid_ts, sig = raw.rsplit("\n", 1)
        hid, ts_s = hid_ts.split("\n", 1)
        ts = int(ts_s)
        msg = f"{hid}\n{ts}"
        expect = hmac.new(
            WEB_SESSION_SECRET, msg.encode("utf-8"), hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expect, sig):
            return None
        if time.time() - ts > WEB_SESSION_MAX_AGE_SEC:
            return None
        return hid.strip()[:128] or None
    except Exception:
        return None


