def _queue_activation_key_ready_email(
    *,
    hardware_id: str = "",
    email: str = "",
    pilot_name: str = "",
    license_key: str,
    lang: str = "",
    background_tasks: BackgroundTasks | None = None,
) -> None:
    prof = _mail_user_profile(hardware_id, email)
    em = (email or prof.get("email") or "").strip()[:200]
    pilot = (pilot_name or prof.get("pilot_name") or "Captain").strip()[:120]
    lg = _mail_lang_norm(lang or prof.get("lang") or "de")
    lk = (license_key or "").strip()
    if not em or "@" not in em or not lk:
        return

    def _task() -> None:
        _run_email_with_retry(
            _send_activation_key_ready_email_i18n, em, pilot, lk, lg
        )

    if background_tasks is not None:
        background_tasks.add_task(_task)
    else:
        threading.Thread(target=_task, daemon=True).start()


def _pg_marketing_recipients(lang: str | None = None) -> list[dict[str, str]]:
    out: list[dict[str, str]] = []
    conn = None
    try:
        conn = get_db_connection()
        with conn.cursor(cursor_factory=DictCursor) as cur:
            if lang:
                cur.execute(
                    """
                    SELECT lower(trim(email)) AS email,
                           trim(username) AS username,
                           trim(hardware_id) AS hardware_id,
                           lower(trim(COALESCE(selected_language, 'de'))) AS selected_language
                    FROM users
                    WHERE email IS NOT NULL AND trim(email) <> ''
                      AND lower(trim(COALESCE(selected_language, 'de'))) = %s;
                    """,
                    (_mail_lang_norm(lang),),
                )
            else:
                cur.execute(
                    """
                    SELECT lower(trim(email)) AS email,
                           trim(username) AS username,
                           trim(hardware_id) AS hardware_id,
                           lower(trim(COALESCE(selected_language, 'de'))) AS selected_language
                    FROM users
                    WHERE email IS NOT NULL AND trim(email) <> '';
                    """
                )
            for row in cur.fetchall() or []:
                em = str(row.get("email") or "").strip()
                if "@" not in em:
                    continue
                out.append(
                    {
                        "email": em[:200],
                        "pilot_name": str(row.get("username") or "Captain")[:120],
                        "hardware_id": str(row.get("hardware_id") or "")[:128],
                        "lang": _mail_lang_norm(str(row.get("selected_language") or "de")),
                    }
                )
    except Exception as exc:
        if conn is not None:
            _pg_rollback(conn)
        _append_admin_log(f"[marketing] PG recipients rollback: {exc!r}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return out


