def _marketing_discount_worker(promo_code: str, target_email: str) -> dict[str, Any]:
    """BackgroundTasks: Massen-Rabatt-Mail (SMTP 587 + Retry)."""
    try:
        code = (promo_code or "").strip().upper()[:48]
        target = (target_email or "ALL").strip()
        sent = failed = 0
        if target.upper() == "ALL":
            recipients: list[dict[str, str]] = []
            for lg in ("de", "en"):
                recipients.extend(_pg_marketing_recipients(lg))
            seen: set[str] = set()
            uniq: list[dict[str, str]] = []
            for r in recipients:
                em = r["email"].lower()
                if em in seen:
                    continue
                seen.add(em)
                uniq.append(r)
            recipients = uniq
        else:
            prof = _mail_user_profile("", target)
            recipients = [
                {
                    "email": target.lower()[:200],
                    "pilot_name": prof.get("pilot_name") or "Captain",
                    "lang": prof.get("lang") or "de",
                }
            ]
        for r in recipients:
            if _send_marketing_discount_email(
                r["email"], r["pilot_name"], code, r["lang"]
            ):
                sent += 1
            else:
                failed += 1
        _append_admin_log(f"[marketing] Rabattcode {code!r} → {sent} OK, {failed} FAIL")
        return {"sent": sent, "failed": failed, "promo_code": code}
    except Exception as exc:
        _append_admin_log(f"[marketing] discount worker: {exc!r}")
        return {"sent": 0, "failed": 0, "error": str(exc)}


def _marketing_newsletter_worker(changelog_de: str, changelog_en: str) -> dict[str, Any]:
    """BackgroundTasks: Massen-Newsletter (SMTP 587 + Retry)."""
    try:
        sent = failed = 0
        for lg, text in (("de", changelog_de), ("en", changelog_en)):
            if not (text or "").strip():
                continue
            for r in _pg_marketing_recipients(lg):
                if _send_marketing_newsletter_email(
                    r["email"], r["pilot_name"], text, lg
                ):
                    sent += 1
                else:
                    failed += 1
        _append_admin_log(f"[marketing] Newsletter → {sent} OK, {failed} FAIL")
        return {"sent": sent, "failed": failed}
    except Exception as exc:
        _append_admin_log(f"[marketing] newsletter worker: {exc!r}")
        return {"sent": 0, "failed": 0, "error": str(exc)}


