def _pilot_name_taken_global(pilot_name: str, exclude_email: str = "") -> bool:
    """True wenn Pilotenname in PG/SQLite bereits vergeben ist."""
    pn = str(pilot_name or "").strip()[:120]
    em_ex = str(exclude_email or "").strip().lower()[:200]
    if not pn:
        return False
    conn = None
    try:
        conn = get_db_connection()
        row = pg_fetchone(
            conn,
            """
            SELECT 1 FROM users
            WHERE lower(trim(username)) = lower(trim(%s))
              AND (
                    %s = '' OR lower(trim(COALESCE(email, ''))) IS DISTINCT FROM %s
                  )
            LIMIT 1;
            """,
            (pn, em_ex, em_ex),
        )
        if row:
            return True
    except Exception:
        if conn is not None:
            _pg_rollback(conn)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        for sql in (
            """
            SELECT 1 FROM license_keys
            WHERE lower(trim(pilot_name)) = lower(trim(?))
              AND (? = '' OR lower(trim(COALESCE(customer_email, ''))) != ?)
            LIMIT 1;
            """,
            """
            SELECT 1 FROM web_pending_users
            WHERE lower(trim(pilot_name)) = lower(trim(?))
              AND (? = '' OR lower(trim(COALESCE(email, ''))) != ?)
            LIMIT 1;
            """,
        ):
            if sconn.execute(sql, (pn, em_ex, em_ex)).fetchone():
                return True
    finally:
        sconn.close()
    return False


def _pilot_name_suggestions(wish: str, exclude_email: str = "") -> list[str]:
    """Drei freie Alternativen: Captain_/Pilot_, _737/_A320, _SkyTycoon."""
    import re

    raw = str(wish or "").strip()[:80]
    base = re.sub(r"[^\w\-]", "_", raw).strip("_") or "Pilot"
    variant_groups = (
        (f"Captain_{base}", f"Pilot_{base}"),
        (f"{base}_737", f"{base}_A320"),
        (f"{base}_SkyTycoon",),
    )
    picked: list[str] = []
    for group in variant_groups:
        for cand in group:
            c = cand[:120]
            if c in picked:
                continue
            if not _pilot_name_taken_global(c, exclude_email):
                picked.append(c)
                break
    n = 2
    while len(picked) < 3:
        extra = f"{base}_Sky_{n}"[:120]
        if extra not in picked and not _pilot_name_taken_global(extra, exclude_email):
            picked.append(extra)
        n += 1
        if n > 99:
            break
    return picked[:3]


@app.get("/api/v1/auth/check_pilot_name")
async def api_check_pilot_name(
    pilot_name: str = "", username: str = "", email: str = ""
) -> JSONResponse:
    """Live-Check: Name frei oder name_taken + 3 Gold-Vorschläge."""
    try:
        wish = str(pilot_name or username or "").strip()[:120]
        em = str(email or "").strip().lower()[:200]
        if not wish:
            return JSONResponse({"status": "bad_request"}, status_code=400)
        if _pilot_name_taken_global(wish, em):
            return JSONResponse(
                {
                    "status": "name_taken",
                    "suggestions": _pilot_name_suggestions(wish, em),
                }
            )
        return JSONResponse({"status": "available", "ok": True})
    except Exception as exc_chk:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[auth] check_pilot_name failed: {exc_chk!s}")
        return JSONResponse({"status": "error"}, status_code=503)


