@app.get("/api/v1/jobs/available")
async def jobs_available(
    request: Request,
    current_icao: str = "",
    hardware_id: str = "",
    password: str = "",
    haul: str = "",
) -> JSONResponse:
    """Offene Cloud-Jobs am Abflug-ICAO — alle JSON-Key-Varianten für die Desktop-App."""
    dep_raw = str(
        current_icao or request.query_params.get("icao", "") or ""
    ).strip().upper()
    dep = dep_raw[:4] if dep_raw else ""
    global_all = not dep_raw or dep_raw == "ALL" or dep == "ALL"

    def _load_jobs_global_fallback(conn: sqlite3.Connection) -> list[dict[str, Any]]:
        cur = conn.execute(
            """
            SELECT job_id, departure_icao, arrival_icao, distance_nm,
                   cargo_weight_lbs, payout_credits, job_type
            FROM global_job_board
            WHERE status = 'open'
            ORDER BY payout_credits DESC, distance_nm DESC
            LIMIT 280;
            """
        )
        return [_job_board_row_to_client(r) for r in cur.fetchall()]

    def _load_jobs() -> tuple[list[dict[str, Any]], bool]:
        if _global_job_board_open_count() < 150:
            _ensure_global_job_board_minimum_open(350)
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        used_global = False
        try:
            if global_all or len(dep) != 4:
                jobs = _load_jobs_global_fallback(conn)
                used_global = True
            else:
                cur = conn.execute(
                    """
                    SELECT job_id, departure_icao, arrival_icao, distance_nm,
                           cargo_weight_lbs, payout_credits, job_type
                    FROM global_job_board
                    WHERE status = 'open' AND departure_icao = ?
                    ORDER BY payout_credits DESC, distance_nm DESC LIMIT 80;
                    """,
                    (dep,),
                )
                local_jobs = [_job_board_row_to_client(r) for r in cur.fetchall()]
                global_jobs = _load_jobs_global_fallback(conn)
                seen: set[int] = set()
                merged: list[dict[str, Any]] = []
                for j in local_jobs:
                    sid = int(j.get("server_job_id") or j.get("job_id") or 0)
                    if sid and sid in seen:
                        continue
                    if sid:
                        seen.add(sid)
                    merged.append(j)
                for j in global_jobs:
                    if len(merged) >= 200:
                        break
                    sid = int(j.get("server_job_id") or j.get("job_id") or 0)
                    if sid and sid in seen:
                        continue
                    if sid:
                        seen.add(sid)
                    merged.append(j)
                jobs = merged if merged else global_jobs
                used_global = len(global_jobs) > 0 and len(local_jobs) < len(jobs)
            if not jobs:
                jobs = _load_jobs_global_fallback(conn)
                used_global = True
            return jobs, used_global
        finally:
            conn.close()

    haul_key = str(haul or request.query_params.get("haul", "")).strip().lower()
    try:
        jobs, global_all = await asyncio.to_thread(_load_jobs)
        if haul_key in ("short", "kurz", "short_haul"):
            jobs = [
                j
                for j in jobs
                if float(j.get("dist_nm", j.get("distance_nm", 0)) or 0)
                < PLATIN_HAUL_NM_THRESHOLD
            ]
            conn_pg = get_db_connection()
            try:
                _ensure_pg_short_haul_job_board_table(conn_pg)
                with conn_pg.cursor() as cur:
                    cur.execute(
                        """
                        SELECT job_id, departure_icao, arrival_icao, distance_nm,
                               cargo_weight_lbs, payout_credits, job_type
                        FROM short_haul_job_board
                        WHERE status = 'open'
                        ORDER BY payout_credits DESC
                        LIMIT 200;
                        """
                    )
                    pg_rows = cur.fetchall() or []
                for r in pg_rows:
                    jobs.append(_job_board_row_to_client(r))
            except Exception:  # noqa: BLE001
                try:
                    conn_pg.rollback()
                except Exception:  # noqa: BLE001
                    pass
            finally:
                conn_pg.close()
        elif haul_key in ("long", "lang", "long_haul"):
            jobs = [
                j
                for j in jobs
                if float(j.get("dist_nm", j.get("distance_nm", 0)) or 0)
                >= PLATIN_HAUL_NM_THRESHOLD
            ]
            conn_pg = get_db_connection()
            try:
                _ensure_pg_short_haul_job_board_table(conn_pg)
                with conn_pg.cursor() as cur:
                    cur.execute(
                        """
                        SELECT job_id, departure_icao, arrival_icao, distance_nm,
                               cargo_weight_lbs, payout_credits, job_type
                        FROM long_haul_job_board
                        WHERE status = 'open'
                        ORDER BY payout_credits DESC
                        LIMIT 200;
                        """
                    )
                    pg_rows = cur.fetchall() or []
                for r in pg_rows:
                    jobs.append(_job_board_row_to_client(r))
            except Exception:  # noqa: BLE001
                try:
                    conn_pg.rollback()
                except Exception:  # noqa: BLE001
                    pass
            finally:
                conn_pg.close()
        jobs = _apply_top5_premium_bonus(jobs)
    except Exception as exc:  # noqa: BLE001
        _server_log_line(f"[job_board] available failed: {exc!s}")
        return JSONResponse(
            {"ok": False, "status": "error", "jobs": [], "error": str(exc)},
            status_code=500,
        )

    loc = "ALL" if global_all else dep
    _server_log_line(
        f"[job_board] {len(jobs)} Jobs für Standort {loc} an App übermittelt."
    )
    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "jobs": jobs,
            "departure_icao": loc,
            "current_icao": loc,
            "global_fallback": global_all,
            "job_count": len(jobs),
        }
    )


@app.post("/api/v1/jobs/force_refresh")
async def jobs_force_refresh(request: Request, body: dict[str, Any] | None = None) -> JSONResponse:
    """Manueller Markt-Refresh (Desktop-Button)."""
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = ""
    n = await asyncio.to_thread(_regenerate_global_job_board, 400)
    await asyncio.to_thread(_regenerate_short_haul_pg, 240)
    await asyncio.to_thread(_regenerate_long_haul_pg, 180)
    dep = str(body.get("current_icao", "") or "").strip().upper()[:4]
    jobs: list[dict[str, Any]] = []
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        if len(dep) == 4:
            cur = conn.execute(
                """
                SELECT job_id, departure_icao, arrival_icao, distance_nm,
                       cargo_weight_lbs, payout_credits, job_type
                FROM global_job_board
                WHERE status = 'open' AND departure_icao = ?
                ORDER BY payout_credits DESC LIMIT 80;
                """,
                (dep,),
            )
            jobs = [_job_board_row_to_client(r) for r in cur.fetchall()]
        cur_g = conn.execute(
            """
            SELECT job_id, departure_icao, arrival_icao, distance_nm,
                   cargo_weight_lbs, payout_credits, job_type
            FROM global_job_board
            WHERE status = 'open'
            ORDER BY payout_credits DESC LIMIT 200;
            """
        )
        global_jobs = [_job_board_row_to_client(r) for r in cur_g.fetchall()]
        seen = {int(j.get("server_job_id") or 0) for j in jobs}
        for j in global_jobs:
            sid = int(j.get("server_job_id") or 0)
            if sid and sid in seen:
                continue
            if sid:
                seen.add(sid)
            jobs.append(j)
            if len(jobs) >= 200:
                break
    finally:
        conn.close()
    jobs = _apply_top5_premium_bonus(jobs)
    _append_admin_log(f"[job_board] force_refresh by {hid or 'anon'}: {n} jobs.")
    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "regenerated": n,
            "jobs": jobs,
            "departure_icao": dep,
            "current_icao": dep,
        }
    )


@app.post("/api/v1/jobs/accept")
def jobs_accept(request: Request, body: dict[str, Any]) -> JSONResponse:
    """Sperrt einen Cloud-Job für alle anderen Spieler."""
    hid = _desktop_api_auth(request, body)
    try:
        job_id = int(body.get("job_id", body.get("id", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_id"}, status_code=400)
    if job_id <= 0:
        return JSONResponse({"ok": False, "error": "bad_id"}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT status, departure_icao, arrival_icao, distance_nm,
                   cargo_weight_lbs, payout_credits, job_type
            FROM global_job_board WHERE job_id = ?;
            """,
            (job_id,),
        ).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        if str(row[0] or "") != "open":
            return JSONResponse({"ok": False, "error": "already_taken"}, status_code=409)
        conn.execute(
            """
            UPDATE global_job_board
            SET status = 'accepted', accepted_by = ?
            WHERE job_id = ?;
            """,
            (hid[:64], job_id),
        )
        conn.commit()
        job = _job_board_row_to_client((job_id, *row[1:]))
        origin = str(row[1] or "").strip().upper()[:4]
        dest = str(row[2] or "").strip().upper()[:4]
        routing_provider = str(body.get("routing_provider") or "simbrief").strip().lower()[:32]
    finally:
        conn.close()
    try:
        pg = get_db_connection()
        try:
            _persist_active_flight_pg(
                pg,
                hid,
                job_id=job_id,
                dep_icao=origin,
                arr_icao=dest,
                routing_provider=routing_provider,
            )
        finally:
            pg.close()
    except psycopg2.Error:
        pass
    return JSONResponse(
        {
            "ok": True,
            "job": job,
            "routing_provider": routing_provider,
            "sky_dispatch_bonus": routing_provider
            in ("sky_dispatch", "skytycoon", "skytycoon_dispatch"),
        }
    )


@app.post("/api/v1/web/market/auftraege")
def web_market_auftraege_accept(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    try:
        job_id = int(body.get("job_id", body.get("id", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_id"}, status_code=400)
    if job_id <= 0:
        return JSONResponse({"ok": False, "error": "bad_id"}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT status, departure_icao, arrival_icao, distance_nm,
                   cargo_weight_lbs, payout_credits, job_type
            FROM global_job_board WHERE job_id = ?;
            """,
            (job_id,),
        ).fetchone()
        if not row:
            conn.rollback()
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        if str(row[0] or "") != "open":
            conn.rollback()
            return JSONResponse({"ok": False, "error": "already_taken"}, status_code=409)
        conn.execute(
            """
            UPDATE global_job_board
            SET status = 'accepted', accepted_by = ?
            WHERE job_id = ? AND status = 'open';
            """,
            (str(hid)[:64], job_id),
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS active_web_flightplans (
                hardware_id TEXT PRIMARY KEY,
                job_id INTEGER NOT NULL DEFAULT 0,
                route TEXT NOT NULL DEFAULT '',
                origin TEXT NOT NULL DEFAULT '',
                destination TEXT NOT NULL DEFAULT '',
                fuel_lbs REAL NOT NULL DEFAULT 0,
                weight_lbs REAL NOT NULL DEFAULT 0,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        origin = str(row[1] or "").strip().upper()[:4]
        dest = str(row[2] or "").strip().upper()[:4]
        distance = float(row[3] or 0)
        cargo = float(row[4] or 0)
        fuel_lbs = max(3500.0, round(distance * 42.0 + cargo * 0.08, 1))
        weight_lbs = round(cargo + fuel_lbs + 42000.0, 1)
        route = f"{origin} → {dest}"
        routing_provider = str(body.get("routing_provider") or "simbrief").strip().lower()[:32]
        plan = {
            "job_id": job_id,
            "route": route,
            "origin": origin,
            "destination": dest,
            "fuel_lbs": fuel_lbs,
            "weight_lbs": weight_lbs,
            "status": "generated",
            "routing_provider": routing_provider,
            "use_sky_dispatch": 1
            if routing_provider in ("sky_dispatch", "skytycoon", "skytycoon_dispatch")
            else 0,
        }
        try:
            sb_response = requests.get(
                "https://www.simbrief.com/api/xml.fetcher.php",
                params={
                    "orig": origin,
                    "dest": dest,
                    "type": "B738",
                    "json": "1",
                },
                timeout=5,
            )
            plan["simbrief_status_code"] = int(sb_response.status_code)
            if sb_response.status_code == 200 and sb_response.text.strip().startswith("{"):
                plan["simbrief_raw"] = sb_response.text[:250000]
                plan["simbrief_synced"] = True
        except requests.RequestException as exc:
            plan["simbrief_synced"] = False
            plan["simbrief_error"] = str(exc)[:300]
        conn.execute(
            """
            INSERT INTO active_web_flightplans (
                hardware_id, job_id, route, origin, destination,
                fuel_lbs, weight_lbs, payload_json, created_ts
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(hardware_id) DO UPDATE SET
                job_id = excluded.job_id,
                route = excluded.route,
                origin = excluded.origin,
                destination = excluded.destination,
                fuel_lbs = excluded.fuel_lbs,
                weight_lbs = excluded.weight_lbs,
                payload_json = excluded.payload_json,
                created_ts = excluded.created_ts;
            """,
            (
                str(hid)[:64],
                job_id,
                route,
                origin,
                dest,
                fuel_lbs,
                weight_lbs,
                json.dumps(plan, ensure_ascii=False),
                time.time(),
            ),
        )
        conn.commit()
        job = _job_board_row_to_client((job_id, *row[1:]))
    except sqlite3.Error as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        conn.close()
    try:
        pg = get_db_connection()
        try:
            _persist_active_flight_pg(
                pg,
                str(hid)[:128],
                job_id=job_id,
                dep_icao=origin,
                arr_icao=dest,
                routing_provider=routing_provider,
            )
        finally:
            pg.close()
    except psycopg2.Error:
        pass
    try:
        _server_kv_set(f"flight_arrived:{str(hid)[:64]}", "")
    except Exception:
        pass
    return JSONResponse(
        {
            "ok": True,
            "status": "accepted",
            "job": job,
            "ofp": plan,
            "routing_provider": routing_provider,
            "sky_dispatch_bonus": plan.get("use_sky_dispatch") == 1,
        }
    )


