@app.post("/api/v1/simbrief/generate")
def web_simbrief_generate(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    """Web-Dispatch: SimBrief-ID annehmen, OFP erzeugen/speichern und FMS-Sync-Link liefern."""
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    simbrief_user = str(
        body.get("simbrief_user")
        or body.get("simbrief_username")
        or body.get("username")
        or body.get("pilot_id")
        or ""
    ).strip()[:120]
    if not simbrief_user:
        return JSONResponse({"ok": False, "error": "missing_simbrief_user"}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS active_web_flightplans (
                hardware_id TEXT PRIMARY KEY,
                job_id INTEGER NOT NULL DEFAULT 0,
                route TEXT NOT NULL DEFAULT '',
                origin TEXT NOT NULL DEFAULT '',
                destination TEXT NOT NULL DEFAULT '',
                fuel_lbs REAL NOT NULL DEFAULT 0,
                weight_lbs REAL NOT NULL DEFAULT 0,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        existing = conn.execute(
            "SELECT payload_json, origin, destination, route FROM active_web_flightplans WHERE hardware_id = ? LIMIT 1;",
            (str(hid)[:64],),
        ).fetchone()
        plan: dict[str, Any] = {}
        if existing:
            try:
                plan = json.loads(str(existing[0] or "{}"))
            except json.JSONDecodeError:
                plan = {}
        origin = str(plan.get("origin") or (existing[1] if existing else "") or body.get("origin") or "EDDF").strip().upper()[:4]
        dest = str(plan.get("destination") or (existing[2] if existing else "") or body.get("destination") or "LOWW").strip().upper()[:4]
        route = str(plan.get("route") or (existing[3] if existing else "") or f"{origin} → {dest}")
        ac_type = str(body.get("aircraft_type") or plan.get("aircraft_type") or "B738").strip().upper()[:16]
        plan.update(
            {
                "origin": origin,
                "destination": dest,
                "route": route,
                "aircraft_type": ac_type,
                "simbrief_user": simbrief_user,
                "status": "generated",
            }
        )
        try:
            sb_response = requests.get(
                "https://www.simbrief.com/api/xml.fetcher.php",
                params={"username": simbrief_user, "orig": origin, "dest": dest, "type": ac_type, "json": "1"},
                timeout=8,
            )
            plan["simbrief_status_code"] = int(sb_response.status_code)
            if sb_response.status_code == 200 and sb_response.text.strip():
                plan["simbrief_raw"] = sb_response.text[:250000]
                plan["simbrief_synced"] = True
        except requests.RequestException as exc:
            plan["simbrief_synced"] = False
            plan["simbrief_error"] = str(exc)[:300]
        fuel_lbs = float(plan.get("fuel_lbs") or plan.get("block_fuel") or 12500)
        weight_lbs = float(plan.get("weight_lbs") or 54000)
        conn.execute(
            """
            INSERT INTO active_web_flightplans (
                hardware_id, job_id, route, origin, destination,
                fuel_lbs, weight_lbs, payload_json, created_ts
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(hardware_id) DO UPDATE SET
                route = excluded.route,
                origin = excluded.origin,
                destination = excluded.destination,
                fuel_lbs = excluded.fuel_lbs,
                weight_lbs = excluded.weight_lbs,
                payload_json = excluded.payload_json,
                created_ts = excluded.created_ts;
            """,
            (str(hid)[:64], int(plan.get("job_id") or 0), route, origin, dest, fuel_lbs, weight_lbs, json.dumps(plan, ensure_ascii=False), time.time()),
        )
        conn.commit()
    finally:
        conn.close()
    fms_sync_url = f"https://www.simbrief.com/system/dispatch.php?username={quote(simbrief_user)}"
    return JSONResponse({"ok": True, "status": "success", "ofp": plan, "fms_sync_url": fms_sync_url})


