FUEL_MARKET_ICAOS: tuple[str, ...] = ("EDDF", "LEPA", "EGLL", "LSZH", "LOWW", "LFPG", "EHAM", "LEBL")


def _ensure_realism_postgres_tables(conn) -> None:
    statements = [
        """
        CREATE TABLE IF NOT EXISTS fuel_market (
            id SERIAL PRIMARY KEY,
            icao VARCHAR(8) UNIQUE NOT NULL,
            price_per_gallon DOUBLE PRECISION NOT NULL DEFAULT 6.50,
            last_price_per_gallon DOUBLE PRECISION NOT NULL DEFAULT 6.50,
            last_update_utc TIMESTAMPTZ DEFAULT NOW()
        )
        """,
        """
        CREATE TABLE IF NOT EXISTS ground_service_sessions (
            hardware_id VARCHAR(128) PRIMARY KEY,
            job_id INTEGER DEFAULT 0,
            status VARCHAR(40) DEFAULT 'BLOCKED',
            progress INTEGER DEFAULT 0,
            updated_ts DOUBLE PRECISION DEFAULT 0,
            payload_json TEXT DEFAULT '{}'
        )
        """,
        """
        CREATE TABLE IF NOT EXISTS captain_loadsheets (
            hardware_id VARCHAR(128) PRIMARY KEY,
            job_id INTEGER DEFAULT 0,
            origin VARCHAR(8) DEFAULT '',
            destination VARCHAR(8) DEFAULT '',
            economy_pax INTEGER DEFAULT 0,
            business_pax INTEGER DEFAULT 0,
            economy_weight_lbs DOUBLE PRECISION DEFAULT 0,
            business_weight_lbs DOUBLE PRECISION DEFAULT 0,
            cargo_lbs DOUBLE PRECISION DEFAULT 0,
            block_fuel_lbs DOUBLE PRECISION DEFAULT 0,
            zfw_lbs DOUBLE PRECISION DEFAULT 0,
            cg_percent DOUBLE PRECISION DEFAULT 25,
            status VARCHAR(40) DEFAULT 'DRAFT',
            payload_json TEXT DEFAULT '{}',
            updated_ts DOUBLE PRECISION DEFAULT 0
        )
        """,
    ]
    with conn.cursor(cursor_factory=DictCursor) as cur:
        for stmt in statements:
            cur.execute(stmt)
            conn.commit()


def _refresh_fuel_market_once() -> None:
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        now = datetime.now(timezone.utc)
        seed = int(now.timestamp() // 3600)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            for icao in FUEL_MARKET_ICAOS:
                rng = random.Random(f"{icao}:{seed}")
                price = round(rng.uniform(5.35, 9.95), 2)
                cur.execute("SELECT price_per_gallon FROM fuel_market WHERE icao = %s;", (icao,))
                old = cur.fetchone()
                last_price = float(old["price_per_gallon"]) if old else price
                cur.execute(
                    """
                    INSERT INTO fuel_market (icao, price_per_gallon, last_price_per_gallon, last_update_utc)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (icao) DO UPDATE SET
                        last_price_per_gallon = fuel_market.price_per_gallon,
                        price_per_gallon = EXCLUDED.price_per_gallon,
                        last_update_utc = NOW()
                    """,
                    (icao, price, last_price),
                )
                conn.commit()
    finally:
        conn.close()


async def _fuel_market_hourly_loop() -> None:
    await asyncio.sleep(2.0)
    while True:
        try:
            await asyncio.to_thread(_refresh_fuel_market_once)
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[fuel_market] refresh failed: {exc!s}")
        await asyncio.sleep(3600.0)


def _fuel_market_rows(*, refresh: bool = False) -> list[dict[str, Any]]:
    if refresh:
        try:
            _refresh_fuel_market_once()
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[fuel_market] refresh skipped: {exc!s}")
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT icao, price_per_gallon, last_price_per_gallon, last_update_utc
                FROM fuel_market
                ORDER BY icao ASC
                """
            )
            rows = [dict(r) for r in cur.fetchall()]
            conn.commit()
    finally:
        conn.close()
    for row in rows:
        price = float(row.get("price_per_gallon") or 0)
        old = float(row.get("last_price_per_gallon") or price)
        row["trend"] = "up" if price > old else "down" if price < old else "flat"
        row["delta"] = round(price - old, 2)
        if hasattr(row.get("last_update_utc"), "isoformat"):
            row["last_update_utc"] = row["last_update_utc"].isoformat()
    return rows


def _loadsheets_from_plan(hid: str, plan: dict[str, Any], status: str = "DRAFT") -> dict[str, Any]:
    job_id = int(plan.get("job_id") or 0)
    origin = str(plan.get("origin") or plan.get("dep") or "EDDF").upper()[:4]
    dest = str(plan.get("destination") or plan.get("arr") or "LSZH").upper()[:4]
    cargo_lbs = float(plan.get("cargo_weight_lbs") or plan.get("cargo_lbs") or max(0, float(plan.get("weight_lbs") or 0) - 54000))
    fuel_lbs = float(plan.get("fuel_lbs") or plan.get("block_fuel") or 12500)
    distance = float(plan.get("distance_nm") or 700)
    pax_total = max(24, min(230, int((distance / 10.0) + 80)))
    business_pax = max(4, int(pax_total * 0.16))
    economy_pax = max(1, pax_total - business_pax)
    economy_weight = round(economy_pax * 195.0, 1)
    business_weight = round(business_pax * 215.0, 1)
    zfw = round(42000.0 + economy_weight + business_weight + cargo_lbs, 1)
    cg = round(22.5 + min(7.0, (business_pax / max(1, pax_total)) * 10.0) + random.Random(f"{hid}:{job_id}:{origin}:{dest}").uniform(-1.2, 1.2), 1)
    sheet = {
        "job_id": job_id,
        "route": str(plan.get("route") or f"{origin} -> {dest}"),
        "origin": origin,
        "destination": dest,
        "economy_pax": economy_pax,
        "business_pax": business_pax,
        "economy_weight_lbs": economy_weight,
        "business_weight_lbs": business_weight,
        "cargo_lbs": round(cargo_lbs, 1),
        "block_fuel_lbs": round(fuel_lbs, 1),
        "zfw_lbs": zfw,
        "cg_percent": cg,
        "status": status,
        "updated_ts": time.time(),
    }
    return sheet


def _store_loadsheet_pg(hid: str, sheet: dict[str, Any]) -> None:
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                INSERT INTO captain_loadsheets (
                    hardware_id, job_id, origin, destination, economy_pax, business_pax,
                    economy_weight_lbs, business_weight_lbs, cargo_lbs, block_fuel_lbs,
                    zfw_lbs, cg_percent, status, payload_json, updated_ts
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    job_id = EXCLUDED.job_id,
                    origin = EXCLUDED.origin,
                    destination = EXCLUDED.destination,
                    economy_pax = EXCLUDED.economy_pax,
                    business_pax = EXCLUDED.business_pax,
                    economy_weight_lbs = EXCLUDED.economy_weight_lbs,
                    business_weight_lbs = EXCLUDED.business_weight_lbs,
                    cargo_lbs = EXCLUDED.cargo_lbs,
                    block_fuel_lbs = EXCLUDED.block_fuel_lbs,
                    zfw_lbs = EXCLUDED.zfw_lbs,
                    cg_percent = EXCLUDED.cg_percent,
                    status = EXCLUDED.status,
                    payload_json = EXCLUDED.payload_json,
                    updated_ts = EXCLUDED.updated_ts
                """,
                (
                    hid[:128],
                    int(sheet.get("job_id") or 0),
                    sheet.get("origin", ""),
                    sheet.get("destination", ""),
                    int(sheet.get("economy_pax") or 0),
                    int(sheet.get("business_pax") or 0),
                    float(sheet.get("economy_weight_lbs") or 0),
                    float(sheet.get("business_weight_lbs") or 0),
                    float(sheet.get("cargo_lbs") or 0),
                    float(sheet.get("block_fuel_lbs") or 0),
                    float(sheet.get("zfw_lbs") or 0),
                    float(sheet.get("cg_percent") or 25),
                    str(sheet.get("status") or "DRAFT")[:40],
                    json.dumps(sheet, ensure_ascii=False),
                    float(sheet.get("updated_ts") or time.time()),
                ),
            )
            conn.commit()
    finally:
        conn.close()


