def _pg_fuel_tank_state(hardware_id: str, email: str = "") -> dict[str, Any]:
    hid = _pg_canonical_user_hid(hardware_id, email)
    out = {"fuel_storage": 0, "fuel_max_capacity": 50000, "credits": 0.0}
    if not hid:
        return out
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT COALESCE(fuel_storage, 0) AS fuel_storage,
                       COALESCE(fuel_max_capacity, 50000) AS fuel_max_capacity,
                       COALESCE(credits, money, 0) AS credits
                FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                LIMIT 1;
                """,
                (hid, hid[:64]),
            )
            row = cur.fetchone()
        if row:
            out["fuel_storage"] = int(row["fuel_storage"] or 0)
            out["fuel_max_capacity"] = max(50000, int(row["fuel_max_capacity"] or 50000))
            out["credits"] = float(row["credits"] or 0)
    finally:
        conn.close()
    return out


