@app.post("/api/v1/fuel/storage/buy")
def api_fuel_storage_buy(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid_raw = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if not hid_raw:
        raise HTTPException(status_code=401, detail="login_required")
    hid, _ = _web_postgres_session_refresh(request, hid_raw)
    if not hid:
        hid = hid_raw
    lang = _web_lang(request)
    try:
        liters = int(body.get("liters") or body.get("amount") or 0)
        price_per_l = float(body.get("price_per_liter") or body.get("price") or 2.5)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="bad_numbers")
    if liters < 100:
        return JSONResponse({"ok": False, "error": "min_liters"}, status_code=400)
    em = _portal_email_for_hardware(hid[:64]) or ""
    tank = _pg_fuel_tank_state(hid, em)
    storage = int(tank["fuel_storage"])
    cap = int(tank["fuel_max_capacity"])
    if storage + liters > cap:
        msg = _web_tx(lang, "fuel_tank_full")
        return JSONResponse({"ok": False, "error": "tank_full", "message": msg}, status_code=400)
    cost = float(liters) * price_per_l
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT COALESCE(credits, money, 0) AS credits FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s LIMIT 1;
                """,
                (hid, hid[:64]),
            )
            row = cur.fetchone()
            credits = float((row or {}).get("credits") or 0)
            if credits + 1e-6 < cost:
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
            cur.execute(
                """
                UPDATE users SET
                    credits = COALESCE(credits, money, 0) - %s,
                    fuel_storage = COALESCE(fuel_storage, 0) + %s
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (cost, liters, hid, hid[:64]),
            )
        conn.commit()
    finally:
        conn.close()
    tank2 = _pg_fuel_tank_state(hid, em)
    return JSONResponse({"ok": True, **tank2, "paid": cost})


FUEL_CAPACITY_TIERS_L = (150_000, 500_000, 2_000_000, 5_000_000, 25_000_000)
FUEL_CAPACITY_TIER_COSTS = (150_000.0, 500_000.0, 2_000_000.0, 5_000_000.0, 25_000_000.0)


