@app.post("/api/v1/fuel/tank/upgrade")
def api_fuel_tank_upgrade(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid_raw = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if not hid_raw:
        raise HTTPException(status_code=401, detail="login_required")
    hid, _ = _web_postgres_session_refresh(request, hid_raw)
    if not hid:
        hid = hid_raw
    lang = _web_lang(request)
    try:
        tier_ix = int(body.get("tier_index", 0))
    except (TypeError, ValueError):
        tier_ix = 0
    if tier_ix < 0 or tier_ix >= len(FUEL_CAPACITY_TIERS_L):
        return JSONResponse({"ok": False, "error": "bad_tier"}, status_code=400)
    target_cap = FUEL_CAPACITY_TIERS_L[tier_ix]
    cost = float(FUEL_CAPACITY_TIER_COSTS[tier_ix])
    em = _portal_email_for_hardware(hid[:64]) or ""
    tank = _pg_fuel_tank_state(hid, em)
    cur_cap = int(tank.get("fuel_max_capacity") or 50_000)
    if target_cap <= cur_cap:
        msg = (
            "Tank already at or above this tier."
            if lang.startswith("en")
            else "Tank hat diese Stufe bereits erreicht."
        )
        return JSONResponse({"ok": False, "error": "already_upgraded", "message": msg})
    conn = get_db_connection()
    try:
        _pg_ensure_user_prefs_columns(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT COALESCE(credits, money, 0) AS credits FROM users
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s LIMIT 1;
                """,
                (hid, hid[:64]),
            )
            row = cur.fetchone()
            credits = float((row or {}).get("credits") or 0)
            if credits + 1e-6 < cost:
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
            cur.execute(
                """
                UPDATE users SET
                    credits = COALESCE(credits, money, 0) - %s,
                    fuel_max_capacity = %s
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (cost, target_cap, hid, hid[:64]),
            )
        conn.commit()
    finally:
        conn.close()
    tank2 = _pg_fuel_tank_state(hid, em)
    return JSONResponse(
        {
            "ok": True,
            "tier_index": tier_ix,
            "fuel_max_capacity": target_cap,
            "paid": cost,
            **tank2,
        }
    )


@app.get("/api/v1/dispatch/live_events")
def api_dispatch_live_events(request: Request) -> JSONResponse:
    lang = _web_lang(request)
    events: list[dict[str, Any]] = []
    notams: list[dict[str, Any]] = []
    raw = _server_kv_get(_PORTAL_ADMIN_GLOBAL_CFG_KEY, "").strip()
    cfg: dict[str, Any] = {}
    if raw:
        try:
            cfg = json.loads(raw)
        except json.JSONDecodeError:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}
    active = cfg.get("active_event")
    if isinstance(active, dict) and active:
        mult = float(active.get("multiplier") or active.get("credit_mult") or 1.5)
        title = str(active.get("title") or active.get("type") or "Live-Event")
        events.append(
            {
                "id": str(active.get("type") or "active"),
                "title": title,
                "title_de": title,
                "title_en": title,
                "credit_mult": mult,
                "xp_mult": mult,
                "notam": bool(active.get("notam")),
            }
        )
    for ek, ev in (cfg.get("events") or {}).items():
        if not isinstance(ev, dict):
            continue
        if not ev.get("active"):
            continue
        mult = float(ev.get("fuel_mult") or ev.get("multiplier") or 1.5)
        events.append(
            {
                "id": str(ek),
                "title": str(ek),
                "title_de": str(ek),
                "title_en": str(ek),
                "credit_mult": mult,
                "xp_mult": mult,
                "notam": "notam" in str(ek).lower(),
            }
        )
    if not events:
        events.append(
            {
                "id": "platin_network",
                "title_de": "Platin-Netzwerk (Demo)",
                "title_en": "Platin network (demo)",
                "title": "Platin" if not lang.startswith("en") else "Platin network",
                "credit_mult": 1.5,
                "xp_mult": 1.5,
                "notam": False,
            }
        )
    for ev in events:
        if ev.get("notam"):
            notams.append({"id": ev.get("id"), "title": ev.get("title")})
    return JSONResponse(
        {
            "ok": True,
            "events": events,
            "notam_zones": notams,
            "bonus_pct": 50,
            "detail_de": "Flüge in Event-/NOTAM-Zonen: +50 % Credits & XP in PostgreSQL.",
            "detail_en": "Flights to event/NOTAM zones: +50% credits & XP in PostgreSQL.",
        }
    )


