@app.post("/api/v1/ground/trigger")
def api_ground_trigger(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    body = body if isinstance(body, dict) else {}
    try:
        progress = max(0, min(100, int(body.get("progress") or 0)))
    except (TypeError, ValueError):
        progress = 0
    status = "DEPARTURE_READY" if progress >= 100 else "BOARDING_ACTIVE"
    conn_s = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn_s.execute("SELECT payload_json FROM active_web_flightplans WHERE hardware_id = ? LIMIT 1;", (str(hid)[:64],)).fetchone()
    finally:
        conn_s.close()
    plan: dict[str, Any] = {}
    if row:
        try:
            plan = json.loads(str(row[0] or "{}"))
        except json.JSONDecodeError:
            plan = {}
    sheet = _loadsheets_from_plan(str(hid)[:64], plan, status=status)
    if progress >= 100:
        _store_loadsheet_pg(str(hid)[:64], sheet)
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                INSERT INTO ground_service_sessions (hardware_id, job_id, status, progress, updated_ts, payload_json)
                VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    job_id = EXCLUDED.job_id,
                    status = EXCLUDED.status,
                    progress = EXCLUDED.progress,
                    updated_ts = EXCLUDED.updated_ts,
                    payload_json = EXCLUDED.payload_json
                """,
                (str(hid)[:64], int(plan.get("job_id") or 0), status, progress, time.time(), json.dumps({"plan": plan, "loadsheet": sheet}, ensure_ascii=False)),
            )
            conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "status": status, "progress": progress, "loadsheet": sheet})


@app.get("/api/v1/ground/status")
def api_ground_status(request: Request) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    return JSONResponse(_ground_status_for_hid(str(hid)[:64]))


def _ground_status_for_hid(hid: str) -> dict[str, Any]:
    if not _pg_has_active_booked_job(hid):
        _pg_force_gsx_release(hid)
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT status, progress, payload_json FROM ground_service_sessions WHERE hardware_id = %s;", (hid[:64],))
            row = cur.fetchone()
            conn.commit()
    finally:
        conn.close()
    if not row:
        return {
            "ok": True,
            "active": False,
            "status": "DEPARTURE_READY",
            "progress": 100,
            "gsx_ready": True,
        }
    payload: dict[str, Any] = {}
    try:
        payload = json.loads(str(row.get("payload_json") or "{}"))
    except json.JSONDecodeError:
        payload = {}
    return {"ok": True, "active": True, "status": row.get("status") or "BLOCKED", "progress": int(row.get("progress") or 0), **payload}


def _ensure_pg_gsx_handling_table(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS gsx_handling (
                hardware_id VARCHAR(128) PRIMARY KEY,
                username VARCHAR(128) NOT NULL DEFAULT '',
                catering_status VARCHAR(32) NOT NULL DEFAULT 'idle',
                baggage_status VARCHAR(32) NOT NULL DEFAULT 'idle',
                boarding_status VARCHAR(32) NOT NULL DEFAULT 'idle',
                catering_pct INTEGER NOT NULL DEFAULT 0,
                baggage_pct INTEGER NOT NULL DEFAULT 0,
                boarding_pct INTEGER NOT NULL DEFAULT 0,
                total_progress INTEGER NOT NULL DEFAULT 0,
                gsx_ready INTEGER NOT NULL DEFAULT 0,
                command_queue VARCHAR(64) NOT NULL DEFAULT '',
                status VARCHAR(32) NOT NULL DEFAULT 'BLOCKED',
                updated_ts DOUBLE PRECISION NOT NULL DEFAULT 0
            );
            """
        )
    conn.commit()


def _gsx_handling_row_for_hid(hid: str) -> dict[str, Any]:
    conn = get_db_connection()
    try:
        _ensure_pg_gsx_handling_table(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                "SELECT * FROM gsx_handling WHERE hardware_id = %s;",
                (hid[:128],),
            )
            row = cur.fetchone()
        return dict(row) if row else {}
    finally:
        conn.close()


def _pg_has_active_booked_job(hardware_id: str) -> bool:
    """Nur gebuchte Cloud-Jobs (job_id > 0) halten GSX-Sperre aktiv."""
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return False
    conn = get_db_connection()
    try:
        _ensure_active_flights_pg(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                "SELECT COALESCE(job_id, 0) AS job_id FROM active_flights WHERE hardware_id = %s LIMIT 1;",
                (hid,),
            )
            row = cur.fetchone()
        return bool(row and int(row.get("job_id") or 0) > 0)
    except psycopg2.Error:
        return False
    finally:
        conn.close()


def _pg_force_gsx_release(hardware_id: str, username: str = "") -> None:
    """Hebt Geister-GSX-Sperren auf (PostgreSQL, sofort commit)."""
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return
    uname = str(username or "").strip()[:80] or _pilot_display_name_for_hid(hid[:64]) or "Pilot"
    now = time.time()
    conn = get_db_connection()
    try:
        _ensure_pg_gsx_handling_table(conn)
        _ensure_realism_postgres_tables(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO gsx_handling (
                    hardware_id, username, catering_status, baggage_status, boarding_status,
                    catering_pct, baggage_pct, boarding_pct, total_progress, gsx_ready,
                    command_queue, status, updated_ts
                ) VALUES (%s,%s,'COMPLETED','COMPLETED','COMPLETED',100,100,100,100,1,'','DEPARTURE_READY',%s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    username = EXCLUDED.username,
                    catering_status = 'COMPLETED',
                    baggage_status = 'COMPLETED',
                    boarding_status = 'COMPLETED',
                    catering_pct = 100,
                    baggage_pct = 100,
                    boarding_pct = 100,
                    total_progress = 100,
                    gsx_ready = 1,
                    command_queue = '',
                    status = 'DEPARTURE_READY',
                    updated_ts = EXCLUDED.updated_ts;
                """,
                (hid, uname, now),
            )
            cur.execute(
                """
                INSERT INTO ground_service_sessions (hardware_id, job_id, status, progress, updated_ts, payload_json)
                VALUES (%s, 0, 'DEPARTURE_READY', 100, %s, '{}')
                ON CONFLICT (hardware_id) DO UPDATE SET
                    status = 'DEPARTURE_READY',
                    progress = 100,
                    updated_ts = EXCLUDED.updated_ts,
                    payload_json = '{}';
                """,
                (hid[:64], now),
            )
        conn.commit()
    except psycopg2.Error as exc:
        conn.rollback()
        _server_log_line(f"[gsx] force_release failed {hid[:12]}…: {exc!s}")
    finally:
        conn.close()


def _pg_maybe_release_gsx_if_idle(hardware_id: str, username: str = "") -> bool:
    if _pg_has_active_booked_job(hardware_id):
        return False
    _pg_force_gsx_release(hardware_id, username)
    return True


def _gsx_status_payload_for_hid(hid: str, username: str = "") -> dict[str, Any]:
    _pg_maybe_release_gsx_if_idle(hid, username)
    row = _gsx_handling_row_for_hid(str(hid)[:128])
    if not row:
        return {
            "ok": True,
            "active": False,
            "status": "DEPARTURE_READY",
            "catering_pct": 100,
            "baggage_pct": 100,
            "boarding_pct": 100,
            "total_progress": 100,
            "gsx_ready": True,
            "command_queue": "",
            "released_idle": True,
        }
    return {
        "ok": True,
        "active": True,
        "username": row.get("username") or "",
        "status": row.get("status") or "DEPARTURE_READY",
        "catering_status": row.get("catering_status") or "COMPLETED",
        "baggage_status": row.get("baggage_status") or "COMPLETED",
        "boarding_status": row.get("boarding_status") or "COMPLETED",
        "catering_pct": int(row.get("catering_pct") or 100),
        "baggage_pct": int(row.get("baggage_pct") or 100),
        "boarding_pct": int(row.get("boarding_pct") or 100),
        "total_progress": int(row.get("total_progress") or 100),
        "gsx_ready": bool(int(row.get("gsx_ready") or 0)),
        "command_queue": row.get("command_queue") or "",
        "updated_ts": float(row.get("updated_ts") or 0),
    }


