@app.post("/api/v1/gsx/status")
@app.post("/api/v1/gsx/update_status")
def api_gsx_update_status(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = str(body.get("hardware_id") or "").strip()[:128]
    if not hid:
        raise HTTPException(status_code=401, detail="auth_failed")
    uname = str(body.get("username") or body.get("pilot_name") or "")[:80]
    c_pct = max(0, min(100, int(body.get("catering_pct", 0) or 0)))
    b_pct = max(0, min(100, int(body.get("baggage_pct", 0) or 0)))
    p_pct = max(0, min(100, int(body.get("boarding_pct", 0) or 0)))
    total = max(0, min(100, int(body.get("total_progress", (c_pct + b_pct + p_pct) // 3) or 0)))
    gsx_ready = bool(body.get("gsx_ready")) or total >= 100
    status = str(body.get("status") or ("DEPARTURE_READY" if gsx_ready else "BOARDING_ACTIVE"))[:32]
    cmd = str(body.get("command") or "").strip().upper()[:64]
    if cmd == "START_GSX":
        cmd = "START_GSX"
    conn = get_db_connection()
    try:
        _ensure_pg_gsx_handling_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO gsx_handling (
                    hardware_id, username, catering_status, baggage_status, boarding_status,
                    catering_pct, baggage_pct, boarding_pct, total_progress, gsx_ready,
                    command_queue, status, updated_ts
                ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                ON CONFLICT (hardware_id) DO UPDATE SET
                    username = EXCLUDED.username,
                    catering_status = EXCLUDED.catering_status,
                    baggage_status = EXCLUDED.baggage_status,
                    boarding_status = EXCLUDED.boarding_status,
                    catering_pct = EXCLUDED.catering_pct,
                    baggage_pct = EXCLUDED.baggage_pct,
                    boarding_pct = EXCLUDED.boarding_pct,
                    total_progress = EXCLUDED.total_progress,
                    gsx_ready = EXCLUDED.gsx_ready,
                    command_queue = CASE
                        WHEN EXCLUDED.command_queue <> '' THEN EXCLUDED.command_queue
                        ELSE gsx_handling.command_queue END,
                    status = EXCLUDED.status,
                    updated_ts = EXCLUDED.updated_ts;
                """,
                (
                    hid[:128],
                    uname,
                    str(body.get("catering_status", "idle"))[:32],
                    str(body.get("baggage_status", "idle"))[:32],
                    str(body.get("boarding_status", "idle"))[:32],
                    c_pct,
                    b_pct,
                    p_pct,
                    total,
                    1 if gsx_ready else 0,
                    cmd,
                    status,
                    time.time(),
                ),
            )
            conn.commit()
    finally:
        conn.close()
    if gsx_ready:
        conn2 = get_db_connection()
        try:
            _ensure_realism_postgres_tables(conn2)
            with conn2.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO ground_service_sessions (hardware_id, job_id, status, progress, updated_ts, payload_json)
                    VALUES (%s, 0, 'DEPARTURE_READY', 100, %s, '{}')
                    ON CONFLICT (hardware_id) DO UPDATE SET
                        status = 'DEPARTURE_READY', progress = 100, updated_ts = EXCLUDED.updated_ts;
                    """,
                    (hid[:64], time.time()),
                )
                conn2.commit()
        finally:
            conn2.close()
    return JSONResponse(
        {
            "ok": True,
            "status": status,
            "gsx_ready": gsx_ready,
            "total_progress": total,
            "command_queue": cmd,
        }
    )


