@app.post("/api/v1/academy/crew/upgrade")
def web_academy_crew_upgrade(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    member_id = str(body.get("member_id") or body.get("id") or "captain").strip()[:80] or "captain"
    cost = 50000.0
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute("BEGIN IMMEDIATE")
        bal_row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (str(hid)[:64],)).fetchone()
        bal = float(bal_row[0] or 0) if bal_row else 0.0
        if bal < cost:
            uconn.rollback()
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS pilot_crew_training (
                hardware_id TEXT NOT NULL,
                member_id TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 1,
                updated_ts REAL NOT NULL DEFAULT 0,
                PRIMARY KEY(hardware_id, member_id)
            );
            """
        )
        row = sconn.execute(
            "SELECT level FROM pilot_crew_training WHERE hardware_id = ? AND member_id = ?;",
            (str(hid)[:64], member_id),
        ).fetchone()
        next_level = int(row[0] or 1) + 1 if row else 2
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (cost, str(hid)[:64]))
        sconn.execute(
            """
            INSERT INTO pilot_crew_training (hardware_id, member_id, level, updated_ts)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(hardware_id, member_id) DO UPDATE SET
                level = excluded.level,
                updated_ts = excluded.updated_ts;
            """,
            (str(hid)[:64], member_id, next_level, time.time()),
        )
        uconn.commit()
        sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback()
        sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close()
        sconn.close()
    return JSONResponse({"ok": True, "member_id": member_id, "level": next_level, "cost": cost})


