@app.post("/api/v1/msfs/load_aircraft")
def web_msfs_load_aircraft(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    body = body if isinstance(body, dict) else {}
    try:
        amount = max(0.0, min(50000.0, float(body.get("amount", body.get("fuel_amount", 0)) or 0)))
    except (TypeError, ValueError):
        amount = 0.0
    icao = str(body.get("icao") or body.get("departure_icao") or "").strip().upper()[:4]
    if not icao:
        conn_s = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            row = conn_s.execute("SELECT origin FROM active_web_flightplans WHERE hardware_id = ? LIMIT 1;", (str(hid)[:64],)).fetchone()
            if row:
                icao = str(row[0] or "").strip().upper()[:4]
        finally:
            conn_s.close()
    icao = icao or "EDDF"
    _refresh_fuel_market_once()
    conn = get_db_connection()
    try:
        _ensure_realism_postgres_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT price_per_gallon FROM fuel_market WHERE icao = %s;", (icao,))
            row_p = cur.fetchone()
            price = float(row_p["price_per_gallon"]) if row_p else 6.50
            total_cost = round(amount * price, 2)
            use_voucher = bool(body.get("use_voucher") or body.get("fuel_voucher"))
            if use_voucher:
                try:
                    import skytycoon_prestige_pack as _prestige_pack

                    prof = _prestige_pack.pg_user_profile_row(str(hid)[:64])
                    if int(prof.get("fuel_vouchers") or 0) > 0:
                        cur.execute(
                            "UPDATE users SET fuel_vouchers = GREATEST(0, COALESCE(fuel_vouchers, 0) - 1) WHERE hardware_id = %s;",
                            (str(hid)[:64],),
                        )
                        total_cost = 0.0
                except Exception:
                    pass
            cur.execute("SELECT credits FROM users WHERE hardware_id = %s;", (str(hid)[:64],))
            row_u = cur.fetchone()
            bal = float(row_u["credits"] or 0) if row_u else 0.0
            if total_cost > bal:
                conn.commit()
                return JSONResponse(
                    {
                        "ok": False,
                        "error": "insufficient_credits",
                        "message_de": "Zu wenig Credits für die aktuelle Kerosinpreis-Ladung.",
                        "message_en": "Not enough credits for the current fuel market price.",
                        "icao": icao,
                        "price_per_gallon": price,
                        "total_cost": total_cost,
                        "credits": bal,
                    },
                    status_code=400,
                )
            cur.execute("UPDATE users SET credits = credits - %s WHERE hardware_id = %s;", (total_cost, str(hid)[:64]))
            conn.commit()
    finally:
        conn.close()
    _server_kv_set(
        f"msfs_command:{str(hid)[:64]}",
        json.dumps({"type": "load_aircraft", "amount": amount, "icao": icao, "price_per_gallon": price, "total_cost": total_cost, "ts": time.time()}, ensure_ascii=False),
    )
    return JSONResponse({"ok": True, "status": "queued", "command": "load_aircraft", "amount": amount, "icao": icao, "price_per_gallon": price, "total_cost": total_cost})


@app.post("/api/v1/market/lease")
def web_market_route_lease(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    route = str(body.get("route") or body.get("route_code") or "").strip().upper()[:24]
    owner = str(body.get("owner_hardware_id") or body.get("owner") or "SERVER").strip()[:64] or "SERVER"
    try:
        price = max(1000.0, min(2_000_000.0, float(body.get("price", body.get("credits", 25000)) or 25000)))
    except (TypeError, ValueError):
        price = 25000.0
    if not route or "→" not in route and "-" not in route:
        return JSONResponse({"ok": False, "error": "bad_route"}, status_code=400)
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute("BEGIN IMMEDIATE")
        bal_row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (str(hid)[:64],)).fetchone()
        bal = float(bal_row[0] or 0) if bal_row else 0.0
        if bal < price:
            uconn.rollback(); sconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (price, str(hid)[:64]))
        if owner != "SERVER":
            uconn.execute("UPDATE users SET credits = credits + ? WHERE hardware_id = ?;", (price * 0.95, owner[:64]))
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS route_leases_market (
                route TEXT NOT NULL,
                lessee_hardware_id TEXT NOT NULL,
                owner_hardware_id TEXT NOT NULL DEFAULT '',
                price_credits REAL NOT NULL DEFAULT 0,
                leased_ts REAL NOT NULL DEFAULT 0,
                PRIMARY KEY(route, lessee_hardware_id)
            );
            """
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO route_leases_market
            (route, lessee_hardware_id, owner_hardware_id, price_credits, leased_ts)
            VALUES (?, ?, ?, ?, ?);
            """,
            (route, str(hid)[:64], owner, price, time.time()),
        )
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "route": route, "price": price, "status": "leased"})


@app.get("/api/v1/world/challenges")
def web_world_challenges() -> JSONResponse:
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    pilots: list[dict[str, Any]] = []
    try:
        cur = conn.execute(
            """
            SELECT pilot_name, route, alt, aircraft, ts
            FROM radar_positions
            ORDER BY ts DESC LIMIT 50;
            """
        )
        seen: set[str] = set()
        for idx, r in enumerate(cur.fetchall(), start=1):
            name = str(r[0] or "Pilot")[:80]
            if name in seen:
                continue
            seen.add(name)
            pilots.append({
                "rank": len(pilots) + 1,
                "pilot_name": name,
                "score": max(1000, 5000 - idx * 137),
                "route": str(r[1] or "—"),
                "aircraft": str(r[3] or "—"),
            })
            if len(pilots) >= 20:
                break
    except sqlite3.Error:
        pilots = []
    finally:
        conn.close()
    return JSONResponse({
        "ok": True,
        "event": "Weekly Challenge: Alpine Precision Ops",
        "goal": "Sammle diese Woche Punkte durch präzise IFR-Flüge und sichere Landungen.",
        "leaderboard": pilots,
    })


