@app.get("/api/v1/weather/metar")
def web_weather_metar(icao: str = "") -> JSONResponse:
    code = str(icao or "").strip().upper()[:4]
    if len(code) != 4:
        return JSONResponse({"ok": False, "error": "bad_icao"}, status_code=400)
    metar = f"METAR {code} — nicht verfügbar"
    taf = f"TAF {code} — nicht verfügbar"
    try:
        mr = requests.get(
            "https://aviationweather.gov/api/data/metar",
            params={"ids": code, "format": "raw"},
            timeout=6,
        )
        if mr.status_code == 200 and (mr.text or "").strip():
            metar = (mr.text or "").strip().splitlines()[0][:600]
    except requests.RequestException:
        pass
    try:
        tr = requests.get(
            "https://aviationweather.gov/api/data/taf",
            params={"ids": code, "format": "raw"},
            timeout=6,
        )
        if tr.status_code == 200 and (tr.text or "").strip():
            taf = (tr.text or "").strip().splitlines()[0][:800]
    except requests.RequestException:
        pass
    return JSONResponse({"ok": True, "icao": code, "metar": metar, "taf": taf})


@app.get("/api/v1/scrapyard/list")
def scrapyard_list_public(
    request: Request,
    market_type: str = "",
    part_type: str = "",
) -> JSONResponse:
    """M189: Cloud-Ersatzteile — filterbar (USED_SCRAPYARD / NEW_PART / P2P_USER_PART)."""
    mt = str(
        market_type or part_type or request.query_params.get("market_type", "")
    ).strip().upper()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    parts: list[dict[str, Any]] = []
    try:
        try:
            open_count = int(conn.execute("SELECT COUNT(*) FROM cloud_scrapyard WHERE buyer_hw_id IS NULL;").fetchone()[0] or 0)
        except sqlite3.Error:
            open_count = 0
        if open_count < 50:
            conn.close()
            _regenerate_cloud_scrapyard_market(260)
            conn = sqlite3.connect(str(SERVER_DB_PATH))
        sql = """
            SELECT id, part_type, part_name, condition, price, seller_hw_id
            FROM cloud_scrapyard
            WHERE buyer_hw_id IS NULL
        """
        params: tuple[Any, ...] = ()
        if mt in ("USED_SCRAPYARD", "NEW_PART", "P2P_USER_PART"):
            sql += " AND part_type = ?"
            params = (mt,)
        elif mt == "USED":
            sql += " AND part_type IN ('USED_SCRAPYARD', 'P2P_USER_PART')"
        sql += " ORDER BY price ASC LIMIT 400;"
        cur = conn.execute(sql, params)
        for row in cur.fetchall():
            pid, ptype, pname, cond, price = row[0], row[1], row[2], row[3], row[4]
            seller = str(row[5] or "") if len(row) > 5 else ""
            parts.append(
                {
                    "id": int(pid),
                    "part_type": str(ptype or ""),
                    "part_name": str(pname or ""),
                    "condition": float(cond or 0),
                    "price": float(price or 0),
                    "player_listing": bool(seller.strip()),
                }
            )
    finally:
        conn.close()
    return JSONResponse({"ok": True, "parts": parts, "count": len(parts)})


