@app.post("/api/v1/scrapyard/list_user_part")
def scrapyard_list_user_part(request: Request, body: dict[str, Any]) -> JSONResponse:
    """M189: P2P-Spieler-Inserat auf dem globalen Schrottplatz."""
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException as exc:
        raise exc
    seller_hw = str(
        body.get("seller_hardware_id", body.get("hardware_id", hid)) or hid
    )[:64]
    part_name = str(body.get("part_name", body.get("name", "")) or "").strip()[:160]
    part_type = str(
        body.get("part_type", body.get("category", "P2P_USER_PART")) or "P2P_USER_PART"
    ).strip()[:48]
    try:
        condition = float(body.get("condition", body.get("wear_pct", 70)) or 70)
        price = float(body.get("price", body.get("price_credits", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse(
            {"ok": False, "status": "error", "message": "bad_numbers"},
            status_code=400,
        )
    if not part_name or price <= 0:
        return JSONResponse(
            {"ok": False, "status": "error", "message": "invalid_listing"},
            status_code=400,
        )
    condition = max(5.0, min(100.0, condition))
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            INSERT INTO cloud_scrapyard
            (part_type, part_name, condition, price, buyer_hw_id, seller_hw_id)
            VALUES (?, ?, ?, ?, NULL, ?);
            """,
            (part_type, part_name, condition, price, seller_hw),
        )
        conn.commit()
        listing_id = int(cur.lastrowid or 0)
    finally:
        conn.close()
    _server_log_line(
        f"[scrapyard] player listing #{listing_id} by {seller_hw[:12]}… — {part_name[:40]}"
    )
    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "listing_id": listing_id,
            "message": "Ersatzteil auf dem Weltmarkt gelistet.",
        }
    )


@app.post("/api/v1/scrapyard/buy/{part_id}")
def purchase_scrapyard_part_atomic(part_id: int, request: Request, body: dict[str, Any]) -> JSONResponse:
    """M187: Atomarer Kauf auf dem Schrottplatz."""
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException as exc:
        raise exc
    buyer_hw_id = str(body.get("buyer_hardware_id", hid) or hid)[:64]

    conn_server = sqlite3.connect(str(SERVER_DB_PATH))
    conn_user = sqlite3.connect(str(USER_DB_PATH))
    conn_server.execute("BEGIN IMMEDIATE")
    conn_user.execute("BEGIN IMMEDIATE")
    cur_server = conn_server.cursor()
    cur_user = conn_user.cursor()
    try:
        cur_server.execute(
            """
            SELECT part_name, price, buyer_hw_id, seller_hw_id
            FROM cloud_scrapyard WHERE id = ?;
            """,
            (int(part_id),),
        )
        part = cur_server.fetchone()
        if not part or part[2] is not None:
            conn_server.rollback()
            conn_user.rollback()
            return JSONResponse(
                {
                    "status": "error",
                    "message": "Dieses Ersatzteil wurde bereits von einem anderen Piloten gekauft!",
                },
                status_code=404,
            )
        part_name, price, _buyer_col, seller_hw_id = part
        seller_hw = str(seller_hw_id or "").strip()[:64]
        cur_user.execute(
            "SELECT credits, spare_parts_inventory_json FROM users WHERE hardware_id = ?;",
            (buyer_hw_id,),
        )
        user_data = cur_user.fetchone()
        if not user_data or float(user_data[0] or 0) < float(price or 0):
            conn_server.rollback()
            conn_user.rollback()
            return JSONResponse(
                {
                    "status": "error",
                    "message": "Ungenügendes Guthaben auf Ihrem Firmenkonto!",
                },
                status_code=400,
            )
        inventory_raw = user_data[1]
        cur_user.execute(
            "UPDATE users SET credits = credits - ? WHERE hardware_id = ?;",
            (float(price), buyer_hw_id),
        )
        if seller_hw and seller_hw != buyer_hw_id:
            cur_user.execute(
                """
                INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');
                """,
                (seller_hw,),
            )
            cur_user.execute(
                "UPDATE users SET credits = credits + ? WHERE hardware_id = ?;",
                (float(price), seller_hw),
            )
        cur_server.execute(
            "UPDATE cloud_scrapyard SET buyer_hw_id = ? WHERE id = ?;",
            (buyer_hw_id, int(part_id)),
        )
        inventory = json.loads(inventory_raw) if inventory_raw else []
        if not isinstance(inventory, list):
            inventory = []
        inventory.append(
            {
                "part_name": str(part_name),
                "bought_at": datetime.utcnow().isoformat(),
            }
        )
        cur_user.execute(
            "UPDATE users SET spare_parts_inventory_json = ? WHERE hardware_id = ?;",
            (json.dumps(inventory, ensure_ascii=False), buyer_hw_id),
        )
        cur_user.execute(
            "SELECT credits, xp, reputation, spare_parts_inventory_json FROM users WHERE hardware_id = ?;",
            (buyer_hw_id,),
        )
        snap = cur_user.fetchone()
        conn_server.commit()
        conn_user.commit()
        buyer_label = _pilot_display_name_for_hid(buyer_hw_id)
        if _looks_like_opaque_hardware_token(buyer_label):
            buyer_label = f"Pilot {buyer_hw_id[:6]}"
        _append_server_live_ticker(
            f"✈️ {buyer_label} hat ein Triebwerk auf dem Schrottplatz erworben!"
        )
        cloud: dict[str, Any] = {
            "status": "success",
            "ok": True,
            "message": "Ersatzteil erfolgreich atomar erworben.",
        }
        if snap:
            cloud["credits"] = float(snap[0] or 0)
            cloud["xp"] = float(snap[1] or 0)
            cloud["reputation"] = float(snap[2] or 0)
            try:
                inv_out = json.loads(snap[3] or "[]")
            except json.JSONDecodeError:
                inv_out = inventory
            if not isinstance(inv_out, list):
                inv_out = inventory
            cloud["spare_parts_inventory_json"] = inv_out
        return JSONResponse(cloud)
    except Exception as exc:  # noqa: BLE001
        conn_server.rollback()
        conn_user.rollback()
        return JSONResponse({"status": "error", "message": str(exc)}, status_code=500)
    finally:
        conn_server.close()
        conn_user.close()


@app.get("/api/v1/alliance/contracts")
def alliance_contracts_list(
    request: Request,
    alliance_id: str = "",
    hardware_id: str = "",
    password: str = "",
) -> JSONResponse:
    """M186: Großaufträge der Allianz (Schwarzes Brett)."""
    _desktop_api_auth_query(request, hardware_id, password)
    aid = str(alliance_id or request.query_params.get("alliance_id", "") or "").strip()[:32]
    if not aid:
        return JSONResponse({"ok": False, "contracts": []}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    out: list[dict[str, Any]] = []
    try:
        cur = conn.execute(
            """
            SELECT contract_id, alliance_id, cargo_weight, origin, destination,
                   reward_credits, progress
            FROM alliance_contracts
            WHERE alliance_id = ?
            ORDER BY contract_id DESC LIMIT 50;
            """,
            (aid,),
        )
        for row in cur.fetchall():
            out.append(
                {
                    "contract_id": int(row[0]),
                    "alliance_id": str(row[1]),
                    "cargo_weight": int(row[2] or 0),
                    "origin": str(row[3] or ""),
                    "destination": str(row[4] or ""),
                    "reward_credits": float(row[5] or 0),
                    "progress": int(row[6] or 0),
                }
            )
    finally:
        conn.close()
    return JSONResponse({"ok": True, "contracts": out})


@app.post("/api/v1/alliance/contracts")
def alliance_contracts_create(request: Request, body: dict[str, Any]) -> JSONResponse:
    """M186: CEO legt Allianz-Großauftrag an."""
    hid = _desktop_api_auth(request, body)
    aid = str(body.get("alliance_id", "") or "").strip()[:32]
    if not aid:
        return JSONResponse({"ok": False, "error": "bad_alliance"}, status_code=400)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[0]) != aid or str(mem[2] or "").lower() != "ceo":
        return JSONResponse({"ok": False, "error": "ceo_only"}, status_code=403)
    origin = str(body.get("origin", "") or "").upper()[:4]
    destination = str(body.get("destination", "") or "").upper()[:4]
    try:
        cargo_weight = int(body.get("cargo_weight", 0) or 0)
        reward_credits = float(body.get("reward_credits", 0) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_numbers"}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            INSERT INTO alliance_contracts
            (alliance_id, cargo_weight, origin, destination, reward_credits, progress)
            VALUES (?, ?, ?, ?, ?, 0);
            """,
            (aid, cargo_weight, origin, destination, reward_credits),
        )
        conn.commit()
        cid = int(cur.lastrowid or 0)
    finally:
        conn.close()
    return JSONResponse({"ok": True, "contract_id": cid})


@app.post("/api/v1/alliance/contracts/progress")
def alliance_contracts_progress(request: Request, body: dict[str, Any]) -> JSONResponse:
    """M186: Flug-Fortschritt auf Allianz-Großauftrag."""
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_in_alliance"}, status_code=403)
    try:
        contract_id = int(body.get("contract_id", 0) or 0)
        delta = int(body.get("progress_delta", body.get("cargo_lbs", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_id"}, status_code=400)
    if contract_id <= 0 or delta <= 0:
        return JSONResponse({"ok": False, "error": "bad_payload"}, status_code=400)
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT alliance_id, cargo_weight, progress, reward_credits
            FROM alliance_contracts WHERE contract_id = ?;
            """,
            (contract_id,),
        ).fetchone()
        if not row or str(row[0]) != str(mem[0]):
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        target = int(row[1] or 0)
        new_prog = min(target, int(row[2] or 0) + delta)
        conn.execute(
            "UPDATE alliance_contracts SET progress = ? WHERE contract_id = ?;",
            (new_prog, contract_id),
        )
        completed = target > 0 and new_prog >= target
        if completed:
            conn.execute(
                "UPDATE alliances SET credits = credits + ? WHERE alliance_id = ?;",
                (float(row[3] or 0), str(mem[0])),
            )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "progress": new_prog, "completed": completed})


