@app.post("/api/v1/alliance/research/start")
@app.post("/api/v1/user/alliance/research/start")
def alliance_research_start(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """M199: Credits in Allianz-Forschungsprojekt einzahlen."""
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse(
            {
                "ok": False,
                "error": "not_member",
                "message": _api_msg(request, "not_member", body=body),
            },
            status_code=403,
        )
    alliance_id = str(
        body.get("alliance_id", mem[0]) or mem[0]
    ).strip()[:32]
    if alliance_id != mem[0]:
        return JSONResponse(
            {
                "ok": False,
                "error": "forbidden",
                "message": _api_msg(request, "forbidden", body=body),
            },
            status_code=403,
        )
    perk_key = str(body.get("perk_key", "fuel_discount_t1") or "fuel_discount_t1")[
        :64
    ]
    try:
        amount = float(body.get("amount", body.get("credits", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse(
            {
                "ok": False,
                "error": "bad_amount",
                "message": _api_msg(request, "bad_amount", body=body),
            },
            status_code=400,
        )
    if amount < 1.0:
        return JSONResponse(
            {
                "ok": False,
                "error": "bad_amount",
                "message": _api_msg(request, "bad_amount", body=body),
            },
            status_code=400,
        )
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE;")
        row = conn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        if not row or float(row[0] or 0) + 1e-6 < amount:
            conn.rollback()
            return JSONResponse(
                {
                    "ok": False,
                    "error": "insufficient_alliance_credits",
                    "message": _api_msg(
                        request, "insufficient_alliance_credits", body=body
                    ),
                },
                status_code=400,
            )
        conn.execute(
            "UPDATE alliances SET credits = credits - ? WHERE alliance_id = ?;",
            (amount, alliance_id),
        )
        ex = conn.execute(
            """
            SELECT investment_progress FROM alliance_research
            WHERE alliance_id = ? AND perk_key = ?;
            """,
            (alliance_id, perk_key),
        ).fetchone()
        if ex:
            new_prog = min(100.0, float(ex[0] or 0) + amount / 1000.0)
            conn.execute(
                """
                UPDATE alliance_research SET investment_progress = ?, status = 'active'
                WHERE alliance_id = ? AND perk_key = ?;
                """,
                (new_prog, alliance_id, perk_key),
            )
        else:
            new_prog = min(100.0, amount / 1000.0)
            conn.execute(
                """
                INSERT INTO alliance_research (
                    alliance_id, perk_key, level, investment_progress, status
                ) VALUES (?, ?, 0, ?, 'active');
                """,
                (alliance_id, perk_key, new_prog),
            )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse(
        {"ok": True, "status": "success", "perk_key": perk_key, "progress": new_prog}
    )


