@app.post("/api/v1/admin/news/publish")
async def admin_news_publish(
    request: Request,
    background_tasks: BackgroundTasks,
    body: dict[str, Any] | None = None,
) -> JSONResponse:
    """Patch Notes / News: KI DE+EN, PostgreSQL, Homepage, E-Mail async."""
    try:
        if not _admin_ok(request, body or {}):
            raise HTTPException(status_code=403, detail="admin_denied")
        payload = body or {}
        raw = str(
            payload.get("message")
            or payload.get("text")
            or payload.get("patch_notes")
            or payload.get("news")
            or ""
        ).strip()
        if not raw:
            return JSONResponse(
                {"status": "error", "message": "empty_message"}, status_code=400
            )
        msg_de = str(payload.get("message_de") or "").strip()
        msg_en = str(payload.get("message_en") or "").strip()
        if not msg_de and not msg_en:
            msg_de, msg_en = _sky_bilingual_from_text(raw)
        elif msg_de and not msg_en:
            _, msg_en = _sky_bilingual_from_text(msg_de)
        elif msg_en and not msg_de:
            msg_de, _ = _sky_bilingual_from_text(msg_en)
        news_id = _pg_publish_site_news(msg_de, msg_en)
        send_mail = bool(payload.get("send_email", True))
        if send_mail:
            background_tasks.add_task(_news_broadcast_worker, msg_de, msg_en)
        return JSONResponse(
            {
                "status": "queued",
                "ok": True,
                "news_id": news_id,
                "message_de": msg_de,
                "message_en": msg_en,
                "message": "News veröffentlicht (E-Mail im Hintergrund).",
            }
        )
    except HTTPException:
        raise
    except Exception as exc:
        _append_admin_log(f"[news/publish] {exc!r}")
        return JSONResponse({"status": "error", "message": str(exc)}, status_code=500)


