@app.websocket("/api/v1/ws/acars")
async def acars_chat_endpoint(websocket: WebSocket) -> None:
    """M185: Live-ACARS-Funknetzwerk für alle Cockpits."""
    await ACARS_CHAT_MANAGER.connect(websocket)
    try:
        while True:
            data_raw = await websocket.receive_text()
            try:
                payload = json.loads(data_raw)
            except json.JSONDecodeError:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            text = str(payload.get("text", payload.get("message", "")) or "").strip()
            if not text:
                continue
            broadcast_payload = {
                "sender": str(payload.get("pilot_name", "Unknown Captain"))[:80],
                "airline": str(payload.get("airline_name", "Freelancer"))[:80],
                "message": text[:500],
                "timestamp": datetime.now(timezone.utc).strftime("%H:%M"),
            }
            await ACARS_CHAT_MANAGER.broadcast_message(broadcast_payload)
    except WebSocketDisconnect:
        ACARS_CHAT_MANAGER.disconnect(websocket)
    except Exception as exc:  # noqa: BLE001
        _server_log_line(f"[acars] ws error: {exc!s}")
        ACARS_CHAT_MANAGER.disconnect(websocket)


def _user_account_frozen(conn: sqlite3.Connection, hid64: str) -> bool:
    row = conn.execute(
        """
        SELECT COALESCE(banned, 0), COALESCE(is_frozen, 0), COALESCE(strikes, 0),
               COALESCE(anti_cheat_strikes, 0)
        FROM users WHERE hardware_id = ?;
        """,
        (hid64,),
    ).fetchone()
    if not row:
        return False
    return bool(int(row[0] or 0) or int(row[1] or 0))


def _trigger_anti_cheat_lock(hid64: str, reason: str) -> None:
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT COALESCE(strikes, 0), COALESCE(anti_cheat_strikes, 0)
            FROM users WHERE hardware_id = ?;
            """,
            (hid64,),
        ).fetchone()
        if not row:
            return
        strikes = int(row[0] or 0) + 1
        ac_strikes = int(row[1] or 0) + 1
        banned = 1 if strikes >= 2 or ac_strikes >= 2 else 0
        conn.execute(
            """
            UPDATE users
            SET strikes = ?, anti_cheat_strikes = ?, is_frozen = 1, banned = ?
            WHERE hardware_id = ?;
            """,
            (strikes, ac_strikes, banned, hid64),
        )
        conn.commit()
    finally:
        conn.close()
    _append_admin_log(f"[ANTI-CHEAT] {hid64[:16]}… — {reason}")
    _server_log_line(f"[ANTI-CHEAT] lock {hid64[:24]} — {reason}")


@app.post("/api/v1/flight/finalize_secure")
async def secure_anti_cheat_validator(request: Request, body: dict[str, Any]) -> JSONResponse:
    """M185: Serverseitige Flug-Abrechnung mit Anti-Cheat (Geschwindigkeit & Credit-Rate)."""
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException as exc:
        raise exc
    dist = float(body.get("distance_nm", body.get("dist_nm", 0)) or 0.0)
    flight_time_min = float(body.get("flight_time_minutes", body.get("duration_min", 0)) or 0.0)
    claimed_credits = float(body.get("payout_credits", body.get("net_pay", 0)) or 0.0)
    custom_plan = _active_custom_route_plan(hid)
    if custom_plan:
        planned_dist = float(custom_plan.get("planned_distance_nm") or 0)
        planned_cr = float(custom_plan.get("planned_credits") or 0)
        planned_xp = float(custom_plan.get("planned_xp") or 0)
        if planned_cr > 0:
            claimed_credits = planned_cr
        if planned_xp > 0:
            body = dict(body)
            body["xp_gain"] = planned_xp
            body["xp"] = planned_xp
        if planned_dist > 0:
            dist = planned_dist
        route_from = str(custom_plan.get("dep_icao") or body.get("route_from", ""))[:4]
        route_to = str(custom_plan.get("arr_icao") or body.get("route_to", ""))[:4]
        if route_from:
            body["route_from"] = route_from
            body["dep"] = route_from
        if route_to:
            body["route_to"] = route_to
            body["arr"] = route_to
    is_stormy = bool(body.get("metar_storm_active", False))
    if is_stormy and claimed_credits > 0.0:
        claimed_credits = round(claimed_credits * 1.30, 2)
        _server_log_line(
            f"[METAR CENTER] +30% Risiko-Bonus für stürmische Landung an {hid[:12]}…"
        )
    xp_add = float(body.get("xp_gain", body.get("xp", 0)) or 0.0)
    route_from = str(body.get("route_from", body.get("dep", "")) or "").upper()[:4]
    route_to = str(body.get("route_to", body.get("arr", "")) or "").upper()[:4]
    flight_id = str(body.get("flight_id", "") or "").strip()[:64]
    pilot_name = str(body.get("pilot_name", "") or _pilot_display_name_for_hid(hid))[:120]

    conn_u = sqlite3.connect(str(USER_DB_PATH))
    try:
        if _user_account_frozen(conn_u, hid):
            return JSONResponse(
                {
                    "ok": False,
                    "status": "frozen",
                    "error": "SECURITY_TRIGGERED_CREDITS_BLOCKED",
                },
                status_code=403,
            )
    finally:
        conn_u.close()

    cheat = False
    cheat_reason = ""
    if dist > 0.0 and flight_time_min > 0.0:
        calculated_knots = (dist / flight_time_min) * 60.0
        credit_per_nm = claimed_credits / dist if dist > 0 else claimed_credits
        if calculated_knots > 1400.0:
            cheat = True
            cheat_reason = f"speed {calculated_knots:.0f} kt"
        elif credit_per_nm > 1000.0:
            cheat = True
            cheat_reason = f"credit_rate {credit_per_nm:.1f}/nm"
    elif claimed_credits > 500_000.0:
        cheat = True
        cheat_reason = "absurd payout"

    if cheat:
        await asyncio.to_thread(_trigger_anti_cheat_lock, hid, cheat_reason)
        raise HTTPException(
            status_code=403,
            detail="SECURITY_TRIGGERED_CREDITS_BLOCKED",
        )

    payout = max(0.0, claimed_credits)
    sd_mult = _routing_provider_bonus_multiplier(hid)
    if sd_mult > 1.0:
        payout = round(payout * sd_mult, 2)
        xp_add = round(xp_add * sd_mult, 2)
        _server_log_line(
            f"[SKY DISPATCH] +15% Credits/XP Bonus für {hid[:12]}… (routing_provider=sky_dispatch)"
        )
    pilot_payout = payout
    alliance_payout = 0.0
    alliance_id_for_split = ""
    if payout > 10_000.0:
        mem = _alliance_member_row(hid)
        if mem:
            alliance_id_for_split = str(mem[0] or "")
            pilot_payout = round(payout * 0.80, 2)
            alliance_payout = round(payout - pilot_payout, 2)
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT credits, xp FROM users WHERE hardware_id = ?;",
            (hid,),
        ).fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="no_user")
        new_cr = float(row[0] or 0) + pilot_payout
        new_xp = float(row[1] or 0) + max(0.0, xp_add)
        conn.execute(
            "UPDATE users SET credits = ?, xp = ? WHERE hardware_id = ?;",
            (new_cr, new_xp, hid),
        )
        conn.commit()
    finally:
        conn.close()

    if alliance_payout > 0.0 and alliance_id_for_split:
        conn_a = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            for alt in (
                "ALTER TABLE alliances ADD COLUMN bank_balance REAL NOT NULL DEFAULT 0;",
                "ALTER TABLE alliances ADD COLUMN flight_tax_collected REAL NOT NULL DEFAULT 0;",
            ):
                try:
                    conn_a.execute(alt)
                    conn_a.commit()
                except sqlite3.OperationalError:
                    pass
            conn_a.execute(
                """
                UPDATE alliances
                SET credits = COALESCE(credits, 0) + ?,
                    bank_balance = COALESCE(bank_balance, 0) + ?,
                    flight_tax_collected = COALESCE(flight_tax_collected, 0) + ?
                WHERE alliance_id = ?;
                """,
                (alliance_payout, alliance_payout, alliance_payout, alliance_id_for_split),
            )
            conn_a.commit()
        finally:
            conn_a.close()

    if flight_id:
        conn_s = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            conn_s.execute(
                """
                UPDATE flight_tracks
                SET completed = 1, route_json = ?
                WHERE flight_id = ? AND hardware_id = ?;
                """,
                (
                    json.dumps(
                        {
                            "dep": route_from,
                            "arr": route_to,
                            "distance_nm": dist,
                            "payout": pilot_payout,
                            "alliance_split": alliance_payout,
                        },
                        ensure_ascii=False,
                    )[:200_000],
                    flight_id,
                    hid,
                ),
            )
            conn_s.commit()
        finally:
            conn_s.close()

    try:
        touchdown_fpm = float(body.get("touchdown_fpm", 0.0) or 0.0)
    except (TypeError, ValueError):
        touchdown_fpm = 0.0
    if -100.0 <= touchdown_fpm < 0.0:
        aconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            aconn.execute(
                """
                INSERT OR IGNORE INTO user_awards (hardware_id, award_key, unlocked_at)
                VALUES (?, ?, ?);
                """,
                (hid, "BUTTER_PILOT", datetime.utcnow().isoformat()),
            )
            aconn.commit()
            _server_log_line(
                f"[AWARD ENGINE] Medaille 'Butter-Pilot' für {hid[:12]}… freigeschaltet."
            )
        except Exception:
            pass
        finally:
            aconn.close()

    miles_add = max(0.0, dist)
    if miles_add <= 0.0 and xp_add > 0:
        miles_add = max(0.0, xp_add)
    pg_result = _pg_apply_flight_rewards(
        hid,
        credit_add=pilot_payout,
        miles_add=miles_add,
        alliance_id=alliance_id_for_split,
        alliance_share=alliance_payout,
    )
    if custom_plan:
        _clear_custom_route_plan_pg(hid)

    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "message": "Flug erfolgreich validiert und abgerechnet.",
            "credits": new_cr,
            "xp": new_xp,
            "payout_applied": pilot_payout,
            "gross_payout": payout,
            "alliance_bank_share": alliance_payout,
            "alliance_id": alliance_id_for_split,
            "storm_bonus_applied": is_stormy,
            "postgres_sync": pg_result,
            "miles_total": pg_result.get("miles"),
            "rank": pg_result.get("rank"),
            "sky_dispatch_bonus_applied": sd_mult > 1.0,
            "reward_multiplier": sd_mult,
        }
    )


