@app.get("/api/v1/flight/msfs_status")
def flight_msfs_status(request: Request) -> JSONResponse:
    """MSFS-In-Game-Panel: Ankunft erkannt → nächsten Job buchen."""
    hid = _web_parse_token(_web_raw_session_cookie(request))[:64]
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    _pg_maybe_release_gsx_if_idle(hid)
    arrived = False
    raw = _server_kv_get(f"flight_arrived:{hid}")
    if raw.strip():
        try:
            data = json.loads(raw)
            arrived = (time.time() - float(data.get("ts") or 0)) < 7200.0
        except (json.JSONDecodeError, TypeError, ValueError):
            arrived = False
    phase = "unknown"
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                "SELECT COALESCE(flight_phase, status, '') AS ph FROM radar_positions WHERE hardware_id = %s LIMIT 1;",
                (hid,),
            )
            row = cur.fetchone()
            if row:
                phase = str(row["ph"] or "").strip()
        conn.commit()
    except Exception:
        pass
    finally:
        conn.close()
    phase_low = phase.lower()
    if any(x in phase_low for x in ("parked", "gate", "offline", "arrived", "landed")):
        arrived = True
    lang = _web_lang(request)
    return JSONResponse(
        {
            "ok": True,
            "arrived": arrived,
            "flight_phase": phase,
            "can_book_next": arrived,
            "jobs_url": f"{_public_origin()}/market/jobs?mode=msfs_panel",
            "label_de": "[ ✈️ Nächsten Job aus der Europa-Börse buchen ]",
            "label_en": "[ ✈️ Book next flight from Europe job board ]",
            "lang": lang,
        }
    )


