@app.post("/api/v1/flight/track/append")
def flight_track_append(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    flight_id = str(body.get("flight_id", "") or "").strip()[:64]
    if not flight_id:
        raise HTTPException(status_code=400, detail="bad_flight_id")
    pt = {
        "lat": float(body.get("lat", 0) or 0),
        "lon": float(body.get("lon", 0) or 0),
        "alt_ft": float(body.get("alt_ft", 0) or 0),
        "ts": time.time(),
    }
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT route_json FROM flight_tracks WHERE flight_id = ? AND hardware_id = ?;",
            (flight_id, hid),
        ).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        try:
            doc = json.loads(str(row[0] or "{}"))
        except json.JSONDecodeError:
            doc = {"points": []}
        if not isinstance(doc, dict):
            doc = {"points": []}
        pts = doc.get("points")
        if not isinstance(pts, list):
            pts = []
        pts.append(pt)
        if len(pts) > 5000:
            pts = pts[-5000:]
        doc["points"] = pts
        conn.execute(
            "UPDATE flight_tracks SET route_json = ? WHERE flight_id = ?;",
            (json.dumps(doc, ensure_ascii=False)[:800_000], flight_id),
        )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True})


@app.get("/api/v1/flight/tracks")
def flight_tracks_list(
    request: Request,
    hardware_id: str = "",
    password: str = "",
    limit: int = 40,
) -> JSONResponse:
    """Desktop: Flight-Tracking-Archiv."""
    body = {
        "hardware_id": hardware_id,
        "password": password,
        "portal_email": request.query_params.get("portal_email", ""),
    }
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        raise
    lim = max(1, min(100, int(limit or 40)))
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    out: list[dict[str, Any]] = []
    try:
        cur = conn.execute(
            """
            SELECT flight_id, pilot_name, route_json, completed, created_ts
            FROM flight_tracks
            WHERE hardware_id = ?
            ORDER BY created_ts DESC LIMIT ?;
            """,
            (hid, lim),
        )
        for fid, pilot, rj, done, cts in cur.fetchall():
            try:
                doc = json.loads(str(rj or "{}"))
            except json.JSONDecodeError:
                doc = {}
            if not isinstance(doc, dict):
                doc = {}
            out.append(
                {
                    "flight_id": str(fid),
                    "pilot_name": str(pilot or ""),
                    "dep": str(doc.get("dep", "")),
                    "arr": str(doc.get("arr", "")),
                    "completed": int(done or 0),
                    "created_ts": float(cts or 0),
                    "point_count": len(doc.get("points") or []),
                }
            )
    finally:
        conn.close()
    return JSONResponse({"ok": True, "tracks": out})


