def _mystery_drop_after_landing(hardware_id: str, report: dict[str, Any]) -> dict[str, Any]:
    """Prozedurale Zufalls-Belohnung nach Landung (SQLite-Inventar-Spiegel)."""
    import random

    hid64 = str(hardware_id or "").strip()[:64]
    if not hid64:
        return {}
    roll = random.random()
    drop: dict[str, Any] = {}
    if roll < 0.12:
        drop = {"type": "fuel_voucher", "kg": random.randint(200, 1200)}
    elif roll < 0.22:
        drop = {"type": "profit_booster", "pct": 5, "minutes": 45}
    elif roll < 0.30:
        drop = {"type": "part_crate", "part": "hydraulic_seal"}
    if not drop:
        return {}
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT spare_parts_inventory_json FROM users WHERE hardware_id = ?;",
            (hid64,),
        ).fetchone()
        inv: list[Any] = []
        if row and row[0]:
            try:
                inv = json.loads(str(row[0] or "[]"))
            except json.JSONDecodeError:
                inv = []
        if not isinstance(inv, list):
            inv = []
        inv.append({"drop": drop, "ts": time.time(), "flight": report.get("route", "")})
        conn.execute(
            "UPDATE users SET spare_parts_inventory_json = ? WHERE hardware_id = ?;",
            (json.dumps(inv, ensure_ascii=False), hid64),
        )
        conn.commit()
    except sqlite3.Error:
        conn.rollback()
    finally:
        conn.close()
    return drop


def _user_flight_logs_for_dashboard(hid64: str, limit: int = 25) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT report_json, created_ts FROM user_flight_logs
            WHERE hardware_id = ? ORDER BY created_ts DESC LIMIT ?;
            """,
            (hid64, int(limit)),
        )
        for raw, ts in cur.fetchall():
            try:
                rep = json.loads(str(raw or "{}"))
            except json.JSONDecodeError:
                rep = {}
            if not isinstance(rep, dict):
                rep = {}
            rep["_ts"] = float(ts or 0)
            out.append(rep)
    finally:
        conn.close()
    return out


def _alliance_member_row(hid64: str) -> tuple[str, str, str, float] | None:
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT m.alliance_id, m.role, a.name, COALESCE(a.credits, 0) AS credits
                FROM alliance_members m
                JOIN alliances a ON a.alliance_id = m.alliance_id
                WHERE (m.hardware_id = %s OR substring(m.hardware_id from 1 for 64) = %s)
                  AND m.role != 'pending'
                LIMIT 1;
                """,
                (hid64, hid64[:64]),
            )
            row = cur.fetchone()
            if not row:
                return None
            return (str(row["alliance_id"]), str(row["role"]), str(row["name"]), float(row["credits"] or 0))
    finally:
        conn.close()


def _alliance_public_list(limit: int = 40) -> list[dict[str, Any]]:
    conn = get_db_connection()
    out: list[dict[str, Any]] = []
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT a.alliance_id, a.name, COALESCE(a.credits, 0) AS credits,
                       (SELECT COUNT(*) FROM alliance_members m
                        WHERE m.alliance_id = a.alliance_id AND m.role != 'pending') AS members
                FROM alliances a ORDER BY COALESCE(a.credits, 0) DESC LIMIT %s;
                """,
                (int(limit),),
            )
            for row in cur.fetchall():
                out.append(
                    {
                        "alliance_id": str(row["alliance_id"]),
                        "name": str(row["name"]),
                        "credits": float(row["credits"] or 0),
                        "members": int(row["members"] or 0),
                    }
                )
    finally:
        conn.close()
    return out


