@app.post("/api/v1/web/alliance/create")
def web_alliance_create(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="unauthorized")
    hid64 = str(hid).strip()[:64]
    if _alliance_member_row(hid64):
        return JSONResponse({"ok": False, "error": "already_member"}, status_code=400)
    name = str(body.get("name", "") or "").strip()[:80]
    if len(name) < 3:
        return JSONResponse({"ok": False, "error": "bad_name"}, status_code=400)
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT credits FROM users WHERE hardware_id = %s;", (hid64,))
            row = cur.fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "no_user"}, status_code=404)
        cr = float(row["credits"] or 0)
        if cr + 1e-6 < ALLIANCE_CREATE_COST:
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        aid = f"AL-{uuid.uuid4().hex[:10].upper()}"
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("UPDATE users SET credits = credits - %s, money = money - %s WHERE hardware_id = %s;", (ALLIANCE_CREATE_COST, ALLIANCE_CREATE_COST, hid64))
            cur.execute(
                "INSERT INTO alliances (alliance_id, name, ceo_hardware_id, credits) VALUES (%s, %s, %s, 0);",
                (aid, name, hid64),
            )
            cur.execute(
                """
                INSERT INTO alliance_members (alliance_id, hardware_id, username, role, contributed_credits, joined_ts)
                VALUES (%s, %s, %s, 'ceo', %s, %s);
                """,
                (aid, hid64, _pilot_display_name_for_hid(hid64), ALLIANCE_CREATE_COST, time.time()),
            )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse({"ok": True, "alliance_id": aid, "name": name})


