@app.post("/api/v1/web/alliance/route-lease")
def web_alliance_route_lease(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=401, detail="unauthorized")
    hid64 = str(hid).strip()[:64]
    mem = _alliance_member_row(hid64)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id, role, _aname, pool = mem[0], mem[1], mem[2], float(mem[3])
    lessee = str(body.get("lessee_hardware_id", body.get("to_hardware_id", "")) or "").strip()[:64]
    icao = str(body.get("icao", "") or "").strip().upper()[:4]
    if len(icao) != 4 or not lessee:
        return JSONResponse({"ok": False, "error": "bad_request"}, status_code=400)
    cost = float(body.get("credits", ROUTE_LEASE_COST_DEFAULT) or ROUTE_LEASE_COST_DEFAULT)
    cost = max(1000.0, min(500_000.0, cost))
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT 1 FROM alliance_members
                WHERE alliance_id = %s AND hardware_id = %s AND role != 'pending';
                """,
                (alliance_id, lessee),
            )
            in_alliance = cur.fetchone()
            if not in_alliance:
                return JSONResponse({"ok": False, "error": "lessee_not_member"}, status_code=400)
            if float(pool) + 1e-6 < cost:
                return JSONResponse({"ok": False, "error": "insufficient_pool"}, status_code=400)
            cur.execute("UPDATE alliances SET credits = credits - %s WHERE alliance_id = %s;", (cost, alliance_id))
            exp = time.time() + ROUTE_LEASE_DAYS * 86400
            cur.execute(
                """
                INSERT INTO alliance_route_leases (
                    alliance_id, lessor_hardware_id, lessee_hardware_id,
                    icao, credits, created_ts, expires_ts
                ) VALUES (%s, %s, %s, %s, %s, %s, %s);
                """,
                (alliance_id, hid64, lessee, icao, cost, time.time(), exp),
            )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse({"ok": True, "icao": icao, "lessee": lessee, "cost": cost})


