@app.post("/api/v1/alliance/hub/purchase")
@app.post("/api/v1/user/alliance/hub/purchase")
def alliance_hub_purchase(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) not in ("ceo", "co_leader"):
        raise HTTPException(
            status_code=403,
            detail=_api_msg(request, "forbidden", body=body),
        )
    alliance_id = mem[0]
    icao = str(body.get("icao", "") or "").strip().upper()[:4]
    if len(icao) != 4:
        return JSONResponse(
            {
                "ok": False,
                "error": "bad_icao",
                "message": _api_msg(request, "bad_icao", body=body),
            },
            status_code=400,
        )
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT credits FROM alliances WHERE alliance_id = %s;", (alliance_id,))
            row = cur.fetchone()
            if not row or float(row["credits"] or 0) + 1e-6 < ALLIANCE_HUB_PURCHASE_COST:
                conn.rollback()
                return JSONResponse(
                    {
                        "ok": False,
                        "error": "insufficient_alliance_credits",
                        "message": _api_msg(
                            request, "insufficient_alliance_credits", body=body
                        ),
                    },
                    status_code=400,
                )
            cur.execute("SELECT 1 FROM alliance_hubs WHERE alliance_id = %s AND icao = %s;", (alliance_id, icao))
            ex = cur.fetchone()
            if ex:
                conn.rollback()
                return JSONResponse(
                    {
                        "ok": False,
                        "error": "hub_exists",
                        "message": _api_msg(request, "hub_exists", body=body),
                    },
                    status_code=400,
                )
            cur.execute("UPDATE alliances SET credits = credits - %s WHERE alliance_id = %s;", (ALLIANCE_HUB_PURCHASE_COST, alliance_id))
            cur.execute(
                """
                INSERT INTO alliance_hubs (alliance_id, icao, bought_ts)
                VALUES (%s, %s, %s);
                """,
                (alliance_id, icao, time.time()),
            )
            conn.commit()
            cur.execute("SELECT credits FROM alliances WHERE alliance_id = %s;", (alliance_id,))
            pool = cur.fetchone()
            new_pool = float(pool["credits"] or 0) if pool else 0.0
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "icao": icao,
            "alliance_credits": new_pool,
            "hub_icaos": _alliance_hubs_icaos(alliance_id),
        }
    )


@app.post("/api/v1/alliance/finance/distribute_dividends")
@app.post("/api/v1/user/alliance/finance/distribute_dividends")
def alliance_distribute_dividends(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) != "ceo":
        raise HTTPException(status_code=403, detail="forbidden")
    alliance_id = mem[0]
    try:
        payout_total = float(body.get("amount", 0) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    if payout_total < 1.0:
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        sconn.execute("BEGIN IMMEDIATE;")
        uconn.execute("BEGIN IMMEDIATE;")
        row = sconn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        if not row or float(row[0] or 0) + 1e-6 < payout_total:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse(
                {"ok": False, "error": "insufficient_alliance_credits"},
                status_code=400,
            )
        inv = sconn.execute(
            """
            SELECT hardware_id, total_contributed FROM alliance_investments
            WHERE alliance_id = ? AND total_contributed > 0;
            """,
            (alliance_id,),
        ).fetchall()
        global_sum = sum(float(r[1] or 0) for r in inv)
        if global_sum <= 0:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "no_investments"}, status_code=400)
        paid: list[dict[str, float]] = []
        for hw_id, user_sum in inv:
            share = float(user_sum) / global_sum
            user_payout = payout_total * share
            if user_payout < 0.01:
                continue
            uconn.execute(
                "UPDATE users SET credits = credits + ? WHERE hardware_id = ?;",
                (user_payout, str(hw_id)),
            )
            paid.append({"hardware_id": str(hw_id), "amount": user_payout})
        sconn.execute(
            "UPDATE alliances SET credits = credits - ? WHERE alliance_id = ?;",
            (payout_total, alliance_id),
        )
        sconn.commit()
        uconn.commit()
        pool = sconn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        new_pool = float(pool[0] or 0) if pool else 0.0
    except Exception:
        sconn.rollback()
        uconn.rollback()
        raise
    finally:
        sconn.close()
        uconn.close()
    return JSONResponse(
        {
            "ok": True,
            "status": "success",
            "amount": payout_total,
            "alliance_credits": new_pool,
            "paid": paid,
        }
    )


