@app.post("/api/v1/alliance/insurance/resolve")
def alliance_insurance_resolve(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) not in ("ceo", "co_leader"):
        raise HTTPException(status_code=403, detail="forbidden")
    claim_id = int(body.get("claim_id", body.get("id", 0)) or 0)
    approve = str(body.get("action", body.get("decision", "approve"))).lower() in (
        "approve",
        "accept",
        "yes",
    )
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        sconn.execute("BEGIN IMMEDIATE;")
        row = sconn.execute(
            """
            SELECT alliance_id, applicant_hardware_id, requested_credits, status
            FROM alliance_insurance_claims WHERE id = ?;
            """,
            (claim_id,),
        ).fetchone()
        if not row or str(row[0]) != mem[0]:
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        if str(row[3]) != "pending":
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "already_resolved"}, status_code=400)
        if approve:
            amt = float(row[2] or 0)
            pool = sconn.execute(
                "SELECT credits FROM alliances WHERE alliance_id = ?;",
                (mem[0],),
            ).fetchone()
            if not pool or float(pool[0] or 0) + 1e-6 < amt:
                sconn.rollback()
                return JSONResponse(
                    {"ok": False, "error": "insufficient_alliance_credits"},
                    status_code=400,
                )
            sconn.execute(
                "UPDATE alliances SET credits = credits - ? WHERE alliance_id = ?;",
                (amt, mem[0]),
            )
            uconn.execute("BEGIN IMMEDIATE;")
            uconn.execute(
                "UPDATE users SET credits = credits + ? WHERE hardware_id = ?;",
                (amt, str(row[1])),
            )
            uconn.commit()
            sconn.execute(
                "UPDATE alliance_insurance_claims SET status = 'approved' WHERE id = ?;",
                (claim_id,),
            )
        else:
            sconn.execute(
                "UPDATE alliance_insurance_claims SET status = 'rejected' WHERE id = ?;",
                (claim_id,),
            )
        sconn.commit()
    except Exception:
        sconn.rollback()
        try:
            uconn.rollback()
        except Exception:
            pass
        raise
    finally:
        sconn.close()
        uconn.close()
    return JSONResponse({"ok": True, "approved": approve})


