@app.post("/api/v1/alliance/raid/contribute")
def alliance_raid_contribute(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    raid_id = int(body.get("raid_id", body.get("id", 0)) or 0)
    try:
        amount = float(body.get("amount", 0) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    if amount < 1.0:
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE;")
        sconn.execute("BEGIN IMMEDIATE;")
        urow = uconn.execute(
            "SELECT credits FROM users WHERE hardware_id = ?;", (hid,)
        ).fetchone()
        if not urow or float(urow[0] or 0) + 1e-6 < amount:
            uconn.rollback()
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        raid = sconn.execute(
            """
            SELECT alliance_id, target_credits, pooled_credits, status
            FROM alliance_raids WHERE id = ?;
            """,
            (raid_id,),
        ).fetchone()
        if not raid or str(raid[0]) != mem[0] or str(raid[3]) != "open":
            uconn.rollback()
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        uconn.execute(
            "UPDATE users SET credits = credits - ? WHERE hardware_id = ?;",
            (amount, hid),
        )
        sconn.execute(
            "UPDATE alliance_raids SET pooled_credits = pooled_credits + ? WHERE id = ?;",
            (amount, raid_id),
        )
        new_pooled = float(raid[2] or 0) + amount
        if new_pooled >= float(raid[1] or 0):
            sconn.execute(
                "UPDATE alliance_raids SET status = 'funded', pooled_credits = ? WHERE id = ?;",
                (new_pooled, raid_id),
            )
        uconn.commit()
        sconn.commit()
    except Exception:
        uconn.rollback()
        sconn.rollback()
        raise
    finally:
        uconn.close()
        sconn.close()
    return JSONResponse({"ok": True, "pooled": new_pooled})


