@app.post("/api/v1/user/alliance/donate")
def user_alliance_donate(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id = mem[0]
    try:
        amount = float(body.get("amount", body.get("credits", 0)) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    if amount < 1.0:
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE;")
        row = uconn.execute(
            "SELECT credits FROM users WHERE hardware_id = ?;", (hid,)
        ).fetchone()
        if not row or float(row[0] or 0) + 1e-6 < amount:
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        uconn.execute(
            "UPDATE users SET credits = credits - ? WHERE hardware_id = ?;",
            (amount, hid),
        )
        sconn.execute("BEGIN IMMEDIATE;")
        sconn.execute(
            "UPDATE alliances SET credits = credits + ? WHERE alliance_id = ?;",
            (amount, alliance_id),
        )
        sconn.execute(
            """
            UPDATE alliance_members SET contributed_credits = contributed_credits + ?
            WHERE alliance_id = ? AND hardware_id = ?;
            """,
            (amount, alliance_id, hid),
        )
        sconn.execute(
            """
            INSERT INTO alliance_investments (alliance_id, hardware_id, total_contributed)
            VALUES (?, ?, ?)
            ON CONFLICT(alliance_id, hardware_id) DO UPDATE SET
                total_contributed = total_contributed + excluded.total_contributed;
            """,
            (alliance_id, hid, amount),
        )
        uconn.commit()
        sconn.commit()
    except Exception:
        try:
            uconn.rollback()
        except Exception:
            pass
        try:
            sconn.rollback()
        except Exception:
            pass
        raise
    finally:
        uconn.close()
        sconn.close()
    row = None
    uconn2 = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = uconn2.execute(
            "SELECT credits, xp, reputation, loan_debt, strikes, credit_score FROM users WHERE hardware_id = ?;",
            (hid,),
        ).fetchone()
        uconn2.commit()
    finally:
        uconn2.close()
    out: dict[str, Any] = {"ok": True, "donated": amount}
    if row:
        out.update(_profile_snapshot_payload_extended(hid, row))
    return JSONResponse(out)


