def _authenticated_hid_from_request(request: Request) -> str | None:
    """Cookie oder Authorization: Bearer — Website + Desktop-App."""
    hid = _web_token_from_request(request)
    if not hid:
        return None
    canon, _ref = _web_postgres_session_refresh(request, hid)
    return canon or hid


@app.get("/api/v1/user/profile")
async def api_user_profile(request: Request) -> JSONResponse:
    """Web-Portal + Desktop: Profil (Cookie oder Bearer access_token)."""
    try:
        hid = _authenticated_hid_from_request(request)
        if not hid:
            return JSONResponse(
                {"status": "error", "message": "unauthorized"},
                status_code=401,
            )
        hid_key = str(hid).strip()[:128]
        hid64 = hid_key[:64]
        portal_email = _portal_email_for_hardware(hid64)
        lic = _license_keys_status_by_email(portal_email)
        pilot_name = ""
        conn = get_db_connection()
        try:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    """
                    SELECT username, email
                    FROM users
                    WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                    LIMIT 1;
                    """,
                    (hid_key, hid64),
                )
                ur = cur.fetchone()
                if ur:
                    pilot_name = str(ur.get("username") or "").strip()
                    if not portal_email:
                        portal_email = str(ur.get("email") or "").strip()[:200]
            conn.commit()
        except Exception as exc_nm:  # noqa: BLE001
            _pg_rollback(conn)
            _server_log_line(f"[web] user/profile name fetch: {exc_nm!s}")
        finally:
            conn.close()
        eco_prof = _pg_live_fetch_user_economy(hid_key, portal_email)
        credits = float(eco_prof.get("credits") or 0)
        xp_prof = float(eco_prof.get("xp") or 0)
        if portal_email and not lic.get("has_license"):
            lic = _license_keys_status_by_email(portal_email)
        if _is_global_superadmin_email(portal_email):
            _apply_global_superadmin_pg(portal_email, hid_key, pilot_name)
            lic = {
                "has_license": True,
                "license_active": True,
                "license_status": "ACTIVE",
                "license_key": _ensure_superadmin_sqlite_license(
                    portal_email, hid_key, pilot_name
                ),
            }
        web_hid = _web_display_hardware_id(hid_key, hid_key)
        out_prof: dict[str, Any] = {
            "ok": True,
            "status": "success",
            "hardware_id": web_hid,
            "web_id": web_hid,
            "pc_hardware_id": web_hid,
            "canonical_hardware_id": hid_key[:128],
            "pilot_name": pilot_name or "Pilot",
            "email": portal_email,
            "has_license": bool(lic.get("has_license")),
            "license_active": bool(lic.get("license_active")),
            "license_status": lic.get("license_status") or "NONE",
            "license_key": lic.get("license_key") or "",
            "credits": credits,
            "xp": xp_prof,
        }
        out_prof.update(_superadmin_api_payload_extra(portal_email))
        out_prof["achievements_unlocked"] = _achievement_unlock_if_needed(hid_key)
        return JSONResponse(out_prof)
    except Exception as exc_prof:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[web] user/profile failed: {exc_prof!s}")
        return JSONResponse({"status": "error"}, status_code=503)


