@app.post("/api/v1/user/profile/upload_logo")
async def upload_custom_airline_logo(
    request: Request, file: UploadFile = File(...)
) -> JSONResponse:
    """Payware-Kunden: Firmenlogo im Web-Portal hochladen (Session-Cookie)."""
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        return JSONResponse(
            {"status": "error", "message": "Nicht autorisierter Zugriff."},
            status_code=403,
        )
    hid64 = str(hid).strip()[:64]
    if not _web_portal_license_ok(hid64):
        return JSONResponse(
            {
                "status": "error",
                "message": "Für den Logo-Upload ist eine aktivierte Lifetime-Lizenz erforderlich.",
            },
            status_code=403,
        )
    fname = (file.filename or "").strip().lower()
    if not fname.endswith((".png", ".jpg", ".jpeg")):
        return JSONResponse(
            {
                "status": "error",
                "message": "Ungültiges Format! Bitte nur PNG oder JPG hochladen.",
            },
            status_code=400,
        )
    ext = os.path.splitext(fname)[1].lower()
    if ext == ".jpeg":
        ext = ".jpg"
    saved_filename = f"{hid64}_logo{ext}"
    file_path = USER_LOGOS_DIR / saved_filename
    try:
        raw = await file.read()
        if len(raw) > USER_LOGO_MAX_BYTES:
            return JSONResponse(
                {
                    "status": "error",
                    "message": "Datei zu groß (max. 2 MB).",
                },
                status_code=400,
            )
        with open(file_path, "wb") as buffer:
            buffer.write(raw)
        rel = f"/static/user_logos/{saved_filename}"
        conn = sqlite3.connect(str(USER_DB_PATH))
        try:
            conn.execute(
                "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
                (hid64,),
            )
            conn.execute(
                "UPDATE users SET logo_url_path = ? WHERE hardware_id = ?;",
                (rel, hid64),
            )
            conn.commit()
        finally:
            conn.close()
        print(f"[LIVERY CENTER] Airline-Logo für {hid64} gespeichert.")
        return JSONResponse({"status": "success", "logo_url": rel})
    except Exception as exc:  # noqa: BLE001
        return JSONResponse(
            {"status": "error", "message": str(exc)},
            status_code=500,
        )


