def _admin_auth_ok(
    request: Request,
    *,
    body: dict | None = None,
    query_admin_master_password: str = "",
    query_admin_password: str = "",
) -> bool:
    """Admin-REST: ``X-Admin-Token`` und/oder ``admin_password`` / ``admin_master_password`` (JSON oder Query)."""
    candidates = [
        (request.headers.get("X-Admin-Token") or request.headers.get("x-admin-token") or "").strip(),
        str((body or {}).get("admin_password") or "").strip(),
        str((body or {}).get("admin_master_password") or "").strip(),
        str(query_admin_password or "").strip(),
        str(query_admin_master_password or "").strip(),
    ]
    boot_pw = _superadmin_boot_password()
    if boot_pw and any(c == boot_pw for c in candidates if c):
        return True
    legacy_defaults = (
        "e85OieJLPMV6Nuv",
        (os.environ.get("SKYTYCOON_ADMIN_MASTER_PASSWORD") or "").strip(),
        ADMIN_MASTER_PASSWORD,
    )
    if any(c in legacy_defaults for c in candidates if c):
        return True
    if not ADMIN_API_PASSWORD:
        return False
    return any(c == ADMIN_API_PASSWORD for c in candidates if c)


def _admin_ok(request: Request, body: dict | None) -> bool:
    if _is_bigmaq_developer_partner(request):
        return True
    return _admin_auth_ok(request, body=body)


def _admin_users_list_enriched_rows() -> list[dict[str, Any]]:
    conn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT hardware_id, banned,
                   coalesce(license_key, ''), coalesce(license_activated, 0),
                   coalesce(has_license, 0), coalesce(is_verified, 0)
            FROM users ORDER BY hardware_id;
            """
        )
        rows: list[dict[str, Any]] = []
        for r in cur.fetchall():
            hid_u = str(r[0] or "")
            pilot = ""
            email = ""
            prow = sconn.execute(
                """
                SELECT pilot_name, email FROM web_pending_users
                WHERE hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (hid_u, hid_u[:64]),
            ).fetchone()
            if prow and prow[0]:
                pilot = str(prow[0]).strip()
            if prow and prow[1]:
                email = str(prow[1]).strip()
            if not pilot:
                lrow = sconn.execute(
                    """
                    SELECT pilot_name, customer_email FROM license_keys
                    WHERE status = 'activated' AND (
                        hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                    )
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (hid_u, hid_u[:64]),
                ).fetchone()
                if lrow and lrow[0]:
                    pilot = str(lrow[0]).strip()
                if lrow and lrow[1] and not email:
                    email = str(lrow[1]).strip()
            lic_key = str(r[2] or "").strip()
            license_active = int(r[3] or 0) == 1 or int(r[4] or 0) == 1
            rows.append(
                {
                    "hardware_id": hid_u,
                    "banned": int(r[1] or 0),
                    "pilot_name": pilot,
                    "username": pilot or email or hid_u,
                    "email": email,
                    "license_key": lic_key,
                    "has_license": 1 if license_active else 0,
                    "license_status": "aktiv" if license_active else "Keine Lizenz",
                    "is_verified": int(r[5] or 0),
                }
            )
        return rows
    finally:
        conn.close()
        sconn.close()


@app.get("/api/v1/admin/users/list")
def admin_users_list(
    request: Request,
    admin_master_password: str = "",
    admin_password: str = "",
) -> JSONResponse:
    """Ohne Passwort: minimale Liste. Mit gültigem Token/Query: inkl. Pilotname (GET-Fallback)."""
    if _admin_auth_ok(
        request,
        query_admin_master_password=admin_master_password,
        query_admin_password=admin_password,
    ):
        return JSONResponse({"users": _admin_users_list_enriched_rows()})
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT hardware_id, banned,
                   coalesce(license_key, ''), coalesce(license_activated, 0),
                   coalesce(has_license, 0), coalesce(is_verified, 0)
            FROM users ORDER BY hardware_id;
            """
        )
        rows = [
            {
                "hardware_id": r[0],
                "banned": int(r[1] or 0),
                "license_key": str(r[2] or ""),
                "has_license": 1 if int(r[3] or 0) == 1 or int(r[4] or 0) == 1 else 0,
                "license_status": (
                    "aktiv" if int(r[3] or 0) == 1 or int(r[4] or 0) == 1 else "Keine Lizenz"
                ),
                "is_verified": int(r[5] or 0),
            }
            for r in cur.fetchall()
        ]
        return JSONResponse({"users": rows})
    finally:
        conn.close()


