_CREDENTIALS_RESEND_PW_HINT = (
    "[Aus Sicherheitsgründen verschlüsselt – Passwort-Reset im Portal: "
    "https://skytycoon.info/login]"
)


def _admin_collect_credentials_resend_targets() -> list[dict[str, str]]:
    """Registrierte Lizenz-Inhaber (E-Mail + Key) für Massen-Nachversand."""
    seen: set[str] = set()
    out: list[dict[str, str]] = []
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        urows = uconn.execute(
            """
            SELECT hardware_id, COALESCE(license_key, ''), COALESCE(has_license, 0),
                   COALESCE(license_activated, 0)
            FROM users
            WHERE COALESCE(banned, 0) = 0
              AND (
                COALESCE(has_license, 0) = 1
                OR COALESCE(license_activated, 0) = 1
              );
            """
        ).fetchall()
        for hid_raw, ukey, _hl, _la in urows:
            hk = str(hid_raw or "").strip()[:64]
            if not hk:
                continue
            lk_row = sconn.execute(
                """
                SELECT license_key, pilot_name, customer_email
                FROM license_keys
                WHERE status = 'activated'
                  AND (hardware_id = ? OR substr(hardware_id, 1, 64) = ?)
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (hk, hk),
            ).fetchone()
            license_key = str(ukey or "").strip()
            pilot = ""
            email = ""
            if lk_row:
                if not license_key:
                    license_key = str(lk_row[0] or "").strip()
                pilot = str(lk_row[1] or "").strip()
                email = str(lk_row[2] or "").strip().lower()
            if not license_key or not email or "@" not in email:
                continue
            if not pilot:
                pilot = email.split("@", 1)[0][:120]
            if email in seen:
                continue
            seen.add(email)
            out.append(
                {
                    "email": email[:200],
                    "pilot_name": pilot[:120],
                    "license_key": license_key,
                }
            )
        for lk_row in sconn.execute(
            """
            SELECT license_key, pilot_name, customer_email
            FROM license_keys
            WHERE status = 'activated'
              AND trim(customer_email) != ''
              AND instr(lower(trim(customer_email)), '@') > 0;
            """
        ):
            license_key = str(lk_row[0] or "").strip()
            pilot = str(lk_row[1] or "").strip()
            email = str(lk_row[2] or "").strip().lower()
            if not license_key or not email or email in seen:
                continue
            if not pilot:
                pilot = email.split("@", 1)[0][:120]
            seen.add(email)
            out.append(
                {
                    "email": email[:200],
                    "pilot_name": pilot[:120],
                    "license_key": license_key,
                }
            )
    finally:
        uconn.close()
        sconn.close()
    return out


def _admin_resend_all_credentials_worker() -> dict[str, Any]:
    """SMTP-Massenversand Port 587/STARTTLS (blockierend — nur aus Thread aufrufen)."""
    targets = _admin_collect_credentials_resend_targets()
    sent = 0
    failed: list[str] = []
    for t in targets:
        em = t["email"]
        try:
            ok = _send_welcome_and_license_email_bilingual(
                em,
                t["pilot_name"],
                _CREDENTIALS_RESEND_PW_HINT,
                t["license_key"],
            )
            if ok:
                sent += 1
            else:
                failed.append(em)
        except Exception as exc:  # noqa: BLE001
            _server_log_line(
                f"[admin] resend credentials FEHLER {em[:80]!r}: {exc!r}"
            )
            failed.append(em)
    return {
        "sent": sent,
        "total": len(targets),
        "failed": failed,
    }


@app.post("/api/v1/admin/users/resend_all_credentials")
async def admin_resend_all_credentials_gate(
    request: Request, body: dict[str, Any]
) -> JSONResponse:
    """Massen-Nachversand: Lizenzschlüssel + Hinweis (kein Klartext-Passwort)."""
    if not _admin_ok(request, body):
        return JSONResponse(
            content={"status": "error", "message": "Zugriff verweigert!"},
            status_code=403,
        )
    result = await asyncio.to_thread(_admin_resend_all_credentials_worker)
    sent = int(result.get("sent") or 0)
    total = int(result.get("total") or 0)
    _append_admin_log(
        f"[admin] Massen-Mail Zugangsdaten: {sent}/{total} versendet"
    )
    return JSONResponse(
        {
            "status": "success",
            "message": (
                f"Datenabgleich abgeschlossen. {sent} E-Mails erfolgreich versendet!"
            ),
            "sent_count": sent,
            "total_targets": total,
            "failed_count": len(result.get("failed") or []),
        }
    )


