def _admin_resolve_pg_user(user_id: str) -> dict[str, Any] | None:
    """user_id = numerische PG-id oder hardware_id."""
    uid = str(user_id or "").strip()
    if not uid:
        return None
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            if uid.isdigit():
                try:
                    cur.execute(
                        """
                        SELECT id, hardware_id, username, email,
                               COALESCE(discord_id, '') AS discord_id
                        FROM users
                        WHERE id = %s
                        LIMIT 1;
                        """,
                        (int(uid),),
                    )
                    row = cur.fetchone()
                    if row:
                        return dict(row)
                except psycopg2.Error:
                    conn.rollback()
            cur.execute(
                """
                SELECT hardware_id, username, email,
                       COALESCE(discord_id, '') AS discord_id
                FROM users
                WHERE hardware_id = %s
                   OR substring(hardware_id from 1 for 64) = %s
                LIMIT 1;
                """,
                (uid[:128], uid[:64]),
            )
            row = cur.fetchone()
            return dict(row) if row else None
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[admin] resolve user failed: {exc_pg!s}")
        return None
    finally:
        conn.close()


def _admin_pg_cascade_delete_user(conn: Any, hardware_id: str, username: str = "") -> None:
    """FK-sichere Vor-Löschung verknüpfter Zeilen (ThreadedConnectionPool)."""
    hk = str(hardware_id or "").strip()[:128]
    un = str(username or "").strip()[:160]
    hk64 = hk[:64]
    if not hk:
        return
    _pg_ensure_p2p_marketplace_table(conn)
    _pg_ensure_pax_feedback_table(conn)
    with conn.cursor() as cur:
        cur.execute(
            """
            DELETE FROM pax_feedback
            WHERE user_id = %s OR user_id = %s
               OR lower(trim(COALESCE(user_id, ''))) = lower(trim(%s));
            """,
            (hk, hk64, un or hk),
        )
        cur.execute(
            """
            DELETE FROM p2p_marketplace
            WHERE seller_id = %s OR buyer_id = %s OR highest_bidder_id = %s
               OR seller_id = %s OR buyer_id = %s OR highest_bidder_id = %s;
            """,
            (hk, hk, hk, hk64, hk64, hk64),
        )
        cur.execute(
            """
            DELETE FROM fleet
            WHERE owner_username = %s OR owner_username = %s
               OR lower(trim(owner_username)) = lower(trim(%s));
            """,
            (hk, hk64, un or hk),
        )
        cur.execute("SAVEPOINT sp_admin_del")
        try:
            cur.execute(
                """
                DELETE FROM support_tickets
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (hk, hk64),
            )
            cur.execute("RELEASE SAVEPOINT sp_admin_del")
        except psycopg2.Error:
            cur.execute("ROLLBACK TO SAVEPOINT sp_admin_del")
        cur.execute(
            """
            DELETE FROM live_flights
            WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
            """,
            (hk, hk64),
        )
        cur.execute(
            """
            DELETE FROM radar_positions
            WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
            """,
            (hk, hk64),
        )
        try:
            cur.execute(
                """
                DELETE FROM license_keys
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                """,
                (hk, hk64),
            )
        except psycopg2.Error:
            conn.rollback()
        cur.execute(
            """
            DELETE FROM users
            WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
            """,
            (hk, hk64),
        )
    conn.commit()


@app.delete("/api/v1/admin/user/delete/{user_id}")
def admin_user_delete(
    request: Request,
    user_id: str,
    admin_master_password: str = "",
    admin_password: str = "",
) -> JSONResponse:
    """SuperAdmin: nukleare Kaskaden-Löschung (PostgreSQL + SQLite)."""
    if not _admin_auth_ok(
        request,
        query_admin_master_password=admin_master_password,
        query_admin_password=admin_password,
    ):
        raise HTTPException(status_code=403, detail="admin_denied")
    row = _admin_resolve_pg_user(user_id)
    if not row:
        raise HTTPException(status_code=404, detail="user_not_found")
    hid = str(row.get("hardware_id") or "").strip()[:128]
    uname = str(row.get("username") or "").strip()[:160]
    em = str(row.get("email") or "").strip().lower()[:200]
    discord_id = str(row.get("discord_id") or "").strip()
    if not discord_id:
        conn_l = get_db_connection()
        try:
            with conn_l.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    """
                    SELECT discord_user_id FROM discord_oauth_links
                    WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                    ORDER BY linked_ts DESC NULLS LAST
                    LIMIT 1;
                    """,
                    (hid, hid[:64]),
                )
                lrow = cur.fetchone()
                if lrow:
                    discord_id = str(lrow.get("discord_user_id") or "").strip()
        except Exception:
            _pg_rollback(conn_l)
        finally:
            conn_l.close()
    conn = get_db_connection()
    ok_pg = False
    try:
        _admin_pg_cascade_delete_user(conn, hid, uname)
        ok_pg = True
    except Exception as exc_del:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[admin] cascade delete failed: {exc_del!s}")
    finally:
        conn.close()
    ok_sqlite = _obliterate_user_cascade(hid, em)
    if discord_id.isdigit():
        _queue_discord_bot_command(
            "admin_ban_user",
            {
                "discord_user_id": discord_id,
                "hardware_id": hid[:64],
                "username": uname or hid[:16],
            },
        )
    elif uname:
        _queue_discord_bot_command(
            "admin_ban_user",
            {"username": uname, "hardware_id": hid[:64]},
        )
    if not ok_pg and not ok_sqlite:
        raise HTTPException(status_code=500, detail="delete_failed")
    _append_admin_log(
        f"[admin] user deleted user_id={user_id!r} hid={hid[:16]!r} discord={discord_id[:12]!r}"
    )
    return JSONResponse(
        {
            "ok": True,
            "status": "deleted",
            "hardware_id": hid[:64],
            "user_id": user_id,
            "discord_ban_queued": bool(discord_id or uname),
        }
    )


