@app.post("/api/v1/admin/users/reset_password")
def admin_users_reset_password(request: Request, body: dict) -> JSONResponse:
    """Setzt Cloud-Passwort (bcrypt) für Nutzer anhand Pilotenname oder hardware_id."""
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    new_pw = str(
        body.get("new_clear_password", body.get("new_password", "")) or ""
    ).strip()
    if len(new_pw) < 4:
        return JSONResponse({"ok": False, "error": "password_too_short"}, status_code=400)
    target_hid = str(body.get("hardware_id", "") or "").strip()[:64]
    target_pilot = str(body.get("target_pilot", body.get("pilot_name", "")) or "").strip()
    if not target_hid and target_pilot:
        conn_l = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            row = conn_l.execute(
                "SELECT hardware_id FROM license_keys WHERE pilot_name = ? COLLATE NOCASE LIMIT 1;",
                (target_pilot[:120],),
            ).fetchone()
            if row:
                target_hid = str(row[0] or "")[:64]
        finally:
            conn_l.close()
    if not target_hid:
        return JSONResponse({"ok": False, "error": "user_not_found"}, status_code=404)
    nh = _user_password_hash_store(new_pw)
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        cur = conn.execute(
            "UPDATE users SET password_hash = ? WHERE hardware_id = ?;",
            (nh, target_hid),
        )
        if cur.rowcount == 0:
            conn.execute(
                "INSERT INTO users (hardware_id, password_hash) VALUES (?, ?);",
                (target_hid, nh),
            )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "hardware_id": target_hid})


