    """Meilenstein 145: Client-Crash-Reports (Tester) → append ``admin_actions.log``."""
    hid = str(body.get("hardware_id", "") or "")[:128]
    pilot = str(body.get("pilot_name", "") or "")[:200]
    ver = str(body.get("app_version", "") or "")[:64]
    tb = str(body.get("traceback", "") or "")
    line = (
        f"\n{'=' * 72}\n{time.strftime('%Y-%m-%d %H:%M:%S')} CRASH_REPORT "
        f"hardware_id={hid!r} pilot={pilot!r} app_version={ver!r}\n{tb[:12000]}\n"
    )
    try:
        ADMIN_ACTIONS_LOG.parent.mkdir(parents=True, exist_ok=True)
        with ADMIN_ACTIONS_LOG.open("a", encoding="utf-8", errors="replace") as lf:
            lf.write(line)
    except OSError:
        pass
    return JSONResponse({"ok": True})


