def _client_update_manifest_dict() -> dict[str, Any]:
    """Öffentliches Update-JSON (MS109): version, url, optional changelog / mandatory / release_channel."""
    path = Path(
        os.environ.get("SKYTYCOON_VERSION_JSON_PATH") or (APP_ROOT / "version.json")
    )
    if path.is_file():
        try:
            data = json.loads(path.read_text(encoding="utf-8", errors="replace"))
            if isinstance(data, dict):
                data.setdefault("protected_download_url", "/api/v1/web/download/app")
                data.setdefault("mobile_apk_url", "/static/downloads/SkyTycoon_Mobile.apk")
                data.setdefault("mobile_filename", "SkyTycoon_Mobile.apk")
                data.setdefault("latest_version", str(data.get("mobile_latest_version") or "1.0.2"))
                data.setdefault("ios_download_url", "/static/downloads/SkyTycoon_iOS.ipa")
                data.setdefault("ios_filename", "SkyTycoon_iOS.ipa")
                ios_doc = data.get("ios") if isinstance(data.get("ios"), dict) else {}
                if not isinstance(ios_doc, dict):
                    ios_doc = {}
                ios_doc.setdefault("latest_version", str(data.get("ios_latest_version") or "1.0.2"))
                ios_doc.setdefault("download_url", str(data.get("ios_download_url") or "/static/downloads/SkyTycoon_iOS.ipa"))
                data["ios"] = ios_doc
                return data
        except (OSError, json.JSONDecodeError):
            pass
    out: dict[str, Any] = {
        "version": (os.environ.get("SKYTYCOON_UPDATE_VERSION") or "1.0.0-GOLD").strip()
        or "1.0.0-GOLD",
        "url": (os.environ.get("SKYTYCOON_UPDATE_EXE_URL") or "").strip(),
        "protected_download_url": "/api/v1/web/download/app",
        "mobile_apk_url": "/static/downloads/SkyTycoon_Mobile.apk",
        "mobile_filename": "SkyTycoon_Mobile.apk",
        "latest_version": "1.0.2",
        "mobile_latest_version": "1.0.2",
        "ios_download_url": "/static/downloads/SkyTycoon_iOS.ipa",
        "ios_filename": "SkyTycoon_iOS.ipa",
        "ios": {
            "latest_version": "1.0.2",
            "download_url": "/static/downloads/SkyTycoon_iOS.ipa",
        },
    }
    ch = (os.environ.get("SKYTYCOON_UPDATE_CHANGELOG") or "").strip()
    if ch:
        out["changelog"] = ch
    return out


@app.get("/api/v1/public/version.json")
def public_client_version_json() -> JSONResponse:
    """Update-Manifest — RAM-Cache (<1 ms), GZip via Middleware."""
    now = time.time()
    if now - float(_PUBLIC_VERSION_RAM.get("ts") or 0) > 8.0:
        _PUBLIC_VERSION_RAM["blob"] = _client_update_manifest_dict()
        _PUBLIC_VERSION_RAM["ts"] = now
    return JSONResponse(
        dict(_PUBLIC_VERSION_RAM.get("blob") or {}),
        headers={
            "Cache-Control": "public, max-age=8",
            "X-Platin-Cache": "HIT",
        },
    )


