def _admin_market_listing_row_to_dict(row: tuple[Any, ...]) -> dict[str, Any]:
    lid, seller, raw, price, _ts = (
        str(row[0] or ""),
        str(row[1] or ""),
        str(row[2] or "{}"),
        float(row[3] or 0),
        float(row[4] or 0),
    )
    try:
        payload: Any = json.loads(raw) if raw.strip() else {}
    except (json.JSONDecodeError, TypeError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    model = str(
        payload.get("model")
        or payload.get("model_name")
        or payload.get("title")
        or ""
    )
    seller_name = str(
        payload.get("seller_name")
        or payload.get("pilot_name")
        or seller
        or ""
    )
    hw = str(payload.get("hardware_id") or payload.get("hwid") or "")
    return {
        "id": lid,
        "model": model,
        "price": price,
        "seller_name": seller_name,
        "hardware_id": hw,
    }


