def _support_ticket_reply_impl(body: dict[str, Any]) -> dict[str, Any]:
    hid = str(body.get("hardware_id") or "").strip()[:128]
    txt = str(body.get("message_text") or body.get("message") or "").strip()[:4000]
    pilot = str(body.get("pilot_name") or "").strip()[:80]
    resolve = bool(body.get("resolve", body.get("set_resolved", True)))
    if not hid or not txt:
        raise HTTPException(status_code=400, detail="bad_request")
    msg_de, msg_en = _sky_bilingual_from_text(txt)
    ts = float(time.time())
    ticket_id = int(body.get("ticket_id") or 0)
    discord_channel_id = ""
    to_email = ""
    user_lang = "de"
    with pg_sync_transaction() as conn:
        _ensure_pg_support_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            if not ticket_id and hid:
                cur.execute(
                    "SELECT id, discord_channel_id FROM support_tickets WHERE hardware_id = %s ORDER BY id DESC LIMIT 1;",
                    (hid,),
                )
                trow = cur.fetchone()
                if trow:
                    ticket_id = int(trow["id"] or 0)
                    discord_channel_id = str(trow["discord_channel_id"] or "")
            cur.execute(
                """
                INSERT INTO support_messages (
                    ticket_id, hardware_id, sender, message_text, message_de, message_en, ts
                ) VALUES (%s, %s, 'admin', %s, %s, %s, %s);
                """,
                (ticket_id, hid, txt, msg_de, msg_en, ts),
            )
            new_status = "RESOLVED" if resolve else "replied"
            if ticket_id:
                cur.execute(
                    """
                    UPDATE support_tickets
                    SET status = %s,
                        pilot_name = CASE WHEN %s != '' THEN %s ELSE pilot_name END,
                        last_message_ts = %s
                    WHERE id = %s;
                    """,
                    (new_status, pilot, pilot, ts, ticket_id),
                )
            elif hid:
                cur.execute(
                    """
                    INSERT INTO support_tickets (hardware_id, status, pilot_name, last_message_ts, subject)
                    VALUES (%s, %s, %s, %s, 'Admin reply')
                    RETURNING id;
                    """,
                    (hid, new_status, pilot or "Pilot", ts),
                )
                nrow = cur.fetchone()
                if nrow:
                    ticket_id = int(nrow[0] if not isinstance(nrow, dict) else nrow.get("id", 0))
    prof = _mail_user_profile(hid)
    to_email = str(prof.get("email") or "").strip()
    user_lang = str(prof.get("lang") or "de")
    if resolve and to_email:
        reply_txt = msg_en if user_lang == "en" else msg_de
        subj = (
            "✅ SkyTycoon Support — Ticket resolved"
            if user_lang == "en"
            else "✅ SkyTycoon Support — Ticket erledigt"
        )
        plain = (
            f"Hello {prof.get('pilot_name', 'Captain')},\n\nYour support ticket was resolved:\n\n{reply_txt}\n"
            if user_lang == "en"
            else f"Hallo {prof.get('pilot_name', 'Captain')},\n\nDein Support-Ticket wurde erledigt:\n\n{reply_txt}\n"
        )
        html_m = f"<html><body style='background:#05070a;color:#e3e7ed;padding:20px;'><h2 style='color:#00ff66;'>{html.escape(subj)}</h2><p>{html.escape(reply_txt).replace(chr(10), '<br/>')}</p></body></html>"
        threading.Thread(
            target=lambda: _mail_guard_send_simple(
                to_email, prof.get("pilot_name", ""), subj, plain, html_m
            ),
            daemon=True,
        ).start()
    try:
        _queue_discord_bot_command(
            "ticket_reply",
            {
                "hardware_id": hid,
                "ticket_id": ticket_id,
                "message": txt,
                "pilot_name": pilot,
                "discord_channel_id": discord_channel_id,
                "created_ts": ts,
            },
        )
    except Exception as exc:  # noqa: BLE001
        _server_log_line(f"[discord] ticket_reply queue failed: {exc!s}")
    return {
        "ok": True,
        "status": "RESOLVED" if resolve else "replied",
        "ticket_id": ticket_id,
        "message_de": msg_de,
        "message_en": msg_en,
    }


@app.post("/api/v1/admin/support/reply")
def admin_support_reply(
    request: Request,
    background_tasks: BackgroundTasks,
    body: dict[str, Any] | None = None,
) -> JSONResponse:
    try:
        payload = body if isinstance(body, dict) else {}
        if not _admin_ok(request, payload):
            raise HTTPException(status_code=403, detail="admin_denied")
        result = _support_ticket_reply_impl(payload)
        return JSONResponse(result)
    except HTTPException:
        raise
    except Exception as exc:
        _append_admin_log(f"[support/reply] {exc!r}")
        return JSONResponse({"ok": False, "message": str(exc)}, status_code=500)


@app.post("/api/v1/admin/support/ticket/reply")
async def admin_support_ticket_reply(
    request: Request,
    background_tasks: BackgroundTasks,
    body: dict[str, Any] | None = None,
) -> JSONResponse:
    """Alias für Admin Commander — sofort queued, DB+Mail im Worker."""
    try:
        payload = body if isinstance(body, dict) else {}
        if not _admin_ok(request, payload):
            raise HTTPException(status_code=403, detail="admin_denied")

        def _worker() -> None:
            try:
                _support_ticket_reply_impl(payload)
            except Exception as wexc:
                _append_admin_log(f"[support/ticket/reply] worker: {wexc!r}")

        background_tasks.add_task(_worker)
        return JSONResponse(
            {
                "status": "queued",
                "ok": True,
                "message": "Antwort gespeichert (E-Mail i18n im Hintergrund).",
            }
        )
    except HTTPException:
        raise
    except Exception as exc:
        _append_admin_log(f"[support/ticket/reply] route: {exc!r}")
        return JSONResponse({"status": "error", "message": str(exc)}, status_code=500)


@app.post("/api/v1/admin/version-manifest")
def admin_version_manifest(request: Request, body: dict) -> JSONResponse:
    """Schreibt ``version.json`` auf dem Server (Admin Commander „Update weltweit freigeben“)."""
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    out: dict[str, Any] = {}
    for k in ("version", "url", "changelog", "mandatory", "release_channel"):
        if k not in body:
            continue
        v = body[k]
        if k == "mandatory":
            out[k] = bool(v)
        elif isinstance(v, str):
            if k == "version":
                out[k] = v.strip()[:64] or "1.0.0"
            elif k == "url":
                out[k] = v.strip()[:2048]
            elif k == "changelog":
                out[k] = v.strip()[:8000]
            elif k == "release_channel":
                out[k] = v.strip()[:32]
        else:
            out[k] = v
    if "version" not in out:
        raise HTTPException(status_code=400, detail="version_required")
    path = Path(
        os.environ.get("SKYTYCOON_VERSION_JSON_PATH") or (APP_ROOT / "version.json")
    )
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        path.write_text(
            json.dumps(out, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    except OSError as exc:
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    _append_admin_log(f"[admin] version.json geschrieben → {path} keys={list(out.keys())}")
    return JSONResponse({"ok": True, "written": str(path)})


@app.post("/api/v1/auth/verify_strict")
def auth_verify_strict(body: dict) -> JSONResponse:
    """Cloud-only: Lizenz, Verifizierung und Freeze-Status — kein Offline-Bypass."""
    hid = str(body.get("hardware_id", "") or body.get("id", "") or "").strip()[:128]
    if not hid:
        return JSONResponse(
            content={"status": "unauthorized", "message": "SECURITY_NO_HARDWARE_ID"},
            status_code=403,
        )
    em_v = str(
        body.get("email") or body.get("portal_email") or body.get("customer_email") or ""
    ).strip().lower()[:200]
    hk = _resolve_desktop_hardware_id(hid, em_v) or hid[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hk,),
        )
        uconn.commit()
        if _user_account_frozen(uconn, hk):
            return JSONResponse(
                content={
                    "status": "frozen",
                    "message": "SECURITY_ACCOUNT_FROZEN_CHEATING",
                },
                status_code=403,
            )
        exists = uconn.execute(
            "SELECT 1 FROM users WHERE hardware_id = ?;", (hk,)
        ).fetchone()
    finally:
        uconn.close()
    if not exists:
        return JSONResponse(
            content={"status": "unauthorized", "message": "SECURITY_NO_ACCOUNT_FOUND"},
            status_code=403,
        )
    is_verified, has_license = _sync_user_license_flags(hk)
    if has_license != 1 or is_verified != 1:
        return JSONResponse(
            content={"status": "unauthorized", "message": "SECURITY_LICENSE_REQUIRED"},
            status_code=403,
        )
    return JSONResponse(
        {"status": "success", "message": "ACCESS_GRANTED_CLOUD_VALIDATED"}
    )


def _resolve_desktop_hardware_id(hid: str, email: str = "") -> str:
    """USER_DB-Schlüssel: kanonische Server-HWID wenn PC-UUID passt."""
    hk = str(hid or "").strip()[:128]
    if not hk:
        return ""
    hk64 = hk[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        if uconn.execute(
            "SELECT 1 FROM users WHERE hardware_id = ?;", (hk64,)
        ).fetchone():
            return hk64
    finally:
        uconn.close()
    em = str(email or "").strip().lower()[:200]
    if em and "@" in em:
        canon, _pc = _account_canonical_hardware_id(hk, em, "")
        if canon:
            canon64 = canon[:64]
            uconn = sqlite3.connect(str(USER_DB_PATH))
            try:
                if uconn.execute(
                    "SELECT 1 FROM users WHERE hardware_id = ?;", (canon64,)
                ).fetchone():
                    return canon64
            finally:
                uconn.close()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        for (bound,) in conn.execute(
            """
            SELECT hardware_id FROM license_keys
            WHERE status = 'activated' AND trim(COALESCE(hardware_id, '')) != '';
            """
        ):
            b = str(bound or "").strip()
            if b and _hwid_accounts_match(b, hk, em):
                return b[:64]
    finally:
        conn.close()
    return hk64


@app.post("/api/v1/auth/verify")
def auth_verify(body: dict) -> JSONResponse:
    hid = str(body.get("hardware_id", "") or "").strip()[:128]
    current_key = str(body.get("current_key", "") or "").strip()
    email_v = str(
        body.get("email") or body.get("portal_email") or body.get("customer_email") or ""
    ).strip().lower()[:200]
    if not current_key:
        return JSONResponse({"status": "key_required"})
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT status, hardware_id, customer_email FROM license_keys WHERE license_key = ?;",
            (current_key,),
        ).fetchone()
        if not row:
            return JSONResponse({"status": "key_required"})
        st = str(row[0] or "")
        bound = str(row[1] or "")
        cust_em = str(row[2] or "").strip().lower()[:200]
        em_use = email_v or cust_em
        if st == "activated" and bound and not _hwid_accounts_match(bound, hid, em_use):
            if not _login_placeholder_hardware_for_bonding(bound):
                conn.execute(
                    "UPDATE license_keys SET hardware_id = ? WHERE license_key = ?;",
                    (hid[:128], current_key),
                )
                conn.commit()
        elif st == "unused":
            return JSONResponse({"status": "key_required"})
        return JSONResponse({"status": "activated"})
    finally:
        conn.close()


@app.post("/api/v1/auth/activate")
def auth_activate(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    try:
        hid = str(body.get("hardware_id", "") or "").strip()[:128]
        key = str(body.get("license_key", "") or "").strip().upper()
        email_c = str(
            body.get("email") or body.get("portal_email") or body.get("customer_email") or ""
        ).strip().lower()[:200]
        pilot = str(body.get("pilot_name") or body.get("username") or "")[:120]
        if not hid or not key:
            return JSONResponse({"status": "bad_request", "message": "bad_request"}, status_code=400)
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            row = conn.execute(
                "SELECT status, hardware_id, customer_email FROM license_keys WHERE license_key = ?;",
                (key,),
            ).fetchone()
            if not row:
                return JSONResponse({"status": "unknown_key"}, status_code=400)
            st, bound = str(row[0] or ""), str(row[1] or "")
            cust_em = str(row[2] or "").strip().lower()[:200]
            if email_c and cust_em and email_c != cust_em:
                return JSONResponse({"status": "email_mismatch"}, status_code=403)
            if st == "activated" and bound and not _hwid_accounts_match(
                bound, hid, email_c or cust_em
            ):
                if not _login_placeholder_hardware_for_bonding(bound):
                    conn.execute(
                        "UPDATE license_keys SET hardware_id = ? WHERE license_key = ?;",
                        (hid, key),
                    )
                    conn.commit()
            conn.execute(
                """
                UPDATE license_keys SET status = 'activated', hardware_id = ?,
                    customer_email = CASE
                        WHEN trim(customer_email) = '' AND ? != '' THEN ?
                        ELSE customer_email END,
                    pilot_name = CASE WHEN trim(pilot_name) = '' AND ? != '' THEN ? ELSE pilot_name END
                WHERE license_key = ?;
                """,
                (hid, email_c, email_c, pilot, pilot, key),
            )
            conn.commit()
        finally:
            conn.close()
        _pg_bind_license_to_hardware(email_c or cust_em, hid, key, pilot)
        _sync_user_license_flags(hid[:64])
        lang = _api_lang_from_request(request, body)
        msg_ok = (
            "License activated — cockpit unlocked."
            if lang.startswith("en")
            else "Lizenz aktiviert — Cockpit freigeschaltet."
        )
        return JSONResponse(
            {
                "status": "activated",
                "message": msg_ok,
                "has_license": 1,
                "license_key": key,
                "hardware_id": hid[:64],
            }
        )
    except Exception as exc_act:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[auth] activate failed: {exc_act!s}")
        return _sky_json_error_response(request, "generic", status_code=503)


@app.post("/api/v1/auth/license/check")
def auth_license_check(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    """Desktop: E-Mail + HWID gegen Lizenzbestand prüfen."""
    body = body if isinstance(body, dict) else {}
    try:
        em = str(
            body.get("email") or body.get("portal_email") or body.get("customer_email") or ""
        ).strip().lower()[:200]
        hid = str(body.get("hardware_id") or body.get("pc_hardware_id") or "")[:128]
        pilot = str(body.get("pilot_name") or body.get("username") or "")[:120]
        pw = str(body.get("password") or "").strip()
        auto_bound = False
        if em and hid and pw:
            ok_auto, lk_auto = _bind_unused_shop_license_to_hwid(em, hid, pilot, pw)
            if ok_auto:
                return JSONResponse(
                    {
                        "status": "ok",
                        "has_license": 1,
                        "license_key": lk_auto,
                        "hardware_id": hid[:64],
                        "auto_license_activated": True,
                    }
                )
        ok, lk = _email_hwid_has_active_license(em, hid)
        if ok:
            return JSONResponse(
                {
                    "status": "ok",
                    "has_license": 1,
                    "license_key": lk,
                    "hardware_id": hid[:64],
                    "auto_license_activated": auto_bound,
                }
            )
        return _license_required_json(request, extra={"hardware_id": hid[:64], "email": em})
    except Exception as exc_chk:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[auth] license/check failed: {exc_chk!s}")
        return _sky_json_error_response(request, "generic", status_code=503)


@app.post("/api/v1/auth/register_license")
def auth_register_license(body: dict) -> JSONResponse:
    key_raw = str(body.get("license_key", "") or "").strip()
    pilot = str(body.get("pilot_name", "") or "").strip()[:120]
    pw = str(body.get("password", "") or "").strip()
    hid = str(body.get("hardware_id", "") or "").strip()[:128]
    if not key_raw or not pilot or not pw or not hid:
        return JSONResponse({"status": "bad_request"})
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = None
        use_key = key_raw
        for cand in (key_raw, key_raw.upper()):
            row = conn.execute(
                "SELECT status, hardware_id FROM license_keys WHERE license_key = ?;",
                (cand,),
            ).fetchone()
            if row:
                use_key = cand
                break
        if not row:
            return JSONResponse({"status": "key_invalid"})
        st, bound = str(row[0] or ""), str(row[1] or "").strip()
        if st == "activated" and bound and not _hwid_accounts_match(
            bound, hid, str(body.get("email") or pilot or "")
        ):
            conn.execute(
                "UPDATE license_keys SET hardware_id = ? WHERE license_key = ?;",
                (hid, use_key),
            )
            conn.commit()
        if st != "unused":
            if not (st == "activated" and not bound):
                return JSONResponse({"status": "key_invalid"})
        is_desktop = bool(str(body.get("app_version", "") or "").strip())
        if is_desktop and _PWD_CTX is None:
            return JSONResponse({"status": "server_misconfigured_bcrypt"})
        salt, ph = _password_hash_store(pw)
        conn.execute(
            """
            UPDATE license_keys SET status = 'activated', hardware_id = ?,
            pilot_name = ?, password_salt = ?, password_hash = ?
            WHERE license_key = ?;
            """,
            (hid, pilot, salt, ph, use_key),
        )
        conn.execute(
            """
            UPDATE web_pending_users SET is_verified = 1, verification_token = ''
            WHERE hardware_id = ? OR hardware_id = ? OR substr(hardware_id, 1, 64) = ?;
            """,
            (hid, hid[:64], hid[:64]),
        )
        conn.commit()
    finally:
        conn.close()
    hid64 = hid.strip()[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hid64,),
        )
        uconn.execute(
            """
            UPDATE users SET license_key = ?, license_activated = 1
            WHERE hardware_id = ?;
            """,
            (use_key, hid64),
        )
        uconn.commit()
    finally:
        uconn.close()
    return JSONResponse({"status": "activated"})


async def _parse_auth_login_body(request: Request) -> dict[str, Any] | JSONResponse:
    """JSON, Form oder Roh-Body — verhindert „invalid JSON“ bei falscher Content-Type."""
    return await _parse_desktop_api_json_body(request)


def _auth_portal_login_response(
    conn: sqlite3.Connection,
    request: Request,
    *,
    hid_use: str,
    pilot: str,
    pw: str,
    p_email: str,
    p_name: str,
    p_hw: str,
    found_hw: str,
) -> JSONResponse:
    """Kostenloses Portal-Konto (ohne ST-Lizenz) — Desktop & Web."""
    hw_full = (hid_use or found_hw or p_hw or "").strip()[:128]
    hw64 = hw_full[:64]
    if not hw64:
        return JSONResponse({"status": "login_failed"})
    em = (p_email or pilot or "").strip()[:200]
    pn = (p_name or pilot or "").strip()[:120]
    if em and "@" in em:
        conn.execute(
            """
            UPDATE web_pending_users SET hardware_id = ?
            WHERE lower(trim(email)) = lower(trim(?));
            """,
            (hw_full, em),
        )
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, ?);",
            (hw64, _user_password_hash_store(pw)),
        )
        uconn.execute(
            """
            UPDATE users SET license_key = '', license_activated = 0, has_license = 0,
                is_verified = 1
            WHERE hardware_id = ?;
            """,
            (hw64,),
        )
        cols = {str(r[1]) for r in uconn.execute("PRAGMA table_info(users);").fetchall()}
        if "username" in cols and pn:
            uconn.execute(
                "UPDATE users SET username = ? WHERE hardware_id = ?;",
                (pn, hw64),
            )
        if "pilot_name" in cols and pn:
            uconn.execute(
                "UPDATE users SET pilot_name = ? WHERE hardware_id = ?;",
                (pn, hw64),
            )
        if "email" in cols and em:
            uconn.execute(
                "UPDATE users SET email = ? WHERE hardware_id = ?;",
                (em, hw64),
            )
        if "license_status" in cols:
            uconn.execute(
                "UPDATE users SET license_status = 'portal_free' WHERE hardware_id = ?;",
                (hw64,),
            )
        ur = uconn.execute(
            "SELECT credits, xp, reputation FROM users WHERE hardware_id = ?;",
            (hw64,),
        ).fetchone()
        uconn.commit()
    finally:
        uconn.close()
    conn.commit()
    _sync_user_license_flags(hw64)
    if em:
        _web_postgres_sync_login_profile(
            hw_full, email=em, pilot_name=pn or pilot, license_active=False
        )
    credits_f = xp_f = rep_f = 0.0
    if ur:
        credits_f, xp_f, rep_f = (
            float(ur[0] or 0),
            float(ur[1] or 0),
            float(ur[2] or 0),
        )
    return _auth_login_json_response(
        request,
        {
            "status": "login_success",
            "portal_account": True,
            "license_key": "",
            "license_status": 0,
            "has_license": 0,
            "hardware_id": hw64,
            "pilot_name": pn or pilot,
            "email": em,
            "credits": credits_f,
            "xp": xp_f,
            "reputation": rep_f,
            **_login_response_language_fields(hw64, em),
        },
        hw64,
    )


@app.post("/api/v1/auth/login")
async def auth_login(request: Request) -> JSONResponse:
    try:
        return await _auth_login_impl(request)
    except HTTPException:
        raise
    except Exception as exc_login:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[auth] login failed: {exc_login!s}")
        return _sky_json_error_response(request, "generic", status_code=503)


async def _auth_login_impl(request: Request) -> JSONResponse:
    body = await _parse_auth_login_body(request)
    if isinstance(body, JSONResponse):
        return body
    pw = str(body.get("password", "") or "").strip()
    hid_raw = str(
        body.get("pc_hardware_id")
        or body.get("incoming_pc_hardware_id")
        or body.get("hardware_id")
        or ""
    ).strip()
    hid_use = _desktop_atomic_pc_hardware_id(hid_raw)
    hid64 = hid_use[:64]
    em_login = str(
        body.get("email")
        or body.get("portal_email")
        or body.get("customer_email")
        or ""
    ).strip().lower()[:200]
    pilot_hint = str(
        body.get("pilot_name") or body.get("username") or ""
    ).strip()[:120]
    if not em_login or "@" not in em_login or not pw or not hid_use:
        return JSONResponse(
            {
                "status": "bad_request",
                "message": "email, password and pc_hardware_id required",
            }
        )
    pilot = pilot_hint or em_login.split("@", 1)[0][:120]
    lang_hint = str(
        body.get("selected_language") or body.get("ui_lang") or ""
    ).strip().lower()[:8]
    conn_pre = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        em_login = _resolve_login_email(conn_pre, pilot, em_login) or em_login
    finally:
        conn_pre.close()
    lk_body = str(body.get("license_key") or body.get("license") or "").strip()[:80]
    lk_repair_pre = ""
    repair_ok_pre = False
    if hid_use and pw and em_login:
        lk_repair_pre, repair_ok_pre = _cloud_sync_repair_portal_login(
            email=em_login,
            pilot_name=pilot,
            hardware_id=hid_use,
            password=pw,
            license_key=lk_body,
        )
    slot_ok = True
    if not repair_ok_pre:
        slot_ok, _slot_err = _hwid_triple_slot_allows(
            em_login or pilot, hid_use[:128]
        )
        if not slot_ok:
            return JSONResponse(
                {
                    "status": "login_failed",
                    "message": _hwid_limit_message(lang_hint),
                    "detail": "hwid_limit",
                },
                status_code=403,
            )
    boot_pw_login = _superadmin_boot_password()
    if _is_global_superadmin_email(em_login) and boot_pw_login and pw == boot_pw_login:
        hid64_sa = _apply_global_superadmin_pg(em_login, hid_use, pilot)
        lk_sa = _ensure_superadmin_sqlite_license(em_login, hid_use, pilot, pw)
        _web_postgres_sync_login_profile(
            hid_use, email=em_login, pilot_name=pilot, license_active=True
        )
        return _auth_login_json_response(
            request,
            {
                "status": "login_success",
                "portal_account": True,
                "license_key": lk_sa,
                "license_status": 1,
                "has_license": 1,
                "hardware_id": hid64_sa,
                "pilot_name": pilot,
                "email": em_login,
                "credits": 0.0,
                "xp": 0.0,
                "reputation": 100.0,
                **_superadmin_api_payload_extra(em_login),
                **_login_response_language_fields(hid64_sa, em_login),
            },
            hid64_sa,
        )
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    hwid_slot_provisioned = bool(repair_ok_pre and lk_repair_pre)
    try:
        if repair_ok_pre and lk_repair_pre:
            row = conn.execute(
                """
                SELECT password_salt, password_hash, hardware_id, status, license_key, customer_email, pilot_name
                FROM license_keys
                WHERE license_key = ?
                LIMIT 1;
                """,
                (lk_repair_pre,),
            ).fetchone()
        else:
            row = None
        if row is None and lk_body:
            row = conn.execute(
                """
                SELECT password_salt, password_hash, hardware_id, status, license_key, customer_email, pilot_name
                FROM license_keys
                WHERE upper(trim(license_key)) = upper(trim(?))
                ORDER BY created_ts DESC
                LIMIT 1;
                """,
                (lk_body,),
            ).fetchone()
        if row is None and em_login and "@" in em_login:
            row = conn.execute(
                """
                SELECT password_salt, password_hash, hardware_id, status, license_key, customer_email, pilot_name
                FROM license_keys
                WHERE lower(trim(customer_email)) = lower(trim(?))
                ORDER BY created_ts DESC
                LIMIT 1;
                """,
                (em_login,),
            ).fetchone()
        if row is None:
            row = conn.execute(
                """
                SELECT password_salt, password_hash, hardware_id, status, license_key, customer_email, pilot_name
                FROM license_keys
                WHERE status = 'activated'
                  AND (
                        lower(trim(pilot_name)) = lower(trim(?))
                     OR lower(trim(customer_email)) = lower(trim(?))
                     OR license_key = ?
                     OR upper(trim(license_key)) = upper(trim(?))
                  )
                ORDER BY created_ts DESC
                LIMIT 1;
                """,
                (pilot, em_login or pilot, pilot, lk_body or pilot),
            ).fetchone()
        if not row:
            pending = conn.execute(
                """
                SELECT email, pilot_name, hardware_id, password_salt, password_hash
                FROM web_pending_users
                WHERE lower(trim(email)) = lower(trim(?))
                   OR lower(trim(pilot_name)) = lower(trim(?))
                   OR hardware_id = ?
                   OR substr(hardware_id,1,64) = ?
                ORDER BY created_ts DESC
                LIMIT 1;
                """,
                (pilot, pilot, hid_use, hid64),
            ).fetchone()
            em_try = _resolve_login_email(conn, pilot, em_login) or em_login
            if not pending and em_try and "@" in em_try:
                pending = conn.execute(
                    """
                    SELECT email, pilot_name, hardware_id, password_salt, password_hash
                    FROM web_pending_users
                    WHERE lower(trim(email)) = lower(trim(?))
                       OR lower(trim(pilot_name)) = lower(trim(?))
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (em_try, pilot),
                ).fetchone()
            if not row and not pending and _hwid_triple_slot_allows(
                em_try or pilot, hid_use
            )[0]:
                ok_prov, lk_prov = _provision_hwid_slot_license(
                    conn, em_try, pilot, hid_use, pw
                )
                if ok_prov and lk_prov:
                    hwid_slot_provisioned = True
                    row = conn.execute(
                        """
                        SELECT password_salt, password_hash, hardware_id, status,
                               license_key, customer_email, pilot_name
                        FROM license_keys WHERE license_key = ? LIMIT 1;
                        """,
                        (lk_prov,),
                    ).fetchone()
            if not row and pending:
                p_email, p_name, p_hw, p_salt, p_hash = (
                    str(pending[0] or ""),
                    str(pending[1] or pilot),
                    str(pending[2] or ""),
                    str(pending[3] or ""),
                    str(pending[4] or ""),
                )
                if not _password_verify_db(p_salt, p_hash, pw):
                    conn.commit()
                    return JSONResponse({"status": "login_failed"})
            elif not row:
                conn.commit()
                return JSONResponse({"status": "login_failed"})
            if not row and pending:
                found_key = ""
                found_hw = p_hw.strip()[:128]
                row_key = conn.execute(
                    """
                    SELECT license_key, hardware_id FROM license_keys
                    WHERE status = 'activated'
                      AND (
                            lower(trim(customer_email)) = lower(trim(?))
                         OR lower(trim(pilot_name)) = lower(trim(?))
                         OR hardware_id = ?
                         OR substr(hardware_id,1,64) = ?
                      )
                    ORDER BY created_ts DESC
                    LIMIT 1;
                    """,
                    (p_email or pilot, p_name or pilot, found_hw, found_hw[:64]),
                ).fetchone()
                if row_key:
                    found_key = str(row_key[0] or "").strip()
                    found_hw = str(row_key[1] or found_hw).strip()[:128]
                uconn_lookup = sqlite3.connect(str(USER_DB_PATH))
                try:
                    cols_l = {
                        str(r[1])
                        for r in uconn_lookup.execute(
                            "PRAGMA table_info(users);"
                        ).fetchall()
                    }
                    selectors_l = [
                        "hardware_id = ?",
                        "trim(coalesce(license_key,'')) = ?",
                    ]
                    params_l: list[Any] = [found_hw[:64], found_key]
                    for lookup_col, lookup_value in (
                        ("username", p_name or pilot),
                        ("pilot_name", p_name or pilot),
                        ("email", p_email or pilot),
                    ):
                        if lookup_col in cols_l and lookup_value:
                            selectors_l.append(
                                f"lower(trim(coalesce({lookup_col},''))) = lower(trim(?))"
                            )
                            params_l.append(lookup_value)
                    urow_l = uconn_lookup.execute(
                        f"""
                        SELECT hardware_id, trim(coalesce(license_key,'')),
                               coalesce(license_activated,0), coalesce(has_license,0),
                               coalesce(is_verified,0), coalesce(license_active,0),
                               coalesce(license_status,0)
                        FROM users
                        WHERE {" OR ".join(selectors_l)}
                        LIMIT 1;
                        """,
                        tuple(params_l),
                    ).fetchone()
                finally:
                    uconn_lookup.close()
                purchased_pending = bool(
                    found_key and _license_key_is_purchased(conn, found_key)
                )
                em_check = (p_email or pilot).strip().lower()
                lic_ok, _lk_p = _email_hwid_has_active_license(em_check, hid_use)
                if not lic_ok and _hwid_triple_slot_allows(em_check, hid_use)[0]:
                    ok_slot, lk_slot = _provision_hwid_slot_license(
                        conn, em_check, p_name or pilot, hid_use, pw
                    )
                    if ok_slot and lk_slot:
                        hwid_slot_provisioned = True
                        lic_ok = True
                        found_key = lk_slot
                if not lic_ok and not (
                    purchased_pending
                    and row_key
                    and _license_key_is_purchased(conn, found_key)
                ):
                    conn.commit()
                    return _license_required_json(
                        request,
                        extra={
                            "portal_account": True,
                            "email": em_check,
                            "hardware_id": hid64,
                            "pilot_name": p_name or pilot,
                        },
                    )
                if lic_ok and found_key:
                    row = (
                        p_salt,
                        p_hash,
                        hid_use[:128],
                        "activated",
                        found_key,
                        em_check if "@" in em_check else p_email,
                        p_name or pilot,
                    )
                elif not purchased_pending and not (
                    urow_l and any(int(v or 0) == 1 for v in urow_l[2:6])
                ):
                    return _auth_portal_login_response(
                        conn,
                        request,
                        hid_use=hid_use,
                        pilot=pilot,
                        pw=pw,
                        p_email=p_email,
                        p_name=p_name,
                        p_hw=p_hw,
                        found_hw=found_hw,
                    )
                if not found_key and urow_l:
                    found_key = str(urow_l[1] or "").strip()
                row = (
                    p_salt,
                    p_hash,
                    str(urow_l[0] or found_hw or p_hw) if urow_l else found_hw,
                    "activated",
                    found_key,
                    p_email,
                    p_name,
                )
        salt, ph, bound_hw, st, lic_key, customer_email, stored_pilot = (
            str(row[0] or ""),
            str(row[1] or ""),
            str(row[2] or ""),
            str(row[3] or ""),
            str(row[4] or ""),
            str(row[5] or ""),
            str(row[6] or pilot),
        )
        if not _password_verify_db(salt, ph, pw):
            return JSONResponse({"status": "login_failed"})
        if str(st).lower() == "unused" and str(lic_key or "").upper().startswith("ST-"):
            em_bind = str(customer_email or em_login or "").strip().lower()
            ok_shop, lk_shop = _bind_unused_shop_license_to_hwid(
                em_bind, hid_use, stored_pilot or pilot, pw
            )
            if ok_shop and lk_shop:
                st = "activated"
                lic_key = lk_shop
                bound_hw = hid_use
                lic_trim = lk_shop
        bound_st = bound_hw.strip()
        lic_trim = lic_key.strip()
        old64 = bound_st[:64]
        purchased_license = _license_key_is_purchased(conn, lic_trim)
        active_main_license = False
        users_bound_hw = ""
        uconn_state = sqlite3.connect(str(USER_DB_PATH))
        try:
            cols = {str(r[1]) for r in uconn_state.execute("PRAGMA table_info(users);").fetchall()}
            selectors: list[str] = ["trim(coalesce(license_key,'')) = ?", "hardware_id = ?", "substr(hardware_id,1,64) = ?"]
            params_state: list[Any] = [lic_trim, old64, old64]
            for lookup_col in ("username", "pilot_name", "email"):
                if lookup_col in cols:
                    selectors.append(f"lower(trim(coalesce({lookup_col},''))) = lower(trim(?))")
                    params_state.append(pilot)
            state_row = uconn_state.execute(
                f"""
                SELECT hardware_id,
                       coalesce(license_activated,0),
                       coalesce(has_license,0),
                       coalesce(is_verified,0),
                       coalesce(license_active,0),
                       coalesce(license_status,0)
                FROM users
                WHERE {" OR ".join(selectors)}
                LIMIT 1;
                """,
                tuple(params_state),
            ).fetchone()
            if state_row:
                users_bound_hw = str(state_row[0] or "").strip()[:128]
                active_main_license = any(int(v or 0) == 1 for v in state_row[1:])
        except sqlite3.Error:
            active_main_license = False
            users_bound_hw = ""
        finally:
            uconn_state.close()
        main_license_ok = purchased_license or active_main_license

        uconn_ban = sqlite3.connect(str(USER_DB_PATH))
        try:
            for h64 in {hid64, old64}:
                if not h64:
                    continue
                br = uconn_ban.execute(
                    "SELECT banned FROM users WHERE hardware_id = ? LIMIT 1;",
                    (h64,),
                ).fetchone()
                if br and int(br[0] or 0) == 1:
                    return JSONResponse({"status": "banned"})
        finally:
            uconn_ban.close()

        if bound_st != hid_use:
            em_bind = _resolve_login_email(
                conn, stored_pilot or pilot, customer_email
            )
            slot_bind_ok, _ = _hwid_triple_slot_allows(em_bind or pilot, hid_use)
            if slot_bind_ok:
                ok_pb, lk_pb = _provision_hwid_slot_license(
                    conn, em_bind, stored_pilot or pilot, hid_use, pw
                )
                if ok_pb and lk_pb:
                    hwid_slot_provisioned = True
                    lic_trim = lk_pb
                    main_license_ok = True
            can_first_bind_pc = (
                main_license_ok
                and (
                    _login_placeholder_hardware_for_bonding(bound_st)
                    or _login_placeholder_hardware_for_bonding(users_bound_hw)
                    or not bound_st
                    or not users_bound_hw
                    or slot_bind_ok
                )
            )
            can_rebind_active_main = bool(main_license_ok)
            if not can_first_bind_pc and not can_rebind_active_main:
                return JSONResponse({"status": "login_failed"})
            uconn_chk = sqlite3.connect(str(USER_DB_PATH))
            try:
                clash = uconn_chk.execute(
                    """
                    SELECT coalesce(license_key,''), coalesce(license_activated,0)
                    FROM users WHERE hardware_id = ? LIMIT 1;
                    """,
                    (hid64,),
                ).fetchone()
                if clash:
                    lk0, act0 = str(clash[0] or ""), int(clash[1] or 0)
                    if (
                        act0
                        and lk0.strip()
                        and lk0.strip() != lic_trim
                        and old64 != hid64
                    ):
                        return JSONResponse({"status": "login_failed"})
            finally:
                uconn_chk.close()
            prev_u_hw = users_bound_hw
            uconn_pre = sqlite3.connect(str(USER_DB_PATH))
            try:
                cols_pre = {str(r[1]) for r in uconn_pre.execute("PRAGMA table_info(users);").fetchall()}
                where_prev = ["trim(coalesce(license_key,'')) = ?"] if "license_key" in cols_pre else ["hardware_id = ?"]
                params_prev: list[Any] = [lic_trim if "license_key" in cols_pre else old64]
                for lookup_col, lookup_value in (
                    ("username", pilot),
                    ("email", customer_email or pilot),
                    ("pilot_name", stored_pilot or pilot),
                ):
                    if lookup_col in cols_pre and lookup_value:
                        where_prev.append(f"lower(trim(coalesce({lookup_col},''))) = lower(trim(?))")
                        params_prev.append(lookup_value)
                r_prev = uconn_pre.execute(
                    f"""
                    SELECT hardware_id FROM users
                    WHERE {" OR ".join(where_prev)}
                    LIMIT 1;
                    """,
                    tuple(params_prev),
                ).fetchone()
                if r_prev:
                    prev_u_hw = str(r_prev[0] or "").strip()[:128]
            finally:
                uconn_pre.close()
            reloc_full = (bound_st or prev_u_hw).strip()[:128]
            reloc64 = reloc_full[:64] if reloc_full else ""
            if lic_trim:
                conn.execute(
                    """
                    UPDATE license_keys SET hardware_id = ?
                    WHERE license_key = ? AND status = 'activated';
                    """,
                    (hid_use, lic_trim),
                )
            if bound_st:
                conn.execute(
                    """
                    UPDATE web_pending_users SET hardware_id = ?
                    WHERE hardware_id = ? OR hardware_id = ? OR substr(hardware_id,1,64) = ?
                       OR lower(trim(pilot_name)) = lower(trim(?))
                       OR lower(trim(email)) = lower(trim(?));
                    """,
                    (hid_use, bound_st, bound_st[:128], old64, stored_pilot or pilot, customer_email or pilot),
                )
            else:
                conn.execute(
                    """
                    UPDATE web_pending_users SET hardware_id = ?
                    WHERE lower(trim(pilot_name)) = lower(trim(?));
                    """,
                    (hid_use, pilot),
                )
            if reloc64:
                for tbl in ("support_tickets", "support_messages", "radar_positions"):
                    try:
                        conn.execute(
                            f"UPDATE {tbl} SET hardware_id = ? WHERE hardware_id = ? OR hardware_id = ?;",
                            (hid64, reloc_full[:128], reloc64),
                        )
                    except sqlite3.OperationalError:
                        pass
            uconn_m = sqlite3.connect(str(USER_DB_PATH))
            try:
                cols_m = {str(r[1]) for r in uconn_m.execute("PRAGMA table_info(users);").fetchall()}
                assignments = ["hardware_id = ?"]
                params_m: list[Any] = [hid64]
                if "license_key" in cols_m:
                    assignments.append("license_key = ?")
                    params_m.append(lic_trim)
                for flag_col in ("license_activated", "has_license", "is_verified", "license_active", "license_status"):
                    if flag_col in cols_m:
                        assignments.append(f"{flag_col} = 1")
                where_sql = ["trim(coalesce(license_key,'')) = ?", "hardware_id = ?", "substr(hardware_id,1,64) = ?"]
                where_params: list[Any] = [lic_trim, old64, old64]
                for lookup_col, lookup_value in (
                    ("username", pilot),
                    ("pilot_name", stored_pilot or pilot),
                    ("email", customer_email or pilot),
                ):
                    if lookup_col in cols_m and lookup_value:
                        where_sql.append(f"lower(trim(coalesce({lookup_col},''))) = lower(trim(?))")
                        where_params.append(lookup_value)
                uconn_m.execute(
                    f"""
                    UPDATE users SET {", ".join(assignments)}
                    WHERE {" OR ".join(where_sql)};
                    """,
                    tuple(params_m + where_params),
                )
                uconn_m.execute("INSERT OR IGNORE INTO users (hardware_id) VALUES (?);", (hid64,))
                uconn_m.execute(
                    f"UPDATE users SET {', '.join(assignments)} WHERE hardware_id = ?;",
                    tuple(params_m + [hid64]),
                )
                for alias_hw in {old64, prev_u_hw[:64], users_bound_hw[:64]}:
                    alias_hw = str(alias_hw or "").strip()[:64]
                    if alias_hw and alias_hw != hid64:
                        uconn_m.execute(
                            "INSERT OR IGNORE INTO users (hardware_id) VALUES (?);",
                            (alias_hw,),
                        )
                        uconn_m.execute(
                            f"UPDATE users SET {', '.join(assignments)} WHERE hardware_id = ?;",
                            tuple(params_m + [alias_hw]),
                        )
                uconn_m.commit()
            finally:
                uconn_m.close()
            conn.commit()
            msg = (
                f"User [{pilot}] hat seine Hardware-ID erfolgreich von Web-ID auf "
                f"PC-UUID [{hid_use!r}] umgestellt."
            )
            _server_log_line(msg)
            _append_admin_log(f"[bond] {msg}")
        uconn = sqlite3.connect(str(USER_DB_PATH))
        ur: tuple | None = None
        try:
            br = uconn.execute(
                "SELECT banned FROM users WHERE hardware_id = ?;", (hid64,)
            ).fetchone()
            if br and int(br[0] or 0) == 1:
                return JSONResponse({"status": "banned"})
            ur = uconn.execute(
                """
                SELECT credits, xp, reputation FROM users WHERE hardware_id = ?;
                """,
                (hid64,),
            ).fetchone()
        finally:
            uconn.close()
        credits_f = xp_f = rep_f = 0.0
        if ur:
            credits_f, xp_f, rep_f = (
                float(ur[0] or 0),
                float(ur[1] or 0),
                float(ur[2] or 0),
            )
        em_final = str(customer_email or "").strip().lower()
        if "@" not in em_final:
            em_final = pilot.strip().lower() if "@" in pilot else em_final
        auto_login_bind = False
        lk_auto = ""
        if em_final and "@" in em_final:
            ok_auto, lk_auto = _bind_unused_shop_license_to_hwid(
                em_final, hid_use, stored_pilot or pilot, pw
            )
            if ok_auto:
                auto_login_bind = True
                lic_trim = lk_auto or lic_trim
        lic_ok, lk_final = _email_hwid_has_active_license(em_final, hid_use)
        if auto_login_bind and lk_auto:
            lic_ok, lk_final = True, lk_auto
        if not lic_ok:
            conn.commit()
            return _license_required_json(
                request,
                extra={
                    "email": em_final,
                    "hardware_id": hid64,
                    "pilot_name": stored_pilot or pilot,
                    "license_key_hint": lic_trim,
                },
            )
        pilot_db = str(stored_pilot or pilot or "").strip()[:120]
        if not pilot_db and em_final and "@" in em_final:
            pilot_db = em_final.split("@", 1)[0][:120]
        login_payload: dict[str, Any] = {
            "status": "login_success",
            "license_key": lk_final or lic_trim,
            "license_status": 1,
            "has_license": 1,
            "auto_license_activated": auto_login_bind or hwid_slot_provisioned,
            "hwid_slot_provisioned": bool(hwid_slot_provisioned),
            "pilot_name": pilot_db,
            "email": em_final,
            "credits": credits_f,
            "xp": xp_f,
            "reputation": rep_f,
            **_login_response_language_fields(hid_use, em_final),
        }
        login_payload.update(_api_hardware_id_symmetry(hid_use, em_final, pilot_db))
        if _is_global_superadmin_email(em_final):
            _apply_global_superadmin_pg(em_final, hid_use, pilot_db)
            login_payload.update(_superadmin_api_payload_extra(em_final))
        return _auth_login_json_response(request, login_payload, hid_use)
    finally:
        conn.close()


@app.post("/api/v1/auth/update_hardware")
def auth_update_hardware(body: dict[str, Any]) -> JSONResponse:
    pilot = str(
        body.get("pilot_name")
        or body.get("username")
        or body.get("portal_email")
        or body.get("email")
        or ""
    ).strip()[:200]
    pw = str(body.get("password", "") or "").strip()
    hid = str(body.get("hardware_id", "") or "").strip()[:128]
    license_key_in = str(body.get("license_key", "") or "").strip()[:80]
    if not pilot or not pw or not hid:
        return JSONResponse({"status": "bad_request"})
    hid64 = hid[:64]
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT license_key, password_salt, password_hash, hardware_id, pilot_name, customer_email, status
            FROM license_keys
            WHERE status = 'activated'
              AND (
                    lower(trim(pilot_name)) = lower(trim(?))
                 OR lower(trim(customer_email)) = lower(trim(?))
                 OR license_key = ?
              )
            ORDER BY created_ts DESC
            LIMIT 1;
            """,
            (pilot, pilot, license_key_in),
        ).fetchone()
        if not row:
            return JSONResponse({"status": "login_failed"})
        lic_key = str(row[0] or "").strip()
        salt = str(row[1] or "")
        ph = str(row[2] or "")
        old_hw = str(row[3] or "").strip()
        pilot_name = str(row[4] or pilot).strip()
        email = str(row[5] or "").strip()
        if not _password_verify_db(salt, ph, pw):
            return JSONResponse({"status": "login_failed"})
        if not _license_key_is_purchased(conn, lic_key):
            return JSONResponse({"status": "license_required"})
        if old_hw and old_hw[:64] != hid64:
            alias_conn = sqlite3.connect(str(USER_DB_PATH))
            try:
                alias_conn.execute("BEGIN IMMEDIATE")
                alias_conn.execute(
                    "INSERT OR IGNORE INTO users (hardware_id) VALUES (?);",
                    (old_hw[:64],),
                )
                alias_cols = {str(r[1]) for r in alias_conn.execute("PRAGMA table_info(users);").fetchall()}
                alias_assigns: list[str] = []
                alias_params: list[Any] = []
                if "license_key" in alias_cols:
                    alias_assigns.append("license_key = ?")
                    alias_params.append(lic_key)
                for flag_col in ("license_activated", "has_license", "is_verified", "license_active", "license_status"):
                    if flag_col in alias_cols:
                        alias_assigns.append(f"{flag_col} = 1")
                if alias_assigns:
                    alias_conn.execute(
                        f"UPDATE users SET {', '.join(alias_assigns)} WHERE hardware_id = ?;",
                        tuple(alias_params + [old_hw[:64]]),
                    )
                alias_conn.commit()
            except sqlite3.Error:
                alias_conn.rollback()
            finally:
                alias_conn.close()
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            UPDATE license_keys SET hardware_id = ?
            WHERE license_key = ? AND status = 'activated';
            """,
            (hid, lic_key),
        )
        conn.execute(
            """
            UPDATE web_pending_users SET hardware_id = ?
            WHERE lower(trim(pilot_name)) = lower(trim(?))
               OR lower(trim(email)) = lower(trim(?))
               OR hardware_id = ?
               OR substr(hardware_id, 1, 64) = ?;
            """,
            (hid, pilot_name, email or pilot, old_hw, old_hw[:64]),
        )
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        conn.close()
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        uconn.execute("INSERT OR IGNORE INTO users (hardware_id) VALUES (?);", (hid64,))
        cols = {str(r[1]) for r in uconn.execute("PRAGMA table_info(users);").fetchall()}
        assigns: list[str] = []
        assign_params: list[Any] = []
        if "license_key" in cols:
            assigns.append("license_key = ?")
            assign_params.append(lic_key)
        for flag_col in ("license_activated", "has_license", "is_verified", "license_active", "license_status"):
            if flag_col in cols:
                assigns.append(f"{flag_col} = 1")
        if assigns:
            uconn.execute(
                f"""
                UPDATE users SET hardware_id = ?, {", ".join(assigns)}
                WHERE hardware_id = ? OR trim(coalesce(license_key,'')) = ?;
                """,
                tuple([hid64] + assign_params + [old_hw[:64], lic_key]),
            )
            uconn.execute(
                f"""
                UPDATE users SET {", ".join(assigns)}
                WHERE hardware_id = ?;
                """,
                tuple(assign_params + [hid64]),
            )
        uconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close()
    return JSONResponse(
        {
            "status": "login_success",
            "license_status": 1,
            "has_license": 1,
            "license_key": lic_key,
            "hardware_id": hid64,
            "pilot_name": pilot_name,
        }
    )


@app.post("/api/v1/auth/mobile_login")
def auth_mobile_login(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _resolve_desktop_hardware_id(body)
    if not hid:
        return JSONResponse({"status": "login_failed"})
    pilot_name = _pilot_display_name_for_hid(hid)
    if not pilot_name:
        pilot_name = str(body.get("pilot_name") or body.get("username") or "").strip()
    email = _portal_email_for_hardware(hid)
    device_token = str(body.get("device_token") or "").strip()[:500]
    if device_token:
        sconn = sqlite3.connect(str(SERVER_DB_PATH))
        uconn = sqlite3.connect(str(USER_DB_PATH))
        try:
            _ensure_auction_tables(sconn)
            sconn.execute(
                """
                INSERT INTO mobile_push_tokens (hardware_id, device_token, locale, platform, updated_ts)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(hardware_id) DO UPDATE SET
                    device_token = excluded.device_token,
                    locale = excluded.locale,
                    platform = excluded.platform,
                    updated_ts = excluded.updated_ts;
                """,
                (hid[:64], device_token, str(body.get("locale") or "de")[:8], str(body.get("platform") or "")[:40], time.time()),
            )
            sconn.commit()
            try:
                uconn.execute("ALTER TABLE users ADD COLUMN device_token TEXT NOT NULL DEFAULT '';")
            except sqlite3.OperationalError:
                pass
            uconn.execute("UPDATE users SET device_token = ? WHERE hardware_id = ?;", (device_token, hid[:64]))
            uconn.commit()
        finally:
            sconn.close(); uconn.close()
    token = _web_issue_token(hid)
    return JSONResponse(
        {
            "status": "success",
            "hardware_id": hid[:64],
            "pilot_name": pilot_name,
            "email": email,
            "token": token,
        }
    )


@app.post("/api/v1/mobile/account")
def mobile_account(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT credits, xp, reputation, loan_debt, strikes, credit_score FROM users WHERE hardware_id = ?;",
            (hid,),
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return JSONResponse({"ok": False, "error": "no_user"}, status_code=404)
    payload = _profile_snapshot_payload_extended(hid, row)
    payload["hardware_id"] = hid[:64]
    payload["pilot_name"] = _pilot_display_name_for_hid(hid)
    payload["email"] = _portal_email_for_hardware(hid)
    payload["alliance_summary"] = _user_alliance_summary(hid)
    mconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        mrow = mconn.execute(
            """
            SELECT aircraft_id, airframe_condition, engine_1_health, updated_at
            FROM server_maintenance_log
            WHERE hardware_id = ?
            ORDER BY updated_at DESC LIMIT 1;
            """,
            (hid,),
        ).fetchone()
    finally:
        mconn.close()
    payload["hangar_telemetry"] = {
        "aircraft_id": str(mrow[0] if mrow else "Standard Flotte"),
        "airframe_condition": float(mrow[1] if mrow else 100.0),
        "engine_1_health": float(mrow[2] if mrow else 100.0),
        "updated_at": str(mrow[3] if mrow else ""),
    }
    payload["simconnect"] = _simconnect_live_mirror_for_hid(hid)
    payload["ok"] = True
    return JSONResponse(payload)


@app.post("/api/v1/mobile/hangar/repair")
def mobile_hangar_repair(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    cost = float(body.get("cost", 25000) or 25000)
    aircraft_id = str(body.get("aircraft_id") or "Standard Flotte").strip()[:120]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
        credits = float(row[0] or 0) if row else 0.0
        if credits + 1e-6 < cost:
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (cost, hid))
        sconn.execute("BEGIN IMMEDIATE")
        now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        sconn.execute(
            """
            INSERT INTO server_maintenance_log (
                hardware_id, aircraft_id, airframe_condition, engine_1_health, updated_at
            ) VALUES (?, ?, 100.0, 100.0, ?)
            ON CONFLICT(hardware_id, aircraft_id) DO UPDATE SET
                airframe_condition = 100.0,
                engine_1_health = 100.0,
                updated_at = excluded.updated_at;
            """,
            (hid, aircraft_id, now),
        )
        uconn.commit()
        sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback()
        sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close()
        sconn.close()
    return JSONResponse({"ok": True, "engine_1_health": 100.0, "airframe_condition": 100.0, "credits_spent": cost})


