@app.post("/api/v1/admin/marketing/discount/kill")
async def admin_marketing_discount_kill(
    request: Request, body: dict[str, Any] | None = None
) -> JSONResponse:
    """Gutschein sofort EXPIRED in PostgreSQL — verschwindet von der Website."""
    if not _admin_ok(request, body or {}):
        raise HTTPException(status_code=403, detail="admin_denied")
    raw = str(
        (body or {}).get("code")
        or (body or {}).get("promo_code")
        or (body or {}).get("voucher_code")
        or ""
    ).strip()
    if len(raw) < 2:
        return JSONResponse(
            {"status": "error", "message": "code_required"}, status_code=400
        )
    code_u = raw.upper()
    past = (datetime.now(timezone.utc) - timedelta(seconds=30)).isoformat()
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        sconn.execute(
            """
            UPDATE promo_codes SET valid_until = ?
            WHERE upper(code) = upper(?);
            """,
            (past, code_u),
        )
        sconn.commit()
    except sqlite3.Error as exc:
        sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        sconn.close()
    try:
        ok_pg = _pg_discount_code_kill(code_u)
    except Exception as exc:
        _append_admin_log(f"[kill] PG rollback-sicher: {exc!r}")
        raise HTTPException(status_code=500, detail="pg_kill_failed") from exc
    if not ok_pg:
        return JSONResponse(
            {"status": "error", "message": "unknown_code_in_pg"}, status_code=404
        )
    _append_admin_log(f"[kill] Gutschein {code_u!r} → EXPIRED (PG + SQLite)")
    return JSONResponse(
        {
            "status": "success",
            "code": code_u,
            "pg_status": "EXPIRED",
            "message": "Gutschein gestoppt und von der Website entfernt.",
        }
    )


