@app.post("/api/v1/admin/promo/upsert")
def admin_promo_upsert(request: Request, body: dict[str, Any]) -> JSONResponse:
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    raw = str(body.get("code", "") or "").strip()
    if len(raw) < 3 or len(raw) > 48:
        raise HTTPException(status_code=400, detail="bad_code_len")
    code_u = raw.upper()
    if not all(ch.isalnum() or ch in "_-" for ch in code_u):
        raise HTTPException(status_code=400, detail="bad_code_chars")
    disc = int(body.get("discount_percent", 0) or 0)
    try:
        discount_eur = round(float(body.get("discount_eur", 0) or 0), 2)
    except (TypeError, ValueError):
        discount_eur = 0.0
    mx = int(body.get("max_uses", 1) or 1)
    if disc < 0 or disc > 100 or discount_eur < 0 or mx < 1 or mx > 10_000_000:
        raise HTTPException(status_code=400, detail="bad_promo_params")
    vf_u = str(body.get("valid_from") or "").strip()
    vu_u = str(body.get("valid_until") or "").strip()
    ts = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            INSERT INTO promo_codes (
                code, discount_percent, discount_eur, max_uses, uses, created_ts,
                valid_from, valid_until
            )
            VALUES (?, ?, ?, ?, 0, ?, ?, ?)
            ON CONFLICT(code) DO UPDATE SET
                discount_percent = excluded.discount_percent,
                discount_eur = excluded.discount_eur,
                max_uses = excluded.max_uses,
                valid_from = excluded.valid_from,
                valid_until = excluded.valid_until;
            """,
            (code_u, disc, discount_eur, mx, ts, vf_u, vu_u),
        )
        conn.commit()
    finally:
        conn.close()
    try:
        _pg_upsert_discount_code_active(
            code_u,
            discount_percent=disc,
            discount_eur=discount_eur,
            max_uses=mx,
            valid_from=vf_u,
            valid_until=vu_u,
        )
    except Exception as exc:
        _append_admin_log(f"[admin] PG sync upsert {code_u!r}: {exc!r}")
    _append_admin_log(
        f"[admin] promo upsert {code_u!r} discount_percent={disc} discount_eur={discount_eur} max_uses={mx}"
    )
    return JSONResponse(
        {
            "ok": True,
            "code": code_u,
            "discount_percent": disc,
            "discount_eur": discount_eur,
            "max_uses": mx,
            "status": "ACTIVE",
        }
    )


@app.post("/api/v1/admin/promo/create")
def admin_promo_create(request: Request, body: dict[str, Any]) -> JSONResponse:
    """Zeitgesteuerte UTC-Kampagne (Meilenstein 163)."""
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    raw = str(body.get("code", "") or "").strip()
    if len(raw) < 3 or len(raw) > 48:
        raise HTTPException(status_code=400, detail="bad_code_len")
    code_u = raw.upper()
    if not all(ch.isalnum() or ch in "_-" for ch in code_u):
        raise HTTPException(status_code=400, detail="bad_code_chars")
    disc = int(body.get("discount_percent", 0) or 0)
    try:
        discount_eur = round(float(body.get("discount_eur", 0) or 0), 2)
    except (TypeError, ValueError):
        discount_eur = 0.0
    mx = int(body.get("max_uses", 1) or 1)
    vf = str(body.get("valid_from") or "").strip()
    vu = str(body.get("valid_until") or "").strip()
    if not vf or not vu:
        raise HTTPException(status_code=400, detail="missing_campaign_window")
    if _parse_iso_utc(vf) is None or _parse_iso_utc(vu) is None:
        raise HTTPException(status_code=400, detail="bad_iso_datetime")
    if disc < 1 or disc > 100 or discount_eur < 0 or mx < 1 or mx > 10_000_000:
        raise HTTPException(status_code=400, detail="bad_promo_params")
    ts = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            INSERT INTO promo_codes (
                code, discount_percent, discount_eur, max_uses, uses, created_ts,
                valid_from, valid_until
            )
            VALUES (?, ?, ?, ?, 0, ?, ?, ?)
            ON CONFLICT(code) DO UPDATE SET
                discount_percent = excluded.discount_percent,
                discount_eur = excluded.discount_eur,
                max_uses = excluded.max_uses,
                valid_from = excluded.valid_from,
                valid_until = excluded.valid_until;
            """,
            (code_u, disc, discount_eur, mx, ts, vf, vu),
        )
        conn.commit()
    finally:
        conn.close()
    try:
        _pg_upsert_discount_code_active(
            code_u,
            discount_percent=disc,
            discount_eur=discount_eur,
            max_uses=mx,
            valid_from=vf,
            valid_until=vu,
        )
    except Exception as exc:
        _append_admin_log(f"[admin] PG sync campaign {code_u!r}: {exc!r}")
    _append_admin_log(
        f"[admin] promo campaign {code_u!r} disc={disc}% discount_eur={discount_eur} max_uses={mx} "
        f"valid_from={vf!r} valid_until={vu!r}"
    )
    return JSONResponse(
        {
            "ok": True,
            "code": code_u,
            "discount_percent": disc,
            "discount_eur": discount_eur,
            "max_uses": mx,
            "valid_from": vf,
            "valid_until": vu,
        }
    )


@app.post("/api/v1/admin/promo/stop")
def admin_promo_stop(request: Request, body: dict[str, Any]) -> JSONResponse:
    """Kampagne vorzeitig beenden: ``valid_until`` in die Vergangenheit setzen."""
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    raw = str(body.get("code", "") or "").strip()
    if len(raw) < 3:
        raise HTTPException(status_code=400, detail="bad_code_len")
    code_u = raw.upper()
    past = (datetime.now(timezone.utc) - timedelta(seconds=15)).isoformat()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            UPDATE promo_codes SET valid_until = ?
            WHERE upper(code) = upper(?);
            """,
            (past, code_u),
        )
        if cur.rowcount != 1:
            raise HTTPException(status_code=404, detail="unknown_promo_code")
        conn.commit()
    finally:
        conn.close()
    try:
        _pg_discount_code_kill(code_u)
    except Exception as exc:
        _append_admin_log(f"[admin] PG kill {code_u!r}: {exc!r}")
        raise HTTPException(status_code=500, detail="pg_kill_failed") from exc
    _append_admin_log(f"[admin] promo STOP {code_u!r} valid_until={past!r} PG=EXPIRED")
    return JSONResponse(
        {"ok": True, "code": code_u, "valid_until": past, "status": "EXPIRED"}
    )


