@app.post("/api/v1/webhook/purchase")
async def webhook_purchase(
    request: Request, background_tasks: BackgroundTasks
) -> JSONResponse:
    try:
        body = await request.json()
    except Exception:
        body = {}
    email = str(body.get("buyer_email", body.get("email", "")) or "").strip()[:200]
    pilot_guess = email.split("@", 1)[0][:120] if "@" in email else ""
    lang = str(body.get("selected_language") or body.get("lang") or "").strip().lower()
    if lang not in ("de", "en"):
        lang = _purchase_email_language(email)
    new_key = _autopilot_fulfill_customer_license(
        email,
        pilot_guess,
        lang=lang,
        background_tasks=background_tasks,
        amount_eur=_paypal_product_eur_amount(),
        paypal_order_id=str(body.get("paypal_order_id") or "WEBHOOK")[:80],
        paypal_capture_id=str(body.get("paypal_capture_id") or "")[:128],
        status="unused",
    )
    if not new_key:
        return JSONResponse(
            {"ok": False, "status": "error", "message": "license_issue_failed"},
            status_code=500,
        )
    return JSONResponse({"ok": True, "license_key": new_key, "email": email})


async def _paypal_create_order_web_secure(request: Request) -> JSONResponse:
    """M204/M205: PayPal Checkout nur per Web-Session-Cookie + echter v2 REST-Handshake."""
    logged_in_pilot = _web_session_hardware_id(request)
    if not logged_in_pilot:
        return JSONResponse(
            content={
                "status": "error",
                "message": "Bitte loggen Sie sich zuerst auf skytycoon.info ein!",
            },
            status_code=401,
        )
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    promo_in = str(body.get("promo_code") or "").strip()
    try:
        amt, promo_u = _portal_checkout_eur_from_promo(promo_in if promo_in else None)
    except HTTPException as exc:
        detail = str(getattr(exc, "detail", "") or "promo_invalid")
        if detail == "promo_free_checkout" and promo_in:
            lk_free = _portal_grant_purchased_license(
                logged_in_pilot,
                None,
                promo_code=promo_in,
                paypal_capture_id="",
                paypal_order_id=f"FREE-{secrets.token_hex(8).upper()}",
                amount_value=0.0,
                currency="EUR",
                free_promo=True,
            )
            if lk_free:
                try:
                    _sync_user_license_flags(str(logged_in_pilot)[:64])
                except Exception:
                    pass
                return JSONResponse(
                    {
                        "status": "success",
                        "free": True,
                        "license_key": lk_free,
                        "promo_code": promo_in.upper(),
                    }
                )
        msg = _promo_checkout_error_message(request, detail)
        return JSONResponse(
            content={"status": "error", "message": msg, "detail": detail},
            status_code=int(getattr(exc, "status_code", 400) or 400),
        )
    if amt < 0.50:
        return JSONResponse(
            content={
                "status": "error",
                "message": "Kostenloser Voll-Gutschein: bitte „Gutschein einlösen“ nutzen.",
                "detail": "promo_free_checkout",
            },
            status_code=400,
        )
    try:
        oid = execute_native_paypal_order_creation_handshake(
            amt,
            logged_in_pilot,
            description=(
                f"SkyTycoon Pro v1.0 - Lifetime License Binding for Pilot ID: "
                f"{logged_in_pilot[:64]}"
            ),
        )
    except RuntimeError as exc:
        err_s = str(exc)
        if "PAYPAL_CLIENT_SECRET" in err_s or "PayPal Auth Failed" in err_s:
            _paypal_log().error("[PAYPAL CRITICAL EXCEPTION]: %s", err_s)
            return JSONResponse(
                content={
                    "status": "error",
                    "message": "PayPal-Schnittstelle temporär ausgelastet. Bitte versuchen Sie es erneut.",
                    "detail": "paypal_oauth_unavailable",
                },
                status_code=503,
            )
        if err_s.startswith("PayPal abgewiesen"):
            return JSONResponse(
                content={
                    "status": "error",
                    "message": err_s.replace("PayPal abgewiesen", "PayPal", 1)[:240],
                    "detail": "paypal_create_failed",
                },
                status_code=400,
            )
        _paypal_log().error("[PAYPAL CRITICAL EXCEPTION]: %s", err_s)
        return JSONResponse(
            content={
                "status": "error",
                "message": "PayPal-Schnittstelle temporär ausgelastet. Bitte versuchen Sie es erneut.",
                "detail": "paypal_network",
            },
            status_code=502,
        )
    except ValueError:
        return JSONResponse(
            content={
                "status": "error",
                "message": "Kostenloser Voll-Gutschein: bitte „Gutschein einlösen“ nutzen.",
                "detail": "promo_free_checkout",
            },
            status_code=400,
        )
    _paypal_bind_order_to_hid(oid, logged_in_pilot)
    if promo_u:
        _paypal_order_meta_save(oid, amt, promo_u)
    _paypal_log().info(
        "[PAYPAL SHOP] Bestellung für Pilot (HW-ID: %s…) initiiert. ID: %s",
        logged_in_pilot[:16],
        oid[:24],
    )
    return JSONResponse(
        {
            "status": "success",
            "id": oid,
            "order_id": oid,
        }
    )


