@app.post("/api/v1/paypal/capture-order")
async def paypal_capture_order(
    request: Request,
    background_tasks: BackgroundTasks,
) -> JSONResponse:
    """Server-seitiges Capture nach Smart-Button-Approval (Web-Session)."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    oid = str(body.get("orderID") or body.get("order_id") or "").strip()
    if not oid:
        raise HTTPException(status_code=400, detail="missing_order_id")
    session_hid = _web_session_hardware_id(request)
    tok = _paypal_access_token()
    if not tok:
        raise HTTPException(status_code=503, detail="paypal_oauth_unavailable")
    try:
        r = requests.post(
            f"{_paypal_api_base()}/v2/checkout/orders/{oid}/capture",
            headers={
                "Authorization": f"Bearer {tok}",
                "Content-Type": "application/json",
                "Prefer": "return=representation",
            },
            json={},
            timeout=60,
        )
    except requests.RequestException as exc:
        _paypal_log().warning("capture-order Netzwerkfehler: %s", exc)
        raise HTTPException(status_code=502, detail="paypal_network") from exc
    if r.status_code not in (200, 201):
        _paypal_log().warning(
            "capture-order HTTP %s: %s", r.status_code, (r.text or "")[:500]
        )
        raise HTTPException(status_code=400, detail="paypal_capture_failed")
    data = r.json()
    tup = _paypal_first_completed_capture(data)
    if not tup:
        raise HTTPException(status_code=400, detail="no_completed_capture")
    cap_id, em, val, cur, order_id = tup
    bound_hid = _paypal_get_bound_hid(oid) or session_hid
    if bound_hid and session_hid and bound_hid[:64] != session_hid[:64]:
        _paypal_log().warning(
            "capture-order: Order-Bindung %s… != Session %s…",
            bound_hid[:16],
            session_hid[:16],
        )
    lk: str | None = None
    if bound_hid:
        lk = _portal_grant_purchased_license(
            bound_hid,
            background_tasks,
            promo_code=None,
            paypal_capture_id=cap_id,
            paypal_order_id=order_id,
            amount_value=float(val),
            currency=str(cur),
            free_promo=False,
        )
        if not lk:
            _paypal_log().warning(
                "Portal capture: Fulfillment fehlgeschlagen order=%r hid=%r",
                oid[:32],
                bound_hid[:32],
            )
    else:
        lk = _paypal_fulfill_lifetime_license(
            em, cap_id, val, cur, background_tasks, paypal_order_id=order_id
        )
    out: dict[str, Any] = {
        "ok": True,
        "status": data.get("status"),
        "capture_id": cap_id,
        "paypal_order_id": order_id,
    }
    if lk:
        out["license_key"] = lk
        show_tok = secrets.token_urlsafe(32)
        mail_em = _customer_email_for_license_key(lk) or em
        _server_kv_set(
            f"paypal_show:{show_tok}",
            json.dumps(
                {
                    "license_key": lk,
                    "email": mail_em,
                    "paypal_order_id": order_id,
                    "capture_id": cap_id,
                },
                ensure_ascii=False,
            ),
        )
        out["purchase_show_token"] = show_tok
    return JSONResponse(out)


@app.post("/api/v1/webhook/paypal")
async def paypal_webhook(
    request: Request, background_tasks: BackgroundTasks
) -> JSONResponse:
    """PayPal Webhook: nur ``PAYMENT.CAPTURE.COMPLETED`` mit Signaturprüfung."""
    try:
        raw = await request.body()
        ev = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
        raise HTTPException(status_code=400, detail="bad_json")
    if not isinstance(ev, dict):
        raise HTTPException(status_code=400, detail="bad_json")
    if not await verify_paypal_webhook_signature(request, ev):
        raise HTTPException(status_code=400, detail="invalid_signature")
    et = str(ev.get("event_type") or "")
    if et != "PAYMENT.CAPTURE.COMPLETED":
        return JSONResponse({"ok": True, "ignored": et})
    res = ev.get("resource") if isinstance(ev.get("resource"), dict) else {}
    cap_id, em, val, cur = _paypal_extract_capture_from_event(ev)
    order_id = _paypal_order_id_from_resource(res)
    bound_hid = _paypal_get_bound_hid(order_id)
    if bound_hid:
        lk_wh = _portal_grant_purchased_license(
            bound_hid,
            background_tasks,
            promo_code=None,
            paypal_capture_id=cap_id,
            paypal_order_id=order_id,
            amount_value=float(val),
            currency=str(cur),
            free_promo=False,
        )
        if lk_wh:
            try:
                _sync_user_license_flags(str(bound_hid)[:64])
            except Exception:
                pass
            _paypal_log().info(
                "[PAYPAL WEBHOOK] Lizenz für %s… freigeschaltet (has_license=1)",
                bound_hid[:16],
            )
        else:
            _paypal_log().warning(
                "PayPal Webhook: Portal-Fulfillment fehlgeschlagen order=%r",
                order_id[:32],
            )
    else:
        lk_legacy = _paypal_fulfill_lifetime_license(
            em, cap_id, val, cur, background_tasks, paypal_order_id=order_id
        )
        if lk_legacy:
            _paypal_log().info("[PAYPAL WEBHOOK] Legacy-Fulfillment key=%s…", lk_legacy[:12])
            try:
                threading.Thread(
                    target=_notify_co_founder_revenue_discord,
                    args=(float(val), cap_id, em),
                    kwargs={
                        "license_key": lk_legacy,
                        "paypal_order_id": order_id,
                    },
                    daemon=True,
                ).start()
            except Exception:
                pass
        elif lk_wh:
            try:
                threading.Thread(
                    target=_notify_co_founder_revenue_discord,
                    args=(float(val), cap_id, em or ""),
                    kwargs={
                        "license_key": str(lk_wh),
                        "paypal_order_id": order_id,
                    },
                    daemon=True,
                ).start()
            except Exception:
                pass
    return JSONResponse({"ok": True})


def _radar_route_icaos(route: str, fallback: str = "") -> tuple[str, str]:
    parts = str(route or "").replace("→", "-").replace("–", "-").split("-")
    origin = (parts[0].strip().upper()[:4] if parts else "") or fallback[:4].upper()
    dest = (parts[1].strip().upper()[:4] if len(parts) > 1 else "") or origin
    return origin, dest


def _radar_active_route_for_hid(hid: str, route: str, current_icao: str) -> tuple[str, str, str]:
    origin, dest = _radar_route_icaos(route, current_icao)
    if origin and dest and origin != dest:
        return route, origin, dest
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT route, origin, destination
            FROM active_web_flightplans
            WHERE hardware_id = ? LIMIT 1;
            """,
            (str(hid)[:64],),
        ).fetchone()
        if row:
            r = str(row[0] or route or "").strip()
            o = str(row[1] or origin or current_icao or "").strip().upper()[:4]
            d = str(row[2] or dest or o or "").strip().upper()[:4]
            if o and d:
                return r or f"{o} → {d}", o, d
    except sqlite3.Error:
        pass
    finally:
        conn.close()
    return route, origin, dest


def _radar_interpolate_offline_position(
    hid: str,
    route: str,
    current_icao: str,
    previous: tuple[float, float, float, float] | None = None,
) -> tuple[float, float, float, float, str, str, str, float]:
    import math

    route, origin, dest = _radar_active_route_for_hid(hid, route, current_icao)
    if origin not in GLOBAL_AIRPORT_COORDS or dest not in GLOBAL_AIRPORT_COORDS or origin == dest:
        if previous:
            lat, lon, _alt, hdg = previous
            return lat + 0.015, lon + 0.018, 35000.0, hdg, route or origin or "SIM", origin, dest, time.time()
        base = GLOBAL_AIRPORT_COORDS.get(current_icao[:4].upper(), GLOBAL_AIRPORT_COORDS.get("EDDF", (50.0379, 8.5622)))
        return float(base[0]), float(base[1]), 35000.0, 90.0, route or current_icao or "SIM", origin, dest, time.time()
    la1, lo1 = GLOBAL_AIRPORT_COORDS[origin]
    la2, lo2 = GLOBAL_AIRPORT_COORDS[dest]
    dist_nm = max(60.0, _haversine_nm(la1, lo1, la2, lo2))
    duration = max(900.0, min(21600.0, dist_nm / 450.0 * 3600.0))
    start_ts = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT offline_start_ts FROM radar_positions WHERE hardware_id = ?;",
            (str(hid)[:128],),
        ).fetchone()
        if row and float(row[0] or 0) > 0:
            start_ts = float(row[0])
    except sqlite3.Error:
        pass
    finally:
        conn.close()
    frac = ((time.time() - start_ts) % duration) / duration
    lat = la1 + (la2 - la1) * frac
    lon = lo1 + (lo2 - lo1) * frac
    hdg = (math.degrees(math.atan2(lo2 - lo1, la2 - la1)) + 360.0) % 360.0
    alt = 35000.0 if 0.08 < frac < 0.86 else max(2500.0, 35000.0 * min(frac / 0.08 if frac <= 0.08 else (1.0 - frac) / 0.14, 1.0))
    return lat, lon, alt, hdg, route or f"{origin} → {dest}", origin, dest, start_ts


def _radar_body_coord(body: dict[str, Any], *keys: str) -> float | None:
    """GPS aus Heartbeat-JSON als double (lat/lon/latitude/longitude)."""
    for key in keys:
        raw = body.get(key)
        if raw is None or raw == "":
            continue
        try:
            if isinstance(raw, str):
                raw = raw.strip().replace(",", ".")
            val = float(raw)
            if val != val:  # NaN
                continue
            if abs(val) > 90 and abs(val) <= 90000000:
                val = val / 1_000_000.0
            elif abs(val) > 180 and abs(val) <= 180000000:
                val = val / 1_000_000.0
            return val
        except (TypeError, ValueError):
            continue
    return None


def _radar_coords_valid(lat: float, lon: float) -> bool:
    if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
        return False
    if abs(lat) < 0.02 and abs(lon) < 0.02:
        return False
    return True


def _radar_normalize_lat_lon(lat: float, lon: float) -> tuple[float, float]:
    """Korrigiert vertauschte LAT/LON (MSFS/EU: lat soll ~47–55, lon ~5–15 sein)."""
    la, lo = float(lat), float(lon)
    if (
        abs(la) < 25.0
        and abs(lo) > 28.0
        and abs(lo) <= 75.0
        and abs(la) < abs(lo)
    ):
        la, lo = lo, la
    return la, lo


HWID_MAX_ACCOUNTS_PER_PC = 3


def _hwid_limit_message(lang: str = "de") -> str:
    _ = lang
    return (
        "Hardware-ID Limit erreicht (Max. 3 Konten pro PC) / "
        "Hardware ID limit reached (Max 3 accounts per PC)"
    )


def _email_registered_on_hwid(email_norm: str, hardware_id: str) -> bool:
    em = str(email_norm or "").strip().lower()[:200]
    hid = str(hardware_id or "").strip()[:128]
    hid64 = hid[:64]
    if not em or "@" not in em or not hid64:
        return False
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = sconn.execute(
            """
            SELECT 1 FROM license_keys
            WHERE lower(trim(customer_email)) = ?
              AND (hardware_id = ? OR substr(hardware_id, 1, 64) = ?)
            LIMIT 1;
            """,
            (em, hid, hid64),
        ).fetchone()
        if row:
            return True
    finally:
        sconn.close()
    conn = None
    try:
        conn = get_db_connection()
        row_pg = pg_fetchone(
            conn,
            """
            SELECT 1
            FROM assigned_licenses al
            INNER JOIN users u ON (
                u.hardware_id = al.hardware_id
                OR substring(u.hardware_id from 1 for 64) = substring(al.hardware_id from 1 for 64)
            )
            WHERE lower(trim(COALESCE(u.email, ''))) = %s
              AND (al.hardware_id = %s OR substring(al.hardware_id from 1 for 64) = %s)
            LIMIT 1;
            """,
            (em, hid, hid64),
        )
        return bool(row_pg)
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return False
    finally:
        if conn is not None:
            conn.close()


def _hwid_collect_bound_emails(hardware_id: str) -> set[str]:
    """Alle E-Mail-Konten, die diese HWID in SQLite/PG bereits nutzen."""
    hid = str(hardware_id or "").strip()[:128]
    hid64 = hid[:64]
    emails: set[str] = set()
    if not hid64:
        return emails
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        rows = sconn.execute(
            """
            SELECT lower(trim(customer_email)) FROM license_keys
            WHERE trim(customer_email) <> ''
              AND lower(trim(customer_email)) LIKE '%@%'
              AND (hardware_id = ? OR substr(hardware_id, 1, 64) = ?);
            """,
            (hid, hid64),
        ).fetchall()
        for r in rows:
            em = str(r[0] or "").strip().lower()
            if em and "@" in em:
                emails.add(em)
    finally:
        sconn.close()
    conn = None
    try:
        conn = get_db_connection()
        rows_pg = pg_fetchall(
            conn,
            """
            SELECT DISTINCT lower(trim(COALESCE(u.email, ''))) AS em
            FROM assigned_licenses al
            INNER JOIN users u ON (
                u.hardware_id = al.hardware_id
                OR substring(u.hardware_id from 1 for 64) = substring(al.hardware_id from 1 for 64)
            )
            WHERE (al.hardware_id = %s OR substring(al.hardware_id from 1 for 64) = %s)
              AND trim(COALESCE(u.email, '')) <> ''
              AND lower(trim(u.email)) LIKE '%%@%%';
            """,
            (hid, hid64),
        )
        for row in rows_pg or []:
            em = str(
                row.get("em") if isinstance(row, dict) else row[0] or ""
            ).strip().lower()
            if em and "@" in em:
                emails.add(em)
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        if conn is not None:
            conn.close()
    return emails


def _hwid_distinct_account_count(hardware_id: str) -> int:
    return len(_hwid_collect_bound_emails(hardware_id))


def _hwid_triple_slot_allows(email_norm: str, hardware_id: str) -> tuple[bool, str]:
    """Max. 3 Konten pro HWID; bestehendes Konto auf dieser HWID immer erlaubt."""
    em = str(email_norm or "").strip().lower()[:200]
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return True, ""
    if em and "@" in em and _email_registered_on_hwid(em, hid):
        return True, ""
    if _hwid_distinct_account_count(hid) >= HWID_MAX_ACCOUNTS_PER_PC:
        return False, "hwid_limit"
    return True, ""


def _resolve_login_email(
    conn: sqlite3.Connection, pilot: str, hint_email: str = ""
) -> str:
    """E-Mail zu Pilotenname (license_keys, web_pending, PostgreSQL)."""
    em = str(hint_email or "").strip().lower()[:200]
    if em and "@" in em:
        return em
    pn = str(pilot or "").strip()[:120]
    if not pn:
        return ""
    row = conn.execute(
        """
        SELECT lower(trim(customer_email)) FROM license_keys
        WHERE lower(trim(customer_email)) LIKE '%@%'
          AND (
                lower(trim(pilot_name)) = lower(trim(?))
             OR lower(trim(customer_email)) = lower(trim(?))
          )
        ORDER BY created_ts DESC LIMIT 1;
        """,
        (pn, pn),
    ).fetchone()
    if row and row[0]:
        return str(row[0]).strip().lower()[:200]
    row2 = conn.execute(
        """
        SELECT lower(trim(email)) FROM web_pending_users
        WHERE lower(trim(pilot_name)) = lower(trim(?))
           OR lower(trim(email)) = lower(trim(?))
        ORDER BY created_ts DESC LIMIT 1;
        """,
        (pn, pn),
    ).fetchone()
    if row2 and row2[0]:
        return str(row2[0]).strip().lower()[:200]
    conn_pg = None
    try:
        conn_pg = get_db_connection()
        row_pg = pg_fetchone(
            conn_pg,
            """
            SELECT lower(trim(email)) FROM users
            WHERE lower(trim(username)) = lower(trim(%s))
               OR lower(trim(email)) = lower(trim(%s))
            LIMIT 1;
            """,
            (pn, pn),
        )
        if row_pg:
            v = str(
                row_pg.get("email") if isinstance(row_pg, dict) else row_pg[0] or ""
            ).strip().lower()
            if v and "@" in v:
                return v[:200]
    except Exception:
        if conn_pg is not None:
            _pg_rollback(conn_pg)
    finally:
        if conn_pg is not None:
            conn.close()
    return ""


def _provision_hwid_slot_license(
    conn: sqlite3.Connection,
    email: str,
    pilot: str,
    hardware_id: str,
    password: str = "",
) -> tuple[bool, str]:
    """
    Triple-Slot: HWID an neues Konto binden (unused Shop-Key, Autopilot oder frischer ST-Key).
    """
    em = _resolve_login_email(conn, pilot, email)
    hid_use = str(hardware_id or "").strip()[:128]
    pilot_n = str(pilot or "").strip()[:120] or (
        em.split("@", 1)[0][:120] if em else "Pilot"
    )
    if not hid_use:
        return False, ""
    slot_ok, _err = _hwid_triple_slot_allows(em or pilot_n, hid_use)
    if not slot_ok:
        return False, ""
    if em and "@" in em:
        ok_bind, lk = _bind_unused_shop_license_to_hwid(
            em, hid_use, pilot_n, password
        )
        if ok_bind and lk:
            return True, lk
        salt, ph = _password_hash_store(password) if password else ("", "")
        lk_auto = _autopilot_fulfill_customer_license(
            em,
            pilot_n,
            hardware_id=hid_use,
            status="activated",
            password_salt=salt,
            password_hash=ph,
            send_email=False,
            reuse_existing_unused=True,
        )
        if lk_auto:
            return True, str(lk_auto).strip()
    lk_new = _generate_unique_st_license_key()
    salt2, ph2 = _password_hash_store(password) if password else ("", "")
    try:
        conn.execute(
            """
            INSERT INTO license_keys (
                license_key, status, hardware_id, pilot_name,
                password_salt, password_hash, customer_email, created_ts
            ) VALUES (?, 'activated', ?, ?, ?, ?, ?, ?);
            """,
            (
                lk_new,
                hid_use,
                pilot_n,
                salt2,
                ph2,
                em if em and "@" in em else "",
                time.time(),
            ),
        )
        conn.commit()
        if em and "@" in em:
            try:
                _pg_bind_license_to_email_account(
                    em, lk_new, pilot_n, hid_use, license_row_status="activated"
                )
                _pg_bind_license_to_hardware(em, hid_use, lk_new, pilot_n)
            except Exception as exc_pg:  # noqa: BLE001
                _server_log_line(f"[hwid-slot] PG bind: {exc_pg!s}")
        return True, lk_new
    except Exception as exc_sql:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:
            pass
        _server_log_line(f"[hwid-slot] provision failed: {exc_sql!s}")
        return False, ""


def _login_response_language_fields(hid64: str, email: str = "") -> dict[str, Any]:
    prefs = _pg_user_prefs(hid64, email=email)
    lang = str(prefs.get("selected_language") or "de").strip().lower()[:8]
    if lang not in ("de", "en"):
        lang = "de"
    return {"selected_language": lang, "ui_lang": lang}


@app.post("/api/v1/radar/update")
def radar_update(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = str(body.get("hardware_id", "") or body.get("id", "") or "").strip()[:128]
    if not hid:
        raise HTTPException(status_code=400, detail="no_id")
    try:
        status_mode = str(body.get("status") or "ONLINE").strip().upper()
        if status_mode not in {"ONLINE", "OFFLINE"}:
            status_mode = "ONLINE"
        cur_icao = str(
            body.get("current_icao", body.get("icao", "")) or ""
        ).strip().upper()[:4]
        route = str(body.get("route", "–"))[:120]
        if cur_icao and route in ("–", "-", ""):
            route = cur_icao
        origin_icao, destination_icao = _radar_route_icaos(route, cur_icao)
        flight_phase = str(
            body.get("flight_phase_key", body.get("flight_phase", "unknown"))
            or "unknown"
        )[:32]
        try:
            ground_speed = float(
                body.get("ground_speed", body.get("gs", 0)) or 0
            )
        except (TypeError, ValueError):
            ground_speed = 0.0
        ac = str(
            body.get("aircraft_model", body.get("aircraft", "")) or ""
        )[:120]
        if ac:
            try:
                _register_dynamic_aircraft_model(ac, "radar_update")
            except Exception:
                pass
        previous_row = None
        try:
            _pc = sqlite3.connect(str(SERVER_DB_PATH))
            previous_row = _pc.execute(
                "SELECT lat, lon, alt, hdg FROM radar_positions WHERE hardware_id = ?;",
                (hid,),
            ).fetchone()
            _pc.close()
        except sqlite3.Error:
            previous_row = None
        previous = (
            (float(previous_row[0] or 0), float(previous_row[1] or 0), float(previous_row[2] or 0), float(previous_row[3] or 0))
            if previous_row
            else None
        )
        if status_mode == "OFFLINE":
            la, lo, alt_off, hdg_off, route, origin_icao, destination_icao, offline_start_ts = _radar_interpolate_offline_position(
                hid, route, cur_icao, previous
            )
            flight_phase = "OFFLINE-SIM"
            ground_speed = 450.0
        else:
            la_v = _radar_body_coord(body, "lat", "latitude")
            lo_v = _radar_body_coord(body, "lon", "longitude")
            if la_v is not None and lo_v is not None:
                la, lo = _radar_normalize_lat_lon(float(la_v), float(lo_v))
                if not _radar_coords_valid(la, lo):
                    la, lo = 50.0379, 8.5622
            else:
                la, lo = 50.0379, 8.5622
            alt_v = _radar_body_coord(body, "alt", "altitude")
            hdg_v = _radar_body_coord(body, "hdg", "heading")
            alt_off = float(alt_v if alt_v is not None else 0.0)
            hdg_off = float(hdg_v if hdg_v is not None else 0.0)
            offline_start_ts = 0.0
        pilot_name = str(
            body.get("username")
            or body.get("pilot_name")
            or body.get("pilot")
            or "?"
        )[:80]
        origin_body = str(
            body.get("origin") or body.get("origin_icao") or ""
        ).strip().upper()[:8]
        dest_body = str(
            body.get("destination") or body.get("destination_icao") or ""
        ).strip().upper()[:8]
        if (
            origin_body == "STANDBY"
            or dest_body == "STANDBY"
            or _radar_phase_is_standby(flight_phase)
        ):
            flight_phase = "AM GATE / PARKING"
            origin_icao = "STANDBY"
            destination_icao = "STANDBY"
            route = "STANDBY"
            if not ac or ac.lower() in ("", "none", "—", "-"):
                ac = str(body.get("aircraft_type") or "None")[:120]
            ground_speed = 0.0
            alt_off = 0.0
        rec = {
            "id": hid,
            "pilot": pilot_name,
            "lat": float(la),
            "lon": float(lo),
            "alt": float(alt_off),
            "hdg": float(hdg_off),
            "route": route,
            "aircraft": ac,
            "ts": float(body.get("ts", time.time())),
            "flight_phase": flight_phase,
            "ground_speed": ground_speed,
            "status": status_mode,
            "origin_icao": origin_icao,
            "destination_icao": destination_icao,
            "offline_start_ts": offline_start_ts,
        }
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="bad_coords")
    with _RADAR_LOCK:
        pilot_clean = str(rec.get("pilot") or "").strip().lower()
        if pilot_clean and pilot_clean not in {"?", "cursor tester", "tester", "test"}:
            _RADAR.pop("cursor-tester", None)
            _RADAR.pop("cursor_tester", None)
            for old_key in [k for k, v in _RADAR.items() if str(v.get("pilot") or "").strip().lower() == "cursor tester"]:
                _RADAR.pop(old_key, None)
        _RADAR[hid] = rec
        peers: list[dict[str, Any]] = []
        for k, v in _RADAR.items():
            if k == hid:
                continue
            try:
                dnm = _haversine_nm(
                    rec["lat"], rec["lon"], float(v["lat"]), float(v["lon"])
                )
            except Exception:
                continue
            if dnm <= 800.0:
                peers.append(dict(v))
    def _persist_radar_row() -> None:
        rconn = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            pilot_clean = str(rec.get("pilot") or "").strip().lower()
            if pilot_clean and pilot_clean not in {"?", "cursor tester", "tester", "test"}:
                rconn.execute(
                    """
                    DELETE FROM radar_positions
                    WHERE lower(trim(coalesce(pilot_name, ''))) IN ('cursor tester', 'tester', 'test')
                       OR lower(trim(coalesce(hardware_id, ''))) IN ('cursor-tester', 'cursor_tester');
                    """
                )
            prev_phase = ""
            prow = rconn.execute(
                "SELECT flight_phase FROM radar_positions WHERE hardware_id = ?;",
                (hid,),
            ).fetchone()
            if prow and prow[0]:
                prev_phase = str(prow[0])
            rconn.execute(
                """
                INSERT OR REPLACE INTO radar_positions (
                    hardware_id, pilot_name, lat, lon, alt, hdg, route, aircraft, ts,
                    flight_phase, ground_speed, status, origin_icao, destination_icao,
                    offline_start_ts, last_online_ts
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
                """,
                (
                    hid,
                    rec["pilot"],
                    rec["lat"],
                    rec["lon"],
                    rec["alt"],
                    rec["hdg"],
                    rec["route"],
                    rec["aircraft"],
                    rec["ts"],
                    rec["flight_phase"],
                    rec["ground_speed"],
                    rec["status"],
                    rec["origin_icao"],
                    rec["destination_icao"],
                    rec["offline_start_ts"],
                    rec["ts"] if rec["status"] == "ONLINE" else 0,
                ),
            )
            rconn.commit()
            if _radar_phase_is_cruise(rec["flight_phase"]) and not _radar_phase_is_cruise(
                prev_phase
            ):
                pilot_name = str(rec.get("pilot") or "").strip()
                if not pilot_name or pilot_name == "?":
                    pilot_name = _pilot_display_name_for_hid(hid[:64])
                if _looks_like_opaque_hardware_token(pilot_name):
                    pilot_name = "Captain"
                _append_server_live_ticker(
                    f"📡 Live-Radar: Cpt. {pilot_name} ist im Reiseflug!"
                )
        finally:
            rconn.close()
        try:
            _persist_radar_postgres(rec, hid)
        except Exception as exc_pg:  # noqa: BLE001
            _server_log_line(f"[radar] PostgreSQL persist failed: {exc_pg!s}")
        try:
            if rec.get("status") == "ONLINE":
                _persist_live_flight_postgres(
                    username=str(rec.get("pilot") or ""),
                    hardware_id=hid,
                    route=str(rec.get("route") or ""),
                    aircraft=str(rec.get("aircraft") or "None"),
                    status="STANDBY"
                    if _radar_phase_is_standby(str(rec.get("flight_phase") or ""))
                    else "ONLINE",
                    flight_phase=str(rec.get("flight_phase") or ""),
                    ts=float(rec.get("ts") or time.time()),
                    lat=float(rec.get("lat") or 0),
                    lon=float(rec.get("lon") or 0),
                )
        except Exception as exc_lf:  # noqa: BLE001
            _server_log_line(f"[radar] live_flights persist failed: {exc_lf!s}")

    try:
        _persist_radar_row()
    except sqlite3.OperationalError as exc:
        _server_log_line(f"[radar] DB write failed, M202 repair: {exc!s}")
        try:
            enforce_absolute_database_integrity()
            _persist_radar_row()
        except Exception as exc2:  # noqa: BLE001
            _server_log_line(f"[radar] persist after M202 failed: {exc2!s}")
    except Exception as exc:  # noqa: BLE001
        _server_log_line(f"[radar] persist failed: {exc!s}")
    return JSONResponse({"status": "success", "mode": rec["status"], "peers": peers})


@app.post("/api/v1/radar/live")
def radar_live_post(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    """Produktiver Alias: main.py darf Live-Telemetrie direkt an /radar/live senden."""
    return radar_update(body)


def _pg_radar_purge_pilot(hardware_id: str, username: str = "") -> int:
    """Entfernt Pilot sofort aus Live-FIDS (PostgreSQL + In-Memory)."""
    hid = str(hardware_id or "").strip()[:128]
    uname = str(username or "").strip()[:80]
    removed = 0
    conn = get_db_connection()
    try:
        _ensure_pg_radar_table(conn)
        _ensure_pg_live_flights_table(conn)
        with conn.cursor() as cur:
            if hid:
                cur.execute("DELETE FROM radar_positions WHERE hardware_id = %s;", (hid,))
                removed += cur.rowcount
                cur.execute(
                    "DELETE FROM live_flights WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;",
                    (hid, hid[:64]),
                )
                removed += cur.rowcount
            if uname:
                cur.execute(
                    "DELETE FROM live_flights WHERE lower(trim(username)) = lower(trim(%s));",
                    (uname,),
                )
                removed += cur.rowcount
                cur.execute(
                    "DELETE FROM radar_positions WHERE lower(trim(pilot_name)) = lower(trim(%s));",
                    (uname,),
                )
                removed += cur.rowcount
        conn.commit()
    except psycopg2.Error:
        conn.rollback()
    finally:
        conn.close()
    with _RADAR_LOCK:
        if hid:
            _RADAR.pop(hid, None)
        if uname:
            for key in list(_RADAR.keys()):
                if str(_RADAR[key].get("pilot") or "").strip().lower() == uname.lower():
                    _RADAR.pop(key, None)
    return removed


def _pg_radar_ghost_cleanup_once() -> int:
    cutoff = time.time() - RADAR_HEARTBEAT_STALE_SEC
    conn = get_db_connection()
    n = 0
    try:
        _ensure_pg_radar_table(conn)
        _ensure_pg_live_flights_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                DELETE FROM radar_positions
                WHERE COALESCE(NULLIF(last_heartbeat, 0), ts) < %s;
                """,
                (cutoff,),
            )
            n += cur.rowcount
            cur.execute(
                """
                DELETE FROM live_flights
                WHERE COALESCE(NULLIF(last_heartbeat, 0), ts) < %s;
                """,
                (cutoff,),
            )
            n += cur.rowcount
        conn.commit()
    except psycopg2.Error:
        conn.rollback()
    finally:
        conn.close()
    if n:
        with _RADAR_LOCK:
            stale_keys = [
                k
                for k, v in _RADAR.items()
                if float(v.get("ts") or 0) < cutoff
            ]
            for k in stale_keys:
                _RADAR.pop(k, None)
    return n


async def _radar_ghost_cleanup_loop() -> None:
    await asyncio.sleep(6.0)
    while True:
        try:
            purged = await asyncio.to_thread(_pg_radar_ghost_cleanup_once)
            if purged:
                _server_log_line(f"[radar] ghost cleanup removed {purged} stale row(s)")
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[radar] ghost cleanup failed: {exc!s}")
        await asyncio.sleep(RADAR_GHOST_CLEANUP_INTERVAL_SEC)


def _pg_radar_pilot_was_online(hid: str) -> bool:
    """True wenn letzter Heartbeat innerhalb der Stale-Grenze (vor diesem Ping)."""
    hk = (hid or "").strip()[:128]
    if not hk:
        return False
    cutoff = time.time() - RADAR_HEARTBEAT_STALE_SEC
    conn = get_db_connection()
    try:
        _ensure_pg_radar_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT COALESCE(NULLIF(last_heartbeat, 0), ts) AS hb
                FROM radar_positions WHERE hardware_id = %s LIMIT 1;
                """,
                (hk,),
            )
            row = cur.fetchone()
        return bool(row and float(row[0] or 0) >= cutoff)
    except Exception:
        return False
    finally:
        conn.close()


def _pg_radar_online_count() -> int:
    cutoff = time.time() - RADAR_HEARTBEAT_STALE_SEC
    conn = get_db_connection()
    try:
        _ensure_pg_radar_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT COUNT(*) FROM radar_positions
                WHERE COALESCE(NULLIF(last_heartbeat, 0), ts) >= %s
                  AND COALESCE(status, 'ONLINE') = 'ONLINE';
                """,
                (cutoff,),
            )
            row = cur.fetchone()
        return int(row[0] if row else 0)
    except Exception:
        return 0
    finally:
        conn.close()


@app.post("/api/v1/radar/heartbeat")
def radar_heartbeat(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """5s-Herzschlag: Standby am Gate oder Live-Position — aktualisiert FIDS."""
    body = body if isinstance(body, dict) else {}
    try:
        return _radar_heartbeat_impl(request, body)
    except HTTPException:
        raise
    except Exception as exc_hb:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[radar] heartbeat failed: {exc_hb!s}")
        return _sky_json_error_response(request, "generic", status_code=503)


def _radar_heartbeat_impl(
    request: Request, body: dict[str, Any]
) -> JSONResponse:
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = str(body.get("hardware_id") or body.get("id") or "")[:128]
    if not hid:
        raise HTTPException(status_code=401, detail="auth_failed")
    was_online = _pg_radar_pilot_was_online(hid)
    if not _pg_has_active_booked_job(hid):
        _pg_maybe_release_gsx_if_idle(
            hid, str(body.get("username") or body.get("pilot_name") or "")
        )
    phase = str(
        body.get("flight_phase")
        or body.get("flight_phase_key")
        or "AM GATE / PARKING"
    )[:64]
    if not _pg_has_active_booked_job(hid):
        phase = "AM GATE / PARKING"
    body["flight_phase"] = phase
    body["flight_phase_key"] = phase
    body["status"] = "ONLINE"
    if (
        phase.upper().find("GATE") >= 0
        or phase.upper().find("PARK") >= 0
        or phase.upper().find("STANDBY") >= 0
        or not _pg_has_active_booked_job(hid)
    ):
        body["origin"] = "STANDBY"
        body["destination"] = "STANDBY"
        body["origin_icao"] = "STANDBY"
        body["destination_icao"] = "STANDBY"
        body["current_icao"] = str(body.get("current_icao") or "STANDBY")[:4]
        body["route"] = "STANDBY"
        try:
            body["ground_speed"] = 0
            body["alt"] = 0
            body["altitude"] = 0
        except (TypeError, ValueError):
            pass
    body["hardware_id"] = hid
    body["ts"] = time.time()
    la_hb = _radar_body_coord(body, "lat", "latitude")
    lo_hb = _radar_body_coord(body, "lon", "longitude")
    if la_hb is not None and lo_hb is not None:
        la_n, lo_n = _radar_normalize_lat_lon(float(la_hb), float(lo_hb))
        if _radar_coords_valid(la_n, lo_n):
            body["latitude"] = la_n
            body["longitude"] = lo_n
            body["lat"] = la_n
            body["lon"] = lo_n
    pilot_label = str(
        body.get("username")
        or body.get("pilot_name")
        or body.get("pilot")
        or ""
    ).strip()[:80]
    resp = radar_update(body)
    online_n = _pg_radar_online_count()
    if not was_online and pilot_label:
        try:
            _queue_discord_bot_command(
                "radar_pilot_online",
                {
                    "hardware_id": hid,
                    "pilot_name": pilot_label,
                    "aircraft": str(body.get("aircraft_model") or body.get("aircraft") or "B738")[:120],
                    "flight_phase": str(body.get("flight_phase") or "AM GATE / PARKING")[:64],
                    "current_icao": str(body.get("current_icao") or "STANDBY")[:8],
                    "online_count": online_n,
                },
            )
        except Exception as exc_dc:  # noqa: BLE001
            _server_log_line(f"[radar] discord pilot_online queue failed: {exc_dc!s}")
    try:
        data = json.loads(resp.body.decode("utf-8"))
        if isinstance(data, dict):
            data["online_count"] = online_n
            data["heartbeat_ok"] = True
            return JSONResponse(data)
    except Exception:
        pass
    return JSONResponse(
        {"ok": True, "status": "heartbeat", "online_count": online_n, "hardware_id": hid}
    )


@app.post("/api/v1/radar/disconnect")
def radar_disconnect(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """App-Schließen: Pilot sofort von der Live-Flugtafel entfernen."""
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = str(body.get("hardware_id") or body.get("id") or "")[:128]
    uname = str(
        body.get("username")
        or body.get("pilot_name")
        or body.get("pilot")
        or ""
    ).strip()[:80]
    if not hid and not uname:
        raise HTTPException(status_code=400, detail="no_id")
    removed = _pg_radar_purge_pilot(hid, uname)
    return JSONResponse(
        {"ok": True, "status": "disconnected", "removed": removed, "hardware_id": hid}
    )


@app.post("/api/v1/radar/initialize_session")
def radar_initialize_session(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    """PC-EXE Startsignal: Pilot sofort im FIDS/Radar sichtbar machen, auch ohne Job."""
    username = str(
        body.get("username")
        or body.get("pilot_name")
        or body.get("pilot")
        or "Pilot"
    ).strip()[:80] or "Pilot"
    hid = str(body.get("hardware_id") or body.get("id") or username).strip()[:128]
    current_icao = str(body.get("current_icao") or body.get("icao") or "EDDF").strip().upper()[:4] or "EDDF"
    default_coords = GLOBAL_AIRPORT_COORDS.get(current_icao, GLOBAL_AIRPORT_COORDS.get("EDDF", (50.0379, 8.5622)))
    try:
        lat = float(body.get("lat", body.get("latitude", default_coords[0])) or default_coords[0])
        lon = float(body.get("lon", body.get("longitude", default_coords[1])) or default_coords[1])
        alt = float(body.get("alt", body.get("altitude", 0)) or 0)
        hdg = float(body.get("hdg", body.get("heading", 0)) or 0)
    except (TypeError, ValueError):
        lat, lon, alt, hdg = float(default_coords[0]), float(default_coords[1]), 0.0, 0.0
    aircraft = str(body.get("aircraft_model") or body.get("aircraft") or "Standard Flotte").strip()[:120] or "Standard Flotte"
    try:
        _register_dynamic_aircraft_model(aircraft, "radar_initialize")
    except Exception:
        pass
    phase = "AM GATE / PARKING"
    now = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT INTO radar_positions (
                hardware_id, pilot_name, lat, lon, alt, hdg, route, aircraft, ts,
                flight_phase, ground_speed, status, origin_icao, destination_icao,
                offline_start_ts, last_online_ts
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 'ONLINE', ?, ?, 0, ?)
            ON CONFLICT(hardware_id) DO UPDATE SET
                pilot_name = excluded.pilot_name,
                lat = excluded.lat,
                lon = excluded.lon,
                alt = excluded.alt,
                hdg = excluded.hdg,
                route = CASE WHEN trim(coalesce(radar_positions.route, '')) = '' THEN excluded.route ELSE radar_positions.route END,
                aircraft = CASE WHEN trim(coalesce(radar_positions.aircraft, '')) = '' THEN excluded.aircraft ELSE radar_positions.aircraft END,
                ts = excluded.ts,
                flight_phase = CASE
                    WHEN trim(coalesce(radar_positions.flight_phase, '')) = '' THEN excluded.flight_phase
                    WHEN radar_positions.flight_phase IN ('unknown', 'Unknown', 'OFFLINE-SIM') THEN excluded.flight_phase
                    ELSE radar_positions.flight_phase
                END,
                status = 'ONLINE',
                origin_icao = CASE WHEN trim(coalesce(radar_positions.origin_icao, '')) = '' THEN excluded.origin_icao ELSE radar_positions.origin_icao END,
                destination_icao = CASE WHEN trim(coalesce(radar_positions.destination_icao, '')) = '' THEN excluded.destination_icao ELSE radar_positions.destination_icao END,
                last_online_ts = excluded.last_online_ts;
            """,
            (
                hid,
                username,
                lat,
                lon,
                alt,
                hdg,
                current_icao,
                aircraft,
                now,
                phase,
                current_icao,
                current_icao,
                now,
            ),
        )
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        conn.close()
    init_rec = {
        "id": hid,
        "pilot": username,
        "lat": lat,
        "lon": lon,
        "alt": alt,
        "hdg": hdg,
        "route": "STANDBY",
        "aircraft": aircraft or "None",
        "ts": now,
        "flight_phase": phase,
        "ground_speed": 0.0,
        "status": "ONLINE",
        "origin_icao": "STANDBY",
        "destination_icao": "STANDBY",
        "offline_start_ts": 0.0,
    }
    try:
        _persist_radar_postgres(init_rec, hid)
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[radar] initialize_session PG: {exc_pg!s}")
    try:
        _persist_live_flight_postgres(
            username=username,
            hardware_id=hid,
            route="STANDBY",
            aircraft=aircraft or "None",
            status="STANDBY",
            flight_phase=phase,
            ts=now,
        )
    except Exception as exc_init:  # noqa: BLE001
        _server_log_line(f"[radar] initialize_session live_flights: {exc_init!s}")
    with _RADAR_LOCK:
        _RADAR[hid] = dict(init_rec)
    return JSONResponse(
        {
            "status": "success",
            "initialized": True,
            "pilot_name": username,
            "hardware_id": hid,
            "flight_phase": phase,
            "current_icao": current_icao,
            "lat": lat,
            "lon": lon,
        }
    )


@app.get("/api/v1/radar/nearby")
def radar_nearby(
    hardware_id: str, lat: float | None = None, lon: float | None = None
) -> JSONResponse:
    hid = (hardware_id or "").strip()[:128]
    peers: list[dict[str, Any]] = []
    with _RADAR_LOCK:
        self_rec = _RADAR.get(hid)
        la = float(lat) if lat is not None else (
            float(self_rec["lat"]) if self_rec else 0.0
        )
        lo = float(lon) if lon is not None else (
            float(self_rec["lon"]) if self_rec else 0.0
        )
        for k, v in _RADAR.items():
            if k == hid:
                continue
            try:
                dnm = _haversine_nm(la, lo, float(v["lat"]), float(v["lon"]))
            except Exception:
                continue
            if dnm <= 800.0:
                peers.append(dict(v))
    return JSONResponse({"peers": peers})


def _m216_hid_for_username(username: str) -> str:
    """Username/Pilot/E-Mail/Hardware-ID robust auf Hardware-ID abbilden."""
    ident = str(username or "").strip()[:160]
    if not ident:
        return ""
    low = ident.lower()
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        for sql, params in (
            ("SELECT hardware_id FROM web_pending_users WHERE lower(trim(email)) = ? OR lower(trim(pilot_name)) = ? ORDER BY created_ts DESC LIMIT 1;", (low, low)),
            ("SELECT hardware_id FROM license_keys WHERE lower(trim(customer_email)) = ? OR lower(trim(pilot_name)) = ? OR license_key = ? ORDER BY created_ts DESC LIMIT 1;", (low, low, ident)),
            ("SELECT hardware_id FROM radar_positions WHERE lower(trim(pilot_name)) = ? ORDER BY ts DESC LIMIT 1;", (low,)),
        ):
            row = sconn.execute(sql, params).fetchone()
            if row and str(row[0] or "").strip():
                return str(row[0]).strip()[:64]
    finally:
        sconn.close()
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        cols = {str(r[1]) for r in uconn.execute("PRAGMA table_info(users);").fetchall()}
        where = ["hardware_id = ?"]
        params2: list[Any] = [ident[:64]]
        for c in ("username", "pilot_name", "email"):
            if c in cols:
                where.append(f"lower(trim({c})) = ?")
                params2.append(low)
        row = uconn.execute(f"SELECT hardware_id FROM users WHERE {' OR '.join(where)} LIMIT 1;", params2).fetchone()
        if row and str(row[0] or "").strip():
            return str(row[0]).strip()[:64]
    except sqlite3.Error:
        pass
    finally:
        uconn.close()
    return ident[:64]


def _rank_catalog() -> list[dict[str, Any]]:
    try:
        import skytycoon_prestige_pack as _prestige_pack

        return _prestige_pack.rank_catalog_full()
    except Exception:
        names = [
            "Flugschüler",
            "Co-Pilot",
            "Senior Co-Pilot",
            "Kapitän",
            "Senior Kapitän",
            "Prüfkapitän",
            "Flottenkommandant",
            "Luftfahrt-Direktor",
            "Globaler Tycoon",
            "Legende der Lüfte",
        ]
        miles = [0, 500, 1500, 5000, 15000, 35000, 75000, 150000, 300000, 600000]
        return [{"level": i + 1, "name": names[i], "min_miles": miles[i]} for i in range(10)]


def _achievement_payload_for_hid(hid64: str) -> dict[str, Any]:
    try:
        import skytycoon_prestige_pack as _prestige_pack

        return _prestige_pack.achievement_payload_for_hid(hid64)
    except Exception:
        pass

    hid = str(hid64 or "").strip()[:64]
    miles = 0.0
    logs = _user_flight_logs_for_dashboard(hid, limit=500) if hid else []
    for fl in logs:
        try:
            miles += float(fl.get("distance_nm") or fl.get("distance") or fl.get("dist_nm") or 0)
        except (TypeError, ValueError):
            pass
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        cols = {str(r[1]) for r in uconn.execute("PRAGMA table_info(users);").fetchall()}
        for alt in (
            "ALTER TABLE users ADD COLUMN miles REAL NOT NULL DEFAULT 0;",
        ):
            try:
                uconn.execute(alt)
                uconn.commit()
            except sqlite3.OperationalError:
                pass
        cols.add("miles")
        row = uconn.execute("SELECT miles FROM users WHERE hardware_id = ? LIMIT 1;", (hid,)).fetchone()
        if row:
            miles = max(miles, float(row[0] or 0))
    finally:
        uconn.close()
    ranks = _rank_catalog()
    rank = ranks[0]
    for r in ranks:
        if miles >= float(r["min_miles"]):
            rank = r
    next_rank = next((r for r in ranks if int(r["level"]) > int(rank["level"])), None)
    next_miles = float(next_rank["min_miles"]) if next_rank else float(rank["min_miles"])
    base_miles = float(rank["min_miles"])
    progress = 100.0 if not next_rank else max(0.0, min(100.0, ((miles - base_miles) / max(1.0, next_miles - base_miles)) * 100.0))
    medals_def = [
        ("atlantic_bridge", "Atlantik-Brücke", "Fliege über den Atlantik oder erreiche 3.000 NM Gesamtstrecke.", miles >= 3000),
        ("storm_rider", "Sturm-Reiter", "Schließe einen Flug mit aktivem Unwetter/METAR-Sturm ab.", any(bool(fl.get("metar_storm_active")) for fl in logs)),
        ("fuel_saver", "Sparfuchs", "Sammle 10.000 NM mit effizientem Betrieb.", miles >= 10000),
        ("alliance_pioneer", "Allianz-Pionier", "Tritt einer Allianz bei oder spende Credits.", _alliance_member_row(hid) is not None),
        ("bruchpilot", "Bruchpilot", "Überlebe eine harte Landung/Crash-Blackbox.", any("bruch" in str(fl.get("status", "") or fl.get("rating", "")).lower() for fl in logs)),
    ]
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    manual: set[str] = set()
    try:
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS player_manual_medals (
                hardware_id TEXT NOT NULL,
                medal_id TEXT NOT NULL,
                assigned_ts REAL NOT NULL DEFAULT 0,
                PRIMARY KEY(hardware_id, medal_id)
            );
            """
        )
        for row in sconn.execute("SELECT medal_id FROM player_manual_medals WHERE hardware_id = ?;", (hid,)).fetchall():
            manual.add(str(row[0]))
    finally:
        sconn.close()
    medals = [
        {"id": mid, "name": name, "description": desc, "unlocked": bool(ok or mid in manual)}
        for mid, name, desc, ok in medals_def
    ]
    return {
        "ok": True,
        "hardware_id": hid,
        "pilot_name": _pilot_display_name_for_hid(hid),
        "miles": round(miles, 1),
        "rank": rank,
        "next_rank": next_rank,
        "progress_pct": round(progress, 1),
        "medals": medals,
        "unlocked_count": sum(1 for m in medals if m["unlocked"]),
    }


