def player_passenger_satisfaction_get(
    request: Request, hardware_id: str = "", username: str = ""
) -> JSONResponse:
    hid = str(hardware_id or "").strip()[:64]
    if not hid and username:
        hid = _m216_hid_for_username(username)
    if not hid:
        hid = _web_parse_token(_web_raw_session_cookie(request))[:64]
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    conn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = conn.execute(
            "SELECT reputation FROM users WHERE hardware_id = ?;",
            (hid,),
        ).fetchone()
        if not row:
            return JSONResponse(
                {"ok": True, "passenger_satisfaction_pct": 100.0, "reputation": 100.0}
            )
        rep = max(0.0, min(100.0, float(row[0] or 72.0)))
        return JSONResponse(
            {
                "ok": True,
                "passenger_satisfaction_pct": round(rep, 2),
                "reputation": round(rep, 2),
            }
        )
    finally:
        conn.close()


