@app.post("/api/v1/alliance/tax/update")
def update_alliance_tax_rate(payload: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _m216_hid_for_username(str(payload.get("username") or ""))
    new_tax = max(0, min(50, int(payload.get("tax_rate", 0) or 0)))
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]).lower() not in ("ceo", "co_leader", "leader"):
        raise HTTPException(status_code=403, detail="Nur der Allianz-Commander darf den Steuersatz ändern!")
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE")
        conn.execute(
            """
            INSERT INTO alliance_tax (alliance_id, tax_pct) VALUES (?, ?)
            ON CONFLICT(alliance_id) DO UPDATE SET tax_pct = excluded.tax_pct;
            """,
            (mem[0], float(new_tax)),
        )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"status": "success", "msg": f"Allianz-Steuersatz erfolgreich auf {new_tax}% geändert!"})


