def _ensure_postgres_alliance_research_table(conn) -> None:
    statements = [
        """
        CREATE TABLE IF NOT EXISTS alliance_research (
            alliance_id VARCHAR(128) PRIMARY KEY,
            kerosin_level INTEGER DEFAULT 0,
            kerosin_credits INTEGER DEFAULT 0,
            wartung_level INTEGER DEFAULT 0,
            wartung_credits INTEGER DEFAULT 0,
            ki_level INTEGER DEFAULT 0,
            ki_credits INTEGER DEFAULT 0,
            sturm_level INTEGER DEFAULT 0,
            sturm_credits INTEGER DEFAULT 0,
            prestige_level INTEGER DEFAULT 0,
            prestige_credits INTEGER DEFAULT 0,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
        """,
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS kerosin_level INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS kerosin_credits INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS wartung_level INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS wartung_credits INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS ki_level INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS ki_credits INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS sturm_level INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS sturm_credits INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS prestige_level INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS prestige_credits INTEGER DEFAULT 0",
        "ALTER TABLE alliance_research ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP",
    ]
    with conn.cursor(cursor_factory=DictCursor) as cur:
        for stmt in statements:
            cur.execute(stmt)
            conn.commit()


def _research_hid_from_request(request: Request, hardware_id: str = "", username: str = "", password: str = "") -> str:
    hid = str(hardware_id or "").strip()[:64]
    if hid and password:
        try:
            return _desktop_api_auth_query(request, hid, password)
        except HTTPException:
            pass
    if hid:
        return hid
    hid = _auth_hid_from_bearer(request) or ""
    if not hid:
        try:
            hid = _web_parse_token(_web_raw_session_cookie(request)) or ""
        except Exception:
            hid = ""
    if not hid and username:
        hid = _m216_hid_for_username(username)
    return str(hid or "").strip()[:64]


def _alliance_research_get_response(
    request: Request,
    *,
    alliance_id: str = "",
    hardware_id: str = "",
    username: str = "",
    password: str = "",
) -> JSONResponse:
    hid = _research_hid_from_request(request, hardware_id=hardware_id, username=username, password=password)
    if not hid and not alliance_id:
        raise HTTPException(status_code=401, detail="auth_failed")
    mem = _alliance_member_row(hid) if hid else None
    aid = str(alliance_id or request.query_params.get("alliance_id", "") or (mem[0] if mem else "") or "").strip()[:80]
    if not aid:
        return JSONResponse({"ok": False, "status": "error", "reason": "NO_ALLIANCE", "perks": []})

    conn = get_db_connection()
    try:
        _ensure_postgres_alliance_research_table(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("INSERT INTO alliance_research (alliance_id) VALUES (%s) ON CONFLICT (alliance_id) DO NOTHING", (aid,))
            conn.commit()
            cur.execute("SELECT * FROM alliance_research WHERE alliance_id = %s", (aid,))
            row = cur.fetchone()
            conn.commit()
    finally:
        conn.close()

    perks: list[dict[str, Any]] = []
    row_map = dict(row or {})
    for meta in _alliance_research_defaults():
        level_col, credits_col = _RESEARCH_COLUMN_MAP[str(meta["perk_key"])]
        lvl = int(row_map.get(level_col) or 0)
        invested = float(row_map.get(credits_col) or 0)
        target = float(meta.get("target") or 1000000.0)
        max_level = int(meta.get("max_level", 5) or 5)
        next_target = target * float(min(max_level, lvl + 1))
        pct = 100.0 if lvl >= max_level else max(0.0, min(100.0, (invested / max(1.0, next_target)) * 100.0))
        perks.append(
            {
                "perk_key": str(meta["perk_key"]),
                "title": str(meta["title"]),
                "title_en": str(meta.get("title_en") or meta["title"]),
                "description": str(meta.get("description") or ""),
                "description_en": str(meta.get("description_en") or meta.get("description") or ""),
                "level": lvl,
                "max_level": max_level,
                "investment_progress": round(pct, 1),
                "invested_credits": round(invested, 1),
                "target_credits": next_target,
                "base_target_credits": target,
                "bonus": str(meta.get("bonus") or ""),
                "bonus_per_level": float(meta.get("bonus_per_level") or 0),
                "active_bonus_value": round(float(meta.get("bonus_per_level") or 0) * lvl, 2),
                "status": "completed" if lvl >= max_level else "active",
            }
        )
    return JSONResponse({"ok": True, "status": "success", "alliance_id": aid, "perks": perks})


@app.get("/api/v1/alliance/research")
def get_alliance_research(request: Request, username: str = "", hardware_id: str = "") -> JSONResponse:
    return _alliance_research_get_response(request, username=username, hardware_id=hardware_id)


@app.post("/api/v1/alliance/research/invest")
def invest_alliance_research(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = _auth_hid_from_bearer(request) or ""
        if not hid:
            try:
                hid = _web_parse_token(_web_raw_session_cookie(request)) or ""
            except Exception:
                hid = ""
        if not hid:
            raise
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "NO_ALLIANCE"}, status_code=400)
    aid = str(mem[0])
    perk_key = _normalize_research_key(str(body.get("perk_key") or "fuel_synthesis"))[:80]
    try:
        amount = max(1.0, float(body.get("amount", 0) or 0))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_amount"}, status_code=400)
    valid = {p["perk_key"]: p for p in _alliance_research_defaults()}
    if perk_key not in valid:
        return JSONResponse({"ok": False, "error": "unknown_research"}, status_code=400)
    level_col, credits_col = _RESEARCH_COLUMN_MAP[perk_key]
    conn = get_db_connection()
    try:
        _ensure_postgres_alliance_research_table(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT COALESCE(credits, 0) AS credits FROM users WHERE hardware_id = %s", (hid,))
            row = cur.fetchone()
            conn.commit()
        credits = float((row or {}).get("credits") or 0)
        if credits + 1e-6 < amount:
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("UPDATE users SET credits = COALESCE(credits, 0) - %s WHERE hardware_id = %s", (amount, hid))
            conn.commit()
            cur.execute("INSERT INTO alliance_research (alliance_id) VALUES (%s) ON CONFLICT (alliance_id) DO NOTHING", (aid,))
            conn.commit()
            cur.execute(f"UPDATE alliance_research SET {credits_col} = COALESCE({credits_col}, 0) + %s, updated_at = CURRENT_TIMESTAMP WHERE alliance_id = %s", (int(amount), aid))
            conn.commit()
            cur.execute(f"SELECT COALESCE({credits_col}, 0) AS invested, COALESCE({level_col}, 0) AS level FROM alliance_research WHERE alliance_id = %s", (aid,))
            current = cur.fetchone()
            conn.commit()
            invested = float((current or {}).get("invested") or 0)
            level = int((current or {}).get("level") or 0)
            target = float(valid[perk_key]["target"])
            max_level = int(valid[perk_key].get("max_level", 5) or 5)
            while level < max_level and invested >= target * float(level + 1):
                level += 1
            cur.execute(f"UPDATE alliance_research SET {level_col} = %s, updated_at = CURRENT_TIMESTAMP WHERE alliance_id = %s", (level, aid))
            conn.commit()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        conn.close()
    return get_alliance_research(request, hardware_id=hid)


@app.post("/api/v1/admin/player/assign_rank")
def admin_player_assign_rank(payload: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    pw = str(payload.get("admin_password") or payload.get("admin_master_password") or "")
    if pw.strip() != ADMIN_API_PASSWORD:
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    hid = _m216_hid_for_username(str(payload.get("username") or payload.get("pilot_id") or ""))
    if not hid:
        raise HTTPException(status_code=400, detail="unknown_user")
    try:
        target_rank = int(payload.get("target_rank", 0) or 0)
    except (TypeError, ValueError):
        target_rank = 0
    medal_id = str(payload.get("medal_id") or "").strip()[:64]
    ranks = _rank_catalog()
    target = next((r for r in ranks if int(r["level"]) == target_rank), None)
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute("BEGIN IMMEDIATE")
        try:
            uconn.execute("ALTER TABLE users ADD COLUMN miles REAL NOT NULL DEFAULT 0;")
        except sqlite3.OperationalError:
            pass
        if target:
            uconn.execute("UPDATE users SET miles = MAX(COALESCE(miles, 0), ?) WHERE hardware_id = ?;", (float(target["min_miles"]), hid))
        if medal_id:
            sconn.execute(
                """
                CREATE TABLE IF NOT EXISTS player_manual_medals (
                    hardware_id TEXT NOT NULL,
                    medal_id TEXT NOT NULL,
                    assigned_ts REAL NOT NULL DEFAULT 0,
                    PRIMARY KEY(hardware_id, medal_id)
                );
                """
            )
            sconn.execute(
                "INSERT OR REPLACE INTO player_manual_medals (hardware_id, medal_id, assigned_ts) VALUES (?, ?, ?);",
                (hid, medal_id, time.time()),
            )
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    rank_name = str(target.get("name", "")) if target else ""
    min_miles = float(target.get("min_miles", 0)) if target else 0.0
    try:
        _pg_sync_pilot_rank_and_discord(hid, min_miles, rank_name, target_rank)
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[assign_rank] PostgreSQL/Discord sync: {exc_pg!s}")
    return JSONResponse({"status": "success", "hardware_id": hid, "rank": target, "medal_id": medal_id})


def _mmo_hid_from_request(request: Request, body: dict[str, Any] | None = None) -> str:
    body = body or {}
    hid = _auth_hid_from_bearer(request)
    if hid:
        return hid[:64]
    try:
        hid = _web_parse_token(_web_raw_session_cookie(request))
        if hid:
            return hid[:64]
    except Exception:
        pass
    raw = str(body.get("hardware_id") or body.get("username") or body.get("pilot_name") or "").strip()
    if raw:
        return _m216_hid_for_username(raw)[:64]
    raise HTTPException(status_code=401, detail="auth_failed")


def _ensure_wallstreet_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS alliance_stocks (
            alliance_id TEXT PRIMARY KEY,
            share_price REAL NOT NULL DEFAULT 100,
            dividend_value REAL NOT NULL DEFAULT 0,
            total_profit REAL NOT NULL DEFAULT 0,
            locked_status TEXT NOT NULL DEFAULT '',
            active_listing INTEGER NOT NULL DEFAULT 0,
            listing_owner TEXT NOT NULL DEFAULT '',
            updated_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    for alt in (
        "ALTER TABLE alliance_stocks ADD COLUMN active_listing INTEGER NOT NULL DEFAULT 0;",
        "ALTER TABLE alliance_stocks ADD COLUMN listing_owner TEXT NOT NULL DEFAULT '';",
    ):
        try:
            conn.execute(alt)
        except sqlite3.OperationalError:
            pass
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS pilot_stock_portfolio (
            hardware_id TEXT NOT NULL,
            alliance_id TEXT NOT NULL,
            shares REAL NOT NULL DEFAULT 0,
            avg_price REAL NOT NULL DEFAULT 0,
            PRIMARY KEY(hardware_id, alliance_id)
        );
        """
    )


def _wallstreet_rows_for_hid(hid: str) -> dict[str, Any]:
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_wallstreet_tables(sconn)
        alliances = sconn.execute(
            """
            SELECT a.alliance_id, a.name, COALESCE(a.credits, 0),
                   (SELECT COUNT(*) FROM alliance_members m WHERE m.alliance_id = a.alliance_id AND m.role != 'pending')
            FROM alliances a ORDER BY a.credits DESC, a.name ASC;
            """
        ).fetchall()
        stocks: list[dict[str, Any]] = []
        for aid, name, credits, members in alliances:
            aid_s = str(aid)
            fleet_mv = _alliance_fleet_market_value_sqlite(sconn, aid_s)
            total_profit = float(credits or 0) + fleet_mv
            price = max(25.0, round(100.0 + total_profit / 10000.0, 2))
            dividend = round(max(0.0, total_profit) * 0.0025, 2)
            sconn.execute(
                """
                INSERT INTO alliance_stocks (alliance_id, share_price, dividend_value, total_profit, active_listing, updated_ts)
                VALUES (?, ?, ?, ?, 0, ?)
                ON CONFLICT(alliance_id) DO UPDATE SET
                    share_price = excluded.share_price,
                    dividend_value = excluded.dividend_value,
                    total_profit = excluded.total_profit,
                    updated_ts = excluded.updated_ts;
                """,
                (aid_s, price, dividend, total_profit, time.time()),
            )
            hrow = sconn.execute(
                "SELECT shares, avg_price FROM pilot_stock_portfolio WHERE hardware_id = ? AND alliance_id = ?;",
                (hid, aid_s),
            ).fetchone()
            lrow = sconn.execute("SELECT locked_status, COALESCE(active_listing, 0), COALESCE(listing_owner, '') FROM alliance_stocks WHERE alliance_id = ?;", (aid_s,)).fetchone()
            role_row = sconn.execute(
                "SELECT role FROM alliance_members WHERE alliance_id = ? AND hardware_id = ? AND role != 'pending' LIMIT 1;",
                (aid_s, hid),
            ).fetchone()
            role_s = str(role_row[0] if role_row else "").lower()
            stocks.append(
                {
                    "alliance_id": aid_s,
                    "name": str(name or aid_s),
                    "share_price": price,
                    "dividend_value": dividend,
                    "total_profit": round(total_profit, 2),
                    "members": int(members or 0),
                    "owned_shares": float(hrow[0] or 0) if hrow else 0.0,
                    "avg_price": float(hrow[1] or 0) if hrow else 0.0,
                    "locked_status": str(lrow[0] if lrow else ""),
                    "active_listing": int(lrow[1] or 0) if lrow else 0,
                    "listing_owner": str(lrow[2] or "") if lrow else "",
                    "trading_enabled": bool(lrow and int(lrow[1] or 0) == 1) and not bool(str(lrow[0] if lrow else "").strip()),
                    "is_ceo": role_s in {"ceo", "co_leader", "owner", "founder", "admin", "leader"},
                }
            )
        sconn.commit()
        portfolio = [
            {
                "alliance_id": str(aid),
                "shares": float(shares or 0),
                "avg_price": float(avg or 0),
            }
            for aid, shares, avg in sconn.execute(
                "SELECT alliance_id, shares, avg_price FROM pilot_stock_portfolio WHERE hardware_id = ? AND shares > 0;",
                (hid,),
            ).fetchall()
        ]
    finally:
        sconn.close()
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
        credits = float(row[0] or 0) if row else 0.0
    finally:
        uconn.close()
    value = 0.0
    by_aid = {s["alliance_id"]: s for s in stocks}
    for p in portfolio:
        value += float(p["shares"]) * float(by_aid.get(p["alliance_id"], {}).get("share_price", p["avg_price"]))
    return {"ok": True, "credits": credits, "portfolio_value": round(value, 2), "stocks": stocks, "portfolio": portfolio}


@app.get("/api/v1/wallstreet/dashboard")
def wallstreet_dashboard(request: Request, username: str = "", hardware_id: str = "") -> JSONResponse:
    hid = hardware_id.strip()[:64] if hardware_id else ""
    if not hid and username:
        hid = _m216_hid_for_username(username)
    if not hid:
        hid = _mmo_hid_from_request(request)
    return JSONResponse(_wallstreet_rows_for_hid(hid))


@app.post("/api/v1/wallstreet/trade")
def wallstreet_trade(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    alliance_id = str(body.get("alliance_id") or "").strip()[:80]
    side = str(body.get("side") or body.get("action") or "buy").strip().lower()
    shares = max(1.0, float(body.get("shares", 1) or 1))
    if side not in {"buy", "sell"} or not alliance_id:
        return JSONResponse({"ok": False, "error": "bad_order"}, status_code=400)
    snapshot = _wallstreet_rows_for_hid(hid)
    stock = next((s for s in snapshot["stocks"] if s["alliance_id"] == alliance_id), None)
    if not stock:
        return JSONResponse({"ok": False, "error": "unknown_alliance"}, status_code=404)
    if not bool(stock.get("active_listing", 0)):
        return JSONResponse({"ok": False, "error": "no_active_stock_listing"}, status_code=423)
    if not bool(stock.get("trading_enabled", True)):
        return JSONResponse({"ok": False, "error": "trading_frozen"}, status_code=423)
    price = float(body.get("sell_price_per_share") or stock["share_price"]) if side == "sell" else float(stock["share_price"])
    total = round(price * shares, 2)
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute("BEGIN IMMEDIATE")
        _ensure_wallstreet_tables(sconn)
        if side == "buy":
            row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
            if not row or float(row[0] or 0) + 1e-6 < total:
                uconn.rollback(); sconn.rollback()
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
            uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (total, hid))
            prev = sconn.execute(
                "SELECT shares, avg_price FROM pilot_stock_portfolio WHERE hardware_id = ? AND alliance_id = ?;",
                (hid, alliance_id),
            ).fetchone()
            old_shares = float(prev[0] or 0) if prev else 0.0
            old_avg = float(prev[1] or 0) if prev else 0.0
            new_shares = old_shares + shares
            new_avg = ((old_shares * old_avg) + total) / max(1.0, new_shares)
            sconn.execute(
                """
                INSERT INTO pilot_stock_portfolio (hardware_id, alliance_id, shares, avg_price)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(hardware_id, alliance_id) DO UPDATE SET
                    shares = excluded.shares,
                    avg_price = excluded.avg_price;
                """,
                (hid, alliance_id, new_shares, new_avg),
            )
        else:
            prev = sconn.execute(
                "SELECT shares FROM pilot_stock_portfolio WHERE hardware_id = ? AND alliance_id = ?;",
                (hid, alliance_id),
            ).fetchone()
            old_shares = float(prev[0] or 0) if prev else 0.0
            if old_shares + 1e-6 < shares:
                uconn.rollback(); sconn.rollback()
                return JSONResponse({"ok": False, "error": "not_enough_shares"}, status_code=400)
            uconn.execute("UPDATE users SET credits = credits + ? WHERE hardware_id = ?;", (total, hid))
            sconn.execute(
                "UPDATE pilot_stock_portfolio SET shares = shares - ? WHERE hardware_id = ? AND alliance_id = ?;",
                (shares, hid, alliance_id),
            )
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "side": side, "alliance_id": alliance_id, "shares": shares, "total": total, "dashboard": _wallstreet_rows_for_hid(hid)})


@app.post("/api/v1/wallstreet/takeover")
def wallstreet_takeover(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    target = str(body.get("target_alliance_id") or body.get("alliance_id") or "").strip()[:80]
    if not target:
        return JSONResponse({"ok": False, "error": "bad_target"}, status_code=400)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "NO_ALLIANCE"}, status_code=403)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_wallstreet_tables(sconn)
        total = sconn.execute("SELECT SUM(shares) FROM pilot_stock_portfolio WHERE alliance_id = ?;", (target,)).fetchone()
        mine = sconn.execute(
            """
            SELECT SUM(p.shares) FROM pilot_stock_portfolio p
            JOIN alliance_members m ON m.hardware_id = p.hardware_id
            WHERE p.alliance_id = ? AND m.alliance_id = ? AND m.role != 'pending';
            """,
            (target, str(mem[0])),
        ).fetchone()
        total_shares = float(total[0] or 0)
        mine_shares = float(mine[0] or 0)
        pct = (mine_shares / total_shares * 100.0) if total_shares > 0 else 0.0
        if pct < 51.0:
            return JSONResponse({"ok": False, "error": "not_enough_control", "control_pct": round(pct, 2)}, status_code=400)
        sconn.execute(
            "UPDATE alliance_stocks SET locked_status = ? WHERE alliance_id = ?;",
            (f"TAKEOVER_BY_{mem[0]}", target),
        )
        sconn.commit()
    finally:
        sconn.close()
    return JSONResponse({"ok": True, "target_alliance_id": target, "control_pct": round(pct, 2), "status": "TAKEOVER_TRIGGERED"})


@app.post("/api/v1/wallstreet/toggle_trading")
def wallstreet_toggle_trading(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    alliance_id = str(body.get("alliance_id") or "").strip()[:80]
    enabled = bool(body.get("enabled", False))
    if not alliance_id:
        return JSONResponse({"ok": False, "error": "bad_alliance"}, status_code=400)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[0]) != alliance_id or str(mem[1]).lower() not in {"ceo", "co_leader", "owner", "founder", "admin", "leader"}:
        return JSONResponse({"ok": False, "error": "ceo_required"}, status_code=403)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_wallstreet_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        sconn.execute(
            """
            INSERT INTO alliance_stocks (alliance_id, locked_status, updated_ts)
            VALUES (?, ?, ?)
            ON CONFLICT(alliance_id) DO UPDATE SET
                locked_status = excluded.locked_status,
                updated_ts = excluded.updated_ts;
            """,
            (alliance_id, "" if enabled else "TRADING_FROZEN_BY_CEO", time.time()),
        )
        sconn.commit()
    except sqlite3.Error as exc:
        sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        sconn.close()
    return JSONResponse({"ok": True, "alliance_id": alliance_id, "trading_enabled": enabled})


def _ensure_auction_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS auction_house (
            auction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            seller_hid TEXT NOT NULL,
            seller_name TEXT NOT NULL DEFAULT '',
            item_type TEXT NOT NULL DEFAULT 'aircraft',
            item_name TEXT NOT NULL,
            condition_pct REAL NOT NULL DEFAULT 100,
            start_price REAL NOT NULL DEFAULT 0,
            buyout_price REAL NOT NULL DEFAULT 0,
            current_bid REAL NOT NULL DEFAULT 0,
            highest_bidder_hid TEXT NOT NULL DEFAULT '',
            highest_bidder_name TEXT NOT NULL DEFAULT '',
            end_ts_utc REAL NOT NULL,
            status TEXT NOT NULL DEFAULT 'active',
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS auction_bids (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            auction_id INTEGER NOT NULL,
            bidder_hid TEXT NOT NULL,
            bidder_name TEXT NOT NULL DEFAULT '',
            amount REAL NOT NULL DEFAULT 0,
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS auction_transfers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            auction_id INTEGER NOT NULL,
            seller_hid TEXT NOT NULL,
            winner_hid TEXT NOT NULL,
            item_type TEXT NOT NULL,
            item_name TEXT NOT NULL,
            amount REAL NOT NULL,
            closed_ts REAL NOT NULL
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS cloud_hangar_assets (
            hardware_id TEXT NOT NULL,
            asset_id TEXT NOT NULL,
            aircraft_model TEXT NOT NULL,
            item_type TEXT NOT NULL DEFAULT 'aircraft',
            source TEXT NOT NULL DEFAULT '',
            condition_pct REAL NOT NULL DEFAULT 100,
            acquired_ts REAL NOT NULL DEFAULT 0,
            PRIMARY KEY(hardware_id, asset_id)
        );
        """
    )
    for alt in (
        "ALTER TABLE cloud_hangar_assets ADD COLUMN status TEXT NOT NULL DEFAULT 'ACTIVE';",
        "ALTER TABLE cloud_hangar_assets ADD COLUMN current_location TEXT NOT NULL DEFAULT '';",
    ):
        try:
            conn.execute(alt)
        except sqlite3.OperationalError:
            pass
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS mobile_push_tokens (
            hardware_id TEXT PRIMARY KEY,
            device_token TEXT NOT NULL,
            locale TEXT NOT NULL DEFAULT 'de',
            platform TEXT NOT NULL DEFAULT '',
            updated_ts REAL NOT NULL DEFAULT 0
        );
        """
    )


