def _aircraft_category_for_name(name: str) -> str:
    up = str(name or "").upper()
    if any(x in up for x in ("172", "CESSNA", "PIPER", "PROP", "TBM", "BONANZA", "BARON")):
        return "propeller"
    if any(x in up for x in ("747", "737", "777", "787", "A320", "A321", "A330", "A340", "A350", "FENIX", "PMDG")):
        return "airliner"
    if any(x in up for x in ("CJ", "Citation".upper(), "LEAR", "GULFSTREAM", "PHENOM", "HONDAJET")):
        return "business_jet"
    return "jet"


def _register_dynamic_aircraft_model(model: str, source: str = "api", conn_existing: sqlite3.Connection | None = None) -> dict[str, Any]:
    display = str(model or "").strip()[:160]
    if not display or display in {"—", "-", "?"}:
        display = "Standard Flotte"
    key = re.sub(r"[^A-Za-z0-9]+", "_", display.upper()).strip("_")[:96] or "STANDARD_FLOTTE"
    category = _aircraft_category_for_name(display)
    up = display.upper()
    base = 850000.0
    if any(x in up for x in ("747", "777", "787", "A350", "A340")):
        base = 180000000.0
    elif any(x in up for x in ("737", "A320", "A321", "FENIX", "PMDG")):
        base = 82000000.0
    elif category == "business_jet":
        base = 18500000.0
    elif category == "propeller":
        base = 550000.0
    curve = {
        "engine_wear_per_hour": 0.85 if category == "propeller" else 1.15,
        "airframe_wear_per_landing": 0.35,
        "default_engine_health": 100,
        "default_airframe_condition": 100,
        "source": source,
    }
    conn = conn_existing or sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_dynamic_aircraft_registry(conn)
        conn.execute(
            """
            INSERT INTO global_aircraft_registry (
                model_key, display_name, category, base_price,
                maintenance_curve_json, created_ts, updated_ts
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(model_key) DO UPDATE SET
                display_name = excluded.display_name,
                category = excluded.category,
                base_price = excluded.base_price,
                maintenance_curve_json = excluded.maintenance_curve_json,
                updated_ts = excluded.updated_ts;
            """,
            (key, display, category, base, json.dumps(curve, ensure_ascii=False), time.time(), time.time()),
        )
        if conn_existing is None:
            conn.commit()
    finally:
        if conn_existing is None:
            conn.close()
    return {"model_key": key, "display_name": display, "category": category, "base_price": base}
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS push_outbox (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            hardware_id TEXT NOT NULL DEFAULT '',
            device_token TEXT NOT NULL DEFAULT '',
            title TEXT NOT NULL DEFAULT 'SkyTycoon',
            message TEXT NOT NULL,
            payload_json TEXT NOT NULL DEFAULT '{}',
            status TEXT NOT NULL DEFAULT 'queued',
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )


def _push_to_device(hid: str, message_de: str, message_en: str, payload: dict[str, Any] | None = None) -> None:
    payload = payload or {}
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        row = sconn.execute("SELECT device_token, locale FROM mobile_push_tokens WHERE hardware_id = ?;", (hid,)).fetchone()
        token = str(row[0] if row else "")
        locale = str(row[1] if row else "de").lower()
        msg = message_en if locale.startswith("en") else message_de
        sconn.execute(
            "INSERT INTO push_outbox (hardware_id, device_token, message, payload_json, status, created_ts) VALUES (?, ?, ?, ?, 'queued', ?);",
            (hid, token, msg, json.dumps(payload, ensure_ascii=False), time.time()),
        )
        sconn.commit()
    finally:
        sconn.close()
    push_url = (os.environ.get("SKYTYCOON_PUSH_ENDPOINT") or "").strip()
    if push_url and token:
        try:
            requests.post(push_url, json={"to": token, "title": "SkyTycoon", "message": msg, "payload": payload}, timeout=6)
        except requests.RequestException:
            pass


def _close_auction_locked(sconn: sqlite3.Connection, uconn: sqlite3.Connection, auction_id: int) -> dict[str, Any]:
    row = sconn.execute(
        """
        SELECT seller_hid, item_type, item_name, current_bid, highest_bidder_hid, status
        FROM auction_house WHERE auction_id = ?;
        """,
        (auction_id,),
    ).fetchone()
    if not row:
        return {"ok": False, "error": "not_found"}
    seller, item_type, item_name, amount, winner, status_s = row
    if str(status_s) != "active":
        return {"ok": False, "error": "not_active"}
    close_ts = time.time()
    if str(winner or "").strip() and float(amount or 0) > 0:
        aircraft = _register_dynamic_aircraft_model(str(item_name), "auction_close", sconn)
        asset_id = f"auction-{auction_id}-{int(close_ts * 1000)}"
        uconn.execute("UPDATE users SET credits = credits + ? WHERE hardware_id = ?;", (float(amount), str(seller)))
        sconn.execute(
            """
            INSERT OR REPLACE INTO cloud_hangar_assets (
                hardware_id, asset_id, aircraft_model, item_type, source, condition_pct, acquired_ts
            ) VALUES (?, ?, ?, ?, 'auction', 100, ?);
            """,
            (str(winner), asset_id, str(item_name), str(item_type), close_ts),
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO server_maintenance_log (
                hardware_id, aircraft_id, airframe_condition, engine_1_health, updated_at
            ) VALUES (?, ?, 100, 100, ?);
            """,
            (str(winner), str(item_name), datetime.fromtimestamp(close_ts, timezone.utc).isoformat()),
        )
        sconn.execute(
            """
            INSERT INTO auction_transfers (auction_id, seller_hid, winner_hid, item_type, item_name, amount, closed_ts)
            VALUES (?, ?, ?, ?, ?, ?, ?);
            """,
            (auction_id, str(seller), str(winner), str(item_type), str(item_name), float(amount), close_ts),
        )
    sconn.execute("UPDATE auction_house SET status = 'closed' WHERE auction_id = ?;", (auction_id,))
    return {"ok": True, "auction_id": auction_id, "winner_hid": str(winner or ""), "amount": float(amount or 0), "committed_transfer": "atomic_pending_commit"}


def _close_auction_atomic_millisecond(auction_id: int) -> dict[str, Any]:
    """Auktionsabschluss in einer SQLite-Transaktion mit ATTACH: Credits + Hangar im selben Commit."""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(conn)
        conn.execute("ATTACH DATABASE ? AS userdb;", (str(USER_DB_PATH),))
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT seller_hid, item_type, item_name, current_bid, highest_bidder_hid, status
            FROM auction_house WHERE auction_id = ?;
            """,
            (auction_id,),
        ).fetchone()
        if not row:
            conn.rollback()
            return {"ok": False, "error": "not_found"}
        seller, item_type, item_name, amount, winner, status_s = row
        if str(status_s) != "active":
            conn.rollback()
            return {"ok": False, "error": "not_active"}
        close_ts = time.time()
        if str(winner or "").strip() and float(amount or 0) > 0:
            _register_dynamic_aircraft_model(str(item_name), "auction_atomic_close", conn)
            asset_id = f"auction-{auction_id}-{int(close_ts * 1000)}"
            conn.execute("UPDATE userdb.users SET credits = credits + ? WHERE hardware_id = ?;", (float(amount), str(seller)))
            conn.execute(
                """
                INSERT OR REPLACE INTO cloud_hangar_assets (
                    hardware_id, asset_id, aircraft_model, item_type, source, condition_pct, acquired_ts
                ) VALUES (?, ?, ?, ?, 'auction', 100, ?);
                """,
                (str(winner), asset_id, str(item_name), str(item_type), close_ts),
            )
            conn.execute(
                """
                INSERT OR REPLACE INTO server_maintenance_log (
                    hardware_id, aircraft_id, airframe_condition, engine_1_health, updated_at
                ) VALUES (?, ?, 100, 100, ?);
                """,
                (str(winner), str(item_name), datetime.fromtimestamp(close_ts, timezone.utc).isoformat()),
            )
            conn.execute(
                """
                INSERT INTO auction_transfers (
                    auction_id, seller_hid, winner_hid, item_type, item_name, amount, closed_ts
                ) VALUES (?, ?, ?, ?, ?, ?, ?);
                """,
                (auction_id, str(seller), str(winner), str(item_type), str(item_name), float(amount), close_ts),
            )
        conn.execute("UPDATE auction_house SET status = 'closed' WHERE auction_id = ?;", (auction_id,))
        conn.commit()
        return {
            "ok": True,
            "auction_id": auction_id,
            "winner_hid": str(winner or ""),
            "amount": float(amount or 0),
            "commit_ts_ms": int(close_ts * 1000),
            "committed_transfer": "credits_and_hangar_same_sql_commit",
        }
    except sqlite3.Error as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        try:
            conn.execute("DETACH DATABASE userdb;")
        except sqlite3.Error:
            pass
        conn.close()


def _settle_expired_auctions() -> None:
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    ids: list[int] = []
    try:
        _ensure_auction_tables(sconn)
        ids = [int(r[0]) for r in sconn.execute("SELECT auction_id FROM auction_house WHERE status = 'active' AND end_ts_utc <= ?;", (time.time(),)).fetchall()]
    finally:
        sconn.close()
    for aid in ids:
        _close_auction_atomic_millisecond(aid)


@app.get("/api/v1/auctions/list")
def auctions_list(request: Request) -> JSONResponse:
    _settle_expired_auctions()
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        rows = sconn.execute(
            """
            SELECT auction_id, seller_hid, seller_name, item_type, item_name, condition_pct,
                   start_price, buyout_price, current_bid, highest_bidder_hid,
                   highest_bidder_name, end_ts_utc, status, created_ts
            FROM auction_house WHERE status = 'active' ORDER BY end_ts_utc ASC;
            """
        ).fetchall()
    finally:
        sconn.close()
    auctions = [
        {
            "auction_id": int(r[0]),
            "seller_hid": str(r[1]),
            "seller_name": str(r[2]),
            "item_type": str(r[3]),
            "item_name": str(r[4]),
            "condition_pct": float(r[5] or 0),
            "start_price": float(r[6] or 0),
            "buyout_price": float(r[7] or 0),
            "current_bid": float(r[8] or 0),
            "highest_bidder_hid": str(r[9] or ""),
            "highest_bidder_name": str(r[10] or ""),
            "end_ts_utc": float(r[11] or 0),
            "end_iso_utc": datetime.fromtimestamp(float(r[11] or 0), timezone.utc).isoformat(),
            "status": str(r[12]),
            "created_ts": float(r[13] or 0),
        }
        for r in rows
    ]
    return JSONResponse({"ok": True, "server_utc": time.time(), "auctions": auctions})


@app.post("/api/v1/auctions/create")
def auctions_create(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    item_name = str(body.get("item_name") or body.get("aircraft") or "SkyTycoon Asset").strip()[:120]
    item_type = str(body.get("item_type") or "aircraft").strip()[:40]
    start_price = max(1.0, float(body.get("start_price", 1000) or 1000))
    buyout = max(0.0, float(body.get("buyout_price", 0) or 0))
    hours = max(1.0, min(168.0, float(body.get("duration_hours", 24) or 24)))
    condition = max(0.0, min(100.0, float(body.get("condition_pct", 100) or 100)))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        _register_dynamic_aircraft_model(item_name, "auction_create", sconn)
        cur = sconn.execute(
            """
            INSERT INTO auction_house (
                seller_hid, seller_name, item_type, item_name, condition_pct,
                start_price, buyout_price, current_bid, end_ts_utc, status, created_ts
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, 'active', ?);
            """,
            (hid, _pilot_display_name_for_hid(hid), item_type, item_name, condition, start_price, buyout, time.time() + hours * 3600.0, time.time()),
        )
        auction_id = int(cur.lastrowid)
        sconn.commit()
    finally:
        sconn.close()
    return JSONResponse({"ok": True, "auction_id": auction_id})


@app.post("/api/v1/auctions/bid")
def auctions_bid(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    auction_id = int(body.get("auction_id", 0) or 0)
    amount = float(body.get("amount", 0) or 0)
    if auction_id <= 0 or amount <= 0:
        return JSONResponse({"ok": False, "error": "bad_bid"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    previous_hid = ""
    try:
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        uconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            "SELECT current_bid, highest_bidder_hid, end_ts_utc, status, item_name FROM auction_house WHERE auction_id = ?;",
            (auction_id,),
        ).fetchone()
        if not row or str(row[3]) != "active":
            sconn.rollback(); uconn.rollback()
            return JSONResponse({"ok": False, "error": "auction_not_active"}, status_code=400)
        current = float(row[0] or 0)
        previous_hid = str(row[1] or "")
        end_ts = float(row[2] or 0)
        item_name = str(row[4] or "Objekt")
        if amount <= current:
            sconn.rollback(); uconn.rollback()
            return JSONResponse({"ok": False, "error": "bid_too_low"}, status_code=400)
        credits = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
        if not credits or float(credits[0] or 0) + 1e-6 < amount:
            sconn.rollback(); uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (amount, hid))
        if previous_hid:
            uconn.execute("UPDATE users SET credits = credits + ? WHERE hardware_id = ?;", (current, previous_hid))
        if end_ts - time.time() <= 30:
            end_ts += 60
        sconn.execute(
            """
            UPDATE auction_house
            SET current_bid = ?, highest_bidder_hid = ?, highest_bidder_name = ?, end_ts_utc = ?
            WHERE auction_id = ?;
            """,
            (amount, hid, _pilot_display_name_for_hid(hid), end_ts, auction_id),
        )
        sconn.execute(
            "INSERT INTO auction_bids (auction_id, bidder_hid, bidder_name, amount, created_ts) VALUES (?, ?, ?, ?, ?);",
            (auction_id, hid, _pilot_display_name_for_hid(hid), amount, time.time()),
        )
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    if previous_hid and previous_hid != hid:
        _push_to_device(
            previous_hid,
            "🧑‍✈️ SkyTycoon: Achtung! Du wurdest bei der Auktion für das Objekt überboten!",
            "🧑‍✈️ SkyTycoon: Warning! You have been outbid on the auction item!",
            {"url": "https://skytycoon.info/market/auction_house", "auction_id": auction_id, "item_name": item_name},
        )
    return JSONResponse({"ok": True, "auction_id": auction_id, "amount": amount})


@app.post("/api/v1/auctions/cancel")
def auctions_cancel(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    auction_id = int(body.get("auction_id", 0) or 0)
    if auction_id <= 0:
        return JSONResponse({"ok": False, "error": "bad_auction"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            """
            SELECT seller_hid, item_type, item_name, current_bid, highest_bidder_hid, status
            FROM auction_house WHERE auction_id = ?;
            """,
            (auction_id,),
        ).fetchone()
        if not row:
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        seller, item_type, item_name, current_bid, highest_bidder, status_s = row
        if str(seller) != hid:
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "seller_only"}, status_code=403)
        if str(status_s) != "active":
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "not_active"}, status_code=400)
        if float(current_bid or 0) > 0 or str(highest_bidder or "").strip():
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "has_bids"}, status_code=409)
        ts = time.time()
        _register_dynamic_aircraft_model(str(item_name), "auction_cancel", sconn)
        sconn.execute("DELETE FROM auction_house WHERE auction_id = ?;", (auction_id,))
        sconn.execute("DELETE FROM auction_bids WHERE auction_id = ?;", (auction_id,))
        sconn.execute(
            """
            INSERT OR REPLACE INTO cloud_hangar_assets (
                hardware_id, asset_id, aircraft_model, item_type, source, condition_pct, acquired_ts
            ) VALUES (?, ?, ?, ?, 'auction_cancel', 100, ?);
            """,
            (hid, f"auction-return-{auction_id}-{int(ts * 1000)}", str(item_name), str(item_type), ts),
        )
        sconn.commit()
    except sqlite3.Error as exc:
        sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        sconn.close()
    return JSONResponse({"ok": True, "auction_id": auction_id, "returned_to_hangar": True})


@app.post("/api/v1/mobile/push/register")
def mobile_push_register(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    token = str(body.get("device_token") or "").strip()[:500]
    locale = str(body.get("locale") or "de").strip()[:8]
    platform = str(body.get("platform") or "").strip()[:40]
    if not token:
        return JSONResponse({"ok": False, "error": "missing_token"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        sconn.execute(
            """
            INSERT INTO mobile_push_tokens (hardware_id, device_token, locale, platform, updated_ts)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(hardware_id) DO UPDATE SET
                device_token = excluded.device_token,
                locale = excluded.locale,
                platform = excluded.platform,
                updated_ts = excluded.updated_ts;
            """,
            (hid, token, locale, platform, time.time()),
        )
        sconn.commit()
        try:
            uconn.execute("ALTER TABLE users ADD COLUMN device_token TEXT NOT NULL DEFAULT '';")
        except sqlite3.OperationalError:
            pass
        uconn.execute("UPDATE users SET device_token = ? WHERE hardware_id = ?;", (token, hid))
        uconn.commit()
    finally:
        sconn.close(); uconn.close()
    return JSONResponse({"ok": True})


@app.post("/api/v1/admin/push/broadcast")
def admin_push_broadcast(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    message = str(body.get("message") or "").strip()[:1000]
    if not message:
        return JSONResponse({"ok": False, "error": "missing_message"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        rows = sconn.execute("SELECT hardware_id, device_token FROM mobile_push_tokens;").fetchall()
        for hid, token in rows:
            sconn.execute(
                "INSERT INTO push_outbox (hardware_id, device_token, title, message, payload_json, status, created_ts) VALUES (?, ?, 'SkyTycoon', ?, ?, 'queued', ?);",
                (str(hid), str(token), message, json.dumps({"url": "https://skytycoon.info"}, ensure_ascii=False), time.time()),
            )
        sconn.commit()
    finally:
        sconn.close()
    try:
        discord_cmd_id =         _queue_discord_bot_command(
            "admin_broadcast",
            {
                "message": message,
                "source": "admin_commander",
                "severity": str(body.get("severity") or body.get("level") or "info").strip().lower()[:32],
                "created_ts": time.time(),
            },
        )
    except Exception as exc:  # noqa: BLE001
        discord_cmd_id = 0
        _server_log_line(f"[discord] admin broadcast queue failed: {exc!s}")
    return JSONResponse({"ok": True, "queued": len(rows), "discord_command_id": discord_cmd_id})


@app.get("/api/v1/admin/auctions/all")
def admin_auctions_all(request: Request, admin_password: str = "", admin_master_password: str = "") -> JSONResponse:
    if not _admin_auth_ok(request, body=None, query_admin_password=admin_password, query_admin_master_password=admin_master_password):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    data = auctions_list(request).body
    parsed = json.loads(data.decode("utf-8"))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        bids = {}
        for aid, bidder, amount, ts in sconn.execute("SELECT auction_id, bidder_name, amount, created_ts FROM auction_bids ORDER BY created_ts DESC;").fetchall():
            bids.setdefault(str(aid), []).append({"bidder": str(bidder), "amount": float(amount or 0), "ts": float(ts or 0)})
    finally:
        sconn.close()
    parsed["bid_history"] = bids
    return JSONResponse(parsed)


@app.post("/api/v1/admin/auctions/delete")
def admin_auctions_delete(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    auction_id = int(body.get("auction_id", 0) or 0)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE"); uconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute("SELECT highest_bidder_hid, current_bid FROM auction_house WHERE auction_id = ?;", (auction_id,)).fetchone()
        if row and str(row[0] or ""):
            uconn.execute("UPDATE users SET credits = credits + ? WHERE hardware_id = ?;", (float(row[1] or 0), str(row[0])))
        sconn.execute("DELETE FROM auction_house WHERE auction_id = ?;", (auction_id,))
        sconn.execute("DELETE FROM auction_bids WHERE auction_id = ?;", (auction_id,))
        uconn.commit(); sconn.commit()
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "auction_id": auction_id})


@app.post("/api/v1/admin/auctions/force_close")
def admin_auctions_force_close(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    auction_id = int(body.get("auction_id", 0) or 0)
    return JSONResponse(_close_auction_atomic_millisecond(auction_id))


def _next_midnight_utc_ts(now_ts: float | None = None) -> float:
    now = datetime.fromtimestamp(now_ts or time.time(), timezone.utc)
    nxt = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    return nxt.timestamp()


def _ensure_daily_market_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS daily_market (
            deal_id INTEGER PRIMARY KEY AUTOINCREMENT,
            market_day TEXT NOT NULL,
            item_type TEXT NOT NULL DEFAULT 'aircraft',
            item_name TEXT NOT NULL,
            category TEXT NOT NULL DEFAULT 'airliner',
            base_price REAL NOT NULL DEFAULT 0,
            price_credits REAL NOT NULL DEFAULT 0,
            trend_pct REAL NOT NULL DEFAULT 0,
            expires_ts_utc REAL NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'active',
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )


def _daily_aircraft_catalog() -> list[str]:
    return [
        "PMDG 737-800", "Fenix Airbus A320", "Asobo Boeing 747-8",
        "iniBuilds Airbus A310", "Working Title CJ4", "Cessna 172 Skyhawk",
        "DAHER TBM 930", "Airbus A330neo", "Boeing 787-10 Dreamliner",
        "Piper PA-28R Arrow III", "FlyByWire A32NX", "ATR 72-600",
    ]


def _generate_daily_market_if_needed(force: bool = False) -> None:
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_daily_market_tables(conn)
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        row = conn.execute("SELECT COUNT(*) FROM daily_market WHERE market_day = ? AND status = 'active';", (today,)).fetchone()
        if not force and int(row[0] or 0) > 0:
            return
        conn.execute("BEGIN IMMEDIATE")
        if force:
            conn.execute("UPDATE daily_market SET status = 'expired' WHERE status = 'active';")
        rng = random.Random(today)
        expires = _next_midnight_utc_ts()
        picks = rng.sample(_daily_aircraft_catalog(), k=6)
        for name in picks:
            reg = _register_dynamic_aircraft_model(name, "daily_market", conn)
            trend = round(rng.uniform(-20.0, 20.0), 2)
            price = round(float(reg["base_price"]) * (1.0 + trend / 100.0), 0)
            conn.execute(
                """
                INSERT INTO daily_market (
                    market_day, item_type, item_name, category, base_price,
                    price_credits, trend_pct, expires_ts_utc, status, created_ts
                ) VALUES (?, 'aircraft', ?, ?, ?, ?, ?, ?, 'active', ?);
                """,
                (today, name, reg["category"], float(reg["base_price"]), price, trend, expires, time.time()),
            )
        conn.commit()
    finally:
        conn.close()


async def _daily_market_midnight_loop() -> None:
    while True:
        try:
            _generate_daily_market_if_needed()
        except Exception as exc:
            try:
                _server_log_line(f"[daily_market] generation failed: {exc!s}")
            except Exception:
                pass
        await asyncio.sleep(max(30.0, min(3600.0, _next_midnight_utc_ts() - time.time() + 1.0)))


@app.on_event("startup")
async def _start_daily_market_background_task() -> None:
    try:
        _generate_daily_market_if_needed()
        asyncio.create_task(_daily_market_midnight_loop())
    except Exception:
        pass


def _web_pilot_credits_sqlite(hid: str) -> float:
    h64 = str(hid or "").strip()[:64]
    if not h64:
        return 0.0
    try:
        uconn = sqlite3.connect(str(USER_DB_PATH))
        try:
            row = uconn.execute(
                "SELECT credits FROM users WHERE hardware_id = ?;", (h64,)
            ).fetchone()
            return float(row[0] or 0) if row else 0.0
        finally:
            uconn.close()
    except sqlite3.Error:
        return 0.0


