@app.post("/api/v1/auctions/daily/buy")
def daily_auctions_buy(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    deal_id = int(body.get("deal_id", 0) or 0)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        _ensure_daily_market_tables(sconn)
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        uconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            "SELECT item_type, item_name, category, price_credits, status FROM daily_market WHERE deal_id = ?;",
            (deal_id,),
        ).fetchone()
        if not row or str(row[4]) != "active":
            sconn.rollback(); uconn.rollback()
            return JSONResponse({"ok": False, "error": "deal_not_active"}, status_code=400)
        item_type, item_name, category, price, _status = row
        price_f = float(price or 0)
        credits = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
        if not credits or float(credits[0] or 0) + 1e-6 < price_f:
            sconn.rollback(); uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        close_ts = time.time()
        asset_id = f"daily-{deal_id}-{int(close_ts * 1000)}"
        _register_dynamic_aircraft_model(str(item_name), "daily_buy", sconn)
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (price_f, hid))
        sconn.execute(
            """
            INSERT OR REPLACE INTO cloud_hangar_assets (
                hardware_id, asset_id, aircraft_model, item_type, source, condition_pct, acquired_ts
            ) VALUES (?, ?, ?, ?, 'daily_market', 100, ?);
            """,
            (hid, asset_id, str(item_name), str(item_type), close_ts),
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO server_maintenance_log (
                hardware_id, aircraft_id, airframe_condition, engine_1_health, updated_at
            ) VALUES (?, ?, 100, 100, ?);
            """,
            (hid, str(item_name), datetime.fromtimestamp(close_ts, timezone.utc).isoformat()),
        )
        sconn.execute("UPDATE daily_market SET status = 'sold' WHERE deal_id = ?;", (deal_id,))
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "deal_id": deal_id, "item_name": str(item_name), "price_credits": price_f, "asset_id": asset_id})


