@app.post("/api/v1/radar/cancel_flight")
def radar_cancel_flight(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    try:
        hid = _desktop_api_auth(request, body)
    except HTTPException:
        hid = _mmo_hid_from_request(request, body)
    hid = str(hid or body.get("hardware_id") or "").strip()[:64]
    if not hid:
        raise HTTPException(status_code=401, detail="auth_failed")
    body_pilot = str(body.get("pilot_name") or body.get("username") or body.get("pilot") or "").strip()[:120]
    pilot_name = body_pilot or _pilot_display_name_for_hid(hid)
    id_candidates = {hid, hid[:64], str(body.get("hardware_id") or "").strip()[:64]}
    name_candidates = {pilot_name, body_pilot, str(body.get("username") or "").strip()[:120]}
    id_candidates = {x for x in id_candidates if x}
    name_candidates = {x for x in name_candidates if x}
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        _ensure_auction_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS live_flights (
                username TEXT PRIMARY KEY,
                hardware_id TEXT NOT NULL DEFAULT '',
                route TEXT NOT NULL DEFAULT '',
                aircraft TEXT NOT NULL DEFAULT '',
                ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS radar_cancel_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                hardware_id TEXT NOT NULL DEFAULT '',
                pilot_name TEXT NOT NULL DEFAULT '',
                cancelled_ts REAL NOT NULL DEFAULT 0,
                source TEXT NOT NULL DEFAULT ''
            );
            """
        )
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS active_web_flightplans (
                hardware_id TEXT PRIMARY KEY,
                job_id INTEGER NOT NULL DEFAULT 0,
                route TEXT NOT NULL DEFAULT '',
                origin TEXT NOT NULL DEFAULT '',
                destination TEXT NOT NULL DEFAULT '',
                fuel_lbs REAL NOT NULL DEFAULT 0,
                weight_lbs REAL NOT NULL DEFAULT 0,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS radar_positions (
                hardware_id TEXT PRIMARY KEY,
                pilot_name TEXT NOT NULL DEFAULT '',
                lat REAL NOT NULL DEFAULT 0,
                lon REAL NOT NULL DEFAULT 0,
                alt REAL NOT NULL DEFAULT 0,
                hdg REAL NOT NULL DEFAULT 0,
                route TEXT NOT NULL DEFAULT '',
                aircraft TEXT NOT NULL DEFAULT '',
                ts REAL NOT NULL DEFAULT 0,
                flight_phase TEXT NOT NULL DEFAULT 'Unknown',
                ground_speed REAL NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'ONLINE',
                origin_icao TEXT NOT NULL DEFAULT '',
                destination_icao TEXT NOT NULL DEFAULT '',
                offline_start_ts REAL NOT NULL DEFAULT 0,
                last_online_ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        id_marks = ",".join("?" for _ in id_candidates)
        name_marks = ",".join("?" for _ in name_candidates)
        last = sconn.execute(
            f"""
            SELECT COALESCE(origin_icao, ''), COALESCE(route, ''), COALESCE(aircraft, '')
            FROM radar_positions
            WHERE hardware_id IN ({id_marks})
               OR substr(hardware_id, 1, 64) = ?
               OR lower(trim(coalesce(pilot_name, ''))) IN ({name_marks})
            LIMIT 1;
            """,
            tuple(id_candidates) + (hid,) + tuple(n.lower() for n in name_candidates),
        ).fetchone()
        route_hint = str(last[1] if last else "")
        route_icao = route_hint.replace("→", "-").split("-")[0].strip().upper()[:4] if route_hint else ""
        last_icao = str((last[0] if last else "") or route_icao or "EDDF").strip().upper()[:4]
        aircraft = str((last[2] if last else "") or "Standard Flotte").strip()[:160]
        sconn.execute(
            f"""
            DELETE FROM live_flights
            WHERE hardware_id IN ({id_marks})
               OR substr(hardware_id, 1, 64) = ?
               OR lower(trim(coalesce(username, ''))) IN ({name_marks});
            """,
            tuple(id_candidates) + (hid,) + tuple(n.lower() for n in name_candidates),
        )
        sconn.execute(
            f"""
            DELETE FROM radar_positions
            WHERE hardware_id IN ({id_marks})
               OR substr(hardware_id, 1, 64) = ?
               OR lower(trim(coalesce(pilot_name, ''))) IN ({name_marks});
            """,
            tuple(id_candidates) + (hid,) + tuple(n.lower() for n in name_candidates),
        )
        sconn.execute(
            f"""
            DELETE FROM active_web_flightplans
            WHERE hardware_id IN ({id_marks})
               OR substr(hardware_id, 1, 64) = ?;
            """,
            tuple(id_candidates) + (hid,),
        )
        sconn.execute(
            f"""
            UPDATE cloud_hangar_assets
            SET status = 'PARKED', current_location = ?
            WHERE hardware_id IN ({id_marks}) AND (aircraft_model = ? OR ? = 'Standard Flotte');
            """,
            (last_icao, *tuple(id_candidates), aircraft, aircraft),
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO aircraft_persist_state (
                hardware_id, aircraft_model, fuel_gallons, gate_icao, gate_label, lat, lon, updated_ts
            ) VALUES (?, ?, 0, ?, 'PARKED', NULL, NULL, ?);
            """,
            (hid, aircraft, last_icao, time.time()),
        )
        sconn.execute(
            """
            INSERT INTO radar_cancel_log (hardware_id, pilot_name, cancelled_ts, source)
            VALUES (?, ?, ?, ?);
            """,
            (hid, pilot_name, time.time(), str(body.get("source") or "unknown")[:40]),
        )
        for alt in (
            "ALTER TABLE users ADD COLUMN active_ofp TEXT DEFAULT NULL;",
            "ALTER TABLE users ADD COLUMN route_sync INTEGER NOT NULL DEFAULT 0;",
        ):
            try:
                uconn.execute(alt)
            except sqlite3.OperationalError:
                pass
        uconn.execute("UPDATE users SET active_ofp = NULL, route_sync = 0 WHERE hardware_id = ?;", (hid,))
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "status": "cancelled", "hardware_id": hid, "pilot_name": pilot_name, "parked_at": last_icao})


@app.get("/api/v1/admin/stresstest/status")
def admin_stresstest_status(
    request: Request,
    admin_master_password: str = "",
    admin_password: str = "",
) -> JSONResponse:
    if not _admin_auth_ok(
        request,
        body=None,
        query_admin_password=admin_password,
        query_admin_master_password=admin_master_password,
    ):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    if not callable(get_load_injector_status):
        raise HTTPException(status_code=503, detail="load_injector_unavailable")
    st = get_load_injector_status()
    st["cpu_cap_percent"] = 85.0
    st["reserve_percent"] = 15.0
    st["update_buffer_percent"] = 5.0
    st["brake_label_de"] = (
        "Adaptive CPU-Bremse: Riegel aktiv bei 85% | 15% Puffer gesichert für Live-Updates"
        if st.get("brake_active")
        else "Adaptive CPU-Bremse: Ziel 15–20% Last | Max. 85% Hard-Cap"
    )
    st["brake_label_en"] = (
        "Adaptive CPU brake: cap at 85% | 15% buffer reserved for live updates"
        if st.get("brake_active")
        else "Adaptive CPU brake: target 15–20% load | 85% hard cap"
    )
    return JSONResponse(st)


@app.post("/api/v1/admin/stresstest/toggle")
async def admin_stresstest_toggle(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    if not _admin_auth_ok(request, body=body if isinstance(body, dict) else {}):
        raise HTTPException(status_code=403, detail="admin_auth_failed")
    if not callable(start_load_injector) or not callable(stop_load_injector):
        raise HTTPException(status_code=503, detail="load_injector_unavailable")
    payload = body if isinstance(body, dict) else {}
    want_on = bool(payload.get("enabled"))
    if payload.get("toggle") and not payload.get("enabled") is False:
        cur = get_load_injector_status()
        want_on = not bool(cur.get("enabled"))
    if want_on:
        out = await start_load_injector(
            conn_factory=get_db_connection,
            persist_fn=_persist_live_flight_postgres,
            route_distance_fn=_custom_route_distance_nm,
            route_rewards_fn=_custom_route_rewards,
        )
        return JSONResponse({"ok": True, "enabled": True, **out})
    out = await stop_load_injector(conn_factory=get_db_connection)
    return JSONResponse({"ok": True, "enabled": False, **out})


