def _regenerate_parts_market_midnight() -> int:
    return _regenerate_cloud_scrapyard_market(300)


async def _parts_market_midnight_loop() -> None:
    while True:
        now = datetime.now(timezone.utc)
        nxt = (now + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
        await asyncio.sleep(max(30.0, (nxt - now).total_seconds() + 1.0))
        try:
            await asyncio.to_thread(_regenerate_parts_market_midnight)
        except Exception as exc:
            try:
                _server_log_line(f"[parts_market] midnight refresh failed: {exc!s}")
            except Exception:
                pass


@app.on_event("startup")
async def _start_parts_market_midnight_task() -> None:
    try:
        asyncio.create_task(_parts_market_midnight_loop())
    except Exception:
        pass


