@app.get("/api/v1/fleet/hangar")
def fleet_hangar_list(request: Request, hardware_id: str = "") -> JSONResponse:
    """PostgreSQL-Flotte für Desktop-Hangar (12 Wartungs-Kacheln pro Flugzeug)."""
    hid = str(hardware_id or request.headers.get("X-Hardware-Id") or "").strip()[:128]
    conn = get_db_connection()
    rows: list[dict[str, Any]] = []
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            if hid:
                cur.execute(
                    """
                    SELECT id, aircraft_id, owner_username, aircraft_model, status, current_location
                    FROM fleet
                    WHERE lower(coalesce(owner_username, '')) = lower(%s)
                       OR owner_username IS NULL OR trim(owner_username) = ''
                    ORDER BY id ASC;
                    """,
                    (hid,),
                )
            else:
                cur.execute(
                    """
                    SELECT id, aircraft_id, owner_username, aircraft_model, status, current_location
                    FROM fleet
                    ORDER BY id ASC
                    LIMIT 500;
                    """
                )
            for r in cur.fetchall() or []:
                rows.append(
                    {
                        "id": int(r["id"] or 0),
                        "aircraft_id": int(r["aircraft_id"] or r["id"] or 0),
                        "owner_username": str(r["owner_username"] or ""),
                        "aircraft_model": str(r["aircraft_model"] or "Standard Flotte"),
                        "status": str(r["status"] or "PARKED"),
                        "current_location": str(r["current_location"] or ""),
                    }
                )
        conn.commit()
    finally:
        conn.close()
    if not rows:
        rows = [
            {
                "id": 0,
                "aircraft_id": 0,
                "owner_username": hid or "",
                "aircraft_model": "Standard Flotte",
                "status": "PARKED",
                "current_location": "EDDF",
            }
        ]
    return JSONResponse({"ok": True, "fleet": rows, "hardware_id": hid})


@app.get("/api/v1/hangar/maintenance/status")
def hangar_maintenance_status(
    request: Request,
    aircraft_id: str = "",
    hardware_id: str = "",
) -> JSONResponse:
    hid = str(hardware_id or request.headers.get("X-Hardware-Id") or "").strip()[:128]
    ac = str(aircraft_id or "Standard Flotte").strip()[:160] or "Standard Flotte"
    catalog = {p["key"]: p for p in _professional_maintenance_catalog()}
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    out: list[dict[str, Any]] = []
    try:
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS hangar_maintenance_positions (
                hardware_id TEXT NOT NULL,
                aircraft_id TEXT NOT NULL,
                maintenance_key TEXT NOT NULL,
                status_value REAL NOT NULL DEFAULT 100,
                last_service_ts REAL NOT NULL DEFAULT 0,
                PRIMARY KEY(hardware_id, aircraft_id, maintenance_key)
            );
            """
        )
        for key, pos in catalog.items():
            row = sconn.execute(
                """
                SELECT status_value, last_service_ts FROM hangar_maintenance_positions
                WHERE hardware_id = ? AND aircraft_id = ? AND maintenance_key = ?;
                """,
                (hid or "local", ac, key),
            ).fetchone()
            sv = float(row[0]) if row else 72.0
            out.append(
                {
                    "key": key,
                    "status_value": sv,
                    "last_service_ts": float(row[1]) if row else 0.0,
                    "de": pos.get("de"),
                    "en": pos.get("en"),
                    "price": pos.get("price"),
                }
            )
        sconn.commit()
    finally:
        sconn.close()
    return JSONResponse({"ok": True, "aircraft_id": ac, "positions": out})


@app.post("/api/v1/hangar/maintenance/execute")
def hangar_maintenance_execute(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _mmo_hid_from_request(request, body)
    key = str(body.get("maintenance_key") or body.get("key") or "daily_check").strip()[:80]
    aircraft_id = str(body.get("aircraft_id") or body.get("aircraft_model") or "Standard Flotte").strip()[:160]
    catalog = {p["key"]: p for p in _professional_maintenance_catalog()}
    pos = catalog.get(key)
    if not pos:
        return JSONResponse({"ok": False, "error": "unknown_maintenance"}, status_code=400)
    cost = float(pos["price"])
    uconn = sqlite3.connect(str(USER_DB_PATH))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        uconn.execute("BEGIN IMMEDIATE")
        sconn.execute("BEGIN IMMEDIATE")
        row = uconn.execute("SELECT credits FROM users WHERE hardware_id = ?;", (hid,)).fetchone()
        if not row or float(row[0] or 0) + 1e-6 < cost:
            uconn.rollback(); sconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        now_iso = datetime.now(timezone.utc).isoformat()
        uconn.execute("UPDATE users SET credits = credits - ? WHERE hardware_id = ?;", (cost, hid))
        _register_dynamic_aircraft_model(aircraft_id, "maintenance_execute", sconn)
        sconn.execute(
            """
            INSERT OR REPLACE INTO server_maintenance_log (
                hardware_id, aircraft_id, airframe_condition, engine_1_health, updated_at
            ) VALUES (?, ?, 100, 100, ?);
            """,
            (hid, aircraft_id, now_iso),
        )
        sconn.execute(
            """
            CREATE TABLE IF NOT EXISTS hangar_maintenance_positions (
                hardware_id TEXT NOT NULL,
                aircraft_id TEXT NOT NULL,
                maintenance_key TEXT NOT NULL,
                status_value REAL NOT NULL DEFAULT 100,
                last_service_ts REAL NOT NULL DEFAULT 0,
                PRIMARY KEY(hardware_id, aircraft_id, maintenance_key)
            );
            """
        )
        sconn.execute(
            """
            INSERT OR REPLACE INTO hangar_maintenance_positions (
                hardware_id, aircraft_id, maintenance_key, status_value, last_service_ts
            ) VALUES (?, ?, ?, 100, ?);
            """,
            (hid, aircraft_id, key, time.time()),
        )
        uconn.commit(); sconn.commit()
    except sqlite3.Error as exc:
        uconn.rollback(); sconn.rollback()
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        uconn.close(); sconn.close()
    return JSONResponse({"ok": True, "maintenance_key": key, "aircraft_id": aircraft_id, "cost_credits": cost, "status_value": 100})


def _ensure_active_flights_pg(conn) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS active_flights (
                hardware_id VARCHAR(128) PRIMARY KEY,
                job_id INTEGER NOT NULL DEFAULT 0,
                dep_icao VARCHAR(8) NOT NULL DEFAULT '',
                arr_icao VARCHAR(8) NOT NULL DEFAULT '',
                routing_provider VARCHAR(32) NOT NULL DEFAULT 'simbrief',
                use_sky_dispatch INTEGER NOT NULL DEFAULT 0,
                aircraft_model TEXT NOT NULL DEFAULT '',
                fleet_aircraft_id INTEGER NOT NULL DEFAULT 0,
                updated_ts DOUBLE PRECISION NOT NULL DEFAULT 0,
                is_custom_route INTEGER NOT NULL DEFAULT 0,
                planned_credits DOUBLE PRECISION NOT NULL DEFAULT 0,
                planned_xp DOUBLE PRECISION NOT NULL DEFAULT 0,
                planned_distance_nm DOUBLE PRECISION NOT NULL DEFAULT 0
            );
            """
        )
        for stmt in (
            "ALTER TABLE active_flights ADD COLUMN IF NOT EXISTS is_custom_route INTEGER NOT NULL DEFAULT 0;",
            "ALTER TABLE active_flights ADD COLUMN IF NOT EXISTS planned_credits DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE active_flights ADD COLUMN IF NOT EXISTS planned_xp DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE active_flights ADD COLUMN IF NOT EXISTS planned_distance_nm DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE active_flights ADD COLUMN IF NOT EXISTS flight_config_json TEXT NOT NULL DEFAULT '{}';",
        ):
            try:
                cur.execute(stmt)
            except psycopg2.Error:
                conn.rollback()
    conn.commit()


def _persist_active_flight_pg(
    conn,
    hardware_id: str,
    *,
    job_id: int,
    dep_icao: str,
    arr_icao: str,
    routing_provider: str,
    aircraft_model: str = "",
    fleet_aircraft_id: int = 0,
    is_custom_route: int = 0,
    planned_credits: float = 0.0,
    planned_xp: float = 0.0,
    planned_distance_nm: float = 0.0,
    flight_config: dict[str, Any] | None = None,
) -> None:
    _ensure_active_flights_pg(conn)
    rp = str(routing_provider or "simbrief").strip().lower()[:32]
    use_sd = 1 if rp in ("sky_dispatch", "skytycoon", "skytycoon_dispatch") else 0
    cfg_json = json.dumps(flight_config or {}, ensure_ascii=False)[:8000]
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO active_flights (
                hardware_id, job_id, dep_icao, arr_icao,
                routing_provider, use_sky_dispatch, aircraft_model,
                fleet_aircraft_id, updated_ts,
                is_custom_route, planned_credits, planned_xp, planned_distance_nm,
                flight_config_json
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT (hardware_id) DO UPDATE SET
                job_id = EXCLUDED.job_id,
                dep_icao = EXCLUDED.dep_icao,
                arr_icao = EXCLUDED.arr_icao,
                routing_provider = EXCLUDED.routing_provider,
                use_sky_dispatch = EXCLUDED.use_sky_dispatch,
                aircraft_model = EXCLUDED.aircraft_model,
                fleet_aircraft_id = EXCLUDED.fleet_aircraft_id,
                updated_ts = EXCLUDED.updated_ts,
                is_custom_route = EXCLUDED.is_custom_route,
                planned_credits = EXCLUDED.planned_credits,
                planned_xp = EXCLUDED.planned_xp,
                planned_distance_nm = EXCLUDED.planned_distance_nm,
                flight_config_json = EXCLUDED.flight_config_json;
            """,
            (
                str(hardware_id)[:128],
                int(job_id),
                str(dep_icao or "")[:8].upper(),
                str(arr_icao or "")[:8].upper(),
                rp,
                use_sd,
                str(aircraft_model or "")[:120],
                int(fleet_aircraft_id or 0),
                time.time(),
                int(is_custom_route or 0),
                float(planned_credits or 0),
                float(planned_xp or 0),
                float(planned_distance_nm or 0),
                cfg_json,
            ),
        )
    conn.commit()


def _flight_settings_from_body(body: dict[str, Any]) -> dict[str, Any]:
    """Flugmodus-Pop-out → verriegeltes JSON für active_flights."""
    pax_mode = body.get("pax_mode") in (True, 1, "1", "true", "yes")
    ferry = body.get("ferry_mode") in (True, 1, "1", "true", "yes")
    if not pax_mode and not ferry:
        pax_mode = str(body.get("flight_mode") or "").strip().lower() in (
            "pax",
            "passenger",
            "passenger_live",
            "live",
        )
    return {
        "pax_mode": bool(pax_mode),
        "ferry_mode": bool(ferry) or not bool(pax_mode),
        "clean_cabin": body.get("clean_cabin") in (True, 1, "1", "true", "yes"),
        "belly_cargo": body.get("belly_cargo") in (True, 1, "1", "true", "yes"),
        "hazard_weather": body.get("hazard_weather") in (True, 1, "1", "true", "yes"),
        "vip_flight": body.get("vip_flight") in (True, 1, "1", "true", "yes"),
        "eco_wear": body.get("eco_wear") in (True, 1, "1", "true", "yes"),
    }


def _apply_flight_settings_rewards(
    rewards: dict[str, Any], settings: dict[str, Any]
) -> dict[str, Any]:
    out = dict(rewards)
    cr_b = float(out.get("credits_base") or out.get("credits") or 0)
    xp_b = float(out.get("xp_miles_base") or out.get("xp") or 0)
    cr_bonus = float(out.get("credits_with_bonus") or cr_b)
    xp_bonus = float(out.get("xp_miles_with_bonus") or xp_b)
    mult = 1.0
    if settings.get("pax_mode"):
        mult *= 1.25
    if settings.get("hazard_weather"):
        mult *= 1.30
    if settings.get("belly_cargo"):
        mult *= 1.15
    if settings.get("vip_flight"):
        mult *= 3.0
    cr_adj = cr_b * mult
    xp_adj = xp_b * mult
    out["credits_base"] = round(cr_b, 2)
    out["xp_miles_base"] = round(xp_b, 2)
    out["credits_with_bonus"] = round(max(cr_bonus, cr_adj), 2)
    out["xp_miles_with_bonus"] = round(max(xp_bonus, xp_adj), 2)
    out["flight_settings"] = settings
    return out


def _active_custom_route_plan(hardware_id: str) -> dict[str, Any] | None:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return None
    conn = get_db_connection()
    try:
        _ensure_active_flights_pg(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT dep_icao, arr_icao, planned_credits, planned_xp, planned_distance_nm,
                       is_custom_route, routing_provider
                FROM active_flights WHERE hardware_id = %s LIMIT 1;
                """,
                (hid,),
            )
            row = cur.fetchone()
        if not row or int(row.get("is_custom_route") or 0) != 1:
            return None
        return dict(row)
    except psycopg2.Error:
        return None
    finally:
        conn.close()


def _clear_custom_route_plan_pg(hardware_id: str) -> None:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return
    conn = get_db_connection()
    try:
        _ensure_active_flights_pg(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE active_flights SET
                    is_custom_route = 0,
                    planned_credits = 0,
                    planned_xp = 0,
                    planned_distance_nm = 0
                WHERE hardware_id = %s;
                """,
                (hid,),
            )
        conn.commit()
    except psycopg2.Error:
        conn.rollback()
    finally:
        conn.close()


def _routing_provider_bonus_multiplier(hardware_id: str) -> float:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return 1.0
    conn = get_db_connection()
    try:
        _ensure_active_flights_pg(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT routing_provider, use_sky_dispatch
                FROM active_flights WHERE hardware_id = %s LIMIT 1;
                """,
                (hid,),
            )
            row = cur.fetchone()
        if not row:
            return 1.0
        rp = str(row[0] if not isinstance(row, dict) else row.get("routing_provider") or "")
        use_sd = int(row[1] if not isinstance(row, dict) else row.get("use_sky_dispatch") or 0)
        if use_sd == 1 or rp in ("sky_dispatch", "skytycoon", "skytycoon_dispatch"):
            return 1.15
    except psycopg2.Error:
        pass
    finally:
        conn.close()
    return 1.0


def _active_flight_prefill_for_hid(hardware_id: str) -> dict[str, Any]:
    hid = str(hardware_id or "").strip()[:128]
    out: dict[str, Any] = {
        "locked": False,
        "free_mode": True,
        "dep_icao": "EDDF",
        "arr_icao": "LEPA",
        "job_id": 0,
    }
    if not hid:
        return out
    conn = get_db_connection()
    try:
        _ensure_active_flights_pg(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT job_id, dep_icao, arr_icao, routing_provider
                FROM active_flights WHERE hardware_id = %s LIMIT 1;
                """,
                (hid,),
            )
            row = cur.fetchone()
        if row and str(row.get("dep_icao") or "").strip():
            out = {
                "locked": True,
                "dep_icao": str(row["dep_icao"] or "").upper()[:4],
                "arr_icao": str(row["arr_icao"] or "").upper()[:4],
                "job_id": int(row["job_id"] or 0),
                "routing_provider": str(row["routing_provider"] or "simbrief"),
            }
            out["free_mode"] = False
            return out
    except psycopg2.Error:
        pass
    finally:
        conn.close()
    conn_s = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn_s.execute(
            """
            SELECT origin, destination, job_id, payload_json
            FROM active_web_flightplans WHERE hardware_id = ? LIMIT 1;
            """,
            (hid[:64],),
        ).fetchone()
        if row:
            dep = str(row[0] or "").upper()[:4]
            arr = str(row[1] or "").upper()[:4]
            if dep and arr:
                out = {
                    "locked": True,
                    "dep_icao": dep,
                    "arr_icao": arr,
                    "job_id": int(row[2] or 0),
                    "routing_provider": "simbrief",
                }
                try:
                    pl = json.loads(str(row[3] or "{}"))
                    out["routing_provider"] = str(pl.get("routing_provider") or "simbrief")
                except json.JSONDecodeError:
                    pass
                out["free_mode"] = False
    finally:
        conn_s.close()
    return out


@app.get("/market/sky_dispatch", response_class=HTMLResponse, response_model=None)
async def web_sky_dispatch(request: Request) -> HTMLResponse:
    """SkyTycoon Dispatch Core — autonomous flight planning (module 22)."""
    import sky_dispatch_engine as dispatch_eng

    cycle = dispatch_eng.get_active_airac_cycle()
    hid, _ = _web_postgres_session_refresh(request)
    if not hid:
        hid = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if hid:
        _pg_maybe_release_gsx_if_idle(hid)
    prefill = _active_flight_prefill_for_hid(hid)
    if not prefill.get("locked"):
        prefill["free_mode"] = True
    msfs = str(request.query_params.get("mode") or "").lower() == "msfs_panel"
    return _web_page_html(
        "market/sky_dispatch.html",
        request,
        airac_cycle=cycle,
        dispatch_prefill=prefill,
        msfs_panel=msfs,
        dispatch_free_mode=bool(prefill.get("free_mode")),
    )


@app.post("/api/v1/dispatch/calculate")
async def api_dispatch_calculate(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """A* route + B738 block fuel; persists OFP to PostgreSQL sky_ofps."""
    import sky_dispatch_engine as dispatch_eng

    lang = _web_lang(request)
    dep = str(
        body.get("dep_icao") or body.get("origin") or body.get("dep") or ""
    ).strip().upper()[:4]
    arr = str(
        body.get("arr_icao") or body.get("destination") or body.get("arr") or ""
    ).strip().upper()[:4]
    try:
        pax = int(body.get("passengers") or body.get("pax") or 78)
    except (TypeError, ValueError):
        pax = 78
    if not dep or not arr:
        return JSONResponse(
            {
                "ok": False,
                "detail": "ICAO required"
                if lang.startswith("en")
                else "ICAO erforderlich",
            },
            status_code=400,
        )
    aircraft_model = str(body.get("aircraft_model") or body.get("fleet_model") or "")
    plan = dispatch_eng.calculate_flight_plan(
        dep, arr, pax, aircraft_model=aircraft_model, lang=lang
    )
    if not plan.get("ok"):
        err = str(plan.get("error") or "fail")
        msgs = {
            "de": {
                "no_route": "Keine Route gefunden.",
                "unknown_dep": f"Unbekannter Abflug: {plan.get('icao', dep)}",
                "unknown_arr": f"Unbekannte Ankunft: {plan.get('icao', arr)}",
            },
            "en": {
                "no_route": "No route found.",
                "unknown_dep": f"Unknown departure: {plan.get('icao', dep)}",
                "unknown_arr": f"Unknown arrival: {plan.get('icao', arr)}",
            },
        }
        table = msgs["en"] if lang.startswith("en") else msgs["de"]
        return JSONResponse(
            {"ok": False, "error": err, "detail": table.get(err, err)},
            status_code=404 if err in ("no_route", "unknown_dep", "unknown_arr") else 400,
        )
    hid, _ = _web_postgres_session_refresh(request)
    if not hid:
        hid = str(body.get("hardware_id") or "web_guest")[:128]
    pilot = str(body.get("username") or body.get("pilot_name") or "").strip()[:80]
    if not pilot:
        pilot = _pilot_display_name_for_hid(hid[:64]) if hid else "Pilot"
    conn = get_db_connection()
    try:
        ofp_id = dispatch_eng.persist_ofp_pg(
            conn,
            hardware_id=hid,
            username=pilot,
            plan=plan,
        )
        try:
            _archive_ofp_history_pg(
                conn, hardware_id=hid, username=pilot, plan=plan
            )
        except Exception:
            pass
        conn.commit()
    finally:
        conn.close()
    plan["ofp_id"] = ofp_id
    if plan.get("ok"):
        plan["passenger_manifest"] = _build_passenger_manifest(
            int(plan.get("passengers") or 78),
            str(plan.get("aircraft_model") or ""),
            lang,
        )
        wps = plan.get("waypoints") or []
        if isinstance(wps, list):
            plan["enroute_alternates"] = _enroute_alternates_for_path(
                [str(x) for x in wps]
            )
    return JSONResponse(plan)


@app.post("/api/v1/dispatch/calculate_custom_route")
async def api_dispatch_calculate_custom_route(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """Freie Charter-Route: Distanz (NM), Credits & XP (Vorschau inkl. +15 % Dispatch-Bonus)."""
    body = body if isinstance(body, dict) else {}
    lang = _api_lang_from_request(request, body)
    try:
        dep = str(
            body.get("dep_icao") or body.get("origin") or body.get("dep") or ""
        ).strip().upper()[:4]
        arr = str(
            body.get("arr_icao") or body.get("destination") or body.get("arr") or ""
        ).strip().upper()[:4]
        if not dep or not arr:
            return JSONResponse(
                {
                    "ok": False,
                    "detail": "ICAO required"
                    if lang.startswith("en")
                    else "ICAO erforderlich",
                },
                status_code=400,
            )
        try:
            pax = int(body.get("passengers") or body.get("pax") or 78)
        except (TypeError, ValueError):
            pax = 78
        aircraft_model = str(
            body.get("aircraft_model") or body.get("fleet_model") or "B738"
        )[:120]
        dist_nm, path, route_mode = _custom_route_distance_nm(dep, arr)
        if dist_nm <= 0.0 or route_mode == "unknown":
            return JSONResponse(
                {
                    "ok": False,
                    "error": "unknown_icao",
                    "detail": (
                        f"Unknown ICAO (not in AIRAC database): {dep}/{arr}"
                        if lang.startswith("en")
                        else f"Unbekannter ICAO (nicht in AIRAC-Datenbank): {dep}/{arr}"
                    ),
                },
                status_code=404,
            )
        rewards = _custom_route_rewards(
            dist_nm, aircraft_model=aircraft_model, passengers=pax, dep=dep, arr=arr
        )
        coords_map = _icao_coord_map()
        map_coords: list[list[float]] = []
        for wp in path:
            if wp in coords_map:
                map_coords.append([coords_map[wp][0], coords_map[wp][1]])
        if len(map_coords) < 2 and dep in coords_map and arr in coords_map:
            map_coords = [list(coords_map[dep]), list(coords_map[arr])]
        plan_extra: dict[str, Any] = {"map_coords": map_coords}
        if str(body.get("include_full_plan") or "").strip().lower() in (
            "1",
            "true",
            "yes",
        ):
            try:
                import sky_dispatch_engine as dispatch_eng

                full = dispatch_eng.calculate_flight_plan(
                    dep, arr, pax, aircraft_model=aircraft_model, lang=lang
                )
                if full.get("ok"):
                    plan_extra = {
                        "wind_matrix": full.get("wind_matrix"),
                        "runway_wind": full.get("runway_wind"),
                        "runways": full.get("runways"),
                        "map_coords": full.get("map_coords") or map_coords,
                        "alternate": full.get("alternate"),
                        "alternate_coords": full.get("alternate_coords"),
                    }
            except Exception as exc_plan:  # noqa: BLE001
                _server_log_line(f"[dispatch] charter full plan skipped: {exc_plan!s}")
        enroute_alts = _enroute_alternates_for_path(path)
        manifest = _build_passenger_manifest(pax, aircraft_model, lang)
        cr_base = float(rewards["credits_base"])
        xp_base = float(rewards["xp_miles_base"])
        cr_bonus = float(rewards["credits_with_bonus"])
        xp_bonus = float(rewards["xp_miles_with_bonus"])
        return JSONResponse(
            {
                "ok": True,
                "dep_icao": dep,
                "arr_icao": arr,
                "distance_nm": round(dist_nm, 1),
                "route_mode": route_mode,
                "waypoints": path,
                "passengers": pax,
                "aircraft_model": aircraft_model,
                "credits": cr_base,
                "xp": xp_base,
                "xp_miles": xp_base,
                "credits_with_bonus": cr_bonus,
                "xp_miles_with_bonus": xp_bonus,
                "xp_with_bonus": xp_bonus,
                "dispatch_bonus_pct": rewards["dispatch_bonus_pct"],
                "platin_bonus_pct": rewards["dispatch_bonus_pct"],
                "enroute_alternates": enroute_alts,
                "passenger_manifest": manifest,
                **rewards,
                **plan_extra,
                "popular_routes": _popular_routes_json(10),
            }
        )
    except Exception as exc:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[dispatch] calculate_custom_route failed: {exc!s}")
        return _sky_json_error_response(
            request,
            "generic",
            status_code=503,
            extra={
                "ok": False,
                "error": "server_error",
                "detail": (
                    "Charter calculation failed."
                    if lang.startswith("en")
                    else "Charter-Berechnung fehlgeschlagen."
                ),
            },
        )


def _build_passenger_manifest(
    pax: int, aircraft_model: str, lang: str = "de"
) -> dict[str, Any]:
    de = lang.startswith("de")
    rng = random.Random(int(time.time()) // 3600 + pax)
    first_de = ["Max", "Anna", "Lukas", "Sophie", "Tim", "Laura", "Felix", "Mia"]
    last_de = ["Müller", "Schmidt", "Weber", "Fischer", "Wagner", "Becker"]
    first_en = ["John", "Emma", "Oliver", "Sophia", "Liam", "Ava", "Noah", "Mia"]
    last_en = ["Smith", "Johnson", "Brown", "Davis", "Wilson", "Moore"]
    pax_n = max(0, min(400, int(pax or 0)))
    pax_rows: list[dict[str, str]] = []
    for i in range(min(pax_n, 48)):
        if de:
            name = f"{rng.choice(first_de)} {rng.choice(last_de)}"
        else:
            name = f"{rng.choice(first_en)} {rng.choice(last_en)}"
        row_n = (i // 6) + 1
        seat = f"{row_n}{chr(65 + (i % 6))}"
        pax_rows.append({"name": name, "seat": seat, "class": "Y"})
    cargo_kg = pax_n * 20
    return {
        "title": "Passagier-Manifest" if de else "Passenger manifest",
        "aircraft_model": aircraft_model or "—",
        "pax_count": pax_n,
        "passengers": pax_rows,
        "cargo_kg": cargo_kg,
        "baggage_kg": pax_n * 15,
    }


@app.post("/api/v1/dispatch/activate_flight")
async def api_dispatch_activate_flight(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """Charter scharfschalten inkl. Flugmodus-Matrix (PostgreSQL, flight_config_json)."""
    body = body if isinstance(body, dict) else {}
    settings = _flight_settings_from_body(body)
    body = dict(body)
    body["pax_mode"] = settings.get("pax_mode")
    body["ferry_mode"] = settings.get("ferry_mode")
    resp = await api_dispatch_dispatch_custom_route(request, body)
    if resp.status_code != 200:
        return resp
    try:
        payload = json.loads(resp.body.decode("utf-8"))
    except (AttributeError, json.JSONDecodeError, UnicodeDecodeError):
        return resp
    if not payload.get("ok"):
        return resp
    hid = str(body.get("hardware_id") or "")[:128]
    if not hid:
        try:
            hid = _desktop_api_auth(request, body)[:128]
        except HTTPException:
            hid = ""
    if hid and settings.get("clean_cabin"):
        pool = _get_pg_pool()
        if pool is not None:
            conn = pool.getconn()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE users SET credits = GREATEST(0, COALESCE(credits, 0) - 850)
                        WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s;
                        """,
                        (hid, hid[:64]),
                    )
                conn.commit()
            except Exception as exc_cl:  # noqa: BLE001
                _pg_rollback(conn)
                _server_log_line(f"[dispatch] clean_cabin debit: {exc_cl!s}")
            finally:
                pool.putconn(conn)
    payload["flight_settings"] = settings
    payload["pax_mode"] = settings.get("pax_mode")
    payload["gsx_auto_requested"] = bool(
        settings.get("pax_mode") or settings.get("vip_flight")
    )
    return JSONResponse(payload)


@app.post("/api/v1/dispatch/dispatch_custom_route")
async def api_dispatch_dispatch_custom_route(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """Charter-Flug scharfschalten: active_flights + route_statistics (PostgreSQL)."""
    body = body if isinstance(body, dict) else {}
    lang = _api_lang_from_request(request, body)
    try:
        hid_raw = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
        hid, _ = _web_postgres_session_refresh(request, hid_raw)
        if not hid:
            try:
                hid = _desktop_api_auth(request, body)[:128]
            except HTTPException:
                hid = str(body.get("hardware_id") or body.get("id") or "")[:128]
        if not hid:
            return JSONResponse(
                {"ok": False, "detail": "login_required"},
                status_code=401,
            )
    except Exception as exc_auth:  # noqa: BLE001
        _server_log_line(f"[dispatch] charter auth: {exc_auth!s}")
        hid = str(body.get("hardware_id") or body.get("id") or "")[:128]
        if not hid:
            return JSONResponse(
                {"ok": False, "detail": "login_required"},
                status_code=401,
            )
    dep = str(
        body.get("dep_icao") or body.get("origin") or body.get("dep") or ""
    ).strip().upper()[:4]
    arr = str(
        body.get("arr_icao") or body.get("destination") or body.get("arr") or ""
    ).strip().upper()[:4]
    if not dep or not arr:
        return JSONResponse(
            {
                "ok": False,
                "detail": "ICAO required"
                if lang.startswith("en")
                else "ICAO erforderlich",
            },
            status_code=400,
        )
    try:
        pax = int(body.get("passengers") or body.get("pax") or 78)
    except (TypeError, ValueError):
        pax = 78
    aircraft_model = str(body.get("aircraft_model") or body.get("fleet_model") or "")
    dist_nm, _path, route_mode = _custom_route_distance_nm(dep, arr)
    if dist_nm <= 0.0 or route_mode == "unknown":
        return JSONResponse(
            {"ok": False, "error": "unknown_icao"},
            status_code=404,
        )
    rewards = _custom_route_rewards(
        dist_nm, aircraft_model=aircraft_model, passengers=pax, dep=dep, arr=arr
    )
    flight_settings = _flight_settings_from_body(body)
    rewards = _apply_flight_settings_rewards(rewards, flight_settings)
    try:
        conn = get_db_connection()
        try:
            _persist_active_flight_pg(
                conn,
                hid,
                job_id=0,
                dep_icao=dep,
                arr_icao=arr,
                routing_provider="sky_dispatch",
                aircraft_model=aircraft_model,
                fleet_aircraft_id=int(body.get("fleet_aircraft_id") or 0),
                is_custom_route=1,
                planned_credits=rewards["credits_with_bonus"],
                planned_xp=rewards["xp_miles_with_bonus"],
                planned_distance_nm=dist_nm,
                flight_config=flight_settings,
            )
            _bump_route_statistics(conn, dep, arr)
            conn.commit()
        except Exception as exc_pg_inner:  # noqa: BLE001
            _pg_rollback(conn)
            _server_log_line(f"[dispatch] charter PG persist: {exc_pg_inner!s}")
            return JSONResponse(
                {"ok": False, "detail": "persist_failed"},
                status_code=503,
            )
        finally:
            conn.close()
    except Exception as exc_pg:  # noqa: BLE001
        _server_log_line(f"[dispatch] charter PG persist skipped: {exc_pg!s}")
    ofp_id = 0
    try:
        import sky_dispatch_engine as dispatch_eng

        plan = dispatch_eng.calculate_flight_plan(
            dep, arr, pax, aircraft_model=aircraft_model, lang=lang
        )
        if plan.get("ok"):
            conn2 = get_db_connection()
            try:
                pilot = str(body.get("username") or body.get("pilot_name") or "").strip()[:80]
                if not pilot:
                    pilot = _pilot_display_name_for_hid(hid[:64]) if hid else "Pilot"
                ofp_id = dispatch_eng.persist_ofp_pg(
                    conn2, hardware_id=hid, username=pilot, plan=plan
                )
                conn2.commit()
            finally:
                conn2.close()
    except Exception:
        pass
    return JSONResponse(
        {
            "ok": True,
            "dep_icao": dep,
            "arr_icao": arr,
            "distance_nm": round(dist_nm, 1),
            "credits": rewards["credits_base"],
            "xp_miles": rewards["xp_miles_base"],
            "credits_with_bonus": rewards["credits_with_bonus"],
            "xp_miles_with_bonus": rewards["xp_miles_with_bonus"],
            "routing_provider": "sky_dispatch",
            "is_custom_route": True,
            "ofp_id": ofp_id,
            "flight_settings": flight_settings,
            "pax_mode": flight_settings.get("pax_mode"),
            "gsx_auto_requested": bool(
                flight_settings.get("pax_mode") or flight_settings.get("vip_flight")
            ),
        }
    )


