@app.get("/api/v1/dispatch/fleet")
def api_dispatch_fleet(request: Request) -> JSONResponse:
    hid, uname = _web_postgres_session_refresh(request)
    if not hid:
        hid = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if not hid:
        return JSONResponse(
            {
                "ok": True,
                "fleet": [
                    {
                        "fleet_id": 0,
                        "aircraft_model": "A320neo (Free Flight)",
                        "status": "SANDBOX",
                        "location": "FREE",
                    }
                ],
                "sandbox": True,
            }
        )
    owner = str(uname or "").strip()[:80]
    planes: list[dict[str, Any]] = []
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, aircraft_id, aircraft_model, status, current_location
                FROM fleet
                WHERE owner_username = %s OR owner_username = %s
                ORDER BY aircraft_model ASC, id ASC;
                """,
                (owner, hid[:64]),
            )
            for row in cur.fetchall() or []:
                planes.append(
                    {
                        "fleet_id": int(row["id"]),
                        "aircraft_id": int(row["aircraft_id"] or 0),
                        "aircraft_model": str(row["aircraft_model"] or "Unknown"),
                        "status": str(row["status"] or "PARKED"),
                        "location": str(row["current_location"] or ""),
                    }
                )
    except psycopg2.Error:
        pass
    finally:
        conn.close()
    if not planes:
        conn_u = sqlite3.connect(str(USER_DB_PATH))
        try:
            rows = conn_u.execute(
                """
                SELECT id, model, icao, condition_pct FROM owned_aircraft
                WHERE hardware_id = ? ORDER BY model ASC;
                """,
                (hid[:64],),
            ).fetchall()
            for r in rows or []:
                planes.append(
                    {
                        "fleet_id": int(r[0]),
                        "aircraft_id": int(r[0]),
                        "aircraft_model": str(r[1] or "Unknown"),
                        "status": "PARKED",
                        "location": str(r[2] or ""),
                    }
                )
        finally:
            conn_u.close()
    if not planes:
        planes = [
            {
                "fleet_id": 0,
                "aircraft_id": 0,
                "aircraft_model": "A320neo (Free Flight)",
                "status": "SANDBOX",
                "location": "FREE",
            },
            {
                "fleet_id": 0,
                "aircraft_id": 0,
                "aircraft_model": "B737-800 (Free Flight)",
                "status": "SANDBOX",
                "location": "FREE",
            },
        ]
    return JSONResponse({"ok": True, "fleet": planes, "sandbox": not bool(owner)})


def _dispatch_pdf_bytes(plan: dict[str, Any], *, pilot: str, lang: str) -> bytes:
    """SkyTycoon Kapitäns-Briefing PDF (reportlab oder minimaler Fallback)."""
    dep = str(plan.get("dep_icao") or "")
    arr = str(plan.get("arr_icao") or "")
    title = "SkyTycoon Captain Briefing" if lang.startswith("en") else "SkyTycoon Kapitäns-Briefing"
    lines = [
        title,
        f"Pilot: {pilot}",
        f"{dep} → {arr}",
        f"Distance: {plan.get('distance_nm', 0)} NM",
        f"Block fuel: {plan.get('block_fuel_kg', 0)} kg",
        f"Route: {plan.get('route_text') or plan.get('route_chain') or '—'}",
        "",
        str(plan.get("ofp_text") or "")[:8000],
    ]
    try:
        from io import BytesIO

        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import cm
        from reportlab.pdfgen import canvas

        buf = BytesIO()
        c = canvas.Canvas(buf, pagesize=A4)
        w, h = A4
        c.setFillColorRGB(0.05, 0.05, 0.08)
        c.rect(0, 0, w, h, fill=1, stroke=0)
        c.setFillColorRGB(0.83, 0.69, 0.22)
        c.setFont("Helvetica-Bold", 18)
        c.drawString(2 * cm, h - 2.5 * cm, title)
        c.setFillColorRGB(0.9, 0.9, 0.92)
        c.setFont("Helvetica", 10)
        y = h - 3.5 * cm
        for line in lines:
            if y < 2 * cm:
                c.showPage()
                y = h - 2 * cm
            c.drawString(2 * cm, y, line[:110])
            y -= 0.45 * cm
        c.save()
        return buf.getvalue()
    except Exception:
        return ("\n".join(lines)).encode("utf-8")


@app.get("/api/v1/dispatch/pdf_briefing")
async def api_dispatch_pdf_briefing(
    request: Request,
    ofp_id: int = 0,
    dep_icao: str = "",
    arr_icao: str = "",
) -> Response:
    """PDF-Kapitäns-Briefing aus letztem OFP oder ICAO-Paar."""
    from fastapi.responses import Response

    lang = _web_lang(request)
    hid = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128] or "sandbox"
    pilot = _pilot_display_name_for_hid(hid[:64]) if hid else "Pilot"
    plan: dict[str, Any] = {}
    if ofp_id > 0:
        conn = get_db_connection()
        try:
            with conn.cursor(cursor_factory=DictCursor) as cur:
                cur.execute(
                    "SELECT payload_json, dep_icao, arr_icao FROM sky_ofps WHERE id = %s LIMIT 1;",
                    (int(ofp_id),),
                )
                row = cur.fetchone()
            if row:
                try:
                    plan = json.loads(str(row.get("payload_json") or "{}"))
                except json.JSONDecodeError:
                    plan = {}
                plan.setdefault("dep_icao", row.get("dep_icao"))
                plan.setdefault("arr_icao", row.get("arr_icao"))
        finally:
            conn.close()
    if not plan.get("ok"):
        import sky_dispatch_engine as dispatch_eng

        dep = str(dep_icao or plan.get("dep_icao") or "EDDF").upper()[:4]
        arr = str(arr_icao or plan.get("arr_icao") or "LEPA").upper()[:4]
        plan = dispatch_eng.calculate_flight_plan(dep, arr, 78, lang=lang)
    raw = _dispatch_pdf_bytes(plan if plan.get("ok") else {}, pilot=pilot, lang=lang)
    if raw[:4] == b"%PDF":
        return Response(
            raw,
            media_type="application/pdf",
            headers={
                "Content-Disposition": f'inline; filename="SkyTycoon_Briefing_{dep_icao or "flight"}.pdf"'
            },
        )
    return Response(raw, media_type="text/plain; charset=utf-8")


