@app.post("/api/v1/crew/recruit")
def api_crew_recruit(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _desktop_api_auth(request, body) if body else ""
    if not hid:
        hid = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    role = str(body.get("role") or "copilot")[:32]
    name = str(body.get("name") or body.get("display_name") or "Crew")[:120]
    try:
        cost = float(body.get("cost") or body.get("salary_cost") or 10000)
    except (TypeError, ValueError):
        cost = 10000.0
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT COALESCE(credits, 0) AS credits FROM users WHERE hardware_id = %s;", (hid,))
            row = cur.fetchone()
            credits = float((row or {}).get("credits") or 0)
            if credits + 1e-6 < cost:
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
            cur.execute(
                "UPDATE users SET credits = COALESCE(credits, 0) - %s WHERE hardware_id = %s;",
                (cost, hid),
            )
        _ensure_pg_crew_members_table(conn)
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO crew_members (hardware_id, role, display_name, morale, salary_cost, hired_ts)
                VALUES (%s, %s, %s, 100, %s, %s);
                """,
                (hid, role, name, int(cost), time.time()),
            )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "name": name, "cost": cost})


