@app.get("/api/v1/web/fleet/maintenance_cards")
def api_web_fleet_maintenance_cards(request: Request) -> JSONResponse:
    """12 Wartungsbalken pro Flugzeug für Web-Dashboard."""
    hid = (_web_parse_token(_web_raw_session_cookie(request)) or "")[:128]
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    cards: list[dict[str, Any]] = []
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT aircraft_model, maintenance_json, condition_pct
                FROM fleet
                WHERE hardware_id = %s OR substring(hardware_id from 1 for 64) = %s
                ORDER BY aircraft_model ASC LIMIT 40;
                """,
                (hid, hid[:64]),
            )
            rows = cur.fetchall()
        for row in rows or []:
            model = str(row.get("aircraft_model") or "Aircraft")[:80]
            parts: dict[str, float] = {}
            raw = row.get("maintenance_json")
            if isinstance(raw, str) and raw.strip():
                try:
                    parsed = json.loads(raw)
                    if isinstance(parsed, dict):
                        parts = {str(k): float(v) for k, v in parsed.items() if v is not None}
                except (TypeError, ValueError, json.JSONDecodeError):
                    pass
            if not parts:
                base = float(row.get("condition_pct") or 85.0)
                keys = (
                    "daily_check", "fifty_hour_check", "engine_overhaul", "landing_gear",
                    "avionics", "hydraulics", "de_icing", "cabin_refit",
                    "hull_inspection", "environmental_systems", "emergency_gear", "full_release",
                )
                parts = {k: base for k in keys}
            bars = [
                {"key": k, "pct": max(0.0, min(100.0, float(v)))}
                for k, v in list(parts.items())[:12]
            ]
            while len(bars) < 12:
                bars.append({"key": f"pos_{len(bars)+1}", "pct": 85.0})
            crit = any(b["pct"] < 50.0 for b in bars)
            cards.append({"model": model, "bars": bars, "critical": crit})
    finally:
        conn.close()
    return JSONResponse({"ok": True, "cards": cards})


