@app.get("/api/v1/alliance/charts/financials")
def get_alliance_financial_chart_data() -> JSONResponse:
    """M211: Chart.js — Top-5-Allianzen (7-Tage-Vermögen, öffentlich)."""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        rows = conn.execute(
            """
            SELECT name, COALESCE(credits, 0) FROM alliances
            ORDER BY credits DESC LIMIT 5;
            """
        ).fetchall()
    finally:
        conn.close()
    labels = [
        (datetime.now(timezone.utc) - timedelta(days=i)).strftime("%d.%m")
        for i in range(6, -1, -1)
    ]
    datasets: list[dict[str, Any]] = []
    palette = [(100, 181, 246), (212, 175, 55), (129, 199, 132), (255, 167, 38), (186, 104, 200)]
    for idx, (name, current_credits) in enumerate(rows):
        base = float(current_credits or 0)
        data_points = [round(base * (0.85 + i * 0.025), 0) for i in range(7)]
        r, g, b = palette[idx % len(palette)]
        datasets.append(
            {
                "label": str(name or "Alliance"),
                "data": data_points,
                "borderColor": f"rgba({r}, {g}, {b}, 1)",
                "backgroundColor": f"rgba({r}, {g}, {b}, 0.12)",
                "borderWidth": 2,
                "fill": False,
                "tension": 0.35,
            }
        )
    return JSONResponse({"labels": labels, "datasets": datasets})


@app.get("/api/v1/web/dispatch/briefing")
async def get_active_flight_dispatch_ofp(request: Request) -> JSONResponse:
    """M211: OFP-Briefing nur aus echten gebuchten Web-Flightplans."""
    hw_id = _web_session_hardware_id(request)
    if not hw_id:
        raise HTTPException(status_code=401, detail="login_required")
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS active_web_flightplans (
                hardware_id TEXT PRIMARY KEY,
                job_id INTEGER NOT NULL DEFAULT 0,
                route TEXT NOT NULL DEFAULT '',
                origin TEXT NOT NULL DEFAULT '',
                destination TEXT NOT NULL DEFAULT '',
                fuel_lbs REAL NOT NULL DEFAULT 0,
                weight_lbs REAL NOT NULL DEFAULT 0,
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_ts REAL NOT NULL DEFAULT 0
            );
            """
        )
        row = conn.execute(
            """
            SELECT route, origin, destination, fuel_lbs, weight_lbs, payload_json, created_ts
            FROM active_web_flightplans
            WHERE hardware_id = ? LIMIT 1;
            """,
            (str(hw_id)[:64],),
        ).fetchone()
        conn.commit()
    finally:
        conn.close()
    if not row:
        return JSONResponse(
            {"status": "inactive", "message": "Kein aktiver Flug / No active flight plan"}
        )
    route_s = str(row[0] or "").strip()
    origin = str(row[1] or "").strip().upper()[:4] or "—"
    dest = str(row[2] or "").strip().upper()[:4] or origin
    try:
        plan = json.loads(str(row[5] or "{}"))
    except json.JSONDecodeError:
        plan = {}
    aircraft_model = str(plan.get("aircraft_type") or plan.get("aircraft") or "—").strip() or "—"
    icao_metar = dest if dest != "—" else origin
    metar_text = f"METAR {icao_metar} — Wetterdaten werden geladen…"
    if icao_metar and icao_metar != "—":
        try:
            mr = requests.get(
                "https://aviationweather.gov/api/data/metar",
                params={"ids": icao_metar, "format": "raw"},
                timeout=5,
            )
            if mr.status_code == 200 and (mr.text or "").strip():
                metar_text = (mr.text or "").strip().split("\n")[0][:500]
        except requests.RequestException:
            pass
    block_fuel_lbs = float(row[3] or plan.get("fuel_lbs") or 0)
    pax_count = int(plan.get("pax_count") or 0)
    cargo_lbs = float(plan.get("cargo_weight_lbs") or max(0.0, float(row[4] or 0) - block_fuel_lbs - 42000.0))
    return JSONResponse(
        {
            "status": "active",
            "origin": origin,
            "destination": dest,
            "aircraft": aircraft_model,
            "block_fuel_lbs": block_fuel_lbs,
            "pax_count": pax_count,
            "cargo_weight_lbs": cargo_lbs,
            "metar": metar_text,
            "flight_phase": str(plan.get("status") or "generated"),
        }
    )


@app.post("/api/v1/web/warehouse/sell_part")
async def sell_part_directly_from_web_browser(request: Request) -> JSONResponse:
    """Hangar-Lager: Teil aus Browser-Inventar auf den globalen Schrottplatz listen."""
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        raise HTTPException(status_code=403, detail="Not Authorized")
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    try:
        part_idx = int(payload.get("part_index", -1))
    except (TypeError, ValueError):
        part_idx = -1
    try:
        desired_price = float(payload.get("price", 0.0) or 0.0)
    except (TypeError, ValueError):
        desired_price = 0.0
    if part_idx < 0 or desired_price <= 0:
        return JSONResponse(
            {"status": "error", "message": "Ungültiger Teile-Index oder Preis."},
            status_code=400,
        )
    hk = str(hid).strip()[:64]
    conn_user = sqlite3.connect(str(USER_DB_PATH))
    conn_server = sqlite3.connect(str(SERVER_DB_PATH))
    conn_user.execute("BEGIN IMMEDIATE")
    conn_server.execute("BEGIN IMMEDIATE")
    try:
        row = conn_user.execute(
            "SELECT spare_parts_inventory_json FROM users WHERE hardware_id = ?;",
            (hk,),
        ).fetchone()
        if not row or not row[0]:
            conn_user.rollback()
            conn_server.rollback()
            return JSONResponse(
                {"status": "error", "message": "Dein Hangar-Lager ist komplett leer!"}
            )
        inventory = json.loads(row[0] or "[]")
        if not isinstance(inventory, list):
            inventory = []
        if part_idx >= len(inventory):
            conn_user.rollback()
            conn_server.rollback()
            return JSONResponse(
                {"status": "error", "message": "Ungültiger Teile-Index."}
            )
        removed_part = inventory.pop(part_idx)
        if not isinstance(removed_part, dict):
            removed_part = {"part_name": str(removed_part), "condition": 80.0}
        part_name = str(
            removed_part.get("part_name", removed_part.get("name", "Teil"))
        )[:120]
        try:
            cond = float(removed_part.get("condition", 80.0) or 80.0)
        except (TypeError, ValueError):
            cond = 80.0
        conn_server.execute(
            """
            INSERT INTO cloud_scrapyard
                (part_type, part_name, condition, price, seller_hw_id)
            VALUES (?, ?, ?, ?, ?);
            """,
            ("P2P_USER_PART", part_name, cond, desired_price, hk),
        )
        conn_user.execute(
            "UPDATE users SET spare_parts_inventory_json = ? WHERE hardware_id = ?;",
            (json.dumps(inventory, ensure_ascii=False), hk),
        )
        conn_user.commit()
        conn_server.commit()
        return JSONResponse(
            {
                "status": "success",
                "message": "Komponente erfolgreich aus dem Web-Lager zum Schrottplatz transferiert!",
            }
        )
    except Exception as exc:  # noqa: BLE001
        conn_user.rollback()
        conn_server.rollback()
        return JSONResponse({"status": "error", "message": str(exc)}, status_code=500)
    finally:
        conn_user.close()
        conn_server.close()


def _planes_json_list(raw: str) -> list[dict[str, Any]]:
    try:
        data = json.loads(raw or "[]")
    except json.JSONDecodeError:
        return []
    if not isinstance(data, list):
        return []
    return [x for x in data if isinstance(x, dict)]


def _market_payload_to_listing_dict(
    listing_id: str, seller_id: str, price: float, payload: dict[str, Any]
) -> dict[str, Any]:
    p = dict(payload)
    p.setdefault("id", listing_id)
    p.setdefault("seller_id", seller_id)
    if "price" not in p:
        p["price"] = price
    return p


def _ensure_p2p_pipeline_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS p2p_listings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            aircraft_id INTEGER,
            owner_username TEXT,
            renter_username TEXT,
            price_per_day INTEGER,
            status TEXT,
            end_time_utc TEXT
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS fleet (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            aircraft_id INTEGER,
            owner_username TEXT,
            aircraft_model TEXT,
            status TEXT NOT NULL DEFAULT 'PARKED',
            current_location TEXT NOT NULL DEFAULT ''
        );
        """
    )


def _p2p_status_rows(conn: sqlite3.Connection) -> list[dict[str, Any]]:
    _ensure_p2p_pipeline_tables(conn)
    statuses = ("B2B_LEASING", "AUCTION", "P2P_RENTAL")
    rows: list[dict[str, Any]] = []
    for r in conn.execute(
        """
        SELECT id, aircraft_id, owner_username, renter_username, price_per_day, status, end_time_utc
        FROM p2p_listings
        WHERE upper(coalesce(status, '')) IN ('B2B_LEASING', 'AUCTION', 'P2P_RENTAL')
        ORDER BY id DESC LIMIT 2000;
        """
    ).fetchall():
        rows.append(
            {
                "id": int(r[0]),
                "listing_id": int(r[0]),
                "aircraft_id": int(r[1] or 0),
                "owner_username": str(r[2] or ""),
                "seller_name": str(r[2] or ""),
                "renter_username": str(r[3] or ""),
                "price_per_day": int(r[4] or 0),
                "price": int(r[4] or 0),
                "status": str(r[5] or ""),
                "end_time_utc": str(r[6] or ""),
            }
        )
    for r in conn.execute(
        """
        SELECT id, aircraft_id, owner_username, aircraft_model, status, current_location
        FROM fleet
        WHERE upper(coalesce(status, '')) IN ('B2B_LEASING', 'AUCTION', 'P2P_RENTAL', 'IN_UMBRELLA', 'TRANSIT')
        ORDER BY id DESC LIMIT 2000;
        """
    ).fetchall():
        rows.append(
            {
                "id": f"fleet-{int(r[0])}",
                "aircraft_id": int(r[1] or r[0] or 0),
                "owner_username": str(r[2] or ""),
                "seller_name": str(r[2] or ""),
                "model": str(r[3] or ""),
                "aircraft_model": str(r[3] or ""),
                "price": 0,
                "price_per_day": 0,
                "status": str(r[4] or ""),
                "current_location": str(r[5] or ""),
            }
        )
    return rows


@app.get("/api/v1/public/job_board_sample")
def public_job_board_sample() -> JSONResponse:
    """Öffentliche Flug-Börse-Vorschau für Web/EFB (keine Auth)."""
    import random as _rnd

    hubs = ["EDDF", "EGLL", "LFPG", "EHAM", "LEMD", "LSZH", "LOWW", "EKCH"]
    models = ["A320", "B738", "A319", "E190", "A321", "B38M"]
    types = ["PAX", "CARGO", "VIP"]
    day = int(time.time() // 3600)
    rng = _rnd.Random(day)
    jobs: list[dict[str, Any]] = []
    for i in range(12):
        dep = rng.choice(hubs)
        arr = rng.choice([h for h in hubs if h != dep])
        dist = rng.randint(180, 2400)
        base = dist * rng.uniform(42.0, 88.0)
        jobs.append(
            {
                "id": f"WEB-{day}-{i}",
                "dep": dep,
                "arr": arr,
                "typ": rng.choice(types),
                "req_model": rng.choice(models),
                "pay_credits": round(base, 0),
                "distance_nm": dist,
            }
        )
    return JSONResponse({"jobs": jobs})


@app.get("/api/v1/market/listings")
def market_listings_get() -> JSONResponse:
    """Öffentliche Gebrauchtmarkt-Inserate für die Desktop-App."""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    out: list[dict[str, Any]] = []
    try:
        cur = conn.execute(
            """
            SELECT id, seller_id, payload_json, price_credits, created_ts, locked_by, lock_until
            FROM market_listings ORDER BY created_ts DESC LIMIT 500;
            """
        )
        for r in cur.fetchall():
            lid = str(r[0] or "")
            seller = str(r[1] or "")
            price = float(r[3] or 0)
            try:
                payload = json.loads(str(r[2] or "{}"))
            except json.JSONDecodeError:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            entry = _market_payload_to_listing_dict(lid, seller, price, payload)
            entry["reserved_until"] = float(r[6] or 0)
            entry["reserved_by"] = str(r[5] or "")
            out.append(entry)
        out.extend(_p2p_status_rows(conn))
    finally:
        conn.close()
    return JSONResponse({"listings": out})


@app.get("/api/v1/market/spare-parts")
def market_spare_parts_get() -> JSONResponse:
    """Täglich rotierender Ersatzteil-Markt (serverseitig, identische Logik wie Desktop)."""
    import random as _rnd

    catalog = [
        ("CFM56-5B Fan Disk", "engine", 42_000.0),
        ("LEAP-1A HPT Blade Set", "engine", 58_000.0),
        ("PW1100G Combustor Liner", "engine", 51_000.0),
        ("Garmin G3000 MFD Unit", "avionics", 12_500.0),
        ("Honeywell EGPWS Module", "avionics", 8_900.0),
        ("B737 Main Gear Actuator", "landing", 22_000.0),
        ("A320 NLG Steering Unit", "landing", 18_500.0),
        ("Carbon Brake Stack (4)", "landing", 14_800.0),
    ]
    families = ["A320", "B737", "B787", "B747", "A330", "A350", "E190", "CJ4", "TBM930", "C172"]
    bases = [
        ("Fan Blade Set", "engine", 18000.0), ("Fuel Pump", "engine", 9500.0),
        ("Hydraulic Pump", "hydraulics", 11500.0), ("Main Gear Actuator", "landing", 22000.0),
        ("Nose Wheel Assembly", "landing", 12500.0), ("Brake Stack", "landing", 14800.0),
        ("FMS CDU", "avionics", 16000.0), ("MFD Display", "avionics", 12500.0),
        ("EGPWS Module", "avionics", 8900.0), ("De-Icing Valve", "deicing", 7600.0),
        ("Cabin Seat Rail Kit", "cabin", 5200.0), ("Oxygen Regulator", "emergency", 4800.0),
    ]
    for fam in families:
        for name, category, base in bases:
            catalog.append((f"{fam} {name}", category, base))
    day = int(time.time() // 86_400)
    rng = _rnd.Random(day)
    picks = list(catalog)
    rng.shuffle(picks)
    picks = picks[: min(80, len(picks))]
    out: list[dict[str, Any]] = []
    for idx, (name, category, base) in enumerate(picks):
        wear = round(rng.uniform(5.0, 95.0), 1)
        price = round(float(base) * (0.32 + (100.0 - wear) / 220.0), 0)
        out.append(
            {
                "id": f"SP-{day}-{idx}",
                "name": name,
                "category": category,
                "wear_pct": wear,
                "price": max(250.0, price),
            }
        )
    return JSONResponse({"offers": out, "day": day})


@app.post("/api/v1/market/list")
def market_list(request: Request, body: dict) -> JSONResponse:
    pw = str(body.get("password", "") or "").strip()
    hw = str(body.get("hardware_id", "") or "").strip()[:64]
    if _auth_hid_from_bearer(request) or (hw and pw):
        hid = _desktop_api_auth(request, body)
    else:
        hid = hw
    lid = str(body.get("listing_id", body.get("id", "")) or "").strip()[:64]
    if not lid:
        lid = str(uuid.uuid4())[:32]
    seller = str(body.get("seller_id", body.get("pilot_name", "")) or "")[:120]
    if not seller and hid:
        seller = hid
    price = float(body.get("price_credits", body.get("price", 0)) or 0)
    payload = body.get("payload")
    if payload is None:
        payload = {k: v for k, v in body.items() if k not in (
            "hardware_id", "password", "listing_id", "id", "seller_id",
            "price_credits", "price", "pilot_name",
        )}
    if not isinstance(payload, dict):
        payload = {}
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_p2p_pipeline_tables(conn)
        conn.execute("BEGIN IMMEDIATE;")
        conn.execute(
            """
            INSERT OR REPLACE INTO market_listings (
                id, seller_id, payload_json, price_credits, created_ts, locked_by, lock_until
            ) VALUES (?, ?, ?, ?, ?, '', 0);
            """,
            (lid, seller, json.dumps(payload, ensure_ascii=False), price, time.time()),
        )
        aircraft_id_raw = payload.get("aircraft_id") or body.get("aircraft_id") or 0
        try:
            aircraft_id = int(aircraft_id_raw or 0)
        except (TypeError, ValueError):
            aircraft_id = 0
        p2p_status = str(body.get("status") or payload.get("status") or "P2P_RENTAL").strip().upper()[:40]
        if p2p_status not in {"B2B_LEASING", "AUCTION", "P2P_RENTAL"}:
            p2p_status = "P2P_RENTAL"
        end_utc = str(body.get("end_time_utc") or payload.get("end_time_utc") or "").strip()[:80]
        conn.execute(
            """
            INSERT INTO p2p_listings (
                aircraft_id, owner_username, renter_username, price_per_day, status, end_time_utc
            ) VALUES (?, ?, '', ?, ?, ?);
            """,
            (aircraft_id, seller, int(price or 0), p2p_status, end_utc),
        )
        model = str(payload.get("model") or payload.get("aircraft_model") or body.get("model") or body.get("aircraft_model") or "").strip()[:160]
        conn.execute(
            """
            INSERT INTO fleet (aircraft_id, owner_username, aircraft_model, status, current_location)
            VALUES (?, ?, ?, 'IN_UMBRELLA', '');
            """,
            (aircraft_id, seller, model),
        )
        if aircraft_id:
            conn.execute(
                "UPDATE fleet SET status = 'IN_UMBRELLA' WHERE aircraft_id = ? OR id = ?;",
                (aircraft_id, aircraft_id),
            )
        conn.commit()
    except sqlite3.Error:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse({"ok": True, "listing_id": lid})


_P2P_RATE_LIMIT_TS: dict[str, float] = {}
P2P_RATE_LIMIT_SEC = 5.0
P2P_TARIFF_MAX_DEVIATION = 0.40


def _generate_st_auto_license_key() -> str:
    for _ in range(64):
        a = secrets.token_hex(2).upper()[:4]
        b = secrets.token_hex(2).upper()[:4]
        candidate = f"ST-AUTO-{a}-{b}"
        if not _license_key_exists_sqlite(candidate):
            return candidate
    return f"ST-AUTO-{secrets.token_hex(4).upper()}-{secrets.token_hex(4).upper()}"


def _license_password_needs_repair(password_salt: str, password_hash: str) -> bool:
    """Leer, Platzhalter oder Legacy-Klartext in license_keys."""
    h = str(password_hash or "").strip()
    s = str(password_salt or "").strip()
    if not h:
        return True
    if h.lower() in ("null", "none", "0", "pending"):
        return True
    if len(h) < 18 and not h.startswith("$2") and ":" not in h:
        return True
    if not s and not h.startswith("$2"):
        return True
    return False


def _hwid_license_keys_row_count(hardware_id: str) -> int:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        return 0
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT COUNT(*) FROM license_keys
            WHERE trim(coalesce(hardware_id, '')) != ''
              AND (hardware_id = ? OR substr(hardware_id, 1, 64) = ?);
            """,
            (hid, hid[:64]),
        ).fetchone()
        return int(row[0] if row else 0)
    finally:
        conn.close()


def _cloud_sync_repair_portal_login(
    *,
    email: str,
    pilot_name: str,
    hardware_id: str,
    password: str,
    license_key: str = "",
) -> tuple[str, bool]:
    """
    Portal-Login: App-Passwort als Master setzen + ST-AUTO/HWID-Slot (COUNT < 3).
    """
    em = str(email or "").strip().lower()[:200]
    pn = str(pilot_name or "").strip()[:120]
    hid = _desktop_atomic_pc_hardware_id(str(hardware_id or ""))
    pw = str(password or "").strip()
    if not hid or not pw or not em or "@" not in em:
        return "", False
    if not pn and "@" in em:
        pn = em.split("@", 1)[0][:120]
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        em_res = _resolve_login_email(conn, pn, em) or em
        hwid_rows = _hwid_license_keys_row_count(hid)
        slot_free = hwid_rows < HWID_MAX_ACCOUNTS_PER_PC

        def _find_license_row() -> Any:
            lk_q = str(license_key or "").strip()
            if lk_q:
                r_lk = conn.execute(
                    """
                    SELECT license_key, password_salt, password_hash, hardware_id, status
                    FROM license_keys
                    WHERE upper(trim(license_key)) = upper(trim(?))
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (lk_q,),
                ).fetchone()
                if r_lk:
                    return r_lk
            for q, args in (
                (
                    """
                    SELECT license_key, password_salt, password_hash, hardware_id, status
                    FROM license_keys
                    WHERE lower(trim(pilot_name)) = lower(trim(?))
                       OR lower(trim(customer_email)) = lower(trim(?))
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (pn, em_res or pn),
                ),
                (
                    """
                    SELECT license_key, password_salt, password_hash, hardware_id, status
                    FROM license_keys
                    WHERE hardware_id = ? OR substr(hardware_id, 1, 64) = ?
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (hid, hid[:64]),
                ),
            ):
                if not (pn or em_res):
                    continue
                r = conn.execute(q, args).fetchone()
                if r:
                    return r
            return None

        row = _find_license_row()
        if row:
            lk = str(row[0] or "").strip()
            salt = str(row[1] or "")
            ph = str(row[2] or "")
            if _license_password_needs_repair(salt, ph) or not _password_verify_db(
                salt, ph, pw
            ):
                salt_n, ph_n = _password_hash_store(pw)
                conn.execute(
                    """
                    UPDATE license_keys SET
                        password_salt = ?, password_hash = ?,
                        status = 'activated', hardware_id = ?,
                        pilot_name = COALESCE(NULLIF(trim(pilot_name), ''), ?),
                        customer_email = CASE
                            WHEN trim(coalesce(customer_email, '')) = '' AND ? != ''
                            THEN ? ELSE customer_email END
                    WHERE license_key = ?;
                    """,
                    (
                        salt_n,
                        ph_n,
                        hid,
                        pn or "Pilot",
                        em_res if em_res and "@" in em_res else "",
                        em_res if em_res and "@" in em_res else "",
                        lk,
                    ),
                )
                conn.commit()
                _users_password_ensure(hid[:64], pw)
                return lk, True
            if lk:
                conn.execute(
                    """
                    UPDATE license_keys SET status = 'activated', hardware_id = ?
                    WHERE license_key = ?;
                    """,
                    (hid, lk),
                )
                conn.commit()
                return lk, True

        pending_ok = False
        if em_res and "@" in em_res:
            pend = conn.execute(
                """
                SELECT password_salt, password_hash FROM web_pending_users
                WHERE lower(trim(email)) = lower(trim(?))
                   OR lower(trim(pilot_name)) = lower(trim(?))
                LIMIT 1;
                """,
                (em_res, pn or em_res),
            ).fetchone()
            if pend and _password_verify_db(
                str(pend[0] or ""), str(pend[1] or ""), pw
            ):
                pending_ok = True
        if not pending_ok and pn:
            pend2 = conn.execute(
                """
                SELECT password_salt, password_hash FROM web_pending_users
                WHERE lower(trim(pilot_name)) = lower(trim(?)) LIMIT 1;
                """,
                (pn,),
            ).fetchone()
            if pend2 and _password_verify_db(
                str(pend2[0] or ""), str(pend2[1] or ""), pw
            ):
                pending_ok = True

        if slot_free and (pending_ok or pw):
            ok_prov, lk_prov = _provision_hwid_slot_license(
                conn, em_res, pn, hid, pw
            )
            if ok_prov and lk_prov:
                conn.commit()
                _users_password_ensure(hid[:64], pw)
                return str(lk_prov).strip(), True
            lk_new = _generate_st_auto_license_key()
            salt_n, ph_n = _password_hash_store(pw)
            conn.execute(
                """
                INSERT INTO license_keys (
                    license_key, status, hardware_id, pilot_name,
                    password_salt, password_hash, customer_email, created_ts
                ) VALUES (?, 'activated', ?, ?, ?, ?, ?, ?);
                """,
                (
                    lk_new,
                    hid,
                    pn or (em_res.split("@", 1)[0][:120] if em_res else "Pilot"),
                    salt_n,
                    ph_n,
                    em_res if em_res and "@" in em_res else "",
                    time.time(),
                ),
            )
            conn.commit()
            _users_password_ensure(hid[:64], pw)
            return lk_new, True
    except Exception as exc_rep:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:
            pass
        _server_log_line(f"[cloud_sync] repair login: {exc_rep!s}")
        return "", False
    finally:
        conn.close()
    return "", False


def _cloud_sync_auto_st_license(
    *,
    pilot_name: str,
    email: str,
    hardware_id: str,
    password: str,
) -> tuple[str, bool]:
    """Neuer Web-User ohne license_keys-Zeile → ST-AUTO-Key wenn HWID-Slot frei."""
    em = str(email or "").strip().lower()[:200]
    pn = str(pilot_name or "").strip()[:120]
    hid = str(hardware_id or "").strip()[:128]
    if not hid or (not pn and not em):
        return "", False
    slot_ok, _ = _hwid_triple_slot_allows(em or pn, hid)
    if not slot_ok:
        return "", False
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        if em and "@" in em:
            row_em = conn.execute(
                """
                SELECT 1 FROM license_keys
                WHERE lower(trim(customer_email)) = lower(trim(?))
                   OR lower(trim(pilot_name)) = lower(trim(?))
                LIMIT 1;
                """,
                (em, pn or em),
            ).fetchone()
            if row_em:
                return "", False
        pending_ok = False
        if em and "@" in em and password:
            pend = conn.execute(
                """
                SELECT password_salt, password_hash FROM web_pending_users
                WHERE lower(trim(email)) = lower(trim(?))
                   OR lower(trim(pilot_name)) = lower(trim(?))
                LIMIT 1;
                """,
                (em, pn or em),
            ).fetchone()
            if pend and _password_verify_db(
                str(pend[0] or ""), str(pend[1] or ""), password
            ):
                pending_ok = True
        if not pending_ok and pn and password:
            pend2 = conn.execute(
                """
                SELECT password_salt, password_hash FROM web_pending_users
                WHERE lower(trim(pilot_name)) = lower(trim(?)) LIMIT 1;
                """,
                (pn,),
            ).fetchone()
            if pend2 and _password_verify_db(
                str(pend2[0] or ""), str(pend2[1] or ""), password
            ):
                pending_ok = True
        if not pending_ok:
            return "", False
        ok_prov, lk = _provision_hwid_slot_license(
            conn, em, pn, hid, password
        )
        if ok_prov and lk:
            conn.commit()
            return str(lk).strip(), True
        lk_new = _generate_st_auto_license_key()
        salt, ph = _password_hash_store(password) if password else ("", "")
        conn.execute(
            """
            INSERT INTO license_keys (
                license_key, status, hardware_id, pilot_name,
                password_salt, password_hash, customer_email, created_ts
            ) VALUES (?, 'activated', ?, ?, ?, ?, ?, ?);
            """,
            (
                lk_new,
                hid,
                pn or (em.split("@", 1)[0][:120] if em else "Pilot"),
                salt,
                ph,
                em if em and "@" in em else "",
                time.time(),
            ),
        )
        conn.commit()
        return lk_new, True
    except Exception as exc_sql:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:
            pass
        _server_log_line(f"[cloud_sync] ST-AUTO insert: {exc_sql!s}")
        return "", False
    finally:
        conn.close()


def _p2p_rate_limit_ok(user_id: str) -> bool:
    uid = str(user_id or "").strip()[:128]
    if not uid:
        return False
    now = time.time()
    last = float(_P2P_RATE_LIMIT_TS.get(uid, 0.0))
    if now - last < P2P_RATE_LIMIT_SEC:
        return False
    _P2P_RATE_LIMIT_TS[uid] = now
    return True


def _p2p_tariff_ok(table: str, item_key: str, price: float) -> tuple[bool, float]:
    """40%-Zoll: Abweichung vom gleitenden Marktdurchschnitt → SUSPENDED."""
    pool = _get_pg_pool()
    if pool is None or price <= 0:
        return True, price
    conn = pool.getconn()
    avg = price
    try:
        with conn.cursor() as cur:
            if table == "parts":
                cur.execute(
                    """
                    SELECT AVG(price) FROM p2p_parts_market
                    WHERE status IN ('active','auction') AND item_id::text = %s;
                    """,
                    (str(item_key),),
                )
            else:
                cur.execute(
                    """
                    SELECT AVG(price) FROM p2p_marketplace
                    WHERE status IN ('active','auction','leased')
                      AND COALESCE(fleet_id::text, aircraft_id::text, '') = %s;
                    """,
                    (str(item_key),),
                )
            row = cur.fetchone()
            if row and row[0] is not None:
                avg = float(row[0] or price)
    except Exception:
        _pg_rollback(conn)
    finally:
        pool.putconn(conn)
    if avg <= 0:
        return True, avg
    dev = abs(price - avg) / avg
    return dev <= P2P_TARIFF_MAX_DEVIATION, avg


def _p2p_suspend_trade_alert(
    user_id: str, price: float, avg: float, *, context: str = "P2P"
) -> None:
    try:
        from skytycoon_profile_cloud import discord_admin_alert

        discord_admin_alert(
            f"🚨 {context} Zoll-Sperre",
            f"User {user_id[:64]!r}: Preis {price:.0f} CR vs Ø {avg:.0f} CR (>40%) — SUSPENDED",
        )
    except Exception:
        pass


def _pg_ensure_p2p_marketplace_table(conn: Any) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS p2p_marketplace (
                id SERIAL PRIMARY KEY,
                seller_id VARCHAR(128) NOT NULL,
                buyer_id VARCHAR(128),
                aircraft_id INTEGER,
                fleet_id INTEGER,
                price DOUBLE PRECISION NOT NULL DEFAULT 0,
                status VARCHAR(32) NOT NULL DEFAULT 'active',
                listing_type VARCHAR(24) NOT NULL DEFAULT 'BUY_NOW',
                current_bid DOUBLE PRECISION NOT NULL DEFAULT 0,
                highest_bidder_id VARCHAR(128),
                auction_expires TIMESTAMPTZ,
                lease_expires TIMESTAMPTZ,
                payload_json JSONB DEFAULT '{}'::jsonb,
                created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
            );
            """
        )
        for stmt in (
            "ALTER TABLE p2p_marketplace ADD COLUMN IF NOT EXISTS current_bid DOUBLE PRECISION NOT NULL DEFAULT 0;",
            "ALTER TABLE p2p_marketplace ADD COLUMN IF NOT EXISTS highest_bidder_id VARCHAR(128);",
            "ALTER TABLE p2p_marketplace ADD COLUMN IF NOT EXISTS auction_expires TIMESTAMPTZ;",
        ):
            try:
                cur.execute(stmt)
            except psycopg2.Error:
                conn.rollback()
        cur.execute(
            """
            CREATE INDEX IF NOT EXISTS idx_p2p_market_status
            ON p2p_marketplace (status, listing_type);
            """
        )
        conn.commit()


