def _p2p_pg_listings_active(limit: int = 200) -> list[dict[str, Any]]:
    pool = _get_pg_pool()
    if pool is None:
        return []
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, seller_id, buyer_id, aircraft_id, fleet_id, price, status,
                       listing_type, lease_expires, payload_json, created_at
                FROM p2p_marketplace
                WHERE status IN ('active', 'leased')
                ORDER BY created_at DESC
                LIMIT %s;
                """,
                (max(1, min(limit, 500)),),
            )
            rows = cur.fetchall() or []
        return [dict(r) for r in rows]
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[p2p] listings: {exc!s}")
        return []
    finally:
        pool.putconn(conn)


def _p2p_lease_repossession_once() -> int:
    """Abgelaufene 48h-Leasing → Flugzeug an Verkäufer zurück."""
    pool = _get_pg_pool()
    if pool is None:
        return 0
    conn = pool.getconn()
    n = 0
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, seller_id, buyer_id, fleet_id, aircraft_id, payload_json
                FROM p2p_marketplace
                WHERE status = 'leased'
                  AND lease_expires IS NOT NULL
                  AND lease_expires < NOW();
                """
            )
            expired = cur.fetchall() or []
            for row in expired:
                seller = str(row["seller_id"] or "")[:128]
                buyer = str(row["buyer_id"] or "")[:128]
                fleet_id = row.get("fleet_id")
                if fleet_id and buyer and seller:
                    cur.execute(
                        """
                        UPDATE fleet SET owner_username = %s
                        WHERE id = %s AND owner_username = %s;
                        """,
                        (seller, fleet_id, buyer),
                    )
                cur.execute(
                    """
                    UPDATE p2p_marketplace
                    SET status = 'active', buyer_id = NULL, lease_expires = NULL
                    WHERE id = %s;
                    """,
                    (int(row["id"]),),
                )
                n += 1
        conn.commit()
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[p2p] repossession: {exc!s}")
    finally:
        pool.putconn(conn)
    return n


async def _p2p_lease_repossession_loop() -> None:
    while True:
        try:
            rep = await asyncio.to_thread(_p2p_lease_repossession_once)
            if rep:
                _server_log_line(f"[p2p] lease repossession: {rep} aircraft")
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[p2p] repossession loop: {exc!s}")
        await asyncio.sleep(900)


def _p2p_lease_hourly_collect_and_dunning() -> int:
    """Stündlich: offene P2P-Leasing-Raten einziehen; Minus → Mahnung."""
    pool = _get_pg_pool()
    if pool is None:
        return 0
    conn = pool.getconn()
    collected = 0
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, buyer_id, seller_id, price
                FROM p2p_marketplace
                WHERE status = 'leased' AND lease_expires > NOW();
                """
            )
            leases = cur.fetchall() or []
            for row in leases:
                buyer = str(row["buyer_id"] or "")[:128]
                seller = str(row["seller_id"] or "")[:128]
                rate = float(row["price"] or 0) * 0.05
                if rate <= 0 or not buyer:
                    continue
                cur.execute(
                    "UPDATE users SET credits = credits - %s WHERE hardware_id = %s;",
                    (rate, buyer),
                )
                cur.execute(
                    "SELECT credits FROM users WHERE hardware_id = %s LIMIT 1;",
                    (buyer,),
                )
                brow = cur.fetchone()
                cred = float(brow["credits"] if brow else 0)
                if seller:
                    cur.execute(
                        "UPDATE users SET credits = credits + %s WHERE hardware_id = %s;",
                        (rate * 0.98, seller),
                    )
                if cred < 0:
                    prof = _mail_user_profile(buyer)
                    em = prof.get("email") or ""
                    if em:
                        lg = prof.get("lang") or "de"
                        if lg == "en":
                            subj, plain = (
                                "💳 P2P lease payment overdue",
                                f"Captain {prof.get('pilot_name')}, balance {cred:.0f} CR.",
                            )
                        else:
                            subj, plain = (
                                "💳 P2P-Leasing-Rückstand",
                                f"Kapitän {prof.get('pilot_name')}, Kontostand {cred:.0f} CR.",
                            )
                        html = f"<html><body style='background:#05070a;color:#e3e7ed;padding:20px;'><p>{html.escape(plain)}</p></body></html>"
                        _mail_guard_send_simple(
                            em, prof.get("pilot_name", ""), subj, plain, html
                        )
                collected += 1
        conn.commit()
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[p2p] lease collect: {exc!s}")
    finally:
        pool.putconn(conn)
    return collected


def _pax_generate_comments_i18n(
    hardware_id: str,
    *,
    werft_bars: list[float] | None = None,
    catering: str = "",
    lang: str = "de",
) -> list[dict[str, Any]]:
    import random

    hid = str(hardware_id or "")[:128]
    bars = werft_bars or [100.0] * 12
    avg = sum(float(b) for b in bars[:12]) / max(1, min(12, len(bars)))
    en = (lang or "de").strip().lower() == "en"
    templates_de = [
        "Fantastischer Service an Bord!",
        "Die Kabine war makellos — weiter so!",
        "Catering {cat} war hervorragend.",
        "Leichte Turbulenz, aber professionelle Crew.",
        "Werft-Zustand {pct:.0f}% — fühlte sich sicher an.",
    ]
    templates_en = [
        "Fantastic in-flight service!",
        "Cabin was spotless — well done!",
        "Catering {cat} was excellent.",
        "Light turbulence, professional crew.",
        "Hangar condition {pct:.0f}% — felt safe.",
    ]
    tpls = templates_en if en else templates_de
    cat = (catering or "standard").strip()[:40]
    out: list[dict[str, Any]] = []
    for _ in range(random.randint(3, 5)):
        stars = 5 if avg >= 85 else (4 if avg >= 70 else 3)
        mult = round(0.9 + stars * 0.05 + random.uniform(-0.05, 0.08), 2)
        txt = random.choice(tpls).format(cat=cat, pct=avg)
        out.append({"stars": stars, "comment": txt, "multiplier": mult})
    pool = _get_pg_pool()
    if pool is None:
        return out
    conn = pool.getconn()
    try:
        with conn.cursor() as cur:
            fid = f"flt-{int(time.time())}-{random.randint(1000, 9999)}"
            for c in out:
                cur.execute(
                    """
                    INSERT INTO pax_feedback (user_id, flight_id, stars, comment, multiplier)
                    VALUES (%s, %s, %s, %s, %s);
                    """,
                    (hid, fid, int(c["stars"]), str(c["comment"])[:500], float(c["multiplier"])),
                )
        conn.commit()
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[pax] insert: {exc!s}")
    finally:
        pool.putconn(conn)
    return out


@app.get("/api/v1/pax/feedback")
def pax_feedback_list(
    hardware_id: str = "", limit: int = 12, lang: str = "de"
) -> JSONResponse:
    hid = str(hardware_id or "").strip()[:128]
    if not hid:
        raise HTTPException(status_code=400, detail="no_id")
    pool = _get_pg_pool()
    if pool is None:
        return JSONResponse({"ok": True, "comments": []})
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT stars, comment, multiplier, created_at
                FROM pax_feedback
                WHERE user_id = %s
                ORDER BY created_at DESC
                LIMIT %s;
                """,
                (hid, max(1, min(int(limit), 50))),
            )
            rows = [dict(r) for r in (cur.fetchall() or [])]
            avg_stars = 0.0
            avg_mult = 1.0
            if rows:
                avg_stars = sum(float(r.get("stars") or 0) for r in rows) / len(rows)
                avg_mult = sum(float(r.get("multiplier") or 1) for r in rows) / len(rows)
            bonus = round(max(1.0, min(1.35, avg_mult)), 3)
            approval_pct = round((avg_stars / 5.0) * 100.0, 1) if rows else 0.0
            mirror = _simconnect_live_mirror_for_hid(hid[:64])
            bars = list(mirror.get("werft_bars") or [100.0] * 12)
            while len(bars) < 12:
                bars.append(100.0)
            werft_idx = round(
                sum(float(b) for b in bars[:12]) / max(1, len(bars[:12])), 1
            )
            catering_score = round(
                float(
                    mirror.get("catering_score")
                    or mirror.get("gsx_catering_quality")
                    or mirror.get("catering_quality")
                    or 88.0
                ),
                1,
            )
            sqi = round(0.6 * werft_idx + 0.4 * catering_score, 1)
        return JSONResponse(
            {
                "ok": True,
                "comments": rows,
                "avg_stars": round(avg_stars, 2),
                "avg_multiplier": round(avg_mult, 3),
                "credit_bonus_multiplier": bonus,
                "approval_pct": approval_pct,
                "service_quality_index": sqi,
                "werft_condition_pct": werft_idx,
                "catering_score": catering_score,
                "lang": (lang or "de")[:8],
            }
        )
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


@app.get("/api/v1/p2p/marketboard")
def p2p_marketboard_feed() -> JSONResponse:
    """Kombiniertes Markt-Board: Flugzeuge + Ersatzteile + Ticker-Zeilen."""
    pool = _get_pg_pool()
    listings: list[dict[str, Any]] = []
    ticker: list[str] = []
    if pool is None:
        return JSONResponse({"ok": True, "listings": [], "ticker": []})
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, seller_id, price, status, listing_type, current_bid,
                       highest_bidder_id, fleet_id, aircraft_id, created_at,
                       'aircraft' AS market_kind
                FROM p2p_marketplace
                WHERE status IN ('active', 'auction', 'leased')
                ORDER BY created_at DESC LIMIT 120;
                """
            )
            for r in cur.fetchall() or []:
                listings.append(dict(r))
            cur.execute(
                """
                SELECT m.id, m.seller_id, m.price, m.status, m.listing_type,
                       m.current_bid, m.highest_bidder_id, m.item_id, m.created_at,
                       w.item_type, w.condition, 'parts' AS market_kind
                FROM p2p_parts_market m
                LEFT JOIN user_warehouse w ON w.id = m.item_id
                WHERE m.status IN ('active', 'auction')
                ORDER BY m.created_at DESC LIMIT 120;
                """
            )
            for r in cur.fetchall() or []:
                listings.append(dict(r))
        for row in listings[:24]:
            kind = str(row.get("market_kind") or "aircraft")
            lid = row.get("id")
            pr = float(row.get("current_bid") or row.get("price") or 0)
            lt = str(row.get("listing_type") or "BUY_NOW")
            seller = str(row.get("seller_id") or "")[:16]
            if kind == "parts":
                ticker.append(
                    f"📦 #{lid} {row.get('item_type','Part')} · {pr:.0f} CR · {lt} · {seller}"
                )
            else:
                ticker.append(
                    f"✈ #{lid} · {pr:.0f} CR · {lt} · {seller}"
                )
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[p2p] marketboard: {exc!s}")
    finally:
        pool.putconn(conn)
    return JSONResponse({"ok": True, "listings": listings, "ticker": ticker})


@app.post("/api/v1/pax/generate")
def pax_feedback_generate(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = str(body.get("hardware_id", "") or "").strip()[:128]
    if not hid:
        raise HTTPException(status_code=400, detail="no_id")
    bars = body.get("werft_bars") or body.get("werft")
    if not isinstance(bars, list):
        bars = [100.0] * 12
    lang = str(body.get("selected_language") or body.get("ui_lang") or "de")[:8]
    comments = _pax_generate_comments_i18n(
        hid, werft_bars=bars, catering=str(body.get("catering") or ""), lang=lang
    )
    return JSONResponse({"ok": True, "comments": comments})


@app.post("/api/v1/p2p/list")
def p2p_list_aircraft(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = str(body.get("hardware_id", "") or "").strip()[:128]
    price = float(body.get("price") or 0)
    listing_type = str(body.get("listing_type") or "BUY_NOW").strip().upper()[:24]
    if listing_type in ("SALE", "LEASE_48H"):
        listing_type = "BUY_NOW" if listing_type == "SALE" else "lease_48h"
    days = int(body.get("auction_days") or body.get("days") or 1)
    if days not in (1, 2, 3):
        days = 1
    fleet_id = body.get("fleet_id")
    if not _p2p_rate_limit_ok(hid):
        raise HTTPException(status_code=429, detail="rate_limit")
    pool = _get_pg_pool()
    if pool is None or not hid:
        raise HTTPException(status_code=503, detail="pg_unavailable")
    conn = pool.getconn()
    try:
        with conn.cursor() as cur:
            lt = listing_type
            if lt == "LEASE_48H":
                lt = "lease_48h"
            if lt not in ("BUY_NOW", "AUCTION", "lease_48h"):
                lt = "BUY_NOW"
            payload_j = json.dumps(body.get("payload_json") or {}, ensure_ascii=False)
            fid = int(fleet_id) if fleet_id else None
            if lt == "lease_48h":
                cur.execute(
                    """
                    INSERT INTO p2p_marketplace (
                        seller_id, price, status, listing_type, lease_expires,
                        fleet_id, payload_json
                    ) VALUES (
                        %s, %s, 'active', %s, CURRENT_TIMESTAMP + INTERVAL '2 days',
                        %s, %s::jsonb
                    ) RETURNING id;
                    """,
                    (hid, price, lt, fid, payload_j),
                )
            elif lt == "AUCTION":
                cur.execute(
                    f"""
                    INSERT INTO p2p_marketplace (
                        seller_id, price, status, listing_type, auction_expires,
                        fleet_id, payload_json
                    ) VALUES (
                        %s, %s, 'auction', %s,
                        CURRENT_TIMESTAMP + INTERVAL '{days} days',
                        %s, %s::jsonb
                    ) RETURNING id;
                    """,
                    (hid, price, lt, fid, payload_j),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO p2p_marketplace (
                        seller_id, price, status, listing_type, fleet_id, payload_json
                    ) VALUES (%s, %s, 'active', 'BUY_NOW', %s, %s::jsonb)
                    RETURNING id;
                    """,
                    (hid, price, fid, payload_j),
                )
            new_id = cur.fetchone()[0]
        conn.commit()
        return JSONResponse({"ok": True, "listing_id": int(new_id)})
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


@app.post("/api/v1/p2p/buy")
def p2p_buy_listing(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    if not _p2p_rate_limit_ok(hid):
        raise HTTPException(status_code=429, detail="rate_limit")
    listing_id = int(body.get("listing_id") or 0)
    if listing_id <= 0:
        raise HTTPException(status_code=400, detail="bad_listing")
    pool = _get_pg_pool()
    if pool is None:
        raise HTTPException(status_code=503, detail="pg_unavailable")
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, seller_id, price, listing_type, fleet_id, status
                FROM p2p_marketplace WHERE id = %s FOR UPDATE;
                """,
                (listing_id,),
            )
            row = cur.fetchone()
            if not row or str(row["status"]) not in ("active", "leased", "auction"):
                conn.rollback()
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            ltype_row = str(row.get("listing_type") or "BUY_NOW").upper()
            if ltype_row == "AUCTION":
                conn.rollback()
                return JSONResponse(
                    {"ok": False, "error": "auction_use_bid"}, status_code=400
                )
            seller = str(row["seller_id"] or "")[:128]
            price = float(row["price"] or 0)
            item_key = str(row.get("fleet_id") or row.get("aircraft_id") or listing_id)
            tariff_ok, avg_p = _p2p_tariff_ok("market", item_key, price)
            if not tariff_ok:
                cur.execute(
                    "UPDATE p2p_marketplace SET status = 'SUSPENDED' WHERE id = %s;",
                    (listing_id,),
                )
                conn.commit()
                _p2p_suspend_trade_alert(hid, price, avg_p, context="P2P-BUY")
                return JSONResponse(
                    {"ok": False, "error": "tariff_suspended", "status": "SUSPENDED"},
                    status_code=403,
                )
            if seller == hid:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "self_listing"}, status_code=400)
            cur.execute(
                "SELECT credits FROM users WHERE hardware_id = %s FOR UPDATE;",
                (hid,),
            )
            brow = cur.fetchone()
            if not brow or float(brow["credits"] or 0) + 1e-6 < price:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=402)
            cur.execute(
                "UPDATE users SET credits = credits - %s WHERE hardware_id = %s;",
                (price, hid),
            )
            if seller:
                cur.execute(
                    "UPDATE users SET credits = credits + %s WHERE hardware_id = %s;",
                    (round(price * 0.98, 2), seller),
                )
            ltype = str(row["listing_type"] or "sale")
            if ltype == "lease_48h":
                cur.execute(
                    """
                    UPDATE p2p_marketplace
                    SET status = 'leased', buyer_id = %s,
                        lease_expires = CURRENT_TIMESTAMP + INTERVAL '2 days'
                    WHERE id = %s;
                    """,
                    (hid, listing_id),
                )
                fleet_id = row.get("fleet_id")
                if fleet_id:
                    cur.execute(
                        "UPDATE fleet SET owner_username = %s WHERE id = %s;",
                        (hid, fleet_id),
                    )
            else:
                cur.execute(
                    """
                    UPDATE p2p_marketplace SET status = 'sold', buyer_id = %s WHERE id = %s;
                    """,
                    (hid, listing_id),
                )
                fleet_id = row.get("fleet_id")
                if fleet_id:
                    cur.execute(
                        "UPDATE fleet SET owner_username = %s WHERE id = %s;",
                        (hid, fleet_id),
                    )
        conn.commit()
        return JSONResponse({"ok": True, "listing_id": listing_id, "buyer_id": hid})
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


@app.post("/api/v1/p2p/bid")
def p2p_place_bid(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    if not _p2p_rate_limit_ok(hid):
        raise HTTPException(status_code=429, detail="rate_limit")
    listing_id = int(body.get("listing_id") or 0)
    bid_amount = float(body.get("bid") or body.get("amount") or 0)
    market = str(body.get("market") or "aircraft").strip().lower()
    if listing_id <= 0 or bid_amount <= 0:
        raise HTTPException(status_code=400, detail="bad_bid")
    pool = _get_pg_pool()
    if pool is None:
        raise HTTPException(status_code=503, detail="pg_unavailable")
    conn = pool.getconn()
    table = "p2p_parts_market" if market == "parts" else "p2p_marketplace"
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                f"""
                SELECT id, seller_id, price, status, listing_type, current_bid,
                       highest_bidder_id, auction_expires, item_id, fleet_id
                FROM {table} WHERE id = %s FOR UPDATE;
                """,
                (listing_id,),
            )
            row = cur.fetchone()
            if not row or str(row["status"]) not in ("active", "auction"):
                conn.rollback()
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            if str(row.get("listing_type") or "").upper() != "AUCTION":
                conn.rollback()
                return JSONResponse({"ok": False, "error": "not_auction"}, status_code=400)
            seller = str(row["seller_id"] or "")[:128]
            if seller == hid:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "self_bid"}, status_code=400)
            min_bid = max(
                float(row["price"] or 0),
                float(row["current_bid"] or 0) * 1.02,
                float(row["current_bid"] or 0) + 100.0,
            )
            if bid_amount + 1e-6 < min_bid:
                conn.rollback()
                return JSONResponse(
                    {"ok": False, "error": "bid_too_low", "min_bid": min_bid},
                    status_code=400,
                )
            item_key = str(
                row.get("item_id") or row.get("fleet_id") or listing_id
            )
            tariff_ok, avg_p = _p2p_tariff_ok(
                "parts" if market == "parts" else "market", item_key, bid_amount
            )
            if not tariff_ok:
                cur.execute(
                    f"UPDATE {table} SET status = 'SUSPENDED' WHERE id = %s;",
                    (listing_id,),
                )
                conn.commit()
                _p2p_suspend_trade_alert(hid, bid_amount, avg_p, context="P2P-BID")
                return JSONResponse(
                    {"ok": False, "error": "tariff_suspended"}, status_code=403
                )
            cur.execute(
                "SELECT credits FROM users WHERE hardware_id = %s FOR UPDATE;",
                (hid,),
            )
            brow = cur.fetchone()
            if not brow or float(brow["credits"] or 0) + 1e-6 < bid_amount:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=402)
            prev_bidder = str(row.get("highest_bidder_id") or "")[:128]
            prev_bid = float(row.get("current_bid") or 0)
            if prev_bidder and prev_bid > 0:
                cur.execute(
                    "UPDATE users SET credits = credits + %s WHERE hardware_id = %s;",
                    (prev_bid, prev_bidder),
                )
            cur.execute(
                "UPDATE users SET credits = credits - %s WHERE hardware_id = %s;",
                (bid_amount, hid),
            )
            cur.execute(
                f"""
                UPDATE {table}
                SET current_bid = %s, highest_bidder_id = %s, status = 'auction'
                WHERE id = %s;
                """,
                (bid_amount, hid, listing_id),
            )
        conn.commit()
        return JSONResponse(
            {"ok": True, "listing_id": listing_id, "bid": bid_amount, "bidder": hid}
        )
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


