@app.post("/api/v1/p2p/parts/list")
def p2p_parts_list(body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = str(body.get("hardware_id") or "").strip()[:128]
    item_id = int(body.get("item_id") or 0)
    price = float(body.get("price") or 0)
    days = int(body.get("auction_days") or body.get("days") or 1)
    if days not in (1, 2, 3):
        days = 1
    listing_type = str(body.get("listing_type") or "BUY_NOW").upper()[:16]
    if not hid or item_id <= 0 or price <= 0:
        raise HTTPException(status_code=400, detail="bad_request")
    if not _p2p_rate_limit_ok(hid):
        raise HTTPException(status_code=429, detail="rate_limit")
    pool = _get_pg_pool()
    if pool is None:
        raise HTTPException(status_code=503, detail="pg_unavailable")
    conn = pool.getconn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id FROM user_warehouse
                WHERE id = %s AND user_id = %s AND status = 'STORED' FOR UPDATE;
                """,
                (item_id, hid),
            )
            if not cur.fetchone():
                conn.rollback()
                return JSONResponse({"ok": False, "error": "item_not_owned"}, status_code=404)
            exp_sql = (
                f"CURRENT_TIMESTAMP + INTERVAL '{days} days'"
                if listing_type == "AUCTION"
                else "NULL"
            )
            cur.execute(
                f"""
                INSERT INTO p2p_parts_market (
                    seller_id, item_id, price, status, listing_type, auction_expires
                ) VALUES (%s, %s, %s, 'active', %s, {exp_sql})
                RETURNING id;
                """,
                (hid, item_id, price, listing_type),
            )
            lid = int(cur.fetchone()[0])
            cur.execute(
                "UPDATE user_warehouse SET status = 'LISTED' WHERE id = %s;",
                (item_id,),
            )
        conn.commit()
        return JSONResponse({"ok": True, "listing_id": lid})
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


@app.post("/api/v1/p2p/parts/buy")
def p2p_parts_buy(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    if not _p2p_rate_limit_ok(hid):
        raise HTTPException(status_code=429, detail="rate_limit")
    listing_id = int(body.get("listing_id") or 0)
    if listing_id <= 0:
        raise HTTPException(status_code=400, detail="bad_listing")
    pool = _get_pg_pool()
    if pool is None:
        raise HTTPException(status_code=503, detail="pg_unavailable")
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT id, seller_id, item_id, price, status, listing_type
                FROM p2p_parts_market WHERE id = %s FOR UPDATE;
                """,
                (listing_id,),
            )
            row = cur.fetchone()
            if not row or str(row["status"]) not in ("active", "auction"):
                conn.rollback()
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            if str(row.get("listing_type") or "").upper() == "AUCTION":
                conn.rollback()
                return JSONResponse({"ok": False, "error": "auction_use_bid"}, status_code=400)
            seller = str(row["seller_id"] or "")[:128]
            price = float(row["price"] or 0)
            item_id = int(row["item_id"] or 0)
            tariff_ok, avg_p = _p2p_tariff_ok("parts", str(item_id), price)
            if not tariff_ok:
                cur.execute(
                    "UPDATE p2p_parts_market SET status = 'SUSPENDED' WHERE id = %s;",
                    (listing_id,),
                )
                conn.commit()
                _p2p_suspend_trade_alert(hid, price, avg_p, context="PARTS-BUY")
                return JSONResponse({"ok": False, "error": "tariff_suspended"}, status_code=403)
            if seller == hid:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "self_listing"}, status_code=400)
            cur.execute(
                "SELECT credits FROM users WHERE hardware_id = %s FOR UPDATE;",
                (hid,),
            )
            brow = cur.fetchone()
            if not brow or float(brow["credits"] or 0) + 1e-6 < price:
                conn.rollback()
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=402)
            cur.execute(
                "UPDATE users SET credits = credits - %s WHERE hardware_id = %s;",
                (price, hid),
            )
            if seller:
                cur.execute(
                    "UPDATE users SET credits = credits + %s WHERE hardware_id = %s;",
                    (round(price * 0.98, 2), seller),
                )
            cur.execute(
                "UPDATE user_warehouse SET user_id = %s, status = 'STORED' WHERE id = %s;",
                (hid, item_id),
            )
            cur.execute(
                "UPDATE p2p_parts_market SET status = 'sold' WHERE id = %s;",
                (listing_id,),
            )
        conn.commit()
        return JSONResponse({"ok": True, "listing_id": listing_id, "item_id": item_id})
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    finally:
        pool.putconn(conn)


def _p2p_auction_settle_once() -> int:
    pool = _get_pg_pool()
    if pool is None:
        return 0
    settled = 0
    conn = pool.getconn()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            for table, is_parts in (
                ("p2p_marketplace", False),
                ("p2p_parts_market", True),
            ):
                cur.execute(
                    f"""
                    SELECT * FROM {table}
                    WHERE status = 'auction'
                      AND listing_type = 'AUCTION'
                      AND auction_expires IS NOT NULL
                      AND auction_expires < NOW()
                    FOR UPDATE;
                    """
                )
                for row in cur.fetchall() or []:
                    winner = str(row.get("highest_bidder_id") or "")[:128]
                    seller = str(row["seller_id"] or "")[:128]
                    price = float(row.get("current_bid") or row.get("price") or 0)
                    if not winner:
                        cur.execute(
                            f"UPDATE {table} SET status = 'active' WHERE id = %s;",
                            (int(row["id"]),),
                        )
                        continue
                    if is_parts:
                        item_id = int(row["item_id"] or 0)
                        cur.execute(
                            "UPDATE user_warehouse SET user_id = %s, status = 'STORED' WHERE id = %s;",
                            (winner, item_id),
                        )
                    else:
                        fleet_id = row.get("fleet_id")
                        if fleet_id:
                            cur.execute(
                                "UPDATE fleet SET owner_username = %s WHERE id = %s;",
                                (winner, fleet_id),
                            )
                    if seller and price > 0:
                        cur.execute(
                            "UPDATE users SET credits = credits + %s WHERE hardware_id = %s;",
                            (round(price * 0.98, 2), seller),
                        )
                    cur.execute(
                        f"UPDATE {table} SET status = 'sold' WHERE id = %s;",
                        (int(row["id"]),),
                    )
                    settled += 1
                    try:
                        from skytycoon_profile_cloud import discord_admin_alert

                        discord_admin_alert(
                            "🔨 Auktion zu Ende",
                            f"Listing {row['id']}: {winner[:32]} gewinnt für {price:.0f} CR",
                        )
                    except Exception:
                        pass
        conn.commit()
    except Exception as exc:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[p2p] auction settle: {exc!s}")
    finally:
        pool.putconn(conn)
    return settled


async def _p2p_auction_settlement_loop() -> None:
    while True:
        try:
            n = await asyncio.to_thread(_p2p_auction_settle_once)
            if n:
                _server_log_line(f"[p2p] auctions settled: {n}")
        except Exception as exc:  # noqa: BLE001
            _server_log_line(f"[p2p] auction loop: {exc!s}")
        await asyncio.sleep(60)


