@app.post("/api/v1/market/reserve/{listing_id}")
def market_reserve(request: Request, listing_id: str, body: dict) -> JSONResponse:
    """60-Sekunden-Lock vor atomarem Kauf (Desktop P2P)."""
    hid = _desktop_api_auth(request, body)
    buyer = str(body.get("buyer_id", hid) or "").strip()[:120] or hid
    lid = str(listing_id or "").strip()[:64]
    if not lid:
        raise HTTPException(status_code=400, detail="bad_listing")
    now = time.time()
    lock_until = now + 60.0
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute("BEGIN IMMEDIATE;")
        row = conn.execute(
            "SELECT seller_id, locked_by, lock_until FROM market_listings WHERE id = ?;",
            (lid,),
        ).fetchone()
        if not row:
            conn.rollback()
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        seller, locked_by, lock_ts = str(row[0] or ""), str(row[1] or ""), float(row[2] or 0)
        if seller == buyer or seller == hid:
            conn.rollback()
            return JSONResponse({"ok": False, "error": "self_listing"}, status_code=400)
        if lock_ts > now and locked_by and locked_by not in (buyer, hid):
            conn.rollback()
            return JSONResponse({"ok": False, "error": "reserved_other"}, status_code=409)
        conn.execute(
            "UPDATE market_listings SET locked_by = ?, lock_until = ? WHERE id = ?;",
            (buyer or hid, lock_until, lid),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    return JSONResponse({"ok": True, "reserved_until": lock_until, "listing_id": lid})


@app.post("/api/v1/market/buy/{listing_id}")
def market_buy(request: Request, listing_id: str, body: dict) -> JSONResponse:
    """Atomarer Kauf: Listing-Sperre, Käufer-Guthaben, 2 % Gebühr (Senke), 98 % an Verkäufer, Flugzeug → planes_json."""
    hid = _desktop_api_auth(request, body)
    lid = str(listing_id or "").strip()[:64]
    if not lid:
        raise HTTPException(status_code=400, detail="bad_listing")
    srv = sqlite3.connect(str(SERVER_DB_PATH))
    usr = sqlite3.connect(str(USER_DB_PATH))
    seller = ""
    raw = "{}"
    fee = 0.0
    seller_payout = 0.0
    buyer_credits_after = 0.0
    try:
        srv.execute("BEGIN IMMEDIATE;")
        row = srv.execute(
            """
            SELECT seller_id, price_credits, payload_json, locked_by, lock_until
            FROM market_listings WHERE id = ?;
            """,
            (lid,),
        ).fetchone()
        if not row:
            srv.rollback()
            raise HTTPException(status_code=404, detail="not_found")
        seller = str(row[0])
        price = float(row[1] or 0)
        raw = str(row[2] or "{}")
        locked_by = str(row[3] or "")
        lock_until = float(row[4] or 0)
        buyer_tag = str(body.get("buyer_id", hid) or "").strip()[:120] or hid
        now_ts = time.time()
        if lock_until > now_ts and locked_by and locked_by not in (buyer_tag, hid):
            srv.rollback()
            usr.rollback()
            return JSONResponse({"ok": False, "error": "reserved_other"}, status_code=409)
        if lock_until > 0 and lock_until < now_ts and locked_by:
            srv.rollback()
            usr.rollback()
            return JSONResponse({"ok": False, "error": "reservation_expired"}, status_code=409)
        if price <= 0:
            srv.rollback()
            return JSONResponse({"ok": False, "error": "invalid_price"})
        usr.execute("BEGIN IMMEDIATE;")
        brow = usr.execute(
            "SELECT credits, planes_json FROM users WHERE hardware_id = ?;", (hid,)
        ).fetchone()
        if not brow:
            usr.rollback()
            srv.rollback()
            raise HTTPException(status_code=404, detail="buyer_not_found")
        buyer_credits = float(brow[0] or 0)
        if buyer_credits + 1e-6 < price:
            usr.rollback()
            srv.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"})
        fee = round(price * 0.02, 2)
        seller_payout = round(price * 0.98, 2)
        usr.execute(
            "UPDATE users SET credits = credits - ? WHERE hardware_id = ?;",
            (price, hid),
        )
        seller_hid = seller.strip()[:64]
        if seller_hid and seller_hid != hid:
            srow = usr.execute(
                "SELECT 1 FROM users WHERE hardware_id = ?;", (seller_hid,)
            ).fetchone()
            if srow:
                usr.execute(
                    "UPDATE users SET credits = credits + ? WHERE hardware_id = ?;",
                    (seller_payout, seller_hid),
                )
        try:
            payload_obj = json.loads(raw) if raw.strip() else {}
        except json.JSONDecodeError:
            payload_obj = {}
        if not isinstance(payload_obj, dict):
            payload_obj = {"payload": payload_obj}
        planes = _planes_json_list(str(brow[1] or "[]"))
        planes.append(payload_obj)
        usr.execute(
            "UPDATE users SET planes_json = ? WHERE hardware_id = ?;",
            (json.dumps(planes, ensure_ascii=False), hid),
        )
        srv.execute("DELETE FROM market_listings WHERE id = ?;", (lid,))
        buyer_row = usr.execute(
            "SELECT credits FROM users WHERE hardware_id = ?;", (hid,)
        ).fetchone()
        buyer_credits_after = float(buyer_row[0] or 0) if buyer_row else 0.0
        usr.commit()
        srv.commit()
    except HTTPException:
        raise
    except Exception:
        try:
            usr.rollback()
        except Exception:
            pass
        try:
            srv.rollback()
        except Exception:
            pass
        raise
    finally:
        usr.close()
        srv.close()
    return JSONResponse(
        {
            "ok": True,
            "fee_credits": fee,
            "seller_payout": seller_payout,
            "payload_json": raw,
            "seller_id": seller,
            "credits": buyer_credits_after,
        }
    )


@app.get("/api/v1/support/chat/{hardware_id}")
def support_chat_get(hardware_id: str) -> JSONResponse:
    hid = (hardware_id or "").strip()[:128]
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        cur = conn.execute(
            """
            SELECT id, sender, message_text, ts FROM support_messages
            WHERE hardware_id = ? ORDER BY id ASC LIMIT 500;
            """,
            (hid,),
        )
        msgs = [
            {"id": r[0], "sender": r[1], "message_text": r[2], "timestamp": r[3]}
            for r in cur.fetchall()
        ]
        head = conn.execute(
            "SELECT status, pilot_name, last_message_ts FROM support_tickets WHERE hardware_id = ?;",
            (hid,),
        ).fetchone()
        status = str(head[0]) if head else "open"
        return JSONResponse({"messages": msgs, "status": status})
    finally:
        conn.close()


@app.post("/api/v1/support/chat/{hardware_id}")
def support_chat_post(hardware_id: str, body: dict) -> JSONResponse:
    hid = (hardware_id or "").strip()[:128]
    sender = str(body.get("sender", "user"))[:16]
    txt = str(body.get("message_text", ""))[:4000]
    pilot = str(body.get("pilot_name", ""))[:80]
    ts = float(body.get("timestamp", time.time()))
    if not hid or not txt:
        raise HTTPException(status_code=400, detail="bad_request")
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        conn.execute(
            """
            INSERT INTO support_messages (hardware_id, sender, message_text, ts)
            VALUES (?, ?, ?, ?);
            """,
            (hid, sender, txt, ts),
        )
        conn.execute(
            """
            INSERT INTO support_tickets (hardware_id, status, pilot_name, last_message_ts)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(hardware_id) DO UPDATE SET
                status = excluded.status,
                pilot_name = CASE WHEN excluded.pilot_name != '' THEN excluded.pilot_name ELSE pilot_name END,
                last_message_ts = excluded.last_message_ts;
            """,
            (
                hid,
                "replied" if sender == "admin" else "open",
                pilot,
                ts,
            ),
        )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True})


