    welcome_button = _web_tx(user_lang, "welcome_button")

    balance_de = _format_credits_display(credits, "de")
    balance_en = _format_credits_display(credits, "en")

    return {
        "hardware_id": user_data["hardware_id"],
        "pilot_name": user_data["pilot_name"],
        "balance_display_de": balance_de,
        "balance_display_en": balance_en,
        "user_has_seen_welcome": user_has_seen_welcome,
        "show_welcome_intro": user_has_seen_welcome == 0,
        "welcome_title": welcome_title,
        "welcome_text": welcome_text,
        "welcome_button": welcome_button,
        "user_selected_language": user_lang,
        "license_masked": license_masked,
        "has_activated_license": has_activated_license,
        "credits": credits,
        "xp": xp,
        "reputation": reputation,
        "credit_score": credit_score,
        "loan_debt": loan_debt,
        "strikes": strikes,
        "branches": branches_lines,
        "branch_plaques": branch_plaques,
        "rating_plaques": rating_plaques,
        "ratings_hint": ratings_hint,
        "user_data": user_data,
        "chart_labels_json": json.dumps(chart_labels, ensure_ascii=False),
        "chart_values_json": json.dumps(chart_vals, ensure_ascii=False),
        "current_shop_price": _web_current_shop_price_display(),
        "flight_logs": flight_logs,
        "alliances_public": _alliance_public_list(),
        "alliance": alliance_ctx,
        "user_inventory_list": user_inventory_list,
        "unlocked_awards_keys": unlocked_awards_keys,
        "pilot_achievements": pilot_achievements,
        "module_catalog": _web_module_catalog_for_hid(hid64, lang),
    }


