@app.get("/api/v1/web/leaderboard/top")
def web_leaderboard_top() -> JSONResponse:
    """M213: Top-3-Allianzen (oder Top-Piloten als Fallback) für Startseiten-Podest."""
    alliances: list[dict[str, Any]] = []
    for row in _alliances_public_leaderboard(3):
        item = dict(row)
        item["credits_fmt"] = _fmt_credits_dot(float(item.get("credits") or 0))
