@app.post("/api/v1/web/alliance/apply")
async def web_alliance_apply(request: Request) -> JSONResponse:
    """Geschützte Web-Bewerbung — nur verifizierte Lizenz-Inhaber."""
    hid_raw, needs_refresh = _web_postgres_session_refresh(request)
    if not hid_raw:
        raise HTTPException(status_code=403, detail="unauthorized")
    hid64 = str(hid_raw).strip()[:64]
    is_verified, has_license = _sync_user_license_flags(hid64)
    if is_verified != 1 or has_license != 1:
        raise HTTPException(status_code=403, detail="license_required")
    if _alliance_member_row(hid64):
        return JSONResponse(
            {"ok": False, "error": "already_member"}, status_code=400
        )
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    aid = str(body.get("alliance_id", "") or "").strip()[:32]
    if not aid:
        raise HTTPException(status_code=400, detail="bad_id")
    pilot_name = _pilot_display_name_for_hid(hid64)
    conn = get_db_connection()
    try:
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT 1 FROM alliances WHERE alliance_id = %s;", (aid,))
            ex = cur.fetchone()
            if not ex:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            cur.execute(
                """
                SELECT status FROM alliance_applications
                WHERE alliance_id = %s AND hardware_id = %s;
                """,
                (aid, hid64),
            )
            pending = cur.fetchone()
            if pending and str(pending["status"]) == "pending":
                response = JSONResponse({"ok": False, "error": "already_pending"})
                if needs_refresh:
                    _web_apply_session_refresh(response, request, hid_raw)
                return response
            cur.execute(
                """
                INSERT INTO alliance_applications (
                    alliance_id, hardware_id, pilot_name, status, created_ts
                ) VALUES (%s, %s, %s, 'pending', %s)
                ON CONFLICT(alliance_id, hardware_id) DO UPDATE SET
                    pilot_name = EXCLUDED.pilot_name,
                    status = 'pending',
                    created_ts = EXCLUDED.created_ts;
                """,
                (aid, hid64, pilot_name[:120], time.time()),
            )
        conn.commit()
    finally:
        conn.close()
    response = JSONResponse({"ok": True, "status": "pending"})
    if needs_refresh:
        _web_apply_session_refresh(response, request, hid_raw)
    return response


