@app.post("/api/v1/alliance/applications/accept")
def alliance_applications_accept(request: Request, body: dict[str, Any]) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) not in ("ceo", "co_leader"):
        raise HTTPException(status_code=403, detail="forbidden")
    alliance_id = mem[0]
    app_id = int(body.get("application_id", body.get("id", 0)) or 0)
    target_hid = str(body.get("hardware_id", "") or "").strip()[:64]
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        if app_id:
            row = conn.execute(
                """
                SELECT hardware_id, pilot_name FROM alliance_applications
                WHERE id = ? AND alliance_id = ? AND status = 'pending';
                """,
                (app_id, alliance_id),
            ).fetchone()
        elif target_hid:
            row = conn.execute(
                """
                SELECT hardware_id, pilot_name FROM alliance_applications
                WHERE hardware_id = ? AND alliance_id = ? AND status = 'pending';
                """,
                (target_hid, alliance_id),
            ).fetchone()
        else:
            raise HTTPException(status_code=400, detail="bad_request")
        if not row:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        applicant = str(row[0])
        pname = str(row[1] or _pilot_display_name_for_hid(applicant))
        if _alliance_member_row(applicant):
            conn.execute(
                "UPDATE alliance_applications SET status = 'rejected' WHERE alliance_id = ? AND hardware_id = ?;",
                (alliance_id, applicant),
            )
            conn.commit()
            return JSONResponse({"ok": False, "error": "already_member"}, status_code=400)
        conn.execute("BEGIN IMMEDIATE;")
        conn.execute(
            """
            INSERT INTO alliance_members (
                alliance_id, hardware_id, role, contributed_credits, joined_ts
            ) VALUES (?, ?, 'trainee', 0, ?);
            """,
            (alliance_id, applicant, time.time()),
        )
        conn.execute(
            """
            UPDATE alliance_applications SET status = 'accepted'
            WHERE alliance_id = ? AND hardware_id = ?;
            """,
            (alliance_id, applicant),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return JSONResponse({"ok": True, "hardware_id": applicant, "pilot_name": pname})


