@app.get("/purchase-success", response_class=HTMLResponse, response_model=None)
async def web_purchase_success(
    request: Request, t: str = ""
) -> HTMLResponse:
    """Einmal-Anzeige des Lizenzschlüssels nach PayPal (Token aus ``server_kv``)."""
    lang = _web_lang(request)
    tok = (t or "").strip()[:220]
    err = _web_tx(lang, "pay_ok_bad_token")
    if not tok:
        return _web_page_html(
            "purchase_success.html",
            request,
            error=err,
            license_key="",
            paypal_order_id="",
            buyer_email="",
        )
    kv_k = f"paypal_show:{tok}"
    raw = _server_kv_get(kv_k)
    if not raw.strip():
        return _web_page_html(
            "purchase_success.html",
            request,
            error=err,
            license_key="",
            paypal_order_id="",
            buyer_email="",
        )
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return _web_page_html(
            "purchase_success.html",
            request,
            error=err,
            license_key="",
            paypal_order_id="",
            buyer_email="",
        )
    lk = str(data.get("license_key") or "").strip()
    oid = str(data.get("paypal_order_id") or "").strip()
    em = str(data.get("email") or "").strip()
    _server_kv_delete(kv_k)
    if not lk:
        return _web_page_html(
            "purchase_success.html",
            request,
            error=err,
            license_key="",
            paypal_order_id="",
            buyer_email="",
        )
    return _web_page_html(
        "purchase_success.html",
        request,
        error=None,
        license_key=lk,
        paypal_order_id=oid,
        buyer_email=em,
    )


@app.post("/portal/purchase/promo", response_class=HTMLResponse)
async def portal_purchase_promo(
    request: Request,
    background_tasks: BackgroundTasks,
    promo_code: str = Form(""),
) -> RedirectResponse:
    """100-%-Promo nur für eingeloggte Portal-Nutzer (keine freie E-Mail-Eingabe)."""
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
    promo_raw = (promo_code or "").strip()
    if not promo_raw:
        return RedirectResponse(
            "/dashboard?promo_err=invalid", status_code=http_status.HTTP_303_SEE_OTHER
        )
    st = _portal_promo_form_status(promo_raw)
    if st == "invalid":
        return RedirectResponse(
            "/dashboard?promo_err=invalid", status_code=http_status.HTTP_303_SEE_OTHER
        )
    if st == "expired":
        return RedirectResponse(
            "/dashboard?promo_err=expired", status_code=http_status.HTTP_303_SEE_OTHER
        )
    if st == "not100":
        return RedirectResponse(
            "/dashboard?promo_err=not100", status_code=http_status.HTTP_303_SEE_OTHER
        )
    lk = _portal_grant_purchased_license(
        hid,
        background_tasks,
        promo_code=promo_raw,
        paypal_capture_id="",
        paypal_order_id="",
        free_promo=True,
    )
    if not lk:
        return RedirectResponse(
            "/dashboard?promo_err=invalid", status_code=http_status.HTTP_303_SEE_OTHER
        )
    return RedirectResponse(
        "/dashboard?purchased=1", status_code=http_status.HTTP_303_SEE_OTHER
    )


@app.post("/api/v1/web/account/resend_welcome")
async def web_account_resend_welcome(
    payload: dict[str, Any], background_tasks: BackgroundTasks
) -> JSONResponse:
    """Erneuter Versand Lizenzschlüssel (Rate-Limit). Kollegen ohne Mail: E-Mail erneut anfordern."""
    email_raw = str(payload.get("email") or "").strip()[:200]
    email_c = email_raw.lower()
    if "@" not in email_c:
        return JSONResponse(
            {"status": "error", "message": "Ungültige E-Mail."},
            status_code=400,
        )
    rl_key = f"resend_welcome:{email_c}"
    last = _server_kv_get(rl_key).strip()
    now = time.time()
    if last:
        try:
            if now - float(last) < 120.0:
                return JSONResponse(
                    {
                        "status": "error",
                        "message": "Bitte 2 Minuten warten, dann erneut versuchen.",
                    },
                    status_code=429,
                )
        except ValueError:
            pass
    row = _lookup_license_email_row(email_c)
    if not row:
        return JSONResponse(
            {
                "status": "ok",
                "message": (
                    "Falls ein Konto existiert, wurde eine E-Mail ausgelöst "
                    "(Datenschutz)."
                ),
            }
        )
    pilot, lk, st = row
    if not pilot:
        pilot = email_c.split("@", 1)[0][:120]
    _server_kv_set(rl_key, str(now))
    background_tasks.add_task(
        _bg_send_welcome_and_license_email_bilingual,
        email_c,
        pilot,
        _CREDENTIALS_RESEND_PW_HINT,
        lk,
    )
    _append_admin_log(f"[email] resend_welcome angefordert {email_c!r} status={st!r}")
    return JSONResponse(
        {
            "status": "success",
            "message": (
                "E-Mail-Versand gestartet. Bitte Posteingang und Spam prüfen "
                "(kann 1–2 Minuten dauern)."
            ),
        }
    )


