@app.post("/api/v1/web/promo/apply_tester")
async def apply_tester_discount_flow(
    payload: dict[str, Any], background_tasks: BackgroundTasks
) -> JSONResponse:
    """M191: 100-%-Tester-Registrierung — DB sofort, E-Mail entkoppelt im Hintergrund."""
    pilot_name = str(payload.get("pilot_name") or "").strip()[:120]
    email_raw = str(payload.get("email") or "").strip()[:200]
    raw_password = str(payload.get("password") or "")
    email_c = email_raw.lower()
    if not pilot_name or not raw_password or "@" not in email_c:
        return JSONResponse(
            {"status": "error", "message": "pilot_name, email und password erforderlich."},
            status_code=400,
        )
    salt, ph = _password_hash_store(raw_password)
    hid = str(payload.get("hardware_id") or "").strip()[:128]
    if not hid:
        hid = f"web-promo-{hashlib.sha256(email_c.encode()).hexdigest()[:24]}"
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        if _email_has_activated_license(conn, email_c):
            return JSONResponse(
                {
                    "status": "error",
                    "message": "E-Mail ist bereits mit einer aktiven Lizenz registriert.",
                },
                status_code=409,
            )
    finally:
        conn.close()
    lang = str(payload.get("selected_language") or "de").strip().lower()[:8]
    if lang not in ("de", "en"):
        lang = "de"
    generated_key = _autopilot_fulfill_customer_license(
        email_c,
        pilot_name,
        hardware_id=hid,
        lang=lang,
        background_tasks=background_tasks,
        amount_eur=0.0,
        paypal_order_id="PROMO100",
        promo_code="TESTER100",
        status="activated",
        password_salt=salt,
        password_hash=ph,
        reuse_existing_unused=False,
        free_promo=True,
    )
    if not generated_key:
        return JSONResponse(
            {"status": "error", "message": "Lizenz konnte nicht erstellt werden."},
            status_code=500,
        )
    hid64 = hid[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hid64,),
        )
        uconn.execute(
            """
            UPDATE users SET license_key = ?, license_activated = 1, has_license = 1,
            is_verified = 1
            WHERE hardware_id = ?;
            """,
            (generated_key, hid64),
        )
        uconn.commit()
    finally:
        uconn.close()
    background_tasks.add_task(
        _bg_send_welcome_and_license_email_bilingual,
        email_c,
        pilot_name,
        raw_password,
        generated_key,
    )
    print(
        f"[PROMO SUCCESS] Lizenz {generated_key} für {pilot_name} registriert "
        "(Autopilot ST-Key + PG + Mail)."
    )
    _append_admin_log(
        f"[promo] apply_tester email={email_c!r} pilot={pilot_name!r} key={generated_key}"
    )
    return JSONResponse(
        {
            "status": "success",
            "message": (
                "Konto erfolgreich erstellt! Ihr Lizenzschlüssel wurde an Ihr Postfach gesendet."
            ),
            "license_key": generated_key,
        }
    )


@app.post("/register", response_class=HTMLResponse, response_model=None)
async def web_register_post(
    request: Request,
    background_tasks: BackgroundTasks,
    email: str = Form(...),
    hardware_id: str = Form(""),
    pilot_name: str = Form(...),
    password: str = Form(...),
    license_key: str = Form(""),
    selected_language: str = Form("de"),
) -> HTMLResponse | RedirectResponse:
    """Meilenstein 190/192: Lizenz in DB, Willkommens-Mail asynchron im Hintergrund."""
    lang = _web_lang(request)
    sel_lang = (selected_language or lang or "de").strip().lower()[:8]
    if sel_lang not in ("de", "en"):
        sel_lang = "de"
    key_in = (license_key or "").strip()
    pilot = pilot_name.strip()[:120]
    raw_password = password
    hid = _web_resolve_registration_hardware_id("")
    email_c = email.strip()[:200].lower()
    email_store = email.strip()[:200]
    if not pilot and email_c and "@" in email_c:
        pilot = email_c.split("@", 1)[0][:120]
    if not raw_password or "@" not in email_c:
        return _web_page_html(
            "register.html", request, error=_web_tx(lang, "err_fill")
        )
    if not pilot:
        return _web_page_html(
            "register.html",
            request,
            error=(
                "Bitte Pilotenname eingeben (Feld „Pilot“)."
                if lang == "de"
                else "Please enter a pilot display name."
            ),
        )
    if _pilot_name_taken_global(pilot, email_c):
        name_err = (
            "Dieser Pilotenname ist bereits vergeben. Wähle einen Vorschlag."
            if lang == "de"
            else "This pilot name is already taken. Pick a suggestion below."
        )
        return _web_page_html(
            "register.html",
            request,
            error=name_err,
            name_suggestions=_pilot_name_suggestions(pilot, email_c),
        )

    use_key = ""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        if key_in:
            row = None
            use_key = key_in
            for cand in (key_in, key_in.upper()):
                row = conn.execute(
                    """
                    SELECT status, hardware_id, customer_email
                    FROM license_keys WHERE license_key = ?;
                    """,
                    (cand,),
                ).fetchone()
                if row:
                    use_key = cand
                    break
            if not row or str(row[0] or "") != "unused":
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_bad_key"),
                )
            bound_hw = str(row[1] or "").strip()
            shop_email = str(row[2] or "").strip().lower()
            if bound_hw and bound_hw != hid:
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_hw_mismatch"),
                )
            if shop_email and shop_email != email_c:
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_email_mismatch"),
                )
        else:
            shop_row = _lookup_license_email_row(email_c)
            if shop_row and str(shop_row[2] or "") == "activated":
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_already_licensed_web"),
                )
            if shop_row and str(shop_row[2] or "") == "unused":
                use_key = str(shop_row[1] or "").strip()
            elif _email_has_purchased_license(conn, email_c):
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_already_licensed_web"),
                )
            elif _email_registered_anywhere(email_c):
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_account_exists_login"),
                )
            else:
                use_key = ""
    finally:
        conn.close()

    salt, ph = _password_hash_store(raw_password)
    ts = time.time()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        activate_key = (use_key or key_in).strip()
        if not activate_key:
            auto_key = _autopilot_fulfill_customer_license(
                email_store,
                pilot,
                hardware_id=hid,
                lang=sel_lang,
                status="activated",
                password_salt=salt,
                password_hash=ph,
                background_tasks=None,
                send_email=False,
                reuse_existing_unused=False,
                skip_pg_bind=True,
            )
            if not auto_key:
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_register_server"),
                )
            activate_key = auto_key
            use_key = auto_key
        if activate_key:
            conn.execute(
                """
                UPDATE license_keys SET status = 'activated', hardware_id = ?,
                pilot_name = ?, password_salt = ?, password_hash = ?,
                customer_email = ?
                WHERE license_key = ?;
                """,
                (hid, pilot, salt, ph, email_store, activate_key),
            )
            conn.execute(
                "DELETE FROM web_pending_users WHERE lower(trim(email)) = ?;",
                (email_c,),
            )
            conn.execute(
                "DELETE FROM web_pending_users WHERE hardware_id = ?;",
                (hid,),
            )
        conn.commit()
    finally:
        conn.close()

    hid64 = hid[:64]
    has_license_key = bool((use_key or key_in).strip())
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        uconn.execute(
            "INSERT OR IGNORE INTO users (hardware_id, password_hash) VALUES (?, '');",
            (hid64,),
        )
        if has_license_key:
            uconn.execute(
                """
                UPDATE users SET license_key = ?, license_activated = 1, has_license = 1,
                is_verified = 1
                WHERE hardware_id = ?;
                """,
                (use_key or key_in, hid64),
            )
        else:
            uconn.execute(
                """
                UPDATE users SET license_key = '', license_activated = 0, has_license = 0,
                is_verified = 1
                WHERE hardware_id = ?;
                """,
                (hid64,),
            )
        uconn.commit()
    finally:
        uconn.close()

    try:
        from skytycoon_profile_cloud import pg_create_fresh_portal_account

        ok_pg, pg_msg = pg_create_fresh_portal_account(
            email=email_store,
            pilot_name=pilot,
            hardware_id=hid,
            get_db_connection=get_db_connection,
            selected_language=sel_lang,
        )
        if not ok_pg:
            if pg_msg == "register_db_retry":
                ok_pg, pg_msg = pg_create_fresh_portal_account(
                    email=email_store,
                    pilot_name=pilot,
                    hardware_id=hid,
                    get_db_connection=get_db_connection,
                    selected_language=sel_lang,
                )
        if not ok_pg:
            if pg_msg in ("email_taken", "username_taken") and has_license_key:
                ok_pg = True
            elif pg_msg == "username_taken":
                name_err = (
                    "Dieser Pilotenname ist bereits vergeben. Wähle einen Vorschlag."
                    if lang == "de"
                    else "This pilot name is already taken. Pick a suggestion below."
                )
                return _web_page_html(
                    "register.html",
                    request,
                    error=name_err,
                    name_suggestions=_pilot_name_suggestions(pilot, email_c),
                )
            elif pg_msg == "email_taken":
                return _web_page_html(
                    "register.html",
                    request,
                    error=_web_tx(lang, "err_account_exists_login"),
                )
            else:
                _append_admin_log(f"[web] PG-Registrierung: {pg_msg}")
                return _web_page_html(
                    "register.html", request, error=_web_tx(lang, "err_register_server")
                )
    except Exception as exc:
        _append_admin_log(f"[web] PG-Registrierung Fehler: {exc}")
        return _web_page_html(
            "register.html", request, error=_web_tx(lang, "err_register_server")
        )

    if has_license_key:
        lk_pg = (use_key or key_in).strip()
        try:
            _pg_bind_license_to_email_account(
                email_c,
                lk_pg,
                pilot,
                hid,
                license_row_status="activated",
                selected_language=sel_lang,
            )
            _pg_bind_license_to_hardware(email_c, hid, lk_pg, pilot)
        except Exception as exc_pg:  # noqa: BLE001
            _server_log_line(f"[web] register PG bind post-create: {exc_pg!s}")

    _web_postgres_sync_login_profile(
        hid, email=email_store, pilot_name=pilot, license_active=has_license_key
    )
    _sync_user_license_flags(hid64)

    mail_ok = False
    _refresh_smtp_env()
    _sh, _sp, _su, _spw, _sf = _smtp_settings()
    if not _spw:
        _append_admin_log(
            f"[email] Web-Registrierung {email_c!r}: SMTP_PASSWORD fehlt in smtp.env — keine Mail."
        )
    elif has_license_key:
        lk_mail = (use_key or key_in).strip()
        background_tasks.add_task(
            _bg_send_welcome_and_license_email_bilingual,
            email_c,
            pilot,
            raw_password,
            lk_mail,
        )
        background_tasks.add_task(
            _autopilot_dispatch_license_emails,
            email_c,
            pilot,
            lk_mail,
            lang=sel_lang,
            amount_eur=0.0,
            paypal_order_id="REGISTER",
        )
        mail_ok = True
    else:
        mail_ok = await asyncio.to_thread(
            _send_welcome_registration_email_i18n,
            email_c,
            pilot,
            raw_password,
            sel_lang,
        )
        if not mail_ok:
            background_tasks.add_task(
                _bg_send_welcome_registration_email_i18n,
                email_c,
                pilot,
                raw_password,
                sel_lang,
            )

    _append_admin_log(
        f"[web] Registrierung email={email_c!r} hardware={hid!r} pilot={pilot!r} "
        f"mode={'shop_key' if key_in else 'portal_only'} mail_ok={mail_ok}"
    )
    return RedirectResponse(
        "/login?registered=1", status_code=http_status.HTTP_303_SEE_OTHER
    )


@app.get("/login", response_class=HTMLResponse)
async def web_login_get(request: Request) -> HTMLResponse:
    try:
        lang = _web_lang(request)
        vb = (request.query_params.get("verify") or "").strip().lower()[:16]
        reg = (request.query_params.get("registered") or "").strip()[:8]
        deleted = (request.query_params.get("deleted") or "").strip()[:8]
        info_banner = None
        if vb == "ok":
            info_banner = _web_tx(lang, "login_verify_ok")
        elif vb == "invalid":
            info_banner = _web_tx(lang, "login_verify_invalid")
        elif reg == "1":
            info_banner = _web_tx(lang, "login_check_email")
        elif deleted == "1":
            info_banner = (
                "Ihr Konto wurde gelöscht. Sie können sich neu registrieren "
                "oder mit einem anderen Konto anmelden."
                if lang == "de"
                else "Your account was deleted. You may register again "
                "or sign in with another account."
            )
        resp = _web_page_html("login.html", request, error=None, info_banner=info_banner)
        if deleted == "1" or (request.query_params.get("err") or "").strip() == "server":
            _web_clear_session_cookies(resp)
        return resp
    except Exception as exc_login:  # noqa: BLE001
        _server_log_line(f"[web] login GET failed: {exc_login!s}")
        lang = _web_lang(request)
        err = (
            "Login vorübergehend nicht verfügbar. Bitte in 1 Minute erneut versuchen."
            if lang == "de"
            else "Login temporarily unavailable. Please try again in one minute."
        )
        return _web_page_html("login.html", request, error=err)


@app.post("/login", response_class=HTMLResponse, response_model=None)
async def web_login_post(
    request: Request,
    email: str = Form(...),
    password: str = Form(...),
    pilot_name: str = Form(""),
    license_key: str = Form(""),
) -> RedirectResponse | HTMLResponse:
    lang = _web_lang(request)
    try:
        email_c = email.strip()[:200].lower()
        pw = password
        if not email_c or "@" not in email_c or not pw:
            return _web_page_html(
                "login.html",
                request,
                error=_web_tx(lang, "err_login_empty"),
            )
        conn = sqlite3.connect(str(SERVER_DB_PATH))
        purchased_license_login = False
        pending_iv: int | None = None
        row = None
        try:
            row = conn.execute(
                """
                SELECT password_salt, password_hash, pilot_name, hardware_id, license_key
                FROM license_keys
                WHERE lower(trim(customer_email)) = ? AND status = 'activated'
                ORDER BY created_ts DESC LIMIT 1;
                """,
                (email_c,),
            ).fetchone()
            if row:
                lk = str(row[4] or "").strip().upper()
                purchased_license_login = lk.startswith("ST-")
            if not row:
                row = conn.execute(
                    """
                    SELECT password_salt, password_hash, pilot_name, hardware_id,
                           COALESCE(is_verified, 1)
                    FROM web_pending_users
                    WHERE lower(trim(email)) = ?
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (email_c,),
                ).fetchone()
                if row:
                    pending_iv = int(row[4] or 1)
                    purchased_license_login = False
        finally:
            conn.close()
        if not row:
            return _web_page_html(
                "login.html",
                request,
                error=_web_tx(lang, "err_no_account"),
            )
        salt, phash, _pilot_row, hid_raw = (
            str(row[0] or ""),
            str(row[1] or ""),
            str(row[2] or ""),
            str(row[3] or ""),
        )
        _pilot = (pilot_name or _pilot_row or "").strip()[:120]
        if not _pilot and email_c and "@" in email_c:
            _pilot = email_c.split("@", 1)[0][:120]
        hid = hid_raw.strip()[:128]
        lk_web = (license_key or "").strip()[:256]
        if lk_web and lk_web.upper().startswith("ST-"):
            try:
                conn_lk = sqlite3.connect(str(SERVER_DB_PATH))
                try:
                    conn_lk.execute(
                        """
                        UPDATE license_keys SET license_key = ?, status = 'activated',
                            customer_email = ?, pilot_name = COALESCE(NULLIF(pilot_name,''), ?)
                        WHERE lower(trim(customer_email)) = lower(trim(?))
                          AND status = 'activated';
                        """,
                        (lk_web.upper(), email_c, _pilot, email_c),
                    )
                    conn_lk.commit()
                finally:
                    conn_lk.close()
            except sqlite3.Error:
                pass
        if not _password_verify_db(salt, phash, pw):
            return _web_page_html(
                "login.html", request, error=_web_tx(lang, "err_bad_password")
            )
        if pending_iv is not None and pending_iv != 1:
            return _web_page_html(
                "login.html",
                request,
                error=_web_tx(lang, "err_not_verified"),
            )
        uconn = sqlite3.connect(str(USER_DB_PATH))
        try:
            br = uconn.execute(
                "SELECT banned FROM users WHERE hardware_id = ?;", (hid[:64],)
            ).fetchone()
            if br and int(br[0] or 0) == 1:
                return _web_page_html(
                    "login.html", request, error=_web_tx(lang, "err_banned")
                )
        finally:
            uconn.close()
        try:
            pg_hid = _web_resolve_postgres_hardware_id(
                email=email_c, sqlite_hid=hid, pilot_name=_pilot
            )
        except Exception as exc_hid:
            _server_log_line(f"[web] login resolve hid failed: {exc_hid!s}")
            pg_hid = hid
        if not pg_hid:
            pg_hid = hid
        canon_web = _pg_desktop_session_isolate_and_sync(
            hid,
            email_c,
            _pilot,
            license_active=purchased_license_login,
        )
        if canon_web:
            pg_hid = canon_web
        else:
            _web_postgres_sync_login_profile(
                pg_hid,
                email=email_c,
                pilot_name=_pilot,
                license_active=purchased_license_login,
            )
        _sync_user_license_flags(pg_hid[:64])
        token = _web_issue_token(pg_hid)
        resp = RedirectResponse("/dashboard", status_code=http_status.HTTP_303_SEE_OTHER)
        _web_set_session_cookie(resp, token, request)
        return resp
    except Exception as exc_login:  # noqa: BLE001
        _server_log_line(f"[web] login POST failed email={email[:32]!r}: {exc_login!s}")
        err = (
            "Anmeldung fehlgeschlagen (Server). Bitte erneut versuchen oder Support kontaktieren."
            if lang == "de"
            else "Login failed (server). Please retry or contact support."
        )
        return _web_page_html("login.html", request, error=err)


