@app.get("/verify-email")
@app.get("/api/v1/auth/verify-email")
async def web_verify_email(t: str = "") -> RedirectResponse:
    """Double-Opt-in: Token prüfen, Konto freischalten, auf Login weiterleiten."""
    tok = (t or "").strip()[:220]
    if not tok:
        return RedirectResponse(
            "/login?verify=invalid", status_code=http_status.HTTP_303_SEE_OTHER
        )
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT 1 FROM web_pending_users
            WHERE verification_token = ? AND verification_token != '';
            """,
            (tok,),
        ).fetchone()
        if not row:
            return RedirectResponse(
                "/login?verify=invalid", status_code=http_status.HTTP_303_SEE_OTHER
            )
        conn.execute(
            """
            UPDATE web_pending_users SET is_verified = 1, verification_token = ''
            WHERE verification_token = ?;
            """,
            (tok,),
        )
        conn.commit()
    finally:
        conn.close()
    return RedirectResponse(
        "/login?verify=ok", status_code=http_status.HTTP_303_SEE_OTHER
    )


@app.get("/dashboard", response_class=HTMLResponse, response_model=None)
async def web_dashboard(request: Request) -> HTMLResponse | RedirectResponse:
    try:
        hid, needs_refresh = _web_postgres_session_refresh(request)
        if not hid:
            return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
        lang = _web_lang(request)
        ctx = _web_dashboard_context(hid, lang)
        cid = (
            os.environ.get("PAYPAL_CLIENT_ID") or PAYPAL_LIVE_CLIENT_ID_DEFAULT
        ).strip()
        mode = (os.environ.get("PAYPAL_MODE") or "live").strip().lower()
        pe = (request.query_params.get("promo_err") or "").strip().lower()
        promo_error = ""
        if pe == "invalid":
            promo_error = _web_tx(lang, "promo_err_invalid")
        elif pe == "exhausted":
            promo_error = _web_tx(lang, "promo_err_exhausted")
        elif pe == "not100":
            promo_error = _web_tx(lang, "promo_err_not100")
        elif pe == "expired":
            promo_error = _web_tx(lang, "promo_err_expired")
        purchased_ok = (request.query_params.get("purchased") or "").strip() == "1"
        _mode = (request.query_params.get("mode") or "").strip().lower()
        ingame_efb = _mode in ("ingame_efb", "msfs_panel", "msfs")
        response = _web_page_html(
            "dashboard.html",
            request,
            paypal_client_id=cid,
            paypal_mode=mode,
            promo_error=promo_error,
            purchased_ok=purchased_ok,
            ingame_efb=ingame_efb,
            **ctx,
        )
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        if needs_refresh:
            _web_apply_session_refresh(response, request, hid)
        return response
    except Exception as exc_dash:  # noqa: BLE001
        _server_log_line(f"[web] dashboard failed: {exc_dash!s}")
        return RedirectResponse("/login?err=server", status_code=http_status.HTTP_303_SEE_OTHER)


