@app.post("/api/v1/web/profile/reset_hardware")
async def web_profile_reset_hardware(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    """
    Meilenstein 167: Web-Self-Service — ``license_keys.hardware_id`` leeren,
    Cooldown in ``users.last_hardware_reset`` (30 Tage). Optional Passwort (2FA).
    """
    hid_raw = _web_parse_token(_web_raw_session_cookie(request))
    if not hid_raw or not str(hid_raw).strip():
        return JSONResponse({"ok": False, "detail": "unauthorized"}, status_code=401)
    pw_check = ""
    if isinstance(body, dict):
        pw_check = str(body.get("password", "") or "").strip()
    if pw_check:
        email = _portal_email_for_hardware(str(hid_raw).strip()[:64])
        if email:
            conn = sqlite3.connect(str(SERVER_DB_PATH))
            try:
                row = conn.execute(
                    """
                    SELECT password_salt, password_hash FROM license_keys
                    WHERE lower(trim(customer_email)) = ? AND status = 'activated'
                    ORDER BY created_ts DESC LIMIT 1;
                    """,
                    (email.lower(),),
                ).fetchone()
                if not row or not _password_verify_db(str(row[0]), str(row[1]), pw_check):
                    return JSONResponse(
                        {"ok": False, "detail": "bad_password"}, status_code=403
                    )
            finally:
                conn.close()
    hid_key = str(hid_raw).strip()[:128]
    hid64 = hid_key[:64]
    lang = _web_lang(request)

    uconn = sqlite3.connect(str(USER_DB_PATH))
    lic = ""
    last_hw = ""
    try:
        row = uconn.execute(
            """
            SELECT trim(coalesce(license_key,'')), trim(coalesce(last_hardware_reset,''))
            FROM users WHERE hardware_id = ? LIMIT 1;
            """,
            (hid64,),
        ).fetchone()
        if not row:
            return JSONResponse(
                {"ok": False, "detail": _web_tx(lang, "dash_hw_reset_err_license")},
                status_code=400,
            )
        lic, last_hw = str(row[0] or ""), str(row[1] or "")
        if not lic:
            return JSONResponse(
                {"ok": False, "detail": _web_tx(lang, "dash_hw_reset_err_license")},
                status_code=400,
            )
        prev_ts = _parse_iso_timestamp_utc(last_hw)
        if prev_ts is not None:
            if datetime.now(timezone.utc) - prev_ts < timedelta(days=30):
                return JSONResponse(
                    {
                        "ok": False,
                        "detail": _web_tx(lang, "dash_hw_reset_err_cooldown"),
                    },
                    status_code=429,
                )
        ts_now = datetime.now(timezone.utc).isoformat()
        uconn.execute(
            "UPDATE users SET last_hardware_reset = ? WHERE hardware_id = ?;",
            (ts_now, hid64),
        )
        uconn.commit()
    finally:
        uconn.close()

    pilot_log = ""
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        pr = sconn.execute(
            "SELECT pilot_name FROM license_keys WHERE trim(license_key) = ? LIMIT 1;",
            (lic,),
        ).fetchone()
        if pr:
            pilot_log = str(pr[0] or "").strip()
        if not pilot_log:
            pr2 = sconn.execute(
                """
                SELECT pilot_name FROM web_pending_users
                WHERE hardware_id = ? LIMIT 1;
                """,
                (hid_key,),
            ).fetchone()
            if pr2:
                pilot_log = str(pr2[0] or "").strip()
        sconn.execute(
            """
            UPDATE license_keys SET hardware_id = NULL
            WHERE trim(license_key) = ? AND status = 'activated';
            """,
            (lic,),
        )
        sconn.commit()
    finally:
        sconn.close()

    disp = pilot_log or "?"
    _append_admin_log(
        f"User [{disp}] hat seine Hardware-ID selbstständig zurückgesetzt."
    )
    return JSONResponse({"ok": True, "detail": _web_tx(lang, "dash_hw_reset_ok")})


