@app.post("/activate-license", response_class=HTMLResponse, response_model=None)
async def web_activate_license_post(
    request: Request,
    license_key: str = Form(...),
) -> HTMLResponse | RedirectResponse:
    lang = _web_lang(request)
    hid_raw = _web_parse_token(_web_raw_session_cookie(request))
    if not hid_raw:
        return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
    hid = hid_raw.strip()[:128]
    key = (license_key or "").strip()
    pilot_disp = ""
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        pend = conn.execute(
            """
            SELECT email, password_salt, password_hash, pilot_name
            FROM web_pending_users WHERE hardware_id = ? LIMIT 1;
            """,
            (hid,),
        ).fetchone()
        if not pend:
            return _web_page_html(
                "activate_license.html",
                request,
                error=_web_tx(lang, "act_err_no_pending_profile"),
            )
        email_c = str(pend[0] or "").strip().lower()
        salt, phash, pilot = str(pend[1] or ""), str(pend[2] or ""), str(pend[3] or "")
        pilot_disp = pilot
        if not key:
            return _web_page_html(
                "activate_license.html",
                request,
                error=_web_tx(lang, "err_fill"),
                pilot_name=pilot_disp,
            )
        row = None
        use_key = key
        for cand in (key, key.upper()):
            row = conn.execute(
                """
                SELECT status, hardware_id, customer_email
                FROM license_keys WHERE license_key = ?;
                """,
                (cand,),
            ).fetchone()
            if row:
                use_key = cand
                break
        if not row or str(row[0] or "") != "unused":
            return _web_page_html(
                "activate_license.html",
                request,
                error=_web_tx(lang, "err_bad_key"),
                pilot_name=pilot_disp,
            )
        bound_hw = str(row[1] or "").strip()
        shop_email = str(row[2] or "").strip().lower()
        if bound_hw and bound_hw != hid:
            return _web_page_html(
                "activate_license.html",
                request,
                error=_web_tx(lang, "err_hw_mismatch"),
                pilot_name=pilot_disp,
            )
        if shop_email and shop_email != email_c:
            return _web_page_html(
                "activate_license.html",
                request,
                error=_web_tx(lang, "err_email_mismatch"),
                pilot_name=pilot_disp,
            )
        conn.execute(
            """
            UPDATE license_keys SET status = 'activated', hardware_id = ?,
            pilot_name = ?, password_salt = ?, password_hash = ?,
            customer_email = ?
            WHERE license_key = ?;
            """,
            (hid, pilot, salt, phash, email_c, use_key),
        )
        conn.execute("DELETE FROM web_pending_users WHERE hardware_id = ?;", (hid,))
        conn.commit()
    finally:
        conn.close()
    _append_admin_log(f"[web] Lizenz nachtragen email={email_c!r} hardware={hid!r}")
    return RedirectResponse("/dashboard", status_code=http_status.HTTP_303_SEE_OTHER)


def _web_portal_license_ok(hid: str) -> bool:
    """True, wenn Installer-Download erlaubt: User mit aktivierter Lizenz ODER aktivierte Desktop-Zeile in SERVER-DB."""
    hk = (hid or "").strip()[:128]
    if not hk:
        return False
    h64 = hk[:64]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        r = uconn.execute(
            """
            SELECT 1 FROM users
            WHERE hardware_id = ?
              AND trim(coalesce(license_key,'')) != ''
              AND (
                    COALESCE(license_activated, 0) = 1
                 OR COALESCE(has_license, 0) = 1
                 OR COALESCE(is_verified, 0) = 1
              )
            LIMIT 1;
            """,
            (h64,),
        ).fetchone()
        if r:
            return True
    finally:
        uconn.close()
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        r2 = sconn.execute(
            """
            SELECT 1 FROM license_keys
            WHERE hardware_id = ? AND status = 'activated' LIMIT 1;
            """,
            (hk,),
        ).fetchone()
        return bool(r2)
    finally:
        sconn.close()


