@app.get("/download", response_model=None)
async def web_download(request: Request) -> FileResponse | RedirectResponse | HTMLResponse:
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid:
        return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
    ok = _web_portal_license_ok(hid)
    want_html = _request_prefers_html(request)
    lang = _web_lang(request)
    if not ok:
        if want_html:
            return HTMLResponse(
                content=_web_portal_error_html(
                    _web_tx(lang, "dl_err_license_title"),
                    _web_tx(lang, "dl_err_license_body"),
                    lang,
                ),
                status_code=403,
            )
        raise HTTPException(status_code=403, detail="Keine aktive Lizenz.")
    if not DIST_EXE_PATH.is_file():
        if want_html:
            return HTMLResponse(
                content=_web_portal_error_html(
                    _web_tx(lang, "dl_err_exe_title"),
                    _web_tx(lang, "dl_err_exe_body"),
                    lang,
                ),
                status_code=404,
            )
        raise HTTPException(
            status_code=404,
            detail=(
                "Installer-Datei fehlt auf dem Server. "
                "Datei nach "
                f"{DOWNLOADS_DIR / 'SkyTycoon_Pro.exe'} "
                "legen oder SKYTYCOON_DIST_EXE setzen."
            ),
        )
    if want_html and (request.query_params.get("file") or "").strip() != "1":
        return HTMLResponse(
            content=_web_download_page_html(lang),
            headers={"Cache-Control": "no-store, max-age=0"},
        )
    return _installer_file_response()


