def _ensure_donations_reviews_tables(conn) -> None:
    statements = [
        """
        CREATE TABLE IF NOT EXISTS donations (
            id SERIAL PRIMARY KEY,
            donor_name TEXT NOT NULL DEFAULT 'Anonymous',
            amount_eur DOUBLE PRECISION DEFAULT 0,
            message TEXT DEFAULT '',
            created_ts DOUBLE PRECISION DEFAULT 0,
            status VARCHAR(32) DEFAULT 'visible'
        )
        """,
        """
        CREATE TABLE IF NOT EXISTS reviews (
            id SERIAL PRIMARY KEY,
            pilot_name TEXT NOT NULL DEFAULT 'Pilot',
            rating INTEGER DEFAULT 5,
            review_text TEXT DEFAULT '',
            created_ts DOUBLE PRECISION DEFAULT 0,
            status VARCHAR(32) DEFAULT 'visible'
        )
        """,
    ]
    with conn.cursor(cursor_factory=DictCursor) as cur:
        for stmt in statements:
            cur.execute(stmt)
            conn.commit()


def _top_donators(limit: int = 5) -> list[dict[str, Any]]:
    conn = get_db_connection()
    try:
        _ensure_donations_reviews_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT donor_name, SUM(amount_eur) AS total_eur, MAX(message) AS message
                FROM donations
                WHERE status = 'visible'
                GROUP BY donor_name
                ORDER BY total_eur DESC, donor_name ASC
                LIMIT %s
                """,
                (int(limit),),
            )
            rows = [dict(r) for r in cur.fetchall()]
            conn.commit()
    finally:
        conn.close()
    return rows


