@app.post("/api/v1/donations/record")
def api_donations_record(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    if not _admin_ok(request, body):
        raise HTTPException(status_code=403, detail="admin_denied")
    donor = str(body.get("donor_name") or body.get("name") or "Anonymous").strip()[:120] or "Anonymous"
    try:
        amount = max(0.0, float(body.get("amount_eur") or body.get("amount") or 0))
    except (TypeError, ValueError):
        amount = 0.0
    msg = str(body.get("message") or "").strip()[:500]
    conn = get_db_connection()
    try:
        _ensure_donations_reviews_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                "INSERT INTO donations (donor_name, amount_eur, message, created_ts, status) VALUES (%s, %s, %s, %s, 'visible')",
                (donor, amount, msg, time.time()),
            )
            conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "donators": _top_donators(5)})


def _pg_ensure_users_discord_columns(conn) -> None:
    with conn.cursor() as cur:
        for stmt in (
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS discord_id VARCHAR(32) DEFAULT '';",
            "ALTER TABLE users ADD COLUMN IF NOT EXISTS discord_username VARCHAR(128) DEFAULT '';",
        ):
            try:
                cur.execute(stmt)
            except psycopg2.Error:
                conn.rollback()


def _ensure_discord_oauth_tables(conn) -> None:
    with conn.cursor(cursor_factory=DictCursor) as cur:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS discord_oauth_links (
                hardware_id VARCHAR(128) PRIMARY KEY,
                username TEXT DEFAULT '',
                discord_user_id VARCHAR(128) DEFAULT '',
                discord_username TEXT DEFAULT '',
                license_active INTEGER DEFAULT 0,
                linked_ts DOUBLE PRECISION DEFAULT 0
            )
            """
        )
        conn.commit()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS discord_bot_commands (
                id SERIAL PRIMARY KEY,
                command_type VARCHAR(64) NOT NULL,
                payload_json TEXT NOT NULL DEFAULT '{}',
                status VARCHAR(32) NOT NULL DEFAULT 'queued',
                created_ts DOUBLE PRECISION DEFAULT 0,
                processed_ts DOUBLE PRECISION DEFAULT 0,
                error TEXT DEFAULT ''
            )
            """
        )
        conn.commit()


def _queue_discord_bot_command(command_type: str, payload: dict[str, Any]) -> int:
    conn = get_db_connection()
    try:
        _ensure_discord_oauth_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                INSERT INTO discord_bot_commands (command_type, payload_json, status, created_ts)
                VALUES (%s, %s, 'queued', %s)
                RETURNING id
                """,
                (command_type[:64], json.dumps(payload, ensure_ascii=False), time.time()),
            )
            row = cur.fetchone()
            pg_commit(conn)
            return int(row["id"] if row else 0)
    except Exception as exc_pg:  # noqa: BLE001
        _pg_rollback(conn)
        _server_log_line(f"[discord] queue command failed: {exc_pg!s}")
        return 0
    finally:
        conn.close()


def _discord_oauth_authorize_url(state: str) -> str:
    scope = quote("identify guilds.join")
    redirect_uri = _discord_oauth_redirect_uri()
    redirect = quote(redirect_uri, safe="")
    _server_log_line(f"[discord] oauth authorize redirect_uri={redirect_uri!r}")
    return (
        "https://discord.com/oauth2/authorize"
        f"?client_id={quote(_discord_oauth_client_id())}"
        f"&redirect_uri={redirect}"
        "&response_type=code"
        f"&scope={scope}"
        f"&state={quote(state)}"
        "&prompt=consent"
    )


def _discord_user_profile(access_token: str) -> dict[str, Any]:
    r = requests.get(
        "https://discord.com/api/v10/users/@me",
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=15,
    )
    if r.status_code >= 400:
        raise HTTPException(status_code=502, detail="discord_profile_failed")
    data = r.json()
    return data if isinstance(data, dict) else {}


def _web_user_for_discord(hid: str) -> dict[str, Any]:
    conn = get_db_connection()
    try:
        _ensure_discord_oauth_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute(
                """
                SELECT hardware_id, username, email, license_status
                FROM users
                WHERE hardware_id = %s
                LIMIT 1
                """,
                (hid[:128],),
            )
            row = cur.fetchone()
            conn.commit()
    except Exception as exc_pg:  # noqa: BLE001
        try:
            conn.rollback()
        except Exception:
            pass
        _server_log_line(f"[discord] web_user lookup failed: {exc_pg!s}")
        raise
    finally:
        conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="web_user_not_found")
    username = str(row.get("username") or row.get("email") or hid[:16]).strip()[:80]
    lic = str(row.get("license_status") or "").strip().lower()
    license_active = lic in ("1", "active", "activated", "true", "yes", "lifetime", "pro")
    return {"hardware_id": hid[:128], "username": username, "license_active": license_active}


@app.get("/api/v1/auth/discord/login", response_model=None)
def discord_oauth_login(request: Request) -> RedirectResponse:
    try:
        if not _discord_oauth_configured():
            return RedirectResponse(
                f"{_public_origin()}/dashboard?discord_oauth=missing",
                status_code=http_status.HTTP_303_SEE_OTHER,
            )
        hid = _web_session_hid(request)
        if not hid:
            return RedirectResponse(
                f"{_public_origin()}/login?discord_oauth=session",
                status_code=http_status.HTTP_303_SEE_OTHER,
            )
        state = f"ST-DISCORD-{uuid.uuid4().hex}"
        _server_kv_set(
            f"discord_oauth_state:{state}",
            json.dumps({"hid": str(hid)[:128], "ts": time.time()}, ensure_ascii=False),
        )
        auth_url = _discord_oauth_authorize_url(state)
        return RedirectResponse(auth_url, status_code=http_status.HTTP_303_SEE_OTHER)
    except Exception as exc_oauth:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[discord] oauth login route failed: {exc_oauth!s}")
        return RedirectResponse(
            f"{_public_origin()}/login?discord_oauth=error",
            status_code=http_status.HTTP_303_SEE_OTHER,
        )


@app.get("/api/v1/auth/discord/callback", response_class=HTMLResponse, response_model=None)
def discord_oauth_callback(request: Request, code: str = "", state: str = "") -> HTMLResponse:
    lang = _web_lang(request)
    title_ok = "Discord verbunden" if lang == "de" else "Discord connected"
    title_fail = "Discord-Verbindung fehlgeschlagen" if lang == "de" else "Discord connection failed"
    redirect_uri = _discord_oauth_redirect_uri()
    try:
        if not _discord_oauth_configured():
            return HTMLResponse(
                f"<h2>{title_fail}</h2><p>Discord OAuth ist noch nicht konfiguriert.</p>",
                status_code=503,
            )
        if not code or not state:
            return HTMLResponse(
                f"<h2>{title_fail}</h2><p>missing_code_or_state</p>", status_code=400
            )
        raw = _server_kv_get(f"discord_oauth_state:{state}")
        if not raw.strip():
            return HTMLResponse(f"<h2>{title_fail}</h2><p>invalid_state</p>", status_code=400)
        try:
            state_data = json.loads(raw)
        except json.JSONDecodeError:
            state_data = {}
        hid = str(state_data.get("hid") or "")[:128]
        if not hid:
            hid = str(_web_session_hid(request) or "")[:128]
        if not hid:
            return RedirectResponse(
                f"{_public_origin()}/login?discord_oauth=session",
                status_code=http_status.HTTP_303_SEE_OTHER,
            )
        token_resp = requests.post(
            "https://discord.com/api/v10/oauth2/token",
            data={
                "client_id": _discord_oauth_client_id(),
                "client_secret": _discord_oauth_client_secret(),
                "grant_type": "authorization_code",
                "code": code,
                "redirect_uri": redirect_uri,
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            timeout=20,
        )
        if token_resp.status_code >= 400:
            err_body = (token_resp.text or "")[:240]
            return HTMLResponse(
                f"<h2>{title_fail}</h2><p>discord_token_failed</p>"
                f"<pre style='color:#90a4ae;font-size:12px'>{err_body}</pre>"
                f"<p>Redirect URI (forced HTTPS): <code>{redirect_uri}</code></p>",
                status_code=502,
            )
        token_data = token_resp.json()
        access_token = str(token_data.get("access_token") or "")
        profile = _discord_user_profile(access_token)
        discord_id = str(profile.get("id") or "")
        discord_name = str(
            profile.get("username") or profile.get("global_name") or discord_id
        )[:120]
        web_user = _web_user_for_discord(hid)
        if not discord_id:
            return HTMLResponse(
                f"<h2>{title_fail}</h2><p>discord_profile_empty</p>",
                status_code=502,
            )
        try:
            with pg_sync_transaction() as conn:
                _ensure_discord_oauth_tables(conn)
                _pg_ensure_users_discord_columns(conn)
                with conn.cursor(cursor_factory=DictCursor) as cur:
                    cur.execute(
                        """
                        UPDATE users
                        SET discord_id = %s,
                            discord_username = %s
                        WHERE hardware_id = %s
                           OR substring(hardware_id from 1 for 64) = %s;
                        """,
                        (
                            discord_id[:32],
                            discord_name[:128],
                            web_user["hardware_id"],
                            web_user["hardware_id"][:64],
                        ),
                    )
                    cur.execute(
                        """
                        INSERT INTO discord_oauth_links (
                            hardware_id, username, discord_user_id, discord_username,
                            license_active, linked_ts
                        ) VALUES (%s, %s, %s, %s, %s, %s)
                        ON CONFLICT (hardware_id) DO UPDATE SET
                            username = EXCLUDED.username,
                            discord_user_id = EXCLUDED.discord_user_id,
                            discord_username = EXCLUDED.discord_username,
                            license_active = EXCLUDED.license_active,
                            linked_ts = EXCLUDED.linked_ts
                        """,
                        (
                            web_user["hardware_id"],
                            web_user["username"],
                            discord_id,
                            discord_name,
                            1 if web_user["license_active"] else 0,
                            time.time(),
                        ),
                    )
        except Exception as exc_pg:  # noqa: BLE001
            _pg_rollback_safeguard_request()
            _server_log_line(f"[discord] oauth PG link failed: {exc_pg!s}")
            return RedirectResponse(
                f"{_public_origin()}/dashboard?discord_oauth=db_error",
                status_code=http_status.HTTP_303_SEE_OTHER,
            )
        portal_em_oauth = _portal_email_for_hardware(web_user["hardware_id"][:64])
        is_sa_oauth = _is_global_superadmin_email(portal_em_oauth)
        if is_sa_oauth:
            _apply_global_superadmin_pg(
                portal_em_oauth, web_user["hardware_id"], web_user["username"]
            )
            _ensure_superadmin_sqlite_license(
                portal_em_oauth, web_user["hardware_id"], web_user["username"]
            )
        _queue_discord_bot_command(
            "oauth_member_sync",
            {
                "hardware_id": web_user["hardware_id"],
                "web_username": web_user["username"],
                "discord_user_id": discord_id,
                "discord_username": discord_name,
                "access_token": access_token,
                "license_active": bool(web_user["license_active"]) or is_sa_oauth,
                "is_superadmin": is_sa_oauth,
                "portal_email": portal_em_oauth,
                "guild_id": _discord_oauth_guild_id(),
            },
        )
        return _web_discord_oauth_finish(request, web_user["hardware_id"])
    except HTTPException:
        raise
    except Exception as exc_oauth:  # noqa: BLE001
        _pg_rollback_safeguard_request()
        _server_log_line(f"[discord] oauth callback failed: {exc_oauth!s}")
        hid_recover = str(_web_session_hid(request) or "")[:128]
        if hid_recover:
            return RedirectResponse(
                f"{_public_origin()}/dashboard?discord_oauth=error",
                status_code=http_status.HTTP_303_SEE_OTHER,
            )
        return RedirectResponse(
            f"{_public_origin()}/login?discord_oauth=error",
            status_code=http_status.HTTP_303_SEE_OTHER,
        )


