def _review_stats() -> dict[str, Any]:
    conn = get_db_connection()
    try:
        _ensure_donations_reviews_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT COUNT(*) AS c, COALESCE(AVG(rating), 5) AS avg_rating FROM reviews WHERE status = 'visible'")
            stats = dict(cur.fetchone() or {})
            conn.commit()
            cur.execute("SELECT pilot_name, rating, review_text, created_ts FROM reviews WHERE status = 'visible' ORDER BY created_ts DESC LIMIT 25")
            rows = [dict(r) for r in cur.fetchall()]
            conn.commit()
    finally:
        conn.close()
    return {"count": int(stats.get("c") or 0), "avg_rating": round(float(stats.get("avg_rating") or 5), 2), "reviews": rows}


