@app.get("/sitemap.xml", response_class=Response, response_model=None)
def web_sitemap_xml() -> Response:
    base = "https://skytycoon.info"
    paths = [
        "/",
        "/features",
        "/reviews",
        "/downloads",
        "/market/jobs",
        "/market/daily_auctions",
        "/market/radar",
        "/market/wallstreet",
        "/bank/finances",
    ]
    body = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    for p in paths:
        body += f"  <url><loc>{base}{p}</loc><changefreq>daily</changefreq><priority>{'1.0' if p == '/' else '0.8'}</priority></url>\n"
    body += "</urlset>\n"
    return Response(content=body, media_type="application/xml")


