def _ensure_property_market_tables(conn) -> None:
    statements = [
        """
        CREATE TABLE IF NOT EXISTS daily_property_deals (
            deal_id VARCHAR(64) PRIMARY KEY,
            market_day VARCHAR(16) NOT NULL,
            property_name TEXT NOT NULL,
            property_name_en TEXT NOT NULL,
            airline_name TEXT NOT NULL,
            airport_icao VARCHAR(8) NOT NULL,
            city TEXT NOT NULL,
            country TEXT NOT NULL,
            price_credits INTEGER DEFAULT 0,
            daily_dividend INTEGER DEFAULT 0,
            rarity VARCHAR(32) DEFAULT 'RARE',
            status VARCHAR(32) DEFAULT 'active',
            created_ts DOUBLE PRECISION DEFAULT 0,
            expires_ts_utc DOUBLE PRECISION DEFAULT 0
        )
        """,
        """
        CREATE TABLE IF NOT EXISTS owned_properties (
            id SERIAL PRIMARY KEY,
            hardware_id VARCHAR(128) NOT NULL,
            deal_id VARCHAR(64) NOT NULL,
            property_name TEXT NOT NULL,
            airline_name TEXT NOT NULL,
            airport_icao VARCHAR(8) NOT NULL,
            price_credits INTEGER DEFAULT 0,
            daily_dividend INTEGER DEFAULT 0,
            purchased_ts DOUBLE PRECISION DEFAULT 0,
            UNIQUE(hardware_id, deal_id)
        )
        """,
    ]
    with conn.cursor(cursor_factory=DictCursor) as cur:
        for stmt in statements:
            cur.execute(stmt)
            conn.commit()


def _generate_daily_property_deals_if_needed() -> None:
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    conn = get_db_connection()
    try:
        _ensure_property_market_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT COUNT(*) AS c FROM daily_property_deals WHERE market_day = %s AND status = 'active'", (today,))
            existing = int((cur.fetchone() or {}).get("c") or 0)
            conn.commit()
            if existing >= 4:
                return
            cur.execute("UPDATE daily_property_deals SET status = 'expired' WHERE market_day <> %s AND status = 'active'", (today,))
            conn.commit()
            rng = random.Random(today)
            picks = list(PROPERTY_DEAL_CATALOG)
            rng.shuffle(picks)
            expires = _next_midnight_utc_ts()
            for idx, item in enumerate(picks[:4], start=1):
                factor = rng.uniform(0.92, 1.18)
                price = int(float(item["base_price"]) * factor)
                dividend = int(float(item["dividend"]) * rng.uniform(0.95, 1.14))
                deal_id = f"PROP-{today}-{idx}-{item['airport_icao']}"
                cur.execute(
                    """
                    INSERT INTO daily_property_deals (
                        deal_id, market_day, property_name, property_name_en, airline_name,
                        airport_icao, city, country, price_credits, daily_dividend,
                        rarity, status, created_ts, expires_ts_utc
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'active', %s, %s)
                    ON CONFLICT (deal_id) DO UPDATE SET
                        price_credits = EXCLUDED.price_credits,
                        daily_dividend = EXCLUDED.daily_dividend,
                        status = 'active',
                        expires_ts_utc = EXCLUDED.expires_ts_utc
                    """,
                    (
                        deal_id,
                        today,
                        item["property_name"],
                        item["property_name_en"],
                        item["airline_name"],
                        item["airport_icao"],
                        item["city"],
                        item["country"],
                        price,
                        dividend,
                        item["rarity"],
                        time.time(),
                        expires,
                    ),
                )
                conn.commit()
    finally:
        conn.close()


async def _property_market_midnight_loop() -> None:
    while True:
        try:
            await asyncio.to_thread(_generate_daily_property_deals_if_needed)
        except Exception as exc:  # noqa: BLE001
            try:
                _server_log_line(f"[property_market] midnight generation failed: {exc!s}")
            except Exception:
                pass
        await asyncio.sleep(max(30.0, min(3600.0, _next_midnight_utc_ts() - time.time() + 1.0)))


@app.on_event("startup")
async def _start_property_market_midnight_task() -> None:
    try:
        await asyncio.to_thread(_generate_daily_property_deals_if_needed)
        asyncio.create_task(_property_market_midnight_loop())
    except Exception:
        pass


def _property_rows_for_hid(hid: str) -> dict[str, Any]:
    _generate_daily_property_deals_if_needed()
    conn = get_db_connection()
    try:
        _ensure_property_market_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT COALESCE(credits, 0) AS credits FROM users WHERE hardware_id = %s", (hid,))
            urow = cur.fetchone()
            conn.commit()
            cur.execute(
                """
                SELECT d.*, CASE WHEN o.id IS NULL THEN 0 ELSE 1 END AS owned
                FROM daily_property_deals d
                LEFT JOIN owned_properties o ON o.deal_id = d.deal_id AND o.hardware_id = %s
                WHERE d.status = 'active'
                ORDER BY d.price_credits DESC
                """,
                (hid,),
            )
            deals = [dict(r) for r in cur.fetchall()]
            conn.commit()
            cur.execute(
                """
                SELECT property_name, airline_name, airport_icao, price_credits, daily_dividend, purchased_ts
                FROM owned_properties
                WHERE hardware_id = %s
                ORDER BY purchased_ts DESC
                """,
                (hid,),
            )
            owned = [dict(r) for r in cur.fetchall()]
            conn.commit()
    finally:
        conn.close()
    return {"ok": True, "credits": float((urow or {}).get("credits") or 0), "deals": deals, "owned": owned}


