@app.post("/api/v1/bank/property_deals/buy")
def api_bank_property_deal_buy(request: Request, body: dict[str, Any] = Body(default_factory=dict)) -> JSONResponse:
    body = body if isinstance(body, dict) else {}
    hid = str(body.get("hardware_id") or "").strip()[:64] or (_web_parse_token(_web_raw_session_cookie(request)) or "").strip()[:64]
    if not hid:
        raise HTTPException(status_code=401, detail="login_required")
    deal_id = str(body.get("deal_id") or "").strip()[:64]
    if not deal_id:
        return JSONResponse({"ok": False, "error": "bad_deal"}, status_code=400)
    _generate_daily_property_deals_if_needed()
    conn = get_db_connection()
    try:
        _ensure_property_market_tables(conn)
        with conn.cursor(cursor_factory=DictCursor) as cur:
            cur.execute("SELECT * FROM daily_property_deals WHERE deal_id = %s AND status = 'active'", (deal_id,))
            deal = cur.fetchone()
            conn.commit()
            if not deal:
                return JSONResponse({"ok": False, "error": "deal_not_found"}, status_code=404)
            cur.execute("SELECT 1 FROM owned_properties WHERE hardware_id = %s AND deal_id = %s", (hid, deal_id))
            already_owned = cur.fetchone()
            conn.commit()
            if already_owned:
                data = _property_rows_for_hid(hid)
                data.update({"purchased": False, "already_owned": True, "deal_id": deal_id})
                return JSONResponse(data)
            cur.execute("SELECT COALESCE(credits, 0) AS credits FROM users WHERE hardware_id = %s", (hid,))
            urow = cur.fetchone()
            conn.commit()
            price = int(deal["price_credits"] or 0)
            if float((urow or {}).get("credits") or 0) < price:
                return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
            cur.execute("UPDATE users SET credits = COALESCE(credits, 0) - %s WHERE hardware_id = %s", (price, hid))
            conn.commit()
            cur.execute(
                """
                INSERT INTO owned_properties (
                    hardware_id, deal_id, property_name, airline_name, airport_icao,
                    price_credits, daily_dividend, purchased_ts
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (hardware_id, deal_id) DO NOTHING
                """,
                (
                    hid,
                    deal_id,
                    deal["property_name"],
                    deal["airline_name"],
                    deal["airport_icao"],
                    price,
                    int(deal["daily_dividend"] or 0),
                    time.time(),
                ),
            )
            conn.commit()
    finally:
        conn.close()
    data = _property_rows_for_hid(hid)
    data.update({"purchased": True, "deal_id": deal_id})
    return JSONResponse(data)


@app.get("/api/v1/web/download/app")
def web_download_app_protected(request: Request) -> FileResponse:
    """
    Geschützter Installer-Download (JSON-API / direkter Link mit Session-Cookie).
    Nur eingeloggtes Web-Portal mit aktivierter Lizenz (siehe ``_web_portal_license_ok``).
    """
    hid = _web_parse_token(_web_raw_session_cookie(request))
    if not hid or not str(hid).strip():
        raise HTTPException(status_code=401, detail="login_required")
    if not _web_portal_license_ok(str(hid).strip()[:128]):
        raise HTTPException(status_code=403, detail="license_required")
    if not DIST_EXE_PATH.is_file():
        raise HTTPException(status_code=404, detail="installer_missing")
    return _installer_file_response()


