try:
    from starlette.middleware.base import BaseHTTPMiddleware

    class _SkyPgSafeguardMiddleware(BaseHTTPMiddleware):
        """Request-weiser PG-Rollback — verhindert hängende Pool-Transaktionen."""

        async def dispatch(self, request: Request, call_next):  # type: ignore[override]
            reset = _REQUEST_PG_CONNS.set([])
            try:
                return await call_next(request)
            finally:
                _pg_rollback_safeguard_request()
                try:
                    _REQUEST_PG_CONNS.reset(reset)
                except ValueError:
                    pass

    app.add_middleware(_SkyPgSafeguardMiddleware)

    class _SkyBigmaqDevPartnerMiddleware(BaseHTTPMiddleware):
        """Markiert BigMaq-Dev-Requests für PG/GZIP/Admin-Pfade."""

        async def dispatch(self, request: Request, call_next):  # type: ignore[override]
            request.state.bigmaq_dev_partner = _is_bigmaq_developer_partner(request)
            return await call_next(request)

    app.add_middleware(_SkyBigmaqDevPartnerMiddleware)
except Exception as _mw_exc:  # noqa: BLE001
    try:
        _server_log_line(f"[shield] PG-Safeguard-Middleware nicht geladen: {_mw_exc!s}")
    except NameError:
        print(f"[shield] PG-Safeguard-Middleware nicht geladen: {_mw_exc!s}")


def _efb_panel_i18n(lang: str, key: str) -> str:
    l = "en" if str(lang or "").lower().startswith("en") else "de"
    table = {
        "err_auth": {
            "de": "Ungültige Zugangsdaten oder keine Lizenz!",
            "en": "Invalid credentials or no license!",
        },
        "err_banned": {
            "de": "Konto gesperrt — Support kontaktieren.",
            "en": "Account banned — contact support.",
        },
        "err_net": {
            "de": "Anmeldung fehlgeschlagen.",
            "en": "Login failed.",
        },
    }
    return table.get(key, {}).get(l, key)


def _efb_resolve_login_row(user_login: str) -> tuple[str, str, str, str, int | None] | None:
    """Returns salt, phash, pilot_name, hid_raw, pending_is_verified (None if license_keys)."""
    ident = user_login.strip()[:200]
    low = ident.lower()
    conn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        row = conn.execute(
            """
            SELECT password_salt, password_hash, pilot_name, hardware_id
            FROM license_keys
            WHERE status = 'activated'
              AND (
                    lower(trim(customer_email)) = ?
                 OR lower(trim(pilot_name)) = ?
              )
            ORDER BY created_ts DESC LIMIT 1;
            """,
            (low, low),
        ).fetchone()
        if row:
            return (
                str(row[0] or ""),
                str(row[1] or ""),
                str(row[2] or ""),
                str(row[3] or ""),
                None,
            )
        row = conn.execute(
            """
            SELECT password_salt, password_hash, pilot_name, hardware_id,
                   COALESCE(is_verified, 1)
            FROM web_pending_users
            WHERE lower(trim(email)) = ? OR lower(trim(pilot_name)) = ?
            ORDER BY created_ts DESC LIMIT 1;
            """,
            (low, low),
        ).fetchone()
        if row:
            return (
                str(row[0] or ""),
                str(row[1] or ""),
                str(row[2] or ""),
                str(row[3] or ""),
                int(row[4] or 1),
            )
    finally:
        conn.close()
    return None


@app.post("/api/v1/auth/efb_panel_login")
async def api_efb_panel_login(request: Request) -> JSONResponse:
    """MSFS EFB cockpit login — PostgreSQL license gate + signed session token."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}
    user_in = str(body.get("username") or body.get("email") or body.get("pilot_name") or "").strip()
    pw = str(body.get("password") or "")
    lang = str(body.get("lang") or "de")[:8]
    if not user_in or not pw:
        return JSONResponse(
            {"ok": False, "detail": _efb_panel_i18n(lang, "err_auth")},
            status_code=401,
        )
    row = _efb_resolve_login_row(user_in)
    if not row:
        return JSONResponse(
            {"ok": False, "detail": _efb_panel_i18n(lang, "err_auth")},
            status_code=401,
        )
    salt, phash, pilot, hid_raw, pending_iv = row
    if not _password_verify_db(salt, phash, pw):
        return JSONResponse(
            {"ok": False, "detail": _efb_panel_i18n(lang, "err_auth")},
            status_code=401,
        )
    if pending_iv is not None and pending_iv != 1:
        return JSONResponse(
            {"ok": False, "detail": _efb_panel_i18n(lang, "err_auth")},
            status_code=401,
        )
    hid = hid_raw.strip()[:128]
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        br = uconn.execute(
            "SELECT banned FROM users WHERE hardware_id = ?;", (hid[:64],)
        ).fetchone()
        if br and int(br[0] or 0) == 1:
            return JSONResponse(
                {"ok": False, "detail": _efb_panel_i18n(lang, "err_banned")},
                status_code=403,
            )
    finally:
        uconn.close()
    email_c = user_in.lower() if "@" in user_in else ""
    pg_hid = _web_resolve_postgres_hardware_id(
        email=email_c, sqlite_hid=hid, pilot_name=pilot
    )
    if not pg_hid:
        pg_hid = hid
    _v, has_license = _sync_user_license_flags(pg_hid[:64])
    if not has_license:
        return JSONResponse(
            {"ok": False, "detail": _efb_panel_i18n(lang, "err_auth")},
            status_code=403,
        )
    _web_postgres_sync_login_profile(
        pg_hid,
        email=email_c or user_in,
        pilot_name=pilot,
        license_active=True,
    )
    token = _web_issue_token(pg_hid)
    return JSONResponse(
        {
            "ok": True,
            "efb_token": token,
            "lang": "en" if lang.lower().startswith("en") else "de",
            "hardware_id": pg_hid[:64],
            "pilot_name": pilot,
        }
    )


