@app.get("/player/career_backup", response_class=HTMLResponse, response_model=None)
async def web_player_career_backup_guaranteed(
    request: Request,
) -> HTMLResponse | RedirectResponse:
    """Guaranteed backup center route (also registered via crash_recovery module)."""
    hid, needs_refresh = _web_postgres_session_refresh(request)
    if not hid:
        return RedirectResponse("/login", status_code=http_status.HTTP_303_SEE_OTHER)
    backups: list[dict[str, Any]] = []
    resume = False
    try:
        import skytycoon_crash_recovery as _cr

        backups = _cr.pg_list_backups(hid[:64])
        resume = bool(_cr.pg_resume_available(hid[:64]))
    except Exception:
        pass
    resp = _web_page_html(
        "player/career_backup.html",
        request,
        crash_backups=backups,
        resume_available=resume,
    )
    if needs_refresh:
        _web_apply_session_refresh(resp, request, hid)
    return resp


def _alliance_fleet_market_value_sqlite(conn: sqlite3.Connection, alliance_id: str) -> float:
    try:
        row = conn.execute(
            """
            SELECT COALESCE(SUM(
                COALESCE(daily_lease_fee, 0) * 30.0 + COALESCE(health, 0) * 500.0
            ), 0)
            FROM alliance_fleet WHERE alliance_id = ?;
            """,
            (alliance_id,),
        ).fetchone()
        return float(row[0] or 0) if row else 0.0
    except sqlite3.Error:
        return 0.0


def _ensure_alliance_platin_tables(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS alliance_fuel_depot (
            alliance_id TEXT PRIMARY KEY,
            liters REAL NOT NULL DEFAULT 0,
            cap_liters REAL NOT NULL DEFAULT 500000,
            updated_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS alliance_auctions (
            auction_id TEXT PRIMARY KEY,
            alliance_id TEXT NOT NULL,
            title TEXT NOT NULL,
            item_type TEXT NOT NULL DEFAULT 'fleet',
            current_bid REAL NOT NULL DEFAULT 0,
            high_bidder TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'open',
            ends_ts REAL NOT NULL DEFAULT 0,
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS alliance_job_splits (
            split_id TEXT PRIMARY KEY,
            alliance_id TEXT NOT NULL,
            route TEXT NOT NULL,
            share_pct REAL NOT NULL DEFAULT 0,
            pilot_hardware_id TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'open',
            credits REAL NOT NULL DEFAULT 0,
            created_ts REAL NOT NULL DEFAULT 0
        );
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS alliance_shipyard_pool (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alliance_id TEXT NOT NULL,
            part_type TEXT NOT NULL,
            qty INTEGER NOT NULL DEFAULT 0,
            condition TEXT NOT NULL DEFAULT '100',
            holder_hardware_id TEXT NOT NULL DEFAULT '',
            updated_ts REAL NOT NULL DEFAULT 0
        );
        """
    )


def _alliance_crisis_fuel_multiplier() -> float:
    try:
        cfg_path = SERVER_DB_PATH.parent / "crisis_state.json"
        if cfg_path.is_file():
            j = json.loads(cfg_path.read_text(encoding="utf-8"))
            return max(0.5, min(3.0, float(j.get("fuel_multiplier", 1.0) or 1.0)))
    except Exception:
        pass
    return 1.0


def _alliance_platin_state_payload(alliance_id: str, hid: str) -> dict[str, Any]:
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_alliance_platin_tables(sconn)
        pool_row = sconn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        credits = float(pool_row[0] or 0) if pool_row else 0.0
        fuel = sconn.execute(
            "SELECT liters, cap_liters FROM alliance_fuel_depot WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        if not fuel:
            sconn.execute(
                "INSERT INTO alliance_fuel_depot (alliance_id, liters, cap_liters, updated_ts) VALUES (?, 0, 500000, ?);",
                (alliance_id, time.time()),
            )
            sconn.commit()
            fuel = (0.0, 500000.0)
        jobs = sconn.execute(
            """
            SELECT route, share_pct, pilot_hardware_id, status, credits
            FROM alliance_job_splits WHERE alliance_id = ? ORDER BY created_ts DESC LIMIT 80;
            """,
            (alliance_id,),
        ).fetchall()
        parts = sconn.execute(
            """
            SELECT part_type, qty, condition, holder_hardware_id
            FROM alliance_shipyard_pool WHERE alliance_id = ? ORDER BY updated_ts DESC LIMIT 120;
            """,
            (alliance_id,),
        ).fetchall()
    finally:
        sconn.close()
    mult = _alliance_crisis_fuel_multiplier()
    return {
        "ok": True,
        "alliance_id": alliance_id,
        "alliance_credits": credits,
        "fuel_depot": {
            "liters": float(fuel[0] or 0),
            "cap_liters": float(fuel[1] or 500000),
            "crisis_multiplier": mult,
        },
        "job_splits": [
            {
                "route": str(r[0]),
                "share_pct": float(r[1] or 0),
                "pilot": str(r[2] or "")[:16],
                "status": str(r[3] or "open"),
                "credits": float(r[4] or 0),
            }
            for r in jobs
        ],
        "shipyard_parts": [
            {
                "part_type": str(r[0]),
                "qty": int(r[1] or 0),
                "condition": str(r[2] or "100"),
                "holder": str(r[3] or "pool")[:16] or "pool",
                "status": "pool",
            }
            for r in parts
        ],
    }


