@app.post("/api/v1/alliance/fuel/buy")
def alliance_fuel_buy(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) not in ("ceo", "co_leader", "treasurer"):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    alliance_id = mem[0]
    try:
        liters = float(body.get("liters", 0) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_liters"}, status_code=400)
    if liters < 100:
        return JSONResponse({"ok": False, "error": "bad_liters"}, status_code=400)
    mult = _alliance_crisis_fuel_multiplier()
    unit_cost = 2.5 * mult
    total_cost = liters * unit_cost
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        sconn.execute("BEGIN IMMEDIATE")
        uconn.execute("BEGIN IMMEDIATE")
        _ensure_alliance_platin_tables(sconn)
        row = sconn.execute(
            "SELECT credits FROM alliances WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        if not row or float(row[0] or 0) + 1e-6 < total_cost:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_alliance_credits"}, status_code=400)
        dep = sconn.execute(
            "SELECT liters, cap_liters FROM alliance_fuel_depot WHERE alliance_id = ?;",
            (alliance_id,),
        ).fetchone()
        cap = float(dep[1] or 500000) if dep else 500000.0
        cur = float(dep[0] or 0) if dep else 0.0
        if cur + liters > cap + 1e-6:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "depot_full"}, status_code=400)
        sconn.execute(
            "UPDATE alliances SET credits = credits - ? WHERE alliance_id = ?;",
            (total_cost, alliance_id),
        )
        sconn.execute(
            """
            INSERT INTO alliance_fuel_depot (alliance_id, liters, cap_liters, updated_ts)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(alliance_id) DO UPDATE SET
                liters = liters + excluded.liters,
                updated_ts = excluded.updated_ts;
            """,
            (alliance_id, liters, cap, time.time()),
        )
        sconn.commit()
        uconn.commit()
    except Exception:
        sconn.rollback()
        uconn.rollback()
        raise
    finally:
        sconn.close()
        uconn.close()
    return JSONResponse(
        {
            "ok": True,
            "liters_added": liters,
            "cost": total_cost,
            "state": _alliance_platin_state_payload(alliance_id, hid),
        }
    )


@app.post("/api/v1/alliance/jobs/split")
def alliance_jobs_split(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem or str(mem[1]) not in ("ceo", "co_leader", "captain"):
        return JSONResponse({"ok": False, "error": "forbidden"}, status_code=403)
    alliance_id = mem[0]
    route = str(body.get("route", "") or "").strip().upper()[:24]
    parts = max(2, min(12, int(body.get("parts", 3) or 3)))
    if not route:
        return JSONResponse({"ok": False, "error": "bad_route"}, status_code=400)
    share = round(100.0 / parts, 2)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_alliance_platin_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        for i in range(parts):
            sid = f"{alliance_id}-{route}-{int(time.time())}-{i}"
            sconn.execute(
                """
                INSERT INTO alliance_job_splits (
                    split_id, alliance_id, route, share_pct, pilot_hardware_id, status, credits, created_ts
                ) VALUES (?, ?, ?, ?, ?, 'open', 0, ?);
                """,
                (sid, alliance_id, route, share, "", time.time()),
            )
        sconn.commit()
    except Exception:
        sconn.rollback()
        raise
    finally:
        sconn.close()
    return JSONResponse(
        {"ok": True, "parts": parts, "state": _alliance_platin_state_payload(alliance_id, hid)}
    )


@app.post("/api/v1/alliance/auction/list")
def alliance_auction_list(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id = mem[0]
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_alliance_platin_tables(sconn)
        rows = sconn.execute(
            """
            SELECT auction_id, title, item_type, current_bid, status, ends_ts
            FROM alliance_auctions
            WHERE alliance_id = ? AND status = 'open'
            ORDER BY ends_ts ASC LIMIT 80;
            """,
            (alliance_id,),
        ).fetchall()
    finally:
        sconn.close()
    auctions = []
    for r in rows:
        auctions.append(
            {
                "auction_id": str(r[0]),
                "title": str(r[1]),
                "item_type": str(r[2]),
                "current_bid": float(r[3] or 0),
                "status": str(r[4]),
                "ends_utc": time.strftime(
                    "%Y-%m-%d %H:%M UTC", time.gmtime(float(r[5] or 0))
                ),
            }
        )
    if not auctions:
        seed_id = f"{alliance_id}-seed-auction"
        sconn2 = sqlite3.connect(str(SERVER_DB_PATH))
        try:
            _ensure_alliance_platin_tables(sconn2)
            sconn2.execute(
                """
                INSERT OR IGNORE INTO alliance_auctions (
                    auction_id, alliance_id, title, item_type, current_bid, status, ends_ts, created_ts
                ) VALUES (?, ?, ?, 'fleet', 25000, 'open', ?, ?);
                """,
                (
                    seed_id,
                    alliance_id,
                    "Alliance fleet slot",
                    time.time() + 86400,
                    time.time(),
                ),
            )
            sconn2.commit()
            row = sconn2.execute(
                """
                SELECT auction_id, title, item_type, current_bid, status, ends_ts
                FROM alliance_auctions
                WHERE alliance_id = ? AND status = 'open'
                ORDER BY ends_ts ASC LIMIT 80;
                """,
                (alliance_id,),
            ).fetchall()
            for r in row:
                auctions.append(
                    {
                        "auction_id": str(r[0]),
                        "title": str(r[1]),
                        "item_type": str(r[2]),
                        "current_bid": float(r[3] or 0),
                        "status": str(r[4]),
                        "ends_utc": time.strftime(
                            "%Y-%m-%d %H:%M UTC", time.gmtime(float(r[5] or 0))
                        ),
                    }
                )
        finally:
            sconn2.close()
    return JSONResponse({"ok": True, "auctions": auctions})


@app.post("/api/v1/alliance/auction/bid")
def alliance_auction_bid(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id = mem[0]
    auction_id = str(body.get("auction_id", "") or "").strip()
    try:
        bid = float(body.get("bid", 0) or 0)
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "bad_bid"}, status_code=400)
    if not auction_id or bid < 1:
        return JSONResponse({"ok": False, "error": "bad_bid"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    uconn = sqlite3.connect(str(USER_DB_PATH))
    try:
        sconn.execute("BEGIN IMMEDIATE")
        uconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            """
            SELECT current_bid, high_bidder, status, ends_ts
            FROM alliance_auctions
            WHERE auction_id = ? AND alliance_id = ?;
            """,
            (auction_id, alliance_id),
        ).fetchone()
        if not row or str(row[2]) != "open":
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "closed"}, status_code=400)
        if float(row[0] or 0) + 1e-6 >= bid:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "bid_too_low"}, status_code=400)
        if time.time() > float(row[3] or 0):
            sconn.execute(
                "UPDATE alliance_auctions SET status = 'closed' WHERE auction_id = ?;",
                (auction_id,),
            )
            sconn.commit()
            uconn.commit()
            return JSONResponse({"ok": False, "error": "ended"}, status_code=400)
        urow = uconn.execute(
            "SELECT credits FROM users WHERE hardware_id = ?;", (hid,)
        ).fetchone()
        if not urow or float(urow[0] or 0) + 1e-6 < bid:
            sconn.rollback()
            uconn.rollback()
            return JSONResponse({"ok": False, "error": "insufficient_credits"}, status_code=400)
        prev_bidder = str(row[1] or "").strip()
        prev_amt = float(row[0] or 0)
        if prev_bidder and prev_bidder != hid:
            uconn.execute(
                "UPDATE users SET credits = credits + ? WHERE hardware_id = ?;",
                (prev_amt, prev_bidder),
            )
        uconn.execute(
            "UPDATE users SET credits = credits - ? WHERE hardware_id = ?;",
            (bid, hid),
        )
        sconn.execute(
            """
            UPDATE alliance_auctions
            SET current_bid = ?, high_bidder = ?
            WHERE auction_id = ?;
            """,
            (bid, hid, auction_id),
        )
        sconn.commit()
        uconn.commit()
    except sqlite3.Error:
        sconn.rollback()
        uconn.rollback()
        return JSONResponse({"ok": False, "error": "db"}, status_code=500)
    finally:
        sconn.close()
        uconn.close()
    return JSONResponse({"ok": True, "auction_id": auction_id, "bid": bid})


@app.get("/api/v1/alliance/leaderboard/global")
def alliance_leaderboard_global(limit: int = 50) -> JSONResponse:
    lim = max(5, min(100, int(limit or 50)))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        rows = sconn.execute(
            """
            SELECT a.alliance_id, a.name, COALESCE(a.credits, 0),
                   (SELECT COUNT(*) FROM alliance_members m
                    WHERE m.alliance_id = a.alliance_id AND m.role != 'pending')
            FROM alliances a
            ORDER BY a.credits DESC
            LIMIT ?;
            """,
            (lim,),
        ).fetchall()
    finally:
        sconn.close()
    out = []
    for aid, name, credits, members in rows:
        aid_s = str(aid)
        fleet_mv = 0.0
        try:
            sc = sqlite3.connect(str(SERVER_DB_PATH))
            fleet_mv = _alliance_fleet_market_value_sqlite(sc, aid_s)
            sc.close()
        except Exception:
            pass
        wealth = float(credits or 0) + fleet_mv
        out.append(
            {
                "alliance_id": aid_s,
                "name": str(name or aid_s),
                "wealth": round(wealth, 2),
                "xp": int(members or 0) * 12500,
                "members": int(members or 0),
            }
        )
    out.sort(key=lambda x: (-float(x["wealth"]), -int(x["xp"])))
    return JSONResponse({"ok": True, "alliances": out})


@app.get("/api/v1/alliance/midnight/status")
def alliance_midnight_status() -> JSONResponse:
    now = time.gmtime()
    sec_today = now.tm_hour * 3600 + now.tm_min * 60 + now.tm_sec
    sec_to = 86400 - sec_today
    return JSONResponse(
        {
            "ok": True,
            "seconds_to_midnight_utc": int(sec_to),
            "server_utc": time.strftime("%Y-%m-%d %H:%M:%S UTC", now),
        }
    )


@app.post("/api/v1/alliance/shipyard/deposit")
def alliance_shipyard_deposit(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id = mem[0]
    part = str(body.get("part_type", "") or "").strip()[:64]
    qty = max(1, min(99, int(body.get("qty", 1) or 1)))
    if not part:
        return JSONResponse({"ok": False, "error": "bad_part"}, status_code=400)
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_alliance_platin_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            """
            SELECT row_id, qty FROM alliance_shipyard_pool
            WHERE alliance_id = ? AND part_type = ? AND holder_hardware_id = ''
            LIMIT 1;
            """,
            (alliance_id, part),
        ).fetchone()
        if row:
            sconn.execute(
                "UPDATE alliance_shipyard_pool SET qty = qty + ?, updated_ts = ? WHERE row_id = ?;",
                (qty, time.time(), int(row[0])),
            )
        else:
            sconn.execute(
                """
                INSERT INTO alliance_shipyard_pool (
                    alliance_id, part_type, qty, condition, holder_hardware_id, updated_ts
                ) VALUES (?, ?, ?, '100', '', ?);
                """,
                (alliance_id, part, qty, time.time()),
            )
        sconn.commit()
    except Exception:
        sconn.rollback()
        raise
    finally:
        sconn.close()
    return JSONResponse(
        {"ok": True, "state": _alliance_platin_state_payload(alliance_id, hid)}
    )


@app.post("/api/v1/alliance/shipyard/withdraw")
def alliance_shipyard_withdraw(
    request: Request, body: dict[str, Any] = Body(default_factory=dict)
) -> JSONResponse:
    hid = _desktop_api_auth(request, body)
    mem = _alliance_member_row(hid)
    if not mem:
        return JSONResponse({"ok": False, "error": "not_member"}, status_code=403)
    alliance_id = mem[0]
    part = str(body.get("part_type", "") or "").strip()[:64]
    qty = max(1, min(99, int(body.get("qty", 1) or 1)))
    sconn = sqlite3.connect(str(SERVER_DB_PATH))
    try:
        _ensure_alliance_platin_tables(sconn)
        sconn.execute("BEGIN IMMEDIATE")
        row = sconn.execute(
            """
            SELECT row_id, qty FROM alliance_shipyard_pool
            WHERE alliance_id = ? AND part_type = ? AND qty >= ?
            ORDER BY row_id ASC LIMIT 1;
            """,
            (alliance_id, part, qty),
        ).fetchone()
        if not row:
            sconn.rollback()
            return JSONResponse({"ok": False, "error": "not_in_pool"}, status_code=400)
        rid, have = int(row[0]), int(row[1] or 0)
        if have <= qty:
            sconn.execute("DELETE FROM alliance_shipyard_pool WHERE row_id = ?;", (rid,))
        else:
            sconn.execute(
                "UPDATE alliance_shipyard_pool SET qty = qty - ?, updated_ts = ? WHERE row_id = ?;",
                (qty, time.time(), rid),
            )
        sconn.commit()
    except Exception:
        sconn.rollback()
        raise
    finally:
        sconn.close()
    return JSONResponse(
        {"ok": True, "state": _alliance_platin_state_payload(alliance_id, hid)}
    )


